#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/spi/spi.h>
#include <linux/gpio.h>

#define MCP3008_DEVICE_PATH "/dev/spidev0.0"
#define MCP3008_CS_GPIO_NUM 8
#define MCP3008_CS_NAME "ce0"

#define ADC_CHANNEL_NUM 0
#define ADC_MAX_VALUE 1023

int main() {
    int spi_fd, gpio_fd, adc_fd;
    struct spi_device *spi;
    struct gpio_desc *gpio;
    struct adc_desc *adc;
    struct timespec start_time, end_time;
    long adc_value;
    char timestamp[80];

    // Initialize SPI and GPIO
    spi_fd = open(MCP3008_DEVICE_PATH, O_RDWR);
    gpio_fd = open(MCP3008_CS_NAME, O_RDWR);
    gpio_set_direction(gpio_fd, GPIO_OUTPUT);
    gpio_output(gpio_fd, MCP3008_CS_GPIO_NUM, 1);

    // Initialize ADC
    adc_fd = open("/dev/adc0", O_RDWR);
    adc = &adc_desc;
    adc->channel = ADC_CHANNEL_NUM;
    adc->bits_per_sample = 8;
    adc->data_width = ADC_WIDTH_BIT_10;
    adc->data_format = ADC_FORMAT_10BIT;
    ioctl(adc_fd, ADC_SET_CHANNEL, adc);

    // Start SPI transfer
    spi = &spi_desc;
    spi->bus_num = 0;
    spi->device_addr = 0;
    spi->mode = SPI_MODE_0;
    spi->bits_per_word = 8;
    spi->max_speed_hz = 1000000;
    spi_setup(spi);

    // Start timer
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        // Read ADC value
        ioctl(adc_fd, ADC_START_CONTINUOUS, 0);
        ioctl(adc_fd, ADC_GET_RAW, &adc_value);

        // Log timestamp and ADC value
        snprintf(timestamp, sizeof(timestamp), "%.2f", (double)gettimeofday()->tv_sec);
        printf("Timestamp: %s, ADC Value: %d\n", timestamp, adc_value);

        // Wait for 1 second
        sleep(1);

        // Stop SPI transfer
        spi_stop(spi);
    }

    // Close SPI and GPIO
    close(spi_fd);
    close(gpio_fd);
    close(adc_fd);

    return 0;
}

