#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x1A

int main() {
    int rc;
    int i;
    int adc_channel = 0;
    int adc_gain = 4;
    int adc_data_rate = 128;
    int adc_samples = 16;
    int adc_conversion_result;
    int adc_current_value;
    int i2c_handle;
    int adc_gpio_pin;
    int adc_gpio_direction;
    int adc_gpio_value;
    int adc_error;
    int adc_log_file;
    int adc_log_file_fd;

    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO.\n");
        return 1;
    }

    if (i2cInit() < 0) {
        printf("Failed to initialize I2C.\n");
        return 1;
    }

    // Set up GPIO and I2C handles
    adc_gpio_pin = 2;
    adc_gpio_direction = OUT;
    gpioSetMode(adc_gpio_pin, adc_gpio_direction);

    adc_gpio_value = 0;

    // Set up I2C handle
    i2c_handle = i2cOpen(I2C_BUS_NUM, I2C_ADDR);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus.\n");
        return 1;
    }

    // Set up ADC channel and gain
    adc_channel = GPIO_PULLUP_IN;
    adc_gain = adc_gain_set(adc_channel, adc_gain);
    if (adc_gain < 0) {
        printf("Failed to set ADC gain.\n");
        return 1;
    }

    adc_data_rate = adc_data_rate_set(adc_channel, adc_data_rate);
    if (adc_data_rate < 0) {
        printf("Failed to set ADC data rate.\n");
        return 1;
    }

    adc_samples = adc_samples_set(adc_channel, adc_samples);
    if (adc_samples < 0) {
        printf("Failed to set ADC samples.\n");
        return 1;
    }

    // Set up ADC conversion result variable
    adc_conversion_result = 0;

    // Set up I2C log file
    adc_log_file = open("adc_log.txt", O_CREAT | O_TRUNC | O_WRONLY, 0644);
    if (adc_log_file < 0) {
        printf("Failed to open I2C log file.\n");
        return 1;
    }

    // Set up I2C log file descriptor
    adc_log_file_fd = fileno(adc_log_file);

    // Main loop
    while (true) {
        // Read ADC conversion result
        adc_conversion_result = adc_get_raw(adc_channel);

        // Check for ADC error
        adc_error = adc_get_error(adc_channel);
        if (adc_error) {
            printf("ADC error: %d\n", adc_error);
            continue;
        }

        // Convert ADC result to current value
        adc_current_value = adc_conversion_result * adc_gain * adc_data_rate / (2^adc_samples - 1);

        // Log current value to console
        printf("Current: %.4f A\n", adc_current_value);

        // Write log file
        if (write(adc_log_file_fd, &adc_current_value, sizeof(adc_current_value)) < 0) {
            printf("Failed to write to I2C log file.\n");
            return 1;
        }

        // Wait for 500ms
        sleep(500);
    }

    // Clean up GPIO and I2C
    gpioTerminate();
    i2cClose(i2c_handle);

    return 0;
}

