#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/mman.h>
#include <linux/spi/spi.h>

#define I2C_BUS "/dev/i2c-1"
#define MCP3008_ADDR 0x00
#define SPI0_BASE 0x3F000000

int gpio_open(int gpio_num);
void gpio_close(int gpio_num);
int spi_open(int spi_num);
void spi_close(int spi_num);
int spi_transfer(int spi_num, unsigned char *tx_data, unsigned char *rx_data, int len);

int main() {
    int gpio_num = 4; // GPIO4 (BCM)
    int mcp_channel = 0; // MCP3008 channel 0 (single-ended)
    int mcp_chip_enable = 8; // MCP3008 chip-enable CE0 (BCM)
    int spi_num = 0; // SPI0 bus

    if (!gpio_open(gpio_num)) {
        fprintf(stderr, "Failed to open GPIO\n");
        return 1;
    }

    if (!spi_open(spi_num)) {
        fprintf(stderr, "Failed to open SPI\n");
        gpio_close(gpio_num);
        return 1;
    }

    if (!mcp3008_init()) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        gpio_close(gpio_num);
        spi_close(spi_num);
        return 1;
    }

    if (!mcp3008_set_channel(mcp_channel)) {
        fprintf(stderr, "Failed to set MCP3008 channel\n");
        mcp3008_close();
        gpio_close(gpio_num);
        spi_close(spi_num);
        return 1;
    }

    if (!mcp3008_read_adc(mcp_channel)) {
        fprintf(stderr, "Failed to read ADC\n");
        mcp3008_close();
        gpio_close(gpio_num);
        spi_close(spi_num);
        return 1;
    }

    int adc_value = mcp3008_get_adc_value(mcp_channel);
    int timestamp = time(NULL);
    int is_flame_detected = (adc_value > 500) ? 1 : 0;
    float approximated_temperature = (adc_value - 100) * 0.004;

    FILE *file = fopen("flame_data.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        mcp3008_close();
        gpio_close(gpio_num);
        spi_close(spi_num);
        return 1;
    }

    fprintf(file, "%d,%d,%f\n", timestamp, is_flame_detected, approximated_temperature);

    fclose(file);

    gpio_close(gpio_num);
    spi_close(spi_num);
    mcp3008_close();

    return 0;
}

int gpio_open(int gpio_num) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO\n");
        return -1;
    }

    struct gpiochip_req req;
    memset(&req, 0, sizeof(req));
    req.cmd = GPIO_CMD_SET_OUTPUT;
    req.gpio_num = gpio_num;
    req.value = 1;

    if (ioctl(fd, GPIO_IOC_CMD, &req) < 0) {
        fprintf(stderr, "Failed to set GPIO output\n");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

void gpio_close(int gpio_num) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to close GPIO\n");
        return;
    }

    struct gpiochip_req req;
    memset(&req, 0, sizeof(req));
    req.cmd = GPIO_CMD_CLEAR_OUTPUT;
    req.gpio_num = gpio_num;

    if (ioctl(fd, GPIO_IOC_CMD, &req) < 0) {
        fprintf(stderr, "Failed to clear GPIO output\n");
        close(fd);
        return;
    }

    close(fd);
}

int spi_open(int spi_num) {
    struct spi_device *spi = spi_open(spi_num, I2C_BUS);
    if (!spi) {
        fprintf(stderr, "Failed to open SPI\n");
        return -1;
    }

    struct spi_transfer transfer[] = {
        {
            .tx_buf = (unsigned char *)&gpio_num,
            .rx_buf = NULL,
            .len = 1,
            .delay_usecs = 500,
        },
    };

    if (spi_transfer(spi, transfer, 2) < 0) {
        fprintf(stderr, "Failed to set SPI bus\n");
        spi_close(spi_num);
        return -1;
    }

    spi_close(spi_num);
    return 0;
}

void spi_close(int spi_num) {
    struct spi_device *spi = spi_open(spi_num, I2C_BUS);
    if (!spi) {
        fprintf(stderr, "Failed to close SPI\n");
        return;
    }

    spi_unregister_device(spi);
    spi_close(spi_num);
}

int spi_transfer(int spi_num, unsigned char *tx_data, unsigned char *rx_data, int len) {
    struct spi_transfer transfer[] = {
        {
            .tx_buf = tx_data,
            .rx_buf = rx_data,
            .len = len,
            .delay_usecs = 500,
        },
    };

    return spi_transfer(spi_num, transfer, 2);
}

int main() {
    int gpio_num = 4; // GPIO4 (BCM)
    int mcp_channel = 0; // MCP3008 channel 0 (single-ended)
    int mcp_chip_enable = 8; // MCP3008 chip-enable CE0 (BCM)
    int spi_num = 0; // SPI0 bus

    if (!gpio_open(gpio_num)) {
        fprintf(stderr, "Failed to open GPIO\n");
        return 1;
    }

    if (!spi_open(spi_num)) {
        fprintf(stderr, "Failed to open SPI\n");
        gpio_close(gpio_num);
        return 1;
    }

    if (!mcp3008_init()) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        gpio_close(gpio_num);
        spi_close(spi_num);
        return 1;
    }

    if (!mcp3008_set_channel(mcp_channel)) {
        fprintf(stderr, "Failed to set MCP3008 channel\n");
        mcp3008_close();
        gpio_close(gpio_num);
        spi_close(spi_num);
        return 1;
    }

    if (!mcp3008_read_adc(mcp_channel)) {
        fprintf(stderr, "Failed to read ADC\n");
        mcp3008_close();
        gpio_close(gpio_num);
        spi_close(spi_num);
        return 1;
    }

    int adc_value = mcp3008_get_adc_value(mcp_channel);
    int timestamp = time(NULL);
    int is_flame_detected = (adc_value > 500) ? 1 : 0;
    float approximated_temperature = (adc_value - 100) * 0.004;

    FILE *file = fopen("flame_data.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        mcp3008_close();
        gpio_close(gpio_num);
        spi_close(spi_num);
        return 1;
