#define TEMP_ADC_CHANNEL_GPIO_FILENAME "value"

#define CSV_FILENAME "flame_data.csv"

#define SPI_TRANSFER_SIZE 8

#define SPI_TRANSFER_TIMEOUT_MS 1000

#define MAX_ERROR_COUNT 10

int main() {
    int sensor_presence_fd, temp_adc_fd, csv_fd;
    struct spi_device *spi_device;
    struct gpio_desc *gpio_desc;
    struct gpio_chip gpio_chip;
    struct spi_msg spi_msg;
    uint8_t data[SPI_TRANSFER_SIZE];
    uint16_t temp_adc_value;
    char timestamp[50];
    int error_count = 0;
    int sensor_presence_flag = 0;
    int temperature_reading = 0;

    // Initialize SPI and GPIO
    if (spi_open(SPI_DEVICE_FILE, &spi_device) < 0) {
        fprintf(stderr, "Error: Failed to open SPI device\n");
        return 1;
    }

    if (gpio_request_from_sysfs(&gpio_desc) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO\n");
        return 1;
    }

    // Set up SPI transfer
    spi_msg.tx_buf = data;
    spi_msg.rx_buf = NULL;
    spi_msg.len = SPI_TRANSFER_SIZE;
    spi_msg.mode = SPI_MODE_0;
    spi_msg.bits_per_word = 8;
    spi_msg.max_speed_hz = SPI_MAX_SPEED_HZ;

    // Set up GPIO
    gpio_desc->base = &gpio_chip;
    gpio_desc->pin = MCP3008_CS_PIN;
    gpio_desc->flags = GPIO_OUTPUT | GPIO_INT_EDGE_FALLING;
    gpio_desc->value = 0;

    // Open CSV file
    if ((csv_fd = open(CSV_FILENAME, O_CREAT | O_WRONLY | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        return 1;
    }

    // Initialize sensor presence flag
    if (write(sensor_presence_fd, &sensor_presence_flag, sizeof(sensor_presence_flag)) < 0) {
        fprintf(stderr, "Error: Failed to write sensor presence flag\n");
        return 1;
    }

    // Initialize temperature reading
    if (read(temp_adc_fd, &temp_adc_value, sizeof(temp_adc_value)) < 0) {
        fprintf(stderr, "Error: Failed to read temperature reading\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor presence
        if (read(sensor_presence_fd, &sensor_presence_flag, sizeof(sensor_presence_flag)) < 0) {
            fprintf(stderr, "Error: Failed to read sensor presence flag\n");
            return 1;
        }

        // Read temperature
        if (read(temp_adc_fd, &temp_adc_value, sizeof(temp_adc_value)) < 0) {
            fprintf(stderr, "Error: Failed to read temperature reading\n");
            return 1;
        }

        // Log data
        timestamp[0] = '\0';
        snprintf(timestamp, sizeof(timestamp), "%s", asctime(localtime(&temp_adc_value)));
        timestamp[strlen(timestamp) - 1] = '\n';

        // Write data to CSV file
        if (write(csv_fd, timestamp, strlen(timestamp) + 1) < 0) {
            fprintf(stderr, "Error: Failed to write data to CSV file\n");
            return 1;
        }

        // Check if sensor is absent
        if (sensor_presence_flag == 0) {
            fprintf(stderr, "Error: Sensor absent\n");
            error_count++;
            if (error_count >= MAX_ERROR_COUNT) {
                fprintf(stderr, "Error: Maximum number of errors reached\n");
                return 1;
            }
            continue;
        }

        // Check if SPI transfer failed
        if (spi_transfer(spi_device, &spi_msg, 1) < 0) {
            fprintf(stderr, "Error: SPI transfer failed\n");
            error_count++;
            if (error_count >= MAX_ERROR_COUNT) {
                fprintf(stderr, "Error: Maximum number of errors reached\n");
                return 1;
            }
            continue;
        }

        // Check if temperature reading is valid
        if (temp_adc_value == 0) {
            fprintf(stderr, "Error: Invalid temperature reading\n");
            error_count++;
            if (error_count >= MAX_ERROR_COUNT) {
                fprintf(stderr, "Error: Maximum number of errors reached\n");
                return 1;
            }
            continue;
        }

        // Log temperature reading
        temperature_reading = temp_adc_value;
        snprintf(timestamp, sizeof(timestamp), "%s", asctime(localtime(&temperature_reading)));
        timestamp[strlen(timestamp) - 1] = '\n';

        // Write data to CSV file
        if (write(csv_fd, timestamp, strlen(timestamp) + 1) < 0) {
            fprintf(stderr, "Error: Failed to write data to CSV file\n");
            return 1;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    close(csv_fd);
    spi_close(spi_device);
    gpio_free(gpio_desc);

    return 0;
}

