    struct gpio_desc *gpio_desc;
    struct gpio_chip *gpio_chip;
    struct gpio_request gpio_request;
    struct gpio_event gpio_event;
    struct timeval tv;
    char *timestamp = "Timestamp";
    char *moisture1_filename = "moisture_log.csv";
    char *moisture2_filename = "moisture_log_2.csv";
    FILE *fp_log1, *fp_log2;

    // Initialize SPI and GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "Failed to initialize SPI.\n");
        return 1;
    }

    // Open SPI device
    if ((spi_dev = spi_open(MCP3008_SPI_DEVICE)) == NULL) {
        fprintf(stderr, "Failed to open SPI device.\n");
        return 1;
    }

    // Open GPIO device
    if ((gpio_cs_fd = gpio_open(MCP3008_CS_NAME, SPI_CS_FLAGS)) < 0) {
        fprintf(stderr, "Failed to open GPIO device.\n");
        return 1;
    }

    if (gpio_chip = gpio_chip_create(NULL, MCP3008_CS_GPIO, MCP3008_CS_SPEED_HZ)) {
