        return 1;
    }

    if (gpio_desc_init(gpio_desc) < 0) {
        fprintf(stderr, "Failed to initialize GPIO descriptor.\n");
        return 1;
    }

    if (gpio_desc_request_line(gpio_desc, MCP3008_CS_GPIO, MCP3008_CS_GPIO_FLAGS, 1) < 0) {
        fprintf(stderr, "Failed to request line for GPIO.\n");
        return 1;
    }

    if (gpio_chip_request(gpio_chip) < 0) {
        fprintf(stderr, "Failed to request GPIO chip.\n");
        return 1;
    }

    if (gpio_chip_request_line(gpio_chip, MCP3008_CS_GPIO, MCP3008_CS_GPIO_FLAGS, 1) < 0) {
        fprintf(stderr, "Failed to request line for GPIO.\n");
        return 1;
    }

    // Open moisture sensors
    if (open_sensors() < 0) {
        fprintf(stderr, "Failed to open moisture sensors.\n");
        return 1;
    }

    // Initialize SPI transfer
    if (spi_setup(spi_dev, MCP3008_SPI_CLK_GPIO, MCP3008_SPI_MOSI_GPIO, MCP3008_SPI_MISO_GPIO, MCP3008_SPI_CS_GPIO, SPI_CS_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to set up SPI transfer.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from sensors
        if (read_sensors() < 0) {
            fprintf(stderr, "Failed to read data from sensors.\n");
