        tv.tv_usec = 0;
        nanosleep(&tv, NULL);
    }

    // Clean up GPIO resources
    gpio_desc_release(gpio_desc);
    gpio_chip_release(gpio_chip);
    gpio_desc_release(gpio_desc);
    gpio_close(gpio_cs_fd);
    spi_close(spi_dev);
    gpio_uninit();

    return 0;
