#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x18
#define GPIO_LED 17

int main() {
    int fd, i2c_fd, gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct i2c_client *client;
    int ret;
    int pressure_kPa = 0;
    int temperature_C = 0;
    int warning_state = 0;

    // Initialize GPIO and I2C
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    i2c_fd = i2c_open(fd, I2C_CLIENT_I2C);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pin 17 as an output
    if (ioctl(gpio_fd, GPIO_SET_LEVEL, GPIO_LED) < 0) {
        perror("Failed to set GPIO LED to active-high");
        exit(EXIT_FAILURE);
    }

    // Set up I2C communication
    client = i2c_new_client_device(i2c_fd, I2C_ADDR, I2C_CLIENT_I2C);
    if (client == NULL) {
        perror("Failed to create I2C client");
        exit(EXIT_FAILURE);
    }

    // Set up I2C communication for pressure channel
    i2c_msgs[0].addr = client->addr;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 2;
    i2c_msgs[0].buf = (void *)&pressure_kPa;
    i2c_msgs[1].addr = client->addr;
    i2c_msgs[1].flags = 0;
    i2c_msgs[1].len = 2;
    i2c_msgs[1].buf = (void *)&pressure_kPa;

    // Set up I2C communication for temperature channel
    i2c_msgs[0].addr = client->addr;
    i2c_msgs[0].flags = I2C_M_RD;
    i2c_msgs[0].len = 2;
    i2c_msgs[1].addr = client->addr;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 2;
    i2c_msgs[1].buf = (void *)&temperature_C;

    // Perform I2C communication
    ret = i2c_transfer(i2c_fd, i2c_msgs, 2, NULL);
    if (ret < 0) {
        perror("Failed to perform I2C communication");
        exit(EXIT_FAILURE);
    }

    // Wait for the sensor to settle
    usleep(100000);

    while (1) {
        // Read pressure and temperature
        ret = i2c_transfer(i2c_fd, i2c_msgs, 2, NULL);
        if (ret < 0) {
            perror("Failed to read pressure and temperature");
            exit(EXIT_FAILURE);
        }

        pressure_kPa = i2c_msgs[0].buf[0] >> 4;
        temperature_C = i2c_msgs[1].buf[0] >> 4;

        // Check for sensor absence or bus errors
        if (pressure_kPa == 0 || temperature_C == 0) {
            printf("Sensor absence or bus error detected\n");
            continue;
        }

        // Check if pressure exceeds 105.0 kPa
        if (pressure_kPa > 105.0) {
            printf("Warning: Pressure exceeds 105.0 kPa\n");
            warning_state = 1;
        }

        // Print pressure and temperature to console
        printf("Pressure: %.2f kPa\n", pressure_kPa);
        printf("Temperature: %.2f °C\n", temperature_C);

        // Check warning state and LED
        if (warning_state == 1) {
            printf("Warning LED is HIGH\n");
            close(gpio_fd);
            i2c_close(client);
            exit(EXIT_SUCCESS);
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

