#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <pigpio.h>

#define MCP3208_ADDRESS 0x20
#define HIH_4602_ADDRESS 0x40

int gpio_open(int gpio_num);
void gpio_close(int gpio_num);
int gpio_read(int gpio_num);
void gpio_write(int gpio_num, int value);

int adc_open(int adc_num);
void adc_close(int adc_num);
int adc_read(int adc_num, float* value);

int main() {
    int adc_num, gpio_num;
    float value;
    char timestamp[80];
    char humidity_log_file[80];
    char* subject = "Humidity Alert";
    char* message = "Humidity level exceeded 80% threshold.";
    char* email_address = "your_email@example.com";
    char* email_password = "your_email_password";

    gpio_num = gpio_open(8);
    if (gpio_num < 0) {
        perror("Error opening GPIO8");
        exit(EXIT_FAILURE);
    }

    adc_num = adc_open(0);
    if (adc_num < 0) {
        perror("Error opening ADC");
        exit(EXIT_FAILURE);
    }

    sprintf(humidity_log_file, "humidity_log.txt");

    while (1) {
        // Read humidity and temperature values
        if (adc_read(adc_num, &value) != 0) {
            perror("Error reading ADC");
            exit(EXIT_FAILURE);
        }

        // Calculate humidity and temperature from the value
        float humidity = (value * 3.3) / 1023.0;
        float temperature = (value - 400) * 0.0048828125;

        // Append timestamp, humidity, and temperature to the log file
        sprintf(timestamp, "%s, %f, %f\n", time(NULL), humidity, temperature);
        FILE* log_file = fopen(humidity_log_file, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            exit(EXIT_FAILURE);
        }
        fprintf(log_file, "%s\n", timestamp);
        fprintf(log_file, "%f, %f\n", humidity, temperature);
        fclose(log_file);

        // Check if humidity value exceeds 80 % threshold
        if (humidity > 0.8) {
            // Send email alert
            if (sendmail(email_address, email_password, subject, message) < 0) {
                perror("Error sending email");
                exit(EXIT_FAILURE);
            }
        }

        // Wait for a short period before reading again
        sleep(1);
    }

    gpio_close(gpio_num);
    adc_close(adc_num);

    return 0;
}

int gpio_open(int gpio_num) {
    gpio_num_t gpio;
    gpio = gpio_request_from_sysfs(GPIO_DIR_IN);
    if (gpio < 0) {
        perror("Error requesting GPIO");
        exit(EXIT_FAILURE);
    }
    gpio_set_direction(gpio, GPIO_OUTPUT);
    gpio_set_value(gpio, 1);
    return gpio;
}

void gpio_close(int gpio_num) {
    gpio_release(gpio_num);
}

int gpio_read(int gpio_num) {
    gpio_value_t value;
    if (gpio_read(gpio_num, &value) != 0) {
        perror("Error reading GPIO");
        exit(EXIT_FAILURE);
    }
    return value;
}

int adc_open(int adc_num) {
    adc_channel_t channel;
    if (adc1_init() != 0) {
        perror("Error initializing ADC");
        exit(EXIT_FAILURE);
    }
    if (adc1_set_channel(adc_num, ADC1_CHANNEL_0) != 0) {
        perror("Error setting ADC channel");
        exit(EXIT_FAILURE);
    }
    channel = ADC1_CHANNEL_0;
    if (adc1_start_adc() != 0) {
        perror("Error starting ADC");
        exit(EXIT_FAILURE);
    }
    return adc_num;
}

void adc_close(int adc_num) {
    adc1_stop_adc();
    adc1_deinit();
}

int adc_read(int adc_num, float* value) {
    adc_result_t result;
    if (adc1_get_result(&result) != 0) {
        perror("Error getting ADC result");
        exit(EXIT_FAILURE);
    }
    *value = result.value;
    return 0;
}

