#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/gpio.h>

#define I2C_ADDR 0x53
#define SPI_DEVICE_NUM 0

int gpio_open(const char *filename) {
    int fd = open(filename, O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("Error opening GPIO device");
        exit(EXIT_FAILURE);
    }
    return fd;
}

void gpio_close(int fd) {
    close(fd);
}

int spi_open(const char *filename) {
    int fd = open(filename, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }
    return fd;
}

void spi_close(int fd) {
    close(fd);
}

int adxl335_init() {
    int fd = spi_open("spi0.0");
    if (fd < 0) {
        perror("Error opening SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_device *spi = &spi_devices[SPI_DEVICE_NUM];
    spi->max_speed_hz = 1000000;

    struct gpio *gpio = &gpio_devices[GPIO_DEVICE_NUM];
    gpio->open(gpio_devices[GPIO_DEVICE_NUM].filename);

    struct i2c_adapter *i2c = &i2c_adapters[I2C_ADAPTER_NUM];
    struct i2c_client *client = &i2c->clients[I2C_CLIENT_NUM];
    client->addr = I2C_ADDR;
    client->flags = I2C_CLIENT_FORCE_SLAVE;

    struct adxl335_data *data = &adxl335_data;
    data->spi = spi;
    data->gpio = gpio;
    data->i2c = i2c;

    if (adxl335_read_reg(data, ADXL335_POWER_CTL, &data->power_ctl) < 0) {
        perror("Error reading power control register");
        exit(EXIT_FAILURE);
    }

    if (adxl335_read_reg(data, ADXL335_POWER_CTL, &data->power_ctl) != 0) {
        data->power_ctl = 0;
    }

    if (adxl335_read_reg(data, ADXL335_X_GYRO_FS_R, &data->gyro_fs_r) < 0) {
        perror("Error reading X gyro FS register");
        exit(EXIT_FAILURE);
    }

    if (adxl335_read_reg(data, ADXL335_X_GYRO_FS_R, &data->gyro_fs_r) != 0) {
        data->gyro_fs_r = 0;
    }

    if (adxl335_read_reg(data, ADXL335_Y_GYRO_FS_R, &data->gyro_fs_r) < 0) {
        perror("Error reading Y gyro FS register");
        exit(EXIT_FAILURE);
    }

    if (adxl335_read_reg(data, ADXL335_Y_GYRO_FS_R, &data->gyro_fs_r) != 0) {
        data->gyro_fs_r = 0;
    }

    if (adxl335_read_reg(data, ADXL335_Z_GYRO_FS_R, &data->gyro_fs_r) < 0) {
        perror("Error reading Z gyro FS register");
        exit(EXIT_FAILURE);
    }

    if (adxl335_read_reg(data, ADXL335_Z_GYRO_FS_R, &data->gyro_fs_r) != 0) {
        data->gyro_fs_r = 0;
    }

    if (adxl335_read_reg(data, ADXL335_POWER_CTL, &data->power_ctl) < 0) {
        perror("Error reading power control register");
        exit(EXIT_FAILURE);
    }

    if (adxl335_read_reg(data, ADXL335_POWER_CTL, &data->power_ctl) != 0) {
        data->power_ctl = 0;
    }

    return 0;
}

void adxl335_read_reg(struct adxl335_data *data, uint8_t reg, uint8_t *value) {
    int result = i2c_master_write_then_read(data->i2c, data->power_ctl, 1, &data->power_ctl, 1);
    if (result < 0) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }

    result = i2c_master_write_then_read(data->i2c, reg, 1, value, 1);
    if (result < 0) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }
}

int adxl335_read_accel(struct adxl335_data *data, float *x, float *y, float *z) {
    int result = i2c_master_write_then_read(data->i2c, ADXL335_X_GYRO_FS_R, 3, x, 3);
    if (result < 0) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }

    result = i2c_master_write_then_read(data->i2c, ADXL335_Y_GYRO_FS_R, 3, y, 3);
    if (result < 0) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }

    result = i2c_master_write_then_read(data->i2c, ADXL335_Z_GYRO_FS_R, 3, z, 3);
    if (result < 0) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }

    return 0;
}

int adxl335_read_mag(struct adxl335_data *data, float *x, float *y, float *z) {
    int result = i2c_master_write_then_read(data->i2c, ADXL335_X_MAG_FS_R, 3, x, 3);
    if (result < 0) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }

    result = i2c_master_write_then_read(data->i2c, ADXL335_Y_MAG_FS_R, 3, y, 3);
    if (result < 0) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }

    result = i2c_master_write_then_read(data->i2c, ADXL335_Z_MAG_FS_R, 3, z, 3);
    if (result < 0) {
        perror("Error writing to I2C device");
        exit(EXIT_FAILURE);
    }

    return 0;
}

int adxl335_read_temperature(struct adxl335_data *data, float *temperature) {
