    error_code = gpio_init();
    if (error_code != 0) {
        log_error(1);
        return;
    }

    gpio_pin = gpio_request_pin(GPIO_OUTPUT_DIGITAL);
    if (gpio_pin == -1) {
        log_error(2);
        return;
    }

    gpio_set_direction(gpio_pin, GPIO_OUTPUT);
}

void init_gpio() {
