    // Perform temperature compensation
    voltage = (raw_adc - MCP3008_CHANNEL_0) * (1023.0 / (1023.0 - 1));
    compensated_voltage = voltage + ambient_temp * 0.1;

    // Log the result
    fprintf(flame_log_file, "%.2f,%.2f,%.2f,%.2f,%.2f\n",
            (double)time(NULL), raw_adc, compensated_voltage, ambient_temp, flame_detected);

    // Check if flame is detected
    if (compensated_voltage > 1023.0) {
        flame_detected = 1;
    }

    // Stop the sampling loop
    gpio_deinit();
    pi_set_speed(GPIO_SPEED_LOW);
    pigpio_spi_close(spi);

    // Log the end of the iteration
    fprintf(stderr_file, "End of iteration\n");

    // Check if flame is detected
    if (flame_detected) {
        // Turn buzzer ON
        gpio_set_level(18, 1);
        // Wait for the flame to be extinguished
        // ...
        // Turn buzzer OFF
        gpio_set_level(18, 0);
    }

    // Close log files
    fclose(flame_log_file);

    return 0;
}
