#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>

#include <gpiod.h>
#include <pigpio.h>

#define MCP3008_CS_GPIO_NUM 8
#define MCP3008_CLK_GPIO_NUM 10
#define MCP3008_DATA_GPIO_NUM 9

int main() {
    int fd, gpio_num, spi_fd, i;
    int chipSelect = MCP3008_CS_GPIO_NUM;
    int clkPin = MCP3008_CLK_GPIO_NUM;
    int dataPin = MCP3008_DATA_GPIO_NUM;
    int spi_bits = 3;
    int spi_speed = 1000000;

    gpio_num = gpio_get_direction(chipSelect);
    gpio_num |= GPIO_OUTPUT;
    gpio_set_direction(chipSelect, gpio_num);

    gpio_num = gpio_get_direction(clkPin);
    gpio_num |= GPIO_OUTPUT;
    gpio_set_direction(clkPin, gpio_num);

    gpio_num = gpio_get_direction(dataPin);
    gpio_num |= GPIO_INPUT;
    gpio_set_direction(dataPin, gpio_num);

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return 1;
    }

    gpio_set_mode(chipSelect, gpio_num);
    gpio_set_level(chipSelect, 1);

    spi_fd = spi_open(fd);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return 1;
    }

    struct spi_device *spi = spi_get_device(spi_fd);
    if (!spi) {
        perror("Error getting SPI device");
        return 1;
    }

    gpio_set_mode(clkPin, gpio_num);
    gpio_set_level(clkPin, 1);

    gpio_set_mode(dataPin, gpio_num);
    gpio_set_level(dataPin, 0);

    struct spi_transfer transfers[1];
    transfers[0].tx_buf = (void *)&spi->max_speed_hz;
    transfers[0].rx_buf = (void *)&spi->max_speed_hz;
    transfers[0].len = sizeof(spi->max_speed_hz);
    transfers[0].delay_usecs = 0;
    transfers[0].speed_hz = spi_speed;

    int moisture_percent = 0;
    int adc_reading = 0;

    while (1) {
        if (ioctl(fd, SPI_IOC_RD_VERB, &transfers[0]) < 0) {
            perror("Error reading SPI data");
            continue;
        }

        if (ioctl(spi_fd, SPI_IOC_RD_DMA, &adc_reading) < 0) {
            perror("Error reading ADC data");
            continue;
        }

        adc_reading = adc_reading * (1023 / (3 * 8 * 1000000));
        adc_reading = adc_reading / (1023 / 8);

        if (adc_reading > 1023) {
            adc_reading = 1023;
        }

        if (adc_reading > 50) {
            moisture_percent = 50;
        } else if (adc_reading < 50) {
            moisture_percent = (adc_reading / 10) * 50;
        }

        printf("Raw ADC Reading: %d\n", adc_reading);
        printf("Moisture Percentage: %.2f%%\n", moisture_percent);

        usleep(500000);
    }

    close(fd);
    spi_close(spi_fd);
    gpio_set_mode(chipSelect, gpio_num);
    gpio_set_level(chipSelect, 0);

    return 0;
}

