#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>
#include <pigpio.h>

#define MAX30102_ADDR 0x55
#define MAX30102_PART_ID_REG 0x00
#define MAX30102_DATA_REG 0x01

int i2c_fd;
int gpio_num;

void init_i2c()
{
    if (i2c_init() < 0) {
        fprintf(stderr, "Error initializing I2C bus\n");
        exit(EXIT_FAILURE);
    }

    if (i2c_open_device(&i2c_fd, MAX30102_ADDR, I2C_CLIENT_TOKEN) < 0) {
        fprintf(stderr, "Error opening I2C device\n");
        exit(EXIT_FAILURE);
    }

    gpio_num = pigpio_pin_allocate(GPIO_DIR_IN);
    if (gpio_num < 0) {
        fprintf(stderr, "Error allocating GPIO\n");
        exit(EXIT_FAILURE);
    }

    if (pigpio_set_mode(gpio_num, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        exit(EXIT_FAILURE);
    }

    if (pigpio_pin_write(gpio_num, 1) < 0) {
        fprintf(stderr, "Error setting GPIO output\n");
        exit(EXIT_FAILURE);
    }
}

void release_i2c()
{
    if (i2c_close(i2c_fd) < 0) {
        fprintf(stderr, "Error closing I2C device\n");
        exit(EXIT_FAILURE);
    }

    if (gpio_num != -1) {
        pigpio_pin_deallocate(gpio_num);
    }
}

void read_sensor()
{
    uint8_t data[2];
    int ret;

    ret = pigpio_i2c_read(gpio_num, MAX30102_DATA_REG, data, 2);
    if (ret < 0) {
        fprintf(stderr, "Error reading data from MAX30102 sensor\n");
        exit(EXIT_FAILURE);
    }

    if (data[0] == 0xFE) {
        fprintf(stderr, "Sensor not found\n");
        exit(EXIT_FAILURE);
    }

    if (data[1] != 0x01) {
        fprintf(stderr, "Invalid sensor response\n");
        exit(EXIT_FAILURE);
    }

    uint16_t sp02 = (data[0] << 8) | data[1];
    uint16_t heart_rate = (data[2] << 8) | data[3];

    if (sp02 < 95) {
        fprintf(stderr, "SpO2 reading below 95%\n");
    }

    if (heart_rate > 100) {
        fprintf(stderr, "Heart rate above 100 BPM\n");
    }
}

int main()
{
    init_i2c();

    while (1) {
        read_sensor();
        sleep(1);
    }

    release_i2c();
    exit(EXIT_SUCCESS);
}

