#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>
#include <linux/gpio.h>

#define MCP3008_CS_PIN 8
#define MCP3008_SPI_HANDLE -1
#define MCP3008_CHANNEL_0_ADDRESS 0x00
#define MCP3008_THRESHOLD_VALUE 500

int main() {
    int rc;
    int spi_fd;
    struct spi_device *spi_dev;
    struct gpio_desc *gpio_desc;
    struct gpio_chip gpio_chip;
    struct gpio_request gpio_request;

    // Initialize SPI and GPIO
    spi_fd = gpio_request_setup(MCP3008_CS_PIN, MCP3008_CHANNEL_0_ADDRESS, &gpio_desc);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return 1;
    }

    // Initialize MCP3008 ADC
    if (gpio_request_setup_mode(spi_fd, MCP3008_CS_PIN, MCP3008_CHANNEL_0_ADDRESS, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO\n");
        gpio_request_cleanup(spi_fd);
        return 1;
    }

    // Initialize MCP3008 ADC
    if (gpio_request_setup_level(spi_fd, MCP3008_CS_PIN, MCP3008_CHANNEL_0_ADDRESS, GPIO_PULLUP) < 0) {
        fprintf(stderr, "Failed to set up GPIO pull-up\n");
        gpio_request_cleanup(spi_fd);
        return 1;
    }

    // Initialize MCP3008 ADC
    if (gpio_request_setup_mode(spi_fd, MCP3008_CS_PIN, MCP3008_CHANNEL_0_ADDRESS, GPIO_MODE_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO input\n");
        gpio_request_cleanup(spi_fd);
        return 1;
    }

    // Set MCP3008 ADC as the system's default GPIO
    if (gpio_request_set_default(spi_fd) < 0) {
        fprintf(stderr, "Failed to set MCP3008 ADC as default GPIO\n");
        gpio_request_cleanup(spi_fd);
        return 1;
    }

    // Initialize SPI
    if (spi_open(spi_fd, 0) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpio_request_cleanup(spi_fd);
        return 1;
    }

    // Initialize MCP3008 ADC
    if (gpio_request_setup_level(spi_fd, MCP3008_CS_PIN, MCP3008_CHANNEL_0_ADDRESS, GPIO_PULLUP) < 0) {
        fprintf(stderr, "Failed to set up GPIO pull-up\n");
        spi_close(spi_fd);
        gpio_request_cleanup(spi_fd);
        return 1;
    }

    // Initialize MCP3008 ADC
    if (gpio_request_setup_mode(spi_fd, MCP3008_CS_PIN, MCP3008_CHANNEL_0_ADDRESS, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO\n");
        gpio_request_cleanup(spi_fd);
        return 1;
    }

    // Set MCP3008 ADC as the system's default GPIO
    if (gpio_request_set_default(spi_fd) < 0) {
        fprintf(stderr, "Failed to set MCP3008 ADC as default GPIO\n");
        gpio_request_cleanup(spi_fd);
        return 1;
    }

    // Set up SPI transfer parameters
    struct spi_transfer transfer[] = {
        {
            .tx_buf = (void *)&(MCP3008_CHANNEL_0_ADDRESS),
            .rx_buf = (void *)&(gpio_desc->channel[0].value),
            .len = 1,
            .delay_usecs = 10,
        },
    };

    // Set up SPI transfer parameters
    if (spi_write(spi_fd, transfer, 2) < 0) {
        fprintf(stderr, "Failed to write to SPI\n");
        gpio_request_cleanup(spi_fd);
        return 1;
    }

    // Set ADC reading threshold
    if (gpio_request_set_threshold(spi_fd, MCP3008_CS_PIN, MCP3008_CHANNEL_0_ADDRESS, MCP3008_THRESHOLD_VALUE) < 0) {
        fprintf(stderr, "Failed to set ADC threshold\n");
        gpio_request_cleanup(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = gpio_request_read(spi_fd, MCP3008_CS_PIN, MCP3008_CHANNEL_0_ADDRESS);

        // Check if ADC reading is below threshold
        if (adc_value < MCP3008_THRESHOLD_VALUE) {
            // Turn off buzzer
            gpio_request_write(spi_fd, MCP3008_CS_PIN, MCP3008_CHANNEL_0_ADDRESS, 0);
        } else {
            // Turn on buzzer
            gpio_request_write(spi_fd, MCP3008_CS_PIN, MCP3008_CHANNEL_0_ADDRESS, 1);
        }

        // Wait for 500 ms
        sleep(500);
    }

    // Clean up
    gpio_request_cleanup(spi_fd);
    return 0;
}

