Here's the complete C code that fulfills the user's request, using libgpiod for GPIO operations and pigpio for SPI communication. This code assumes that you have already initialized the SPI interface and GPIO pins correctly.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>

#define CS0 8
#define CS1 7
#define CS2 25

int main() {
    int fd, chipSelect0, chipSelect1, chipSelect2;
    struct spi_device *spi;
    struct gpiod_chip *chip;
    struct gpiod_line *cs0, *cs1, *cs2;
    struct gpiod_line *sensor0, *sensor1, *sensor2;
    struct timeval start, end;
    unsigned long start_time, end_time;
    unsigned int sensorValues[3];
    char filename[50];
    int i, j, k;

    // Initialize SPI device
    if (spi_open(0, &fd, 0, SPI_MODE_0 | SPI_CPOL_LOW | SPI_MSB_FIRST, 8, 0) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    // Initialize GPIO pins
    if (gpio_request_from_mem(CS0, 1, &chipSelect0) < 0 ||
        gpio_request_from_mem(CS1, 1, &chipSelect1) < 0 ||
        gpio_request_from_mem(CS2, 1, &chipSelect2) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        spi_close(fd);
        return 1;
    }

    if (gpio_request_from_mem(CS0, 1, &sensor0) < 0 ||
        gpio_request_from_mem(CS1, 1, &sensor1) < 0 ||
        gpio_request_from_mem(CS2, 1, &sensor2) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpio_release_from_mem(CS0);
        gpio_release_from_mem(CS1);
        gpio_release_from_mem(CS2);
        spi_close(fd);
        return 1;
    }

    // Set up SPI device
    if (spi_select(fd, 0) < 0) {
        fprintf(stderr, "Failed to select SPI device\n");
        gpio_release_from_mem(CS0);
        gpio_release_from_mem(CS1);
        gpio_release_from_mem(CS2);
        spi_close(fd);
        return 1;
    }

    // Set up GPIO lines
    if (gpio_direction_output(sensor0, 1) < 0 ||
        gpio_direction_output(sensor1, 1) < 0 ||
        gpio_direction_output(sensor2, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO lines as outputs\n");
        gpio_release_from_mem(CS0);
        gpio_release_from_mem(CS1);
        gpio_release_from_mem(CS2);
        spi_close(fd);
        return 1;
