#define RELAY_GPIO 18
#define RELAY_ACTIVE_HIGH 1

#define THRESHOLD_DEFAULT 30
#define PULSE_DURATION_DEFAULT 10
#define SLEEP_INTERVAL_DEFAULT 60

#define IRRIGATION_LOG_FILE "irrigation.log"

#define MAX_RETRIES 3

#define SPI_BUS_OPEN_FAILURE_ACTION "Failed to open SPI bus"

void log_error(const char *message) {
    char error_message[128];
    snprintf(error_message, sizeof(error_message), "%s\n%s", message, SPI_BUS_OPEN_FAILURE_ACTION);
    openlog(NULL, LOG_CONS | LOG_PERROR, LOG_MAIL);
    syslog(LOG_ERR, error_message);
    closelog();
}

int main(int argc, char *argv[]) {
    int retries = MAX_RETRIES;
    int threshold = THRESHOLD_DEFAULT;
    int pulse_duration = PULSE_DURATION_DEFAULT;
    int sleep_interval = SLEEP_INTERVAL_DEFAULT;
    int log_interval = 60;
    int log_file_fd;
    int ret;

    if (argc < 4) {
        log_error("Usage: %s [-t <threshold>] [-d <pulse_duration>] [-s <sleep_interval>] [-s <log_interval>] [-s <log_file>]\n", argv[0]);
        return 1;
    }

    if (sscanf(argv[1], "-t", &threshold) != 1) {
        log_error("Invalid option: -t\n");
        return 1;
    }

    if (sscanf(argv[2], "-d", &pulse_duration) != 1) {
        log_error("Invalid option: -d\n");
        return 1;
    }

    if (sscanf(argv[3], "-s", &sleep_interval) != 1) {
        log_error("Invalid option: -s\n");
        return 1;
    }

    if (sscanf(argv[4], "-s", &log_interval) != 1) {
        log_error("Invalid option: -s\n");
        return 1;
    }

    if (argc - 4 < 3) {
        log_error("Insufficient arguments\n");
        return 1;
    }

    if (sscanf(argv[5], "-s", &log_file_fd) != 1) {
        log_error("Invalid option: -s\n");
        return 1;
    }

    if (log_file_fd < 0) {
        log_error("Invalid log file descriptor\n");
