#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x1A // Honeywell SS49E I2C address

#define AIN_CHANNEL_AIN0
#define PGA_GAIN_4_096V

#define LED_GPIO_PIN 17
#define BCM_GPIO_PIN 17

#define THRESHOLD 100.0 // Default threshold in Gauss

int main(int argc, char *argv[]) {
    int i2c_fd;
    int gpio_fd;
    int result;
    uint16_t data;
    uint16_t threshold;
    int threshold_set = 0;
    int led_on = 0;
    int led_off = 0;
    int exit_flag = 0;

    // Initialize GPIO and I2C
    gpio_init();
    gpio_set_mode(BCM_GPIO_PIN, GPIO_OUTPUT);
    gpio_set_direction(BCM_GPIO_PIN, GPIO_MODE_OUTPUT);

    // Initialize I2C
    if (i2c_init() < 0) {
        printf("Failed to initialize I2C bus.\n");
        return 1;
    }

    // Open I2C device file
    if ((i2c_fd = i2c_open(I2C_BUS_NUM)) < 0) {
        printf("Failed to open I2C device file.\n");
        return 1;
    }

    // Set I2C address for Honeywell sensor
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        printf("Failed to set I2C address for Honeywell sensor.\n");
        return 1;
    }

    // Set threshold for magnetic field strength
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold < 0.0 || threshold > 1000.0) {
            printf("Invalid threshold value. Defaulting to 100.0 Gauss.\n");
            threshold = 100.0;
        }
        threshold_set = 1;
    }

    // Main loop
    while (!exit_flag) {
        // Read magnetic field strength from the sensor
        if (ioctl(i2c_fd, I2C_RD_RETRIES, &data) < 0) {
            printf("Failed to read magnetic field strength from the sensor.\n");
            continue;
        }

        // Check if the measured magnetic field strength exceeds the threshold
        if (data > threshold) {
            // Turn on LED
            gpio_set_value(LED_GPIO_PIN, 1);
            led_on = 1;
            // Blink the LED for 1 second
            sleep(1);
            led_off = 0;
            // Turn off LED
            gpio_set_value(LED_GPIO_PIN, 0);
            // Wait for 1 second
            sleep(1);
            // Reset LED
            gpio_set_value(LED_GPIO_PIN, led_on);
            // Wait for 1 second
            sleep(1);
        }

        // Print magnetic field strength to console
        printf("Magnetic field strength: %.2f Gauss\n", data / PGA_GAIN_4_096V);

        // Wait for 100 milliseconds
        sleep(0.1);
    }

    // Cleanup
    gpio_exit();
    i2c_exit();

    return 0;
}

