#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#include <linux/gpio.h>
#include <linux/gpio/sysfs.h>

#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>

#include <pigpio.h>

#define MCP3008_DEVICE_PATH "/dev/spidev0.0"
#define RELAY_GPIO_PIN 17

int gpio_open(const char *device_path);
void gpio_close(int gpio_fd);
int gpio_read(int gpio_fd, int *value);
void gpio_write(int gpio_fd, int value);

int i2c_open(const char *device_path);
void i2c_close(int i2c_fd);
int i2c_read(int i2c_fd, void *buf, int size);
void i2c_write(int i2c_fd, const void *buf, int size);

int main() {
    int gpio_fd, i2c_fd;
    int relays_on = 0;
    int relays_count = 0;
    int i;

    gpio_fd = gpio_open(MCP3008_DEVICE_PATH);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO device\n");
        return 1;
    }

    i2c_fd = i2c_open(MCP3008_DEVICE_PATH);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpio_close(gpio_fd);
        return 1;
    }

    gpio_write(gpio_fd, relays_on, 1); // Turn on the relay

    while (1) {
        // Read the soil moisture sensor
        int moisture_reading = read_soil_moisture_sensor();

        // Log the reading
        printf("Moisture reading: %d%%\n", (moisture_reading * 100) / 100);

        // Check if the relay should be turned on
        if (moisture_reading < 30) {
            relays_on = 1;
        } else {
            relays_on = 0;
        }

        // Log the relay state
        printf("Relay state: %d%%\n", relays_on * 100);

        // Check if the pump should be turned on
        if (relays_on == 1) {
            gpio_write(relay_gpio_pin, relays_on, 1); // Turn on the pump
        } else {
            gpio_write(relay_gpio_pin, relays_on, 0); // Turn off the pump
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Close the I2C and GPIO resources
    i2c_close(i2c_fd);
    gpio_close(gpio_fd);

    return 0;
}

int read_soil_moisture_sensor() {
    int value;
    int i;

    // Perform SPI transfer to read the sensor value
    if (spi_transfer(SPI_CHANNEL_0, 0x00, &value, 1) != 1) {
        fprintf(stderr, "Failed to read SPI transfer\n");
        return -1;
    }

    // Verify the SPI transfer
    if (value != 0x10) {
        fprintf(stderr, "Failed to read SPI transfer\n");
        return -1;
    }

    return value;
}

int spi_transfer(int channel, int data_out, void *data_in, int size) {
    int fd;
    int ret;

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &data_out);
    if (ret < 0) {
        fprintf(stderr, "Failed to send SPI data\n");
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &data_in);
    if (ret < 0) {
        fprintf(stderr, "Failed to receive SPI data\n");
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_open(const char *device_path) {
    int fd;
    int ret;

    fd = open(device_path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO device\n");
        return -1;
    }

    ret = ioctl(fd, GPIO_IOC_RD_GPIO_EDGE, GPIO_EDGE_FALLING);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return -1;
    }

    ret = ioctl(fd, GPIO_IOC_WR_GPIO_VALUE, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO value\n");
        return -1;
    }

    ret = ioctl(fd, GPIO_IOC_RD_GPIO_VALUE, &relays_on);
    if (ret < 0) {
        fprintf(stderr, "Failed to read GPIO value\n");
        return -1;
    }

    return fd;
}

void gpio_close(int gpio_fd) {
    close(gpio_fd);
}

void gpio_write(int gpio_fd, int value, int delay_ms) {
    struct gpio_request request;
    request.type = GPIO_SET_VALUE;
    request.value = value;
    request.delay_ms = delay_ms;

    if (ioctl(gpio_fd, GPIO_IOCTL_REQUEST, &request) < 0) {
        fprintf(stderr, "Failed to write GPIO value\n");
    }
}

void i2c_open(const char *device_path) {
    int fd;
    int ret;

    fd = open(device_path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return;
    }

    ret = ioctl(fd, I2C_SLAVE, MCP3008_DEVICE_PATH_ID);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return;
    }

    ret = ioctl(fd, I2C_SLAVE, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C master address\n");
        return;
    }

    ret = ioctl(fd, I2C_SLAVE, MCP3008_DEVICE_PATH_ID);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return;
    }
}

void i2c_close(int i2c_fd) {
    close(i2c_fd);
}

void i2c_read(int i2c_fd, void *buf, int size) {
    struct i2c_rdwr_ioctl_data data;
    data.flags = 0;
    data.timeout_ms = 100;
    data.nbytes = size;
    data.buf = buf;

    if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "Failed to read I2C data\n");
    }
}
