int gpio_open(const char *dev_name) {
    int fd;
    struct gpiod_info info;

    fd = gpiod_open(dev_name, 0);
    if (fd < 0) {
        perror("Failed to open gpio");
        exit(EXIT_FAILURE);
    }

    if (gpiod_get_property(fd, "label", &info.label, sizeof(info.label)) < 0) {
        perror("Failed to get label");
        exit(EXIT_FAILURE);
    }

    if (gpiod_get_property(fd, "state", &info.state, sizeof(info.state)) < 0) {
        perror("Failed to get state");
        exit(EXIT_FAILURE);
    }

    if (gpiod_get_property(fd, "direction", &info.direction, sizeof(info.direction)) < 0) {
        perror("Failed to get direction");
        exit(EXIT_FAILURE);
    }

    if (gpiod_get_property(fd, "active_low", &info.active_low, sizeof(info.active_low)) < 0) {
        perror("Failed to get active_low");
        exit(EXIT_FAILURE);
    }

    if (gpiod_get_property(fd, "value", &info.value, sizeof(info.value)) < 0) {
        perror("Failed to get value");
        exit(EXIT_FAILURE);
    }

    return fd;
}

