    struct gpiod_info info;
    int ret;

    ret = gpiod_get_property(gpio_fd, "active_low", &info.active_low, sizeof(info.active_low));
    if (ret < 0) {
        perror("Failed to get active_low");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_get_property(gpio_fd, "value", value, sizeof(*value));
    if (ret < 0) {
        perror("Failed to get value");
        exit(EXIT_FAILURE);
    }

    if (info.active_low) {
        *value = 1 - *value;
    }

    return 0;
}

