void spi_close(int spi_fd);
int spi_transfer(int spi_fd, uint8_t *tx_data, uint8_t *rx_data, int tx_len);

void soil_data_log(uint16_t value, int timestamp);

int main() {
    int gpio_fd, spi_fd;
    int retry_count = 0;
    int i;
    struct timespec start_time, end_time;
    uint16_t value;
    char filename[50];

    gpio_fd = gpio_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    spi_fd = spi_open("/dev/spide1.0");
    if (spi_fd < 0) {
        perror("Failed to open spide1.0");
        exit(EXIT_FAILURE);
    }

    gpio_set_mode(gpio_fd, GPIO_OUTPUT);
    gpio_set_mode(gpio_fd, GPIO_OUTPUT_DIGITAL);
    gpio_set_level(gpio_fd, 1);

    sprintf(filename, "soil_data.txt");
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        struct timespec start_time, end_time;
        uint16_t value;

        retry_count = 0;
        while (retry_count < 5) {
            retry_count++;
            gpio_set_level(gpio_fd, 0);
            gpio_delay(1);
            gpio_set_level(gpio_fd, 1);
            gpio_delay(1);

            value = gpio_read(gpio_fd, 0, &value);
