    }

    int adcFile = open("/dev/i2c-1", O_RDWR);
    if (adcFile < 0) {
        perror("Error opening ADC file");
        exit(EXIT_FAILURE);
    }

    struct i2c_rdwr_ioctl_data i2cData;
    memset(&i2cData, 0, sizeof(i2cData));
    i2cData.flags = 0;
    i2cData.timeout = 100;

    if (ioctl(adcFile, I2C_RDWR, MCP3008_I2C_ADDR) < 0) {
        perror("Error initializing ADC");
        exit(EXIT_FAILURE);
    }

    int adcChannel = ADC_CHANNEL;
    int adcResolution = ADC_RESOLUTION;
    int adcMinVoltage = ADC_MIN_VOLTAGE;
    int adcMaxVoltage = ADC_MAX_VOLTAGE;

    if (ioctl(adcFile, I2C_RD_RES, &adcResolution) < 0) {
        perror("Error reading ADC resolution");
        exit(EXIT_FAILURE);
    }

    if (ioctl(adcFile, I2C_RD_AVG, &adcChannel) < 0) {
        perror("Error reading ADC channel");
        exit(EXIT_FAILURE);
    }

    if (ioctl(adcFile, I2C_RD_AVG, &adcMinVoltage) < 0) {
        perror("Error reading ADC min voltage");
        exit(EXIT_FAILURE);
    }

    if (ioctl(adcFile, I2C_RD_AVG, &adcMaxVoltage) < 0) {
        perror("Error reading ADC max voltage");
        exit(EXIT_FAILURE);
    }

    int adcThreshold = (adcMaxVoltage - adcMinVoltage) / ADC_RESOLUTION;

    struct gpio_desc gpioDesc;
    memset(&gpioDesc, 0, sizeof(gpioDesc));
    gpioDesc.flags = GPIOF_IN;
    gpioDesc.dir = GPIO_OUT;
    gpioDesc.value = 0;

    int trigPin = open("/dev/pigpio", O_RDWR);
    if (trigPin < 0) {
        perror("Error opening pigpio file");
        exit(EXIT_FAILURE);
    }

