    if (echoPin < 0) {
        perror("Error opening pigpio file");
        exit(EXIT_FAILURE);
    }

    struct pigpio *pi = pigpio_init();
    if (pi == NULL) {
        perror("Error initializing pigpio");
        exit(EXIT_FAILURE);
    }

    if (pigpio_set_mode(pi, TRIG_PIN) < 0) {
        perror("Error setting trigger pin mode");
        exit(EXIT_FAILURE);
    }

    if (pigpio_set_mode(pi, ECHO_PIN) < 0) {
        perror("Error setting echo pin mode");
        exit(EXIT_FAILURE);
    }

    if (pigpio_set_mode(pi, GPIO_OUTPUT) < 0) {
        perror("Error setting trigger pin mode");
        exit(EXIT_FAILURE);
    }

    if (pigpio_set_mode(pi, GPIO_INPUT) < 0) {
        perror("Error setting echo pin mode");
        exit(EXIT_FAILURE);
    }

    if (pigpio_set_mode(pi, GPIO18) < 0) {
        perror("Error setting PWM pin mode");
        exit(EXIT_FAILURE);
    }

    if (pigpio_set_PWM_frequency(pi, PWM_FREQUENCY) < 0) {
        perror("Error setting PWM frequency");
        exit(EXIT_FAILURE);
    }

    if (pigpio_set_PWM_pulse_width(pi, PWM_PULSE_WIDTH_MIN, PWM_PULSE_WIDTH_MAX) < 0) {
        perror("Error setting PWM pulse width");
        exit(EXIT_FAILURE);
    }

    if (pigpio_set_PWM_duty_cycle(pi, 0) < 0) {
        perror("Error setting PWM duty cycle");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int distance = readUltrasonicSensor();
        int volume = readLDR();

        if (distance == -1) {
            perror("Error reading ultrasonic sensor");
            continue;
        }

        if (volume == -1) {
            perror("Error reading LDR");
            continue;
        }

        int validDistance = (distance > ADC_THRESHOLD) ? distance : ADC_THRESHOLD;
        int validVolume = (volume > ADC_THRESHOLD) ? volume : ADC_THRESHOLD;

        if (validDistance != lastDistance || validVolume != lastVolume) {
            int pwmValue = (validDistance * PWM_PULSE_WIDTH_MAX) / ADC_MAX_VOLTAGE;
            if (pigpio_set_PWM_duty_cycle(pi, pwmValue) < 0) {
                perror("Error setting PWM duty cycle");
                exit(EXIT_FAILURE);
            }

            if (pigpio_set_PWM_pulse_width(pi, pwmValue) < 0) {
                perror("Error setting PWM pulse width");
                exit(EXIT_FAILURE);
            }

            if (pigpio_set_PWM_frequency(pi, PWM_FREQUENCY) < 0) {
                perror("Error setting PWM frequency");
                exit(EXIT_FAILURE);
            }

            lastDistance = validDistance;
            lastVolume = validVolume;
        }

        usleep(1000);
    }

    pigpio_exit(pi);
    close(trigPin);
    close(echoPin);
    close(adcFile);
    close(pwmFile);

    return 0;
}

