#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <sys/spidev.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/syscall.h>

#define MCP3008_SPI_DEVICE_PATH "/dev/spidev0.0"
#define MCP3008_CS_GPIO_PIN 24
#define MCP3008_CS_BCM_NUMBER 24
#define MCP3008_SPI_MAX_CLK_MHZ 1000000

#define SPI_TRANSFER_SIZE 8

int main() {
    int fd, cs_gpio_fd, log_fd;
    struct spi_device *spi_device;
    struct gpiod_chip *chip;
    struct gpiod_line *cs_gpio_line;
    struct timespec start_time, end_time;
    uint32_t raw_adc_value;
    uint64_t timestamp_ns;
    char log_file_path[128];

    // Initialize GPIO and SPI
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "Failed to initialize SPI.\n");
        return 1;
    }

    // Open SPI device
    fd = open(MCP3008_SPI_DEVICE_PATH, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        return 1;
    }

    // Configure SPI device
    if (ioctl(fd, SPI_IOC_WR_MODE, MCP3008_SPI_MAX_CLK_MHZ) < 0) {
        fprintf(stderr, "Failed to set SPI mode.\n");
        return 1;
    }

    // Set chip select GPIO line
    cs_gpio_fd = gpio_request_line(MCP3008_CS_GPIO_PIN, MCP3008_CS_BCM_NUMBER);
    if (cs_gpio_fd < 0) {
        fprintf(stderr, "Failed to request GPIO line.\n");
        return 1;
    }

    chip = gpio_chip_request(cs_gpio_fd);
    if (chip == NULL) {
        fprintf(stderr, "Failed to request GPIO chip.\n");
        return 1;
    }

    cs_gpio_line = gpio_line_request(chip, MCP3008_CS_GPIO_PIN);
    if (cs_gpio_line == NULL) {
        fprintf(stderr, "Failed to request GPIO line.\n");
        return 1;
    }

    // Open log file
    snprintf(log_file_path, sizeof(log_file_path), "/audio_log.txt");
    log_fd = open(log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    // Initialize SPI transfer
    spi_device = spi_alloc_device();
    if (spi_device == NULL) {
        fprintf(stderr, "Failed to allocate SPI device.\n");
        return 1;
    }

    if (spi_device->max_speed_hz < MCP3008_SPI_MAX_CLK_MHZ) {
        fprintf(stderr, "SPI device maximum clock speed (%d Hz) is lower than required (%d Hz).\n", spi_device->max_speed_hz, MCP3008_SPI_MAX_CLK_MHZ);
        return 1;
    }

    spi_device->mode = SPI_MODE_0;
    spi_device->bits_per_word = 8;
    spi_device->max_transfer_size = SPI_TRANSFER_SIZE;

    if (spi_setup(spi_device) < 0) {
        fprintf(stderr, "Failed to set up SPI device.\n");
        return 1;
    }

    // Set up SPI transfer
    if (spi_transfer(spi_device, (uint8_t *)&timestamp_ns, sizeof(uint64_t), NULL, 0) < 0) {
        fprintf(stderr, "Failed to transfer data to SPI device.\n");
        return 1;
    }

    // Start ADC sampling
    if (ioctl(fd, SPI_IOC_MESSAGE_SIZE, sizeof(uint32_t)) < 0) {
        fprintf(stderr, "Failed to set SPI message size.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Sleep for 1 ms
        nanosleep(NULL, &start_time);

        // Acquire ADC reading
        raw_adc_value = read_adc_raw();

        // Write timestamp and ADC reading to log file
        if (write(log_fd, &timestamp_ns, sizeof(uint64_t)) < 0) {
            fprintf(stderr, "Failed to write to log file.\n");
            return 1;
        }

        if (write(log_fd, &raw_adc_value, sizeof(uint32_t)) < 0) {
            fprintf(stderr, "Failed to write to log file.\n");
            return 1;
        }

        // Flush log file
        if (fsync(log_fd) < 0) {
            fprintf(stderr, "Failed to sync log file.\n");
            return 1;
        }

        // Release resources
        gpio_line_release(cs_gpio_line);
        gpio_chip_release(chip);
        spi_free_device(spi_device);
        spi_device_release(spi_device);
        gpio_release_line(cs_gpio_line);
        close(log_fd);
        close(fd);
        gpio_exit();

        // Exit program
        return 0;
    }
}

