#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <pigpio.h>

#define MCP3008_DEVICE_ADDRESS 0x27
#define PWM_PIN 17

int main() {
    int fd, gpioHandle, i2cHandle;
    struct i2c_rdwr_ioctl_data i2cData;
    struct gpio_desc gpioDesc;
    struct gpio_direction_ioctl_data gpioDirection;
    struct gpio_get_level_data gpioLevel;
    struct gpio_set_level_data gpioSetLevel;
    struct timeval startTime, endTime;
    char logFilePath[128] = "watering.log";

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Open SPI device
    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open SPI device\n");
        return 1;
    }

    // Open MCP3008 ADC
    if (ioctl(fd, I2C_SLAVE, MCP3008_DEVICE_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to open MCP3008 ADC\n");
        return 1;
    }

    // Open GPIO pin
    gpioHandle = gpioOpen(17);
    if (gpioHandle < 0) {
        fprintf(stderr, "Error: Failed to open GPIO pin\n");
        return 1;
    }

    // Open I2C device
    if (ioctl(fd, I2C_SLAVE, MCP3008_DEVICE_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to open I2C device\n");
        return 1;
    }

    // Set up GPIO direction and level
    gpioDirection.gpio_num = 17;
    gpioDirection.direction = PI_OUTPUT;
    gpioSetLevel(gpioHandle, 0);

    // Set up GPIO level
    gpioLevel.gpio_num = 17;
    gpioLevel.level = 1;
    gpioSetLevel(gpioHandle, &gpioLevel);

    // Set up I2C communication
    i2cData.readWrite = PI_TRANSACTION_READ;
    i2cData.timeout = 100;
    i2cData.bytesToRead = 1;
    i2cData.bytesToWrite = 0;

    // Set up SPI communication
    gpioDirection.direction = PI_OUTPUT;
    gpioDirection.gpio_num = PWM_PIN;
    gpioDirection.output = 1;
    gpioSetLevel(PWM_PIN, 1);

    // Set up GPIO level
    gpioLevel.gpio_num = PWM_PIN;
    gpioLevel.level = 0;
    gpioSetLevel(PWM_PIN, &gpioLevel);

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read soil moisture level
        if (ioctl(fd, SPI_I2C_RDWR, i2cData) < 0) {
            fprintf(stderr, "Error: Failed to read soil moisture level\n");
            continue;
        }

        // Evaluate moisture level
        int moistureLevel = (gpioLevel.level == 1) ? 30 : 70;

        // Check if the pump should be turned on
        if (moistureLevel < 30) {
            gpioSetLevel(17, 1);
        } else {
            gpioSetLevel(17, 0);
        }

        // Log the event
        struct timeval currentTime;
        gettimeofday(&currentTime, NULL);
        char logMessage[128];
        sprintf(logMessage, "Pump turned on at %s\n", ctime(&currentTime.tv_sec));
        fprintf(logFile, "%s\n", logMessage);

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup
    gpioClose(gpioHandle);
    gpioUninitialize();
    close(fd);

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    gpioSetLevel(17, 0);
    exit(0);
}

