#define KY038_GPIO_LINE 17
#define KY038_GPIO_LINE_NAME "gpio17"
#define KY038_ALARM_GPIO_LINE 18
#define KY038_ALARM_GPIO_LINE_NAME "gpio18"

int main() {
    int fd, gpio_fd;
    struct gpiod_line_config line_config;
    struct gpiod_event_config event_config;
    struct gpiod_event event;
    int sound_level;
    int alarm_state;
    int exit_flag = 0;

    // Initialize GPIO driver
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO driver\n");
        exit(EXIT_FAILURE);
    }

    // Open GPIO line
    if ((fd = gpiod_line_request(KY038_GPIO_LINE, GPIDIO_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        exit(EXIT_FAILURE);
    }

    // Open GPIO alarm line
    if ((gpio_fd = gpiod_line_request(KY038_ALARM_GPIO_LINE, GPIDIO_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to request GPIO alarm line\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO line to BCM17 (KY-038 DO pin)
    if (gpiod_line_set_property(fd, "gpio_num", "17") < 0) {
        fprintf(stderr, "Failed to set GPIO line property\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO alarm line to BCM18 (KY-038 ALARM LED)
    if (gpiod_line_set_property(gpio_fd, "gpio_num", "18") < 0) {
        fprintf(stderr, "Failed to set GPIO alarm line property\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO line direction
    if (gpiod_line_set_direction(fd, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO line direction\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO alarm line to active
    if (gpiod_line_set_active(gpio_fd, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO alarm line active\n");
        exit(EXIT_FAILURE);
    }

    // Set KY-038 DO pin to input
    if (gpiod_line_set_property(fd, "gpio_num", "17") < 0) {
        fprintf(stderr, "Failed to set GPIO line property\n");
        exit(EXIT_FAILURE);
    }

    // Set KY-038 ALARM LED to output
    if (gpiod_line_set_property(gpio_fd, "gpio_num", "18") < 0) {
        fprintf(stderr, "Failed to set GPIO alarm line property\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO line to input
    if (gpiod_line_set_direction(fd, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO line direction\n");
        exit(EXIT_FAILURE);
    }

    // Set KY-038 DO pin to high
    if (gpiod_line_set_level(fd, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO line level\n");
        exit(EXIT_FAILURE);
    }

    // Set KY-038 ALARM LED to high
    if (gpiod_line_set_level(gpio_fd, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO alarm line level\n");
        exit(EXIT_FAILURE);
    }

    // Wait for sound event
    while (1) {
        // Read sound level
        if (gpiod_line_read(fd, &sound_level) < 0) {
            fprintf(stderr, "Failed to read sound level\n");
            exit(EXIT_FAILURE);
        }

        // Check if sound event detected
        if (sound_level == 1) {
            // Trigger alarm
            if (gpiod_line_set_level(gpio_fd, 1) < 0) {
                fprintf(stderr, "Failed to set GPIO alarm line level\n");
                exit(EXIT_FAILURE);
            }

            // Wait for 1 second
            sleep(1);

            // Turn off alarm
            if (gpiod_line_set_level(gpio_fd, 0) < 0) {
                fprintf(stderr, "Failed to set GPIO alarm line level\n");
                exit(EXIT_FAILURE);
            }
        }

        // Print sound level
        printf("Sound level: %d\n", sound_level);

        // Delay for 100 ms
        sleep(100);
    }

    // Cleanup GPIO lines
    gpiod_line_release(fd);
    gpiod_line_release(gpio_fd);

    // Release GPIO driver
    gpiod_exit();

    return 0;
}

