#include <sys/stat.h>
#include <sys/mman.h>
#include <linux/gpio.h>

#define GPIO_LINE_FILE "/dev/gpiochip0"
#define VIBRATION_SENSOR_PIN 11
#define VIBRATION_THRESHOLD_MICRO_SEC 1000000

volatile sig_atomic_t stop_flag = 0;

int main() {
    int line_fd, chip_fd;
    struct gpiod_chip_info chip_info;
    struct gpiod_event_info event_info;
    char line_path[128];
    char log_path[128];

    // Initialize GPIO and chip
    if (gpiochip_init() < 0) {
        perror("Failed to initialize GPIO chip");
        return 1;
    }

    // Get chip information
    if (gpiod_chip_info_get(VIBRATION_SENSOR_PIN, &chip_info) < 0) {
        perror("Failed to get chip info");
        return 1;
    }

    // Open GPIO line
    line_fd = open(line_path, O_RDWR);
    if (line_fd < 0) {
        perror("Failed to open GPIO line");
        return 1;
    }

    // Request the single line with the consumer label "vibration-monitor"
    if (gpiod_request_line(line_fd, VIBRATION_SENSOR_PIN, "vibration-monitor", NULL) < 0) {
        perror("Failed to request line");
        return 1;
    }

    // Configure the line for falling-edge detection
    if (gpiod_line_config_input(line_fd, VIBRATION_SENSOR_PIN, GPIO_INPUT_PULLUP) < 0) {
        perror("Failed to configure line for falling-edge detection");
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (!stop_flag) {
        // Wait for an event on the line
        if (gpiod_wait_event(line_fd, VIBRATION_SENSOR_PIN, &event_info, NULL) < 0) {
            perror("Failed to wait for event");
            continue;
        }

        // Check if the event is a falling-edge
        if (event_info.edge_type == GPIO_FALLING_EDGE) {
            // Log the event
            if (log_event(event_info.timestamp) < 0) {
                perror("Failed to log event");
                continue;
            }

            // Print the event message to stdout
            printf("Falling-edge detected at timestamp: %s\n", event_info.timestamp);

            // Shutdown the system
            system("sudo shutdown -h now");
        }
    }

    // Release the GPIO line and chip
    if (gpiod_release_line(line_fd, VIBRATION_SENSOR_PIN) < 0) {
        perror("Failed to release GPIO line");
        return 1;
    }

    if (gpiod_chip_release(chip_fd) < 0) {
        perror("Failed to release GPIO chip");
        return 1;
    }

    return 0;
}

// Signal handlers
void sigint_handler(int signum) {
    stop_flag = 1;
}

void sigterm_handler(int signum) {
    stop_flag = 1;
}

// Function to log the event to the log file
int log_event(const char* timestamp) {
    char log_message[128];
    snprintf(log_message, sizeof(log_message), "[%s] Vibration sensor detected a falling-edge at %s\n",
             get_current_time(), timestamp);
    FILE* log_file = fopen("/var/log/vibration_shutdown.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }
    fprintf(log_file, "%s", log_message);
    fclose(log_file);
    return 0;
}

