    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (!stop_flag) {
        // Wait for an event on the line
        if (gpiod_wait_event(line_fd, VIBRATION_SENSOR_PIN, &event_info, NULL) < 0) {
            perror("Failed to wait for event");
            continue;
        }

        // Check if the event is a falling-edge
        if (event_info.edge_type == GPIO_FALLING_EDGE) {
            // Log the event
            if (log_event(event_info.timestamp) < 0) {
                perror("Failed to log event");
                continue;
            }

            // Print the event message to stdout
            printf("Falling-edge detected at timestamp: %s\n", event_info.timestamp);

            // Shutdown the system
            system("sudo shutdown -h now");
        }
    }

    // Release the GPIO line and chip
    if (gpiod_release_line(line_fd, VIBRATION_SENSOR_PIN) < 0) {
        perror("Failed to release GPIO line");
        return 1;
    }

    if (gpiod_chip_release(chip_fd) < 0) {
        perror("Failed to release GPIO chip");
        return 1;
    }

    return 0;
}

// Signal handlers
void sigint_handler(int signum) {
    stop_flag = 1;
}

void sigterm_handler(int signum) {
    stop_flag = 1;
}

// Function to log the event to the log file
int log_event(const char* timestamp) {
    char log_message[128];
    snprintf(log_message, sizeof(log_message), "[%s] Vibration sensor detected a falling-edge at %s\n",
             get_current_time(), timestamp);
    FILE* log_file = fopen("/var/log/vibration_shutdown.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }
    fprintf(log_file, "%s", log_message);
    fclose(log_file);
    return 0;
}
