#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 12
#define ADC_MAX_VALUE 65535
#define ADC_MIN_VALUE 0

int main() {
    int i2c_fd, spi_fd, gpio_fd, adc_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct spi_transfer spi_data;
    uint8_t adc_data[ADC_RESOLUTION];
    char environmental_log_file[] = "environmental_log.txt";

    // Initialize GPIO, I2C, and SPI
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return 1;
    }

    // Open the ADC channel
    if (adc_open() < 0) {
        fprintf(stderr, "Failed to open ADC channel\n");
        return 1;
    }

    // Open the environmental log file
    if (open_log_file(environmental_log_file) < 0) {
        fprintf(stderr, "Failed to open environmental log file\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read the ambient light from the BH1750 sensor
        if (i2c_read_reg8(I2C_BUS, BH1750_LIGHT_LED, &i2c_data[0]) < 0) {
            fprintf(stderr, "Failed to read BH1750 light sensor\n");
            return 1;
        }
        uint16_t ambient_light = i2c_data[0];

        // Read the sound level from the MAX4466 analog microphone
        if (i2c_read_reg8(I2C_BUS, MAX4466_SOUND_ADC, &i2c_data[0]) < 0) {
            fprintf(stderr, "Failed to read MAX4466 sound sensor\n");
            return 1;
        }
        uint16_t sound_level = i2c_data[0];

        // Append the readings to the environmental log file
        if (write_log_file(environmental_log_file, "%s, Light: %d, Sound: %d\n",
                            asctime(localtime()), ambient_light, sound_level) < 0) {
            fprintf(stderr, "Failed to write to environmental log file\n");
            return 1;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up resources
    close_log_file();
    close_adc();
    close_spi();
    close_i2c();
    gpio_cleanup();
    return 0;
}

