                fprintf(stderr, "Error writing to log file\n");
                exit(EXIT_FAILURE);
            }
            // Print the alarm message
            printf("%s\n", alarm_message);
        }

        // Release the GPIO resources
        gpioReleaseLine(gpioHandle);
    }

    // Clean up resources
    gpioTerminate();

    return 0;
}

