#include <gpiod.h>
#include <pigpio.h>

#define RELAY_PIN_1 17
#define RELAY_PIN_2 22
#define RELAY_PIN_3 23
#define RELAY_PIN_4 24

int main() {
    int relays[4] = {RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4};
    int i;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO.\n");
        return 1;
    }

    // Set all relay pins to inactive (LOW)
    for (i = 0; i < 4; i++) {
        gpioSetDirection(relays[i], GPIO_IN);
    }

    // Infinite loop
    while (1) {
        // Activate relay 1 for 1 second
        gpioWrite(relays[0], GPIO_HIGH);
        sleep(1);
        gpioWrite(relays[0], GPIO_LOW);

        // Activate relay 2 for 1 second
        gpioWrite(relays[1], GPIO_HIGH);
        sleep(1);
        gpioWrite(relays[1], GPIO_LOW);

        // Activate relay 3 for 1 second
        gpioWrite(relays[2], GPIO_HIGH);
        sleep(1);
        gpioWrite(relays[2], GPIO_LOW);

        // Activate relay 4 for 1 second
        gpioWrite(relays[3], GPIO_HIGH);
        sleep(1);
        gpioWrite(relays[3], GPIO_LOW);

        // Wait for 1 second before moving to the next relay
        sleep(1);
    }

    // Deinitialize GPIO
    gpioTerminate();

    return 0;
}

