#include <gpiod.h>

#define GPIO17 BCM_GPIO_17

int main() {
    int fd;
    struct gpiod_event event;
    struct gpiod_event_attr attr;
    struct timespec start_time, end_time;
    int distance;
    char timestamp[80];
    char buffer[32];
    char *filename = "distance_log.txt";
    int retry_count = 0;

    // Initialize GPIO
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    // Open the GPIO file in append mode
    fd = open(filename, O_RDWR | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return 1;
    }

    // Set the GPIO pin as an input
    if (gpiod_set_direction(GPIO17, GPIDX_IN) < 0) {
        fprintf(stderr, "Error setting GPIO17 direction\n");
        return 1;
    }

    // Set the GPIO pin to high
    if (gpiod_set_value(GPIO17, 1) < 0) {
        fprintf(stderr, "Error setting GPIO17 value to high\n");
        return 1;
    }

    // Set up the event
    memset(&event, 0, sizeof(event));
    event.type = GPIGPIO_EVENT_RISING;
    event.attr = &attr;

    // Loop to continuously read and log the sensor data
    while (1) {
        // Wait for the event to occur
        if (gpiod_event_wait(GPIO17, &event, NULL) < 0) {
            fprintf(stderr, "Error waiting for event\n");
            continue;
        }

        // Get the distance value from the sensor
        distance = gpiod_get_value(GPIO17);

        // Format the timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&event.timestamp));

        // Print the distance value and "Feeder Activated" message
        if (distance < 200) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        // Log the distance value to the file
        if (write(STDOUT_FILENO, timestamp, strlen(timestamp)) < 0) {
            fprintf(stderr, "Error writing to distance_log.txt\n");
            retry_count++;
            if (retry_count < 3) {
                sleep(1);
            } else {
                fprintf(stderr, "Maximum retry limit reached. Exiting.\n");
                break;
            }
        }

        // Print the distance value to the console
        printf("Distance: %d\n", distance);

        // Print the timestamp
        printf("Timestamp: %s\n", timestamp);

        // Reset the GPIO pin to low
        if (gpiod_set_value(GPIO17, 0) < 0) {
            fprintf(stderr, "Error setting GPIO17 value to low\n");
            return 1;
        }

        // Reset the event
        memset(&event, 0, sizeof(event));
        event.type = GPIGPIO_EVENT_FALLING;
        event.attr = &attr;

        // Wait for the next event
        if (gpiod_event_wait(GPIO17, &event, NULL) < 0) {
            fprintf(stderr, "Error waiting for event\n");
            continue;
        }
    }

    // Clean up GPIO
    gpiod_unexport(GPIO17);
    gpiod_exit();

    return 0;
}

