#include <linux/spi/spi.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define MCP3008_I2C_ADDR 0x10
#define LED_GPIO_PIN 21

int gpio_open(const char *file);
void gpio_close(int fd);
int gpio_read(int fd, int gpio_pin);
void gpio_write(int fd, int gpio_pin, int value);

int spi_open(const char *file);
void spi_close(int fd);
int spi_transfer(int fd, const uint8_t *tx_data, uint8_t *rx_data, int num_bytes);

int adc_open(const char *file);
void adc_close(int fd);
int adc_read(int fd, int channel, uint16_t *value);

void magnetic_field_strength_to_t(int magnetic_field_strength_mT);

int main() {
    int spi_fd, adc_fd, gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_request gpio_request;
    struct adc_request adc_request;
    char magnetic_log_file[] = "magnetic_log.txt";

    if (gpio_open(gpio_fd) < 0) {
        perror("Failed to open GPIO");
        return 1;
    }

    if (spi_open(spi_fd) < 0) {
        perror("Failed to open SPI");
        goto close_gpio;
    }

    if (adc_open(magnetic_log_file) < 0) {
        perror("Failed to open ADC log file");
        goto close_spi;
    }

    if (gpio_request.direction != GPIO_OUT) {
        gpio_write(gpio_fd, GPIO_PIN_0, 0);
    }

    if (adc_request.direction != ADC_INPUT) {
        adc_request.value = 0;
    }

    if (spi_transfer(spi_fd, (uint8_t *)&i2c_data, (uint8_t *)&i2c_data + 1, 1) < 0) {
        perror("Failed to open SPI");
        goto close_adc;
    }

    if (adc_read(adc_fd, 0, &adc_request.value) < 0) {
        perror("Failed to read ADC");
        goto close_spi;
    }

    magnetic_field_strength_to_t(adc_request.value);

    if (gpio_request.value == 1) {
        gpio_write(gpio_fd, GPIO_PIN_0, 1);
    } else {
        gpio_write(gpio_fd, GPIO_PIN_0, 0);
    }

    if (spi_close(spi_fd) < 0) {
        perror("Failed to close SPI");
        goto close_adc;
    }

    if (adc_close(adc_fd) < 0) {
        perror("Failed to close ADC");
        goto close_spi;
    }

    if (gpio_close(gpio_fd) < 0) {
        perror("Failed to close GPIO");
        goto close_spi;
    }

    return 0;

close_spi:
    spi_close(spi_fd);

close_adc:
    adc_close(adc_fd);

close_gpio:
    gpio_close(gpio_fd);

    return 1;
}

int gpio_open(int *fd) {
    int ret;
    struct file *filp;
    int dev_index = 0;

    if (dev_index >= NR_OPEN_DEVICES) {
        fprintf(stderr, "Failed to open GPIO device\n");
        return -1;
    }

    filp = filp_open(NULL, O_RDWR, 0);
    if (IS_ERR(filp)) {
        return PTR_ERR(filp);
    }

    ret = gpiochip_request(dev_index, filp);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO device\n");
        goto close_filp;
    }

    *fd = filp->f_dentry->d_inode->i_rdev;
    return 0;

close_filp:
    filp_close(filp, NULL);
    return -1;
}

void gpio_close(int fd) {
    struct file *filp = filp_open(NULL, O_RDWR, 0);
    if (IS_ERR(filp)) {
        perror("Failed to close GPIO device");
        return;
    }

    gpiochip_release(filp->f_dentry->d_inode->i_rdev);
    filp_close(filp, NULL);
}

int gpio_read(int fd, int gpio_pin) {
    struct file *filp = filp_open(NULL, O_RDONLY, 0);
    if (IS_ERR(filp)) {
        perror("Failed to open GPIO file");
        return -1;
    }

    int ret = gpio_request(filp, gpio_pin, GPIO_IN);
    if (ret < 0) {
        perror("Failed to read GPIO");
        goto close_filp;
    }

    return ret;

close_filp:
    filp_close(filp, NULL);
    return -1;
}

void gpio_write(int fd, int gpio_pin, int value) {
    struct file *filp = filp_open(NULL, O_WRONLY, 0);
    if (IS_ERR(filp)) {
        perror("Failed to open GPIO file");
        return;
    }

    int ret = gpio_request(filp, gpio_pin, GPIO_OUT);
    if (ret < 0) {
        perror("Failed to write GPIO");
        goto close_filp;
    }

    ret = value ? 1 : 0;
    gpio_request(filp, gpio_pin, GPIO_LOW);
    gpio_write(filp, gpio_pin, ret);
    gpio_request(filp, gpio_pin, GPIO_HIGH);

close_filp:
    filp_close(filp, NULL);
    return;
}

