    }

    filp = filp_open(NULL, O_RDWR, 0);
    if (IS_ERR(filp)) {
        perror("Failed to open SPI file");
        return -1;
    }

    ret = spi_open_setup(filp);
    if (ret < 0) {
        perror("Failed to open SPI");
        goto close_filp;
    }

    return filp->f_dentry->d_inode->i_rdev;

close_filp:
    filp_close(filp, NULL);
    return -1;
}

