    struct file *filp = filp_open(NULL, O_RDWR, 0);
    if (IS_ERR(filp)) {
        perror("Failed to open SPI file");
        return -1;
    }

    int ret = spi_transfer(filp, tx_data, rx_data, num_bytes);
    if (ret < 0) {
        perror("Failed to transfer SPI data");
