#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <syslog.h>
#include <pigpio.h>

#define GPIO_FILE "/dev/gpiochip0"
#define PIR_PIN 17
#define DEBOUNCE_DELAY 200
#define SNAPSHOT_DIR "/home/pi/security_cam/"
#define SNAPSHOT_FILENAME_FORMAT "%d_%s.jpg"

int main(void)
{
    int fd, ret;
    struct gpiod_event event;
    char output_path[128];
    char motion_detected = 0;
    char timestamp[64];
    pid_t child_pid;
    int syslog_fd;

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }

    // Open GPIO file
    fd = open(GPIO_FILE, O_RDWR);
    if (fd < 0)
    {
        fprintf(stderr, "Error: Failed to open GPIO file\n");
        gpioTerminate();
        return 1;
    }

    // Set PIR sensor output as an input with a pull-down resistor
    ret = gpiod_set_dir(PIR_PIN, GPIO_DIR_IN);
    if (ret < 0)
    {
        fprintf(stderr, "Error: Failed to set PIR sensor as input\n");
        goto cleanup;
    }

    // Set PIR sensor as an interrupt source
    ret = gpiod_interrupt_enable(PIR_PIN);
    if (ret < 0)
    {
        fprintf(stderr, "Error: Failed to enable PIR sensor interrupt\n");
        goto cleanup;
    }

    // Set up syslog
    syslog_fd = openlog("security_cam", LOG_PID | LOG_CONS, LOG_AUTH);
    if (syslog_fd < 0)
    {
        fprintf(stderr, "Error: Failed to open syslog\n");
        goto cleanup;
    }

    // Initialize debounce delay
    debounce_delay = DEBOUNCE_DELAY;

    // Main loop
    while (1)
    {
        // Read PIR sensor output
        ret = gpiod_get_event(PIR_PIN, &event);
        if (ret < 0)
        {
            fprintf(stderr, "Error: Failed to read PIR sensor output\n");
            goto cleanup;
        }

        // Check PIR sensor state
        if (event.state == GPIO_EVENT_FALLING)
        {
            motion_detected = 1;
        }

        // Check if motion has been detected
        if (motion_detected)
        {
            // Log motion detection
            syslog(LOG_INFO, "Motion detected at %s\n", timestamp);

            // Capture a snapshot
            child_pid = fork();
            if (child_pid < 0)
            {
                fprintf(stderr, "Error: Failed to fork\n");
                goto cleanup;
            }
            else if (child_pid == 0)
            {
                // Child process
                char filename[128];
                snprintf(filename, sizeof(filename), SNAPSHOT_FILENAME_FORMAT, getpid());
                char *cmd = "libcamera-still -o /home/pi/security_cam/" SNAPSHOT_FILENAME_FORMAT;
                if (execvp(cmd, NULL) < 0)
                {
                    fprintf(stderr, "Error: Failed to execute command\n");
                    goto cleanup;
                }
                exit(0);
            }
            else
            {
                // Parent process
                close(child_pid);
                // Wait for child process to finish
                wait(NULL);
            }
        }

        // Wait for 50 ms
        usleep(50000);
    }

cleanup:
    // Cleanup
    gpioTerminate();
    close(syslog_fd);
    close(fd);
    return 0;
}

