#define FRAGMENT_SIZE (65000 / 4)

int main(int argc, char *argv[]) {
    int fd, gpio, csi_fd, i, j, k, index, fragment_index, total_fragments, payload_size;
    void *vaddr, *vaddr_frame, *vaddr_fragment;
    struct v4l2_buffer v4l2_buffer;
    struct sockaddr_in target_addr;
    char *target_ip = "192.168.1.1";
    int target_port = 1234;
    char *payload = "Hello, World!";

    if (argc != 4) {
        printf("Usage: %s <CSI library's API call> <the library's API call> <target IP> <target port>\n", argv[0]);
        return 1;
    }

    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }

    if (pigpio_init() < 0) {
        perror("pigpio_init");
        return 1;
    }

    if (gpio_open(&gpio, GPIO_OUTPUT) < 0) {
        perror("gpio_open");
        return 1;
    }

    if (pigpio_open(&csi_fd, PI_OPEN_RW, GPIO_UNUSED) < 0) {
        perror("pigpio_open");
        return 1;
    }

    if (pigpio_set_mode(csi_fd, PI_MODE_CSII) < 0) {
        perror("pigpio_set_mode");
        return 1;
    }

    if (pigpio_set_format(csi_fd, PI_FMT_YUYV) < 0) {
        perror("pigpio_set_format");
        return 1;
    }

    if (pigpio_open_output(csi_fd, &fd) < 0) {
        perror("pigpio_open_output");
        return 1;
    }

    if (pigpio_set_resolution(fd, PI_RES_720P) < 0) {
        perror("pigpio_set_resolution");
        return 1;
    }

    if (pigpio_set_mem(fd, &vaddr, CSI_BUFFER_SIZE, PI_MEM_TYPE_CONTIG) < 0) {
        perror("pigpio_set_mem");
        return 1;
    }

    if (pigpio_mem_alloc(fd, CSI_BUFFER_SIZE, &vaddr_frame) < 0) {
        perror("pigpio_mem_alloc");
        return 1;
    }

    if (pigpio_mem_alloc(fd, FRAME_SIZE, &vaddr) < 0) {
        perror("pigpio_mem_alloc");
        return 1;
    }

    if (pigpio_mem_alloc(fd, FRAGMENT_SIZE * 4, &vaddr_fragment) < 0) {
        perror("pigpio_mem_alloc");
        return 1;
    }

    if (pigpio_mem_copy(vaddr_frame, vaddr, CSI_BUFFER_SIZE) < 0) {
        perror("pigpio_mem_copy");
        return 1;
    }

    if (pigpio_mem_copy(vaddr_fragment, vaddr, FRAME_SIZE) < 0) {
        perror("pigpio_mem_copy");
        return 1;
    }

    index = 0;
    fragment_index = 0;
    total_fragments = 4;

    while (1) {
        if (pigpio_ioctl(csi_fd, PI_CSI_WAIT_EVENT, &v4l2_buffer) < 0) {
            perror("pigpio_ioctl");
            return 1;
        }

        if (v4l2_buffer.type != V4L2_BUF_TYPE_VIDEO_CAPTURE) {
            continue;
        }

        if (v4l2_buffer.index != index) {
            continue;
        }

        if (v4l2_buffer.type == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
            for (j = 0; j < FRAME_SIZE / 2; j++) {
                if (pigpio_mem_copy(vaddr_fragment + j * 2, vaddr_frame + j * 2, FRAGMENT_SIZE) < 0) {
                    perror("pigpio_mem_copy");
                    return 1;
                }
            }

            payload_size = strlen(payload);
            if (payload_size > FRAGMENT_SIZE) {
                payload_size = FRAGMENT_SIZE;
            }

            if (pigpio_mem_copy(vaddr_fragment + payload_size, vaddr_frame + payload_size, payload_size) < 0) {
                perror("pigpio_mem_copy");
                return 1;
            }

            printf("Sending frame %d to %s:%d\n", index, target_ip, target_port);
            if (sendto(target_port, vaddr_fragment, payload_size, 0, (struct sockaddr *)&target_addr, sizeof(target_addr)) < 0) {
                perror("sendto");
                return 1;
            }

            index++;
            fragment_index++;
            total_fragments--;
            if (total_fragments == 0) {
                printf("Sending the last frame\n");
                if (sendto(target_port, vaddr_fragment, payload_size, 0, (struct sockaddr *)&target_addr, sizeof(target_addr)) < 0) {
                    perror("sendto");
                    return 1;
                }
                index = 0;
                fragment_index = 0;
                total_fragments = 4;
            }
        }

        if (pigpio_ioctl(csi_fd, PI_CSI_WAIT_EVENT, &v4l2_buffer) < 0) {
            perror("pigpio_ioctl");
            return 1;
        }
    }

    pigpio_close(csi_fd);
    gpio_close(gpio);
    pigpio_exit();

    return 0;
