                exit(EXIT_FAILURE);
            }

            uint8_t* frame = gpio_mem_map(device_id, (void**)&buf.m.mmap, &buf_size);
            if (!frame) {
                perror("Error mapping video buffer");
                exit(EXIT_FAILURE);
            }

            convert_frame_to_rgb24(frame, rgb_frame);

            apply_blur_filter(rgb_frame, kernel_size);

            encode_jpeg(rgb_frame, width, height, quality);

            gpio_mem_unmap(frame);
        }

        if (FD_ISSET(fd, &(struct pollfd){.fd = fd, .events = POLLOUT})) {
            ret = ioctl(fd, VIDIOC_STREAMOFF, &buf);
            if (ret < 0) {
                perror("Error offloading video buffer");
                exit(EXIT_FAILURE);
            }
        }
    }

    gpio_close(device_id);

    return 0;
}

