#define VIDEO_DEVICE_NODE "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_querycap qcap;
    struct v4l2_frmsizeenum enum_fsize;
    struct v4l2_queryframeinterval enum_fint;
    int focus_supported = 0;

    // Initialize GPIO and PWM
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetSpeed(GPIO_SPEED_HIGH) < 0) {
        fprintf(stderr, "Failed to set GPIO speed to high\n");
        return 1;
    }

    if (gpioSetMode(GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode to output\n");
        return 1;
    }

    // Open the CSI camera device node
    if ((fd = open(VIDEO_DEVICE_NODE, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open camera device node\n");
        return 1;
    }

    // Check if the device node exists
    if (fd < 0) {
        fprintf(stderr, "Camera device node does not exist\n");
        return 1;
    }

    // Query the device capabilities
    memset(&cap, 0, sizeof(cap));
    cap.capabilities = V4L2_CAP_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Failed to query device capabilities\n");
        return 1;
    }

    // Check if the device supports frame-size and interval enumeration
    if ((cap.capabilities & V4L2_CAP_FRAMESIZE) == 0 ||
        (cap.capabilities & V4L2_CAP_STREAMON) == 0) {
        fprintf(stderr, "Camera does not support frame-size or interval enumeration\n");
        return 1;
    }

    // Query the V4L2_CID_FOCUS_AUTO control
    memset(&qcap, 0, sizeof(qcap));
    qcap.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &qcap) < 0) {
        fprintf(stderr, "Failed to query focus control\n");
        return 1;
    }

    // Check if the focus control is present
    if (qcap.flags & V4L2_CTRL_FLAG_PRESENT) {
        focus_supported = 1;
    }

    // Close the device node
    close(fd);

    // Print the summary
    printf("Camera device node: %s\n", VIDEO_DEVICE_NODE);
    printf("Camera supports frame-size and interval enumeration: %s\n", (focus_supported ? "Yes" : "No"));
    printf("Camera supports autofocus: %s\n", (focus_supported ? "Yes" : "No"));
    printf("Supported frame sizes: ");
    for (int i = 0; i < V4L2_FRMSIZE_MAX; i++) {
        if (qcap.fmtcap[i].bytes > 0) {
            printf("%s ", v4l2_fmtcap_get(i));
        }
    }
    printf("\n");

    return 0;
}

