    struct v4l2_stream_id stream_id;
    struct v4l2_stream_parm stream_parm;
    struct v4l2_format format;
    struct v4l2_mmap_parm mmap_parm;
    struct v4l2_rect32 crop_rect;
    char *filename = "cropped.yuv";

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("Error initializing GPIO");
        exit(EXIT_FAILURE);
    }

    // Initialize PWM
    if (gpioSetPwmFrequency(100) < 0) {
        perror("Error setting PWM frequency");
        exit(EXIT_FAILURE);
    }

    // Open the USB UVC camera
    camera_fd = pigpio_open_video_device("/dev/video0");
    if (camera_fd < 0) {
        perror("Error opening camera device");
        exit(EXIT_FAILURE);
    }

    // Query the camera device
    if (pigpio_query_device(camera_fd, &cap_capability, &stream_id, &stream_parm) < 0) {
        perror("Error querying device");
        exit(EXIT_FAILURE);
    }

    // Check if the camera is V4L2 compliant
    if (cap_capability.capabilities != V4L2_CAP_VIDEO_CAPTURE) {
        perror("Error: Camera is not V4L2 compliant");
        exit(EXIT_FAILURE);
    }

    // Configure the capture
    if (pigpio_set_format(camera_fd, V4L2_PIX_FMT_YUYV, V4L2_FIELD_NONE, &stream_parm) < 0) {
        perror("Error configuring capture format");
        exit(EXIT_FAILURE);
    }

    // Request a single memory-mapped buffer
    if (pigpio_mmap_buffer(camera_fd, &mmap_parm, &format, &mmap_fd) < 0) {
        perror("Error requesting memory-mapped buffer");
        exit(EXIT_FAILURE);
    }

    // Start streaming
    if (pigpio_start_streaming(camera_fd, &mmap_parm) < 0) {
        perror("Error starting streaming");
        exit(EXIT_FAILURE);
    }

    // Wait for a frame
    struct timespec start_time, stop_time;
    start_time.tv_sec = 0;
    start_time.tv_nsec = 1000000000;
    stop_time.tv_sec = 0;
    stop_time.tv_nsec = 1000000000;

    while (1) {
        if (pigpio_wait_for_event(camera_fd, &stop_time, mmap_fd, &stop_time) < 0) {
            perror("Error waiting for event");
            exit(EXIT_FAILURE);
        }

        // Check if a frame has been captured
        if (pigpio_get_frame_count(camera_fd) > 0) {
            break;
        }
    }

    // Check if the returned width, height, and pixel format match the requested values
    if (pigpio_get_frame_width(camera_fd) != format.width ||
        pigpio_get_frame_height(camera_fd) != format.height ||
        pigpio_get_frame_bytes_per_line(camera_fd) != format.bytes_per_line) {
        perror("Error: Frame dimensions or format do not match requested values");
        exit(EXIT_FAILURE);
    }

    // Copy the complete YUYV macroblocks (Y0, U, Y1, V) to avoid color corruption
    // ...

    // Crop the region of interest (200x150)
    crop_rect.x = 0;
    crop_rect.y = 0;
    crop_rect.width = 200;
    crop_rect.height = 150;

    // Write the cropped YUYV macroblocks to a file
    if (pigpio_mmap_buffer(camera_fd, &mmap_parm, &format, &mmap_fd) < 0) {
        perror("Error writing to file");
        exit(EXIT_FAILURE);
    }

    if (pigpio_write(filename, mmap_fd, format.bytes_per_line, mmap_fd, &crop_rect, &mmap_parm) < 0) {
        perror("Error writing to file");
        exit(EXIT_FAILURE);
    }

    // Unmap the buffer
    if (pigpio_munmap(mmap_fd, &mmap_parm) < 0) {
        perror("Error unmapping buffer");
        exit(EXIT_FAILURE);
    }

    // Close the file descriptor
    if (pigpio_close(filename) < 0) {
        perror("Error closing file");
        exit(EXIT_FAILURE);
    }

    // Free allocated memory
    pigpio_free(mmap_fd);
    pigpio_close(camera_fd);
    pigpio_unexport();

    return 0;
}

