#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#include <wiringPiI2C.h>

#define I2C_BUS_NUM 1
#define OLED_ADDRESS 0x3C

// Function prototypes
void init_gpio(int);
void init_i2c(int);
void init_oled(int);
void update_cpu_temperature(int);
void update_cpu_usage(int);
void render_text(int, int, const char*);

int main() {
    int fd, i2c_fd, oled_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct wiringPiI2C_struct wiringPiI2C;
    uint8_t buffer[2];
    char error_string[32];

    // Initialize GPIO
    init_gpio(1);

    // Initialize I2C
    init_i2c(1);

    // Initialize OLED
    init_oled(1);

    while (1) {
        // Read CPU temperature
        if (read_temperature() < 0) {
            fprintf(stderr, "Error reading CPU temperature\n");
            exit(EXIT_FAILURE);
        }

        // Read CPU usage
        if (read_cpu_usage() < 0) {
            fprintf(stderr, "Error reading CPU usage\n");
            exit(EXIT_FAILURE);
        }

        // Render text on OLED
        render_text(1, 0, "CPU Temperature: " + sprintf("%0.2f", get_temperature()) + "°C");
        render_text(1, 24, "CPU Usage: " + sprintf("%0.2f", get_cpu_usage()) + "%");

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

void init_gpio(int gpio_num) {
    if (gpio_num >= 0 && gpio_num <= 29) {
        if (gpio_init(gpio_num) < 0) {
            fprintf(stderr, "Error initializing GPIO %d\n", gpio_num);
            exit(EXIT_FAILURE);
        }
    }
}

void init_i2c(int i2c_bus_num) {
    if (i2c_init(i2c_bus_num) < 0) {
        fprintf(stderr, "Error initializing I2C bus %d\n", i2c_bus_num);
        exit(EXIT_FAILURE);
    }
}

void init_oled(int i2c_bus_num) {
    if (i2c_init_oled(i2c_bus_num, OLED_ADDRESS) < 0) {
        fprintf(stderr, "Error initializing OLED display\n");
        exit(EXIT_FAILURE);
    }
}

void update_temperature() {
    // Read temperature from sensor
    int temperature = read_temperature();

    if (temperature < 0) {
        fprintf(stderr, "Error reading temperature\n");
        exit(EXIT_FAILURE);
    }

    // Update temperature value
    sprintf(temperature_str, "%0.2f", temperature);
}

void update_cpu_usage() {
    // Read CPU usage from /proc/stat
    int cpu_usage = read_cpu_usage();

    if (cpu_usage < 0) {
        fprintf(stderr, "Error reading CPU usage\n");
        exit(EXIT_FAILURE);
    }

    // Update CPU usage value
    sprintf(cpu_usage_str, "%0.2f", cpu_usage);
}

void render_text(int x, int y, const char* text) {
    // Render text on OLED
    if (oled_init() < 0) {
        fprintf(stderr, "Error initializing OLED display\n");
        exit(EXIT_FAILURE);
    }

    if (oled_string(x, y, text) < 0) {
        fprintf(stderr, "Error rendering text on OLED\n");
        exit(EXIT_FAILURE);
    }

    oled_display();
}

int read_temperature() {
