#define HD44780_ADDRESS 0x3F

int main() {
    int rc;
    int flow_rate = 0;
    int total_volume = 0;
    int last_update_time = 0;
    int i2c_fd;
    int lcd_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpiod_event gpiod_event;
    struct pigpio *pi;

    // Initialize GPIO and I2C
    pi = pigpio_init();
    if (pi == NULL) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    rc = pigpio_set_mode(17, PI_OUT);
    if (rc < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as output.\n");
        return 1;
    }

    rc = pigpio_set_mode(1, PI_IN);
    if (rc < 0) {
        fprintf(stderr, "Failed to set I2C as input.\n");
        return 1;
    }

    rc = pigpio_open_i2c(&i2c_fd, 1, YF_S201_ADDRESS);
    if (rc < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        return 1;
    }

    rc = pigpio_read_i2c(i2c_fd, &i2c_data, 1, 1);
    if (rc < 0) {
        fprintf(stderr, "Failed to read from YF-S201 sensor.\n");
        return 1;
    }

    if (i2c_data.w1 == YF_S201_DATA_READY) {
        flow_rate = pigpio_get_gpio_level(17);
        total_volume += flow_rate;
        last_update_time = time(NULL);
    }

