    printf("Total Volume: %d\n", total_volume);

    // Update LCD
    lcd_fd = pigpio_open_i2c(1, HD44780_ADDRESS);
    if (lcd_fd < 0) {
        fprintf(stderr, "Failed to open HD44780 LCD.\n");
        return 1;
    }

    rc = pigpio_write_i2c(lcd_fd, 0x00, 1, &i2c_data, 1);
    if (rc < 0) {
        fprintf(stderr, "Failed to write to HD44780 LCD.\n");
        return 1;
    }

    rc = pigpio_write_i2c(lcd_fd, 0x01, 1, &i2c_data, 1);
    if (rc < 0) {
        fprintf(stderr, "Failed to write to HD44780 LCD.\n");
        return 1;
    }

    // Handle SIGINT and SIGTERM signals
    signal(SIGINT, graceful_shutdown);
    signal(SIGTERM, graceful_shutdown);

    // Main loop
    while (1) {
        // Sleep for 1 second
        sleep(1);

        // Check if it's time to update flow rate and total volume
        if (time(NULL) - last_update_time >= 10) {
            last_update_time = time(NULL);
            flow_rate = 0;
            total_volume = 0;

            // Read data from YF-S201 sensor
            rc = pigpio_get_gpio_level(17);
            if (rc < 0) {
                fprintf(stderr, "Failed to read from YF-S201 sensor.\n");
                continue;
            }

            flow_rate = rc;
            total_volume += flow_rate;
        }

        // Update LCD
        rc = pigpio_write_i2c(lcd_fd, 0x01, 1, &i2c_data, 1);
        if (rc < 0) {
            fprintf(stderr, "Failed to write to HD44780 LCD.\n");
            return 1;
        }

        // Log current flow rate and total volume
        printf("Current Flow Rate: %d\n", flow_rate);
        printf("Total Volume: %d\n", total_volume);
    }

    // Clean up
    pigpio_close(pi);
    pigpio_unexport(pi);
    pigpio_release(pi);

    return 0;
}

// Graceful shutdown function
void graceful_shutdown(int signum) {
    printf("Shutting down...\n");
    // Release GPIO and I2C resources
    pigpio_unexport(pi);
    pigpio_release(pi);
    gpio_close(pi);
}

