#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spi.h>

#include "libgpiod.h"
#include "pigpio.h"
#include "pcf8574.h"

#define ADC_CHANNEL_0 0
#define ADC_RESOLUTION 12
#define ADC_MAX_VALUE (1 << ADC_RESOLUTION) - 1

int main() {
    int gpio_fd, adc_fd, i2c_fd, spi_fd;
    struct gpiod_event event;
    struct gpiod_event_attr attr;
    struct i2c_msg i2c_msgs[2];
    struct spi_msg spi_msgs[2];
    struct pcf8574_config config;
    struct pcf8574_data data;
    uint16_t adc_value, adc_sample_rate;
    uint16_t wind_speed, wind_direction;
    char lcd_buffer[16];
    char lcd_message[20];
    int rc;

    // Initialize GPIO, SPI, and I2C
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "Failed to initialize SPI.\n");
        return 1;
    }

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        return 1;
    }

    // Set up GPIO 17 as an interrupt on rising edge
    if (gpio_direction_input(17) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as input.\n");
        return 1;
    }

    if (gpio_interrupt_mode_set(17, GPIO_INT_EDGE_RISING) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 to interrupt mode.\n");
        return 1;
    }

    // Set up ADC channel 0 for reading
    if (adc_channel_config_set(ADC_CHANNEL_0, ADC_RESOLUTION) < 0) {
        fprintf(stderr, "Failed to configure ADC channel 0.\n");
        return 1;
    }

    // Set up MCP3008 ADC
    if (pcf8574_init(&config) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008 ADC.\n");
        return 1;
    }

    if (pcf8574_config_channel_set(&config, ADC_CHANNEL_0, ADC_MAX_VALUE / ADC_RESOLUTION) < 0) {
        fprintf(stderr, "Failed to set MCP3008 ADC channel 0 to ADC_MAX_VALUE / ADC_RESOLUTION.\n");
        return 1;
    }

    // Set up LCD
    if (lcd_init() < 0) {
        fprintf(stderr, "Failed to initialize LCD.\n");
        return 1;
    }

    // Set up SPI
    if (spi_setup(&spi_msgs[0], &spi_msgs[1], &spi_msgs[2], SPI_MODE_0, SPI_CPOL_LOW, 8, 0) < 0) {
        fprintf(stderr, "Failed to set up SPI.\n");
        return 1;
    }

    // Set up I2C
    if (i2c_setup(&i2c_msgs[0], &i2c_msgs[1], &i2c_msgs[2]) < 0) {
        fprintf(stderr, "Failed to set up I2C.\n");
        return 1;
    }

    // Set up MCP3008 ADC
    if (pcf8574_config_channel_set(&config, ADC_CHANNEL_0, ADC_MAX_VALUE / ADC_RESOLUTION) < 0) {
        fprintf(stderr, "Failed to set MCP3008 ADC channel 0 to ADC_MAX_VALUE / ADC_RESOLUTION.\n");
        return 1;
    }

    // Set up I2C and SPI bit-bang helpers
    if (i2c_bit_bang_setup(&i2c_fd, &config) < 0) {
        fprintf(stderr, "Failed to set up I2C bit-bang.\n");
        return 1;
    }

    if (spi_bit_bang_setup(&spi_fd, &spi_msgs[0], &spi_msgs[1], &spi_msgs[2]) < 0) {
        fprintf(stderr, "Failed to set up SPI bit-bang.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        adc_value = pcf8574_read_adc_value(&data);

        // Read wind speed and direction from MCP3008 ADC
        adc_sample_rate = ADC_MAX_VALUE / ADC_RESOLUTION;
        adc_value = pcf8574_read_adc_value(&data);
        wind_speed = adc_value * adc_sample_rate / ADC_MAX_VALUE;
        adc_value = pcf8574_read_adc_value(&data);
        adc_value = adc_value * adc_sample_rate / ADC_MAX_VALUE;
        adc_value = adc_value * adc_sample_rate / ADC_MAX_VALUE;
        adc_value = adc_value * adc_sample_rate / ADC_MAX_VALUE;
        adc_value = adc_value * adc_sample_rate / ADC_MAX_VALUE;

        // Update LCD with wind speed and direction
        sprintf(lcd_buffer, "Wind Speed: %.2f m/s", wind_speed);
        sprintf(lcd_message, "Wind Direction: %d", adc_value);
        lcd_update(&lcd_buffer, &lcd_message, 16, 2);

        // Check for sensor absence conditions
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "ADC reading stuck at 0 or 1023. Sensor absent.\n");
            continue;
        }

        // Check for I2C and SPI errors
        if (i2c_error() || spi_error()) {
            fprintf(stderr, "I2C or SPI error.\n");
            continue;
        }

        // Handle interrupts
        if (gpio_interrupt_enable(17) < 0) {
            fprintf(stderr, "Failed to enable GPIO 17 interrupt.\n");
            return 1;
        }

        if (gpio_interrupt_clear(17) < 0) {
            fprintf(stderr, "Failed to clear GPIO 17 interrupt.\n");
            return 1;
        }

        // Check for SIGINT and SIGTERM
        if (sigismember(signal(SIGINT), SIGINT) || sigismember(signal(SIGTERM), SIGTERM)) {
            fprintf(stderr, "Received SIGINT or SIGTERM. Shutting down...\n");
            gpio_interrupt_disable(17);
            gpio_interrupt_uninstall(17);
            gpio_cleanup();
            return 0;
        }

        // Perform graceful shutdown
        usleep(500000);
    }

    return 0;
}

