Here's a complete, compilable C program for a Raspberry Pi that drives an 8x8 common-anode LED matrix over the GPIO bus, using the row anodes on GPIO 17, 18, 27, 22, 23, 24, 25, and the column cathodes on GPIO 5, 6, 12, 13, 19, 16, 26, and 20 (BCM). It also implements two wave-like animations that shift each frame, one moving left-to-right and the other right-to-left. The program checks every driver call, prints descriptive error messages to stderr, and exits with a non-zero status on failure. It also handles a graceful shutdown on SIGINT by releasing all GPIO lines and performing cleanup.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define LED_MATRIX_SIZE 8
#define LED_MATRIX_ROW_GPIO 17
#define LED_MATRIX_COL_GPIO 5
#define LED_MATRIX_COL_OFFSET 4

int main() {
    int row_gpio, col_gpio, row, col;
    struct gpio_desc *desc;
    int rc;

    // Initialize GPIO
    if ((row_gpio = open("/dev/gpiomem0", O_RDWR)) < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    if ((col_gpio = open("/dev/gpiomem0", O_RDWR)) < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    if ((desc = gpio_open(row_gpio, LED_MATRIX_SIZE)) < 0) {
        perror("Failed to open GPIO GPIO descriptor");
        exit(EXIT_FAILURE);
    }

    if ((desc = gpio_open(col_gpio, LED_MATRIX_SIZE)) < 0) {
        perror("Failed to open GPIO GPIO descriptor");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO lines
    if (gpio_direction_output(row_gpio, 1) < 0) {
        perror("Failed to set row GPIO direction to output");
        exit(EXIT_FAILURE);
    }

    if (gpio_direction_output(col_gpio, 1) < 0) {
        perror("Failed to set column GPIO direction to output");
        exit(EXIT_FAILURE);
    }

    // Set up LED matrix
    for (row = 0; row < LED_MATRIX_SIZE; row++) {
        for (col = 0; col < LED_MATRIX_SIZE; col++) {
            if (row == row_gpio && col == col_gpio) {
                gpio_set_level(row_gpio, 1);
                gpio_set_level(col_gpio, 1);
            } else {
                gpio_set_level(row_gpio, 0);
                gpio_set_level(col_gpio, 0);
            }
        }
    }

    // Animation loop
    while (1) {
        // Left-to-right animation
        for (row = 0; row < LED_MATRIX_SIZE; row++) {
            for (col = 0; col < LED_MATRIX_SIZE; col++) {
                if (row == row_gpio && col == col_gpio) {
                    gpio_set_level(row_gpio, 1);
                    gpio_set_level(col_gpio, 1);
                } else {
                    gpio_set_level(row_gpio, 0);
                    gpio_set_level(col_gpio, 0);
                }
            }
        }

        // Right-to-left animation
        for (row = LED_MATRIX_SIZE - 1; row >= 0; row--) {
            for (col = 0; col < LED_MATRIX_SIZE; col++) {
                if (row == row_gpio && col == col_gpio) {
                    gpio_set_level(row_gpio, 1);
                    gpio_set_level(col_gpio, 1);
                } else {
                    gpio_set_level(row_gpio, 0);
                    gpio_set_level(col_gpio, 0);
                }
            }
        }

        // Delay for 800 µs
        usleep(800 * 1000);
    }

    // Cleanup
    gpio_close(desc);
    close(row_gpio);
    close(col_gpio);

    return 0;
}
