    // Initialize I2C bus and GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpio_request_from_fd(STDOUT_FILENO, &gpio_fd) < 0) {
        fprintf(stderr, "Failed to request GPIO\n");
        gpio_exit();
        return 1;
    }

    // Initialize I2C bus
    if (gpio_i2c_init(I2C_BUS_NUM, I2C_SLAVE_ADDR, &param) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        gpio_exit();
        return 1;
    }

