        exit(EXIT_FAILURE);
    }

    if (gpioSetBitMode(GPIO_I2C, GPIO_PIN_4, GPIO_MODE_OUTPUT_PP) < 0) {
        fprintf(stderr, "Error: Failed to set I2C output mode.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetBitValue(GPIO_I2C, GPIO_PIN_4, 1) < 0) {
