#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/ioctl.h>

#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x29

int main() {
    int i2c_fd, gpio_fd, result_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_request gpio_request;
    struct timeval timeout;
    char distance_log_file[] = "distance_log.txt";
    char timestamp[20];
    char distance_mm[10];
    int sensor_absent = 0;
    int measurement_success = 0;
    int measurement_count = 0;

    // Initialize I2C and GPIO
    if (i2c_init() != 0) {
        fprintf(stderr, "Failed to initialize I2C bus.\n");
        return 1;
    }

    if (gpio_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    // Open I2C file descriptor
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        fprintf(stderr, "Failed to open I2C device file.\n");
        return 1;
    }

    // Open GPIO file descriptor
    if ((gpio_fd = open("/sys/class/gpio/gpio17/gpio/value", O_WRONLY)) == -1) {
        fprintf(stderr, "Failed to open GPIO file.\n");
        return 1;
    }

    // Set falling-edge trigger input on GPIO 17 with a pull-up resistor
    if (gpio_set_edge_detect(gpio_fd, GPIO_FALLING_EDGE) != 0) {
        fprintf(stderr, "Failed to set falling-edge trigger input.\n");
        return 1;
    }

    if (gpio_set_pull_up_en(gpio_fd, 1) != 0) {
        fprintf(stderr, "Failed to enable pull-up resistor.\n");
        return 1;
    }

    // Wait for sensor presence
    if (i2c_wait_for_sensor_absent(i2c_fd) != 0) {
        fprintf(stderr, "Failed to wait for sensor presence.\n");
        return 1;
    }

    // Wait for falling edge
    if (gpio_wait_for_edge(gpio_fd, GPIO_FALLING_EDGE) != 0) {
        fprintf(stderr, "Failed to wait for falling edge.\n");
        return 1;
    }

    // Trigger a single distance measurement
    if (i2c_write(i2c_fd, &i2c_data, sizeof(i2c_data)) != 0) {
        fprintf(stderr, "Failed to trigger distance measurement.\n");
        return 1;
    }

    if (i2c_read(i2c_fd, &i2c_data, sizeof(i2c_data)) != 0) {
        fprintf(stderr, "Failed to read distance measurement.\n");
        return 1;
    }

    measurement_success = 1;
    measurement_count++;

    // Poll RESULT_INTERRUPT_STATUS
    if (i2c_wait_for_interrupt_status(i2c_fd, &result_fd, &timeout) != 0) {
        fprintf(stderr, "Failed to poll RESULT_INTERRUPT_STATUS.\n");
        return 1;
    }

    if (result_fd != -1) {
        if (i2c_read(i2c_fd, &result_data, sizeof(result_data)) != 0) {
            fprintf(stderr, "Failed to read RESULT_INTERRUPT_STATUS.\n");
            return 1;
        }

        if (result_data & 0x8000) {
            // Distance measurement successful
            sprintf(distance_mm, "%.2f", result_data & 0x7FFF);

            // Log distance to file
            if (snprintf(timestamp, sizeof(timestamp), "%s,%.2f",
                          getctime(), atof(distance_mm)) >= sizeof(timestamp)) {
                if (write(STDOUT_FILENO, timestamp, strlen(timestamp)) != strlen(timestamp)) {
                    fprintf(stderr, "Failed to write timestamp to stdout.\n");
                    return 1;
                }

                if (write(distance_log_file, distance_mm, strlen(distance_mm)) != strlen(distance_mm)) {
                    fprintf(stderr, "Failed to write distance to distance_log.txt.\n");
                    return 1;
                }
            }
        }
    }

    // Release resources
    if (i2c_close(i2c_fd) != 0) {
        fprintf(stderr, "Failed to close I2C device file.\n");
        return 1;
    }

    if (gpio_close(gpio_fd) != 0) {
        fprintf(stderr, "Failed to close GPIO file.\n");
        return 1;
    }

    if (i2c_unregister_device(i2c_fd) != 0) {
        fprintf(stderr, "Failed to unregister I2C device.\n");
        return 1;
    }

    if (gpio_unregister_device(gpio_fd) != 0) {
        fprintf(stderr, "Failed to unregister GPIO file.\n");
        return 1;
    }

    return 0;
}

// Function to initialize I2C bus
int i2c_init() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) == -1) {
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) == -1) {
        return 1;
    }

    return 0;
}

// Function to initialize GPIO
int gpio_init() {
    int gpio_fd;
    struct gpio_request gpio_request;

    if ((gpio_fd = open("/sys/class/gpio/gpio17/gpio/value", O_WRONLY)) == -1) {
        return 1;
    }

    if (ioctl(gpio_fd, GPIO_SET_DIR, GPIO_OUTPUT) == -1) {
        return 1;
    }

    if (ioctl(gpio_fd, GPIO_SET_VALUE, 1) == -1) {
        return 1;
    }

    if (ioctl(gpio_fd, GPIO_GET_VALUE, &gpio_request) == -1) {
        return 1;
    }

    return 0;
