#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_PATH "/dev/i2c-1"
#define I2C_SLAVE_ADDRESS 0x1A
#define I2C_TIMEOUT_MS 100

static int i2c_fd;
static gpiod_context *gpiod_ctx;
static char log_file_path[128];

void init_i2c_bus() {
    int rc;
    struct gpiod_i2c_config config = GPIOD_I2C_DEFAULT_CONFIG();
    config.speed = GPIDD_I2C_SPEED_STANDARD;
    config.timeout_ms = I2C_TIMEOUT_MS;

    rc = gpiod_open(gpiod_ctx, I2C_BUS_NUM, I2C_DEVICE_PATH, &config);
    if (rc < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", gpiod_strerror(rc));
        exit(1);
    }

    rc = gpiod_request(gpiod_ctx, I2C_BUS_NUM, I2C_DEVICE_PATH, GPIDD_I2C_OUTPUT_PULLUP, 1);
    if (rc < 0) {
        fprintf(stderr, "Failed to request I2C output pull-up: %s\n", gpiod_strerror(rc));
        exit(1);
    }

    rc = gpiod_request(gpiod_ctx, I2C_BUS_NUM, I2C_DEVICE_PATH, GPIDD_I2C_INPUT, 1);
    if (rc < 0) {
        fprintf(stderr, "Failed to request I2C input: %s\n", gpiod_strerror(rc));
        exit(1);
    }
}

void close_i2c_bus() {
    if (i2c_fd >= 0) {
        gpiod_release(gpiod_ctx, i2c_fd);
        i2c_fd = -1;
    }
}

void open_log_file() {
    int rc;
    char log_file_name[128];

    snprintf(log_file_name, sizeof(log_file_name), "distance_log.txt");

    rc = open(log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (rc < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", log_file_name);
        exit(1);
    }
}

void log_distance(uint32_t timestamp, uint16_t distance_mm) {
    FILE *log_file = fopen(log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file for writing: %s\n", log_file_path);
        exit(1);
    }

    char log_line[32];
    snprintf(log_line, sizeof(log_line), "%.4u-%.2u-%.2u, %.2u\n", timestamp, distance_mm);
    fputs(log_line, log_file);
    fclose(log_file);
}

void handle_i2c_error(int error) {
    fprintf(stderr, "I2C error: %s\n", strerror(error));
    log_distance(0, 0);
    exit(1);
