#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/stat.h>
#include <fcntl.h>

#define I2C_ADDR 0x1A // TCRT5000 I2C address
#define GPIO_17 17 // GPIO 17 for sensor 1
#define GPIO_18 18 // GPIO 18 for sensor 2

int main() {
    int sensor1_fd, sensor2_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct i2c_client *client;
    int rc;

    // Initialize GPIOs
    if (gpio_request_from_mem(GPIO_17, 1, &gpio1_data) < 0) {
        fprintf(stderr, "Failed to request GPIO 17\n");
        return 1;
    }
    gpio1_data.value = 1;
    if (gpio_request_from_mem(GPIO_18, 1, &gpio2_data) < 0) {
        fprintf(stderr, "Failed to request GPIO 18\n");
        return 1;
    }
    gpio2_data.value = 1;

    // Open I2C bus
    if ((client = i2c_open_client_with_opts(I2C_ADDR, I2C_CLIENT_DEFAULT_TIMEOUT)) == NULL) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up I2C messages
    i2c_msgs[0].addr = client->addr;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 2;
    i2c_msgs[0].buf = (void *)&sensor1_data;
    i2c_msgs[1].addr = client->addr;
    i2c_msgs[1].flags = 0;
    i2c_msgs[1].len = 2;
    i2c_msgs[1].buf = (void *)&sensor2_data;

    // Perform sensor reads
    if (i2c_transfer(client, i2c_msgs, 2) < 0) {
        fprintf(stderr, "Failed to read sensors\n");
        return 1;
    }

    // Log sensor readings
    FILE *log_file = fopen("obstacle_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open obstacle_log.txt\n");
        return 1;
    }

    // Log sensor readings
    for (int i = 0; i < 2; i++) {
        if (i2c_msgs[i].flags & I2C_M_RD) {
            fprintf(log_file, "%d ", i2c_msgs[i].buf[0]);
        } else {
            fprintf(log_file, "0 ");
        }
    }
    fprintf(log_file, "\n");
    fclose(log_file);

    // Handle SIGINT
    signal(SIGINT, graceful_shutdown);

    // Wait for user to press Ctrl+C
    while (1) {
        sleep(1);
    }

    // Release GPIOs and I2C bus
    gpio_release_from_mem(GPIO_17, &gpio1_data);
    gpio_release_from_mem(GPIO_18, &gpio2_data);
    i2c_release_client(client);

    return 0;
}

// Graceful shutdown function
void graceful_shutdown(int signum) {
    printf("Shutting down...\n");
    // Perform any necessary cleanup here
    exit(0);
}

