            fprintf(stderr, "Failed to get current time.\n");
            break;
        }

        // Calculate elapsed time
        if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1) {
            fprintf(stderr, "Failed to get current time.\n");
            break;
        }

        elapsed_time.tv_sec = end_time.tv_sec - start_time.tv_sec;
        elapsed_time.tv_nsec = end_time.tv_nsec - start_time.tv_nsec;

        // Calculate distance
        distance = calculate_distance(start_time, end_time);

        // Log distance and timestamp
        if (log_distance(distance, timestamp) == -1) {
            fprintf(stderr, "Failed to log distance.\n");
            break;
        }

        // Log timestamp
        if (snprintf(timestamp, sizeof(timestamp), "%s",
                     ctime(&end_time.tv_sec)) == -1) {
            fprintf(stderr, "Failed to format timestamp.\n");
            break;
        }

        // Log distance and timestamp to file
        if (fwrite(timestamp, sizeof(char), strlen(timestamp), log_file) == -1) {
            fprintf(stderr, "Failed to write to log file.\n");
            break;
        }

        // Wait for 100 ms
        usleep(100000);
    }

    // Release resources
    gpio_release(&gpio_desc);
    i2c_release(i2c_fd);
    gpio_cleanup();

    // Close log file
    fclose(log_file);

    return 0;
}

