#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/ioctl.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1A // Default address of the 3D TOF sensor

int main() {
    int i, j, sensor_fd, measurement_fd, log_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_rdwr_ioctl_data measurement_data;
    struct i2c_rdwr_ioctl_data log_data;
    struct timeval start_time, end_time;
    uint16_t distance;
    float average_distance;
    char timestamp[80];
    FILE *log_file;

    // Initialize I2C bus
    if (ioctl(sensor_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C bus address");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO pins
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    // Initialize log file
    log_file = fopen("intrusion_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Initialize average distance variable
    average_distance = 0.0;

    // Initialize sensor file descriptor
    sensor_fd = open(I2C_BUS, O_RDWR);
    if (sensor_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Initialize measurement file descriptor
    measurement_fd = open("/dev/i2c-1", O_RDWR);
    if (measurement_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Initialize log file descriptor
    log_fd = open("intrusion_log.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Set I2C timeout
    gpioSetMode(GPIO_I2C, GPIO_MODE_OUTPUT);
    gpioSetPulseWidth(GPIO_I2C, 0, 100);
    gpioDelay(100);
    gpioSetMode(GPIO_I2C, GPIO_MODE_INPUT);

    // Set sensor to measurement mode
    gpioWrite(GPIO_I2C, GPIO_PIN_4);
    gpioDelay(100);

    // Wait for sensor to be ready
    gpioWaitForEdge(GPIO_I2C, GPIO_PIN_4, GPIO_FALLING);

    // Send 4-byte command frame
    i2c_data.cmd = 0x00;
    i2c_data.len = 4;
    i2c_data.buf = (uint8_t *)&i2c_data.cmd;
    i2c_data.buf[0] = 0x01;
    i2c_data.buf[1] = 0x00;
    i2c_data.buf[2] = 0x00;
    i2c_data.buf[3] = 0x00;

    if (ioctl(sensor_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    if (write(sensor_fd, &i2c_data, sizeof(struct i2c_rdwr_ioctl_data)) < 0) {
        perror("Failed to send command frame");
        exit(EXIT_FAILURE);
    }

    // Wait for at least 10 ms
    gpioDelay(10);

    // Read 15-byte response
    measurement_data.cmd = 0x00;
    measurement_data.len = 15;
    measurement_data.buf = (uint8_t *)&measurement_data.cmd;

    if (ioctl(sensor_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    if (read(sensor_fd, measurement_data.buf, sizeof(measurement_data.buf)) < 0) {
        perror("Failed to read response");
        exit(EXIT_FAILURE);
    }

    // Check if measurement was successful
    if (measurement_data.buf[0] != 0x55) {
        perror("Failed to get measurement result");
        exit(EXIT_FAILURE);
    }

    // Extract distance from response
    measurement_data.buf[11] = measurement_data.buf[11] >> 8;
    measurement_data.buf[12] = measurement_data.buf[12] >> 8;
    distance = measurement_data.buf[11] | (measurement_data.buf[12] << 8);

    // Compute average distance
    for (j = 0; j < 10; j++) {
        // Wait for 100 ms
        gpioDelay(100);

        // Read distance measurement
        measurement_data.cmd = 0x00;
        measurement_data.len = 2;
        measurement_data.buf = (uint8_t *)&measurement_data.cmd;
        measurement_data.buf[0] = 0x01;
        measurement_data.buf[1] = 0x01;

        if (ioctl(sensor_fd, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("Failed to set I2C address");
            exit(EXIT_FAILURE);
        }

        if (read(sensor_fd, measurement_data.buf, sizeof(measurement_data.buf)) < 0) {
            perror("Failed to read distance measurement");
            exit(EXIT_FAILURE);
        }

        // Check if measurement was successful
        if (measurement_data.buf[0] != 0x55) {
            perror("Failed to get distance measurement");
            exit(EXIT_FAILURE);
        }

        distance += measurement_data.buf[1] << 8;
    }

    average_distance = (float)distance / 10.0;

    // Log the average distance
    log_data.cmd = 0x00;
    log_data.len = sizeof(struct i2c_rdwr_ioctl_data);
    log_data.buf = (uint8_t *)&log_data.cmd;
    log_data.buf[0] = 0x01;
    log_data.buf[1] = 0x00;
    log_data.buf[2] = 0x00;
    log_data.buf[3] = 0x00;

    if (ioctl(log_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    if (write(log_fd, &log_data, sizeof(struct i2c_rdwr_ioctl_data)) < 0) {
        perror("Failed to log average distance");
        exit(EXIT_FAILURE);
    }

    // Close all file descriptors
    close(sensor_fd);
    close(measurement_fd);
    close(log_fd);

    // Release GPIO pins
    gpioRelease(GPIO_I2C);
    gpioRelease(GPIO_GPIO);

    return 0;
}

