int main() {
    int i2c_fd;
    int gpio_fd;
    int sensor_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_desc *gpio_desc;
    struct gpio_direction_ioctl_data gpio_direction;
    struct gpio_value_ioctl_data gpio_value;
    struct gpio_event_ioctl_data gpio_event;
    struct i2c_msg i2c_msgs[2];
    int ret;
    int bus_error_count = 0;
    int sig_caught = 0;

    // Initialize I2C bus
    if ((i2c_fd = pigpio_i2c_open(I2C_BUS_NUM)) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    // Initialize GPIO
    gpio_fd = pigpio_get_gpio_file(i2c_fd);
    gpio_desc = pigpio_get_gpio_desc(gpio_fd);
    gpio_direction.gpio_num = GPIO_OUTPUT;
    gpio_direction.direction = GPIO_OUTPUT_HIGH;
    if (pigpio_set_gpio_direction(gpio_fd, gpio_direction) < 0) {
        fprintf(stderr, "Error setting GPIO direction\n");
        return 1;
    }

    // Open sensor
    if ((sensor_fd = pigpio_open_i2c_device(i2c_fd, SENSOR_ADDRESS)) < 0) {
        fprintf(stderr, "Error opening sensor\n");
        return 1;
    }

    // Set up I2C messages
    i2c_msgs[0].addr = SENSOR_ADDRESS;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 2;
    i2c_msgs[0].buf = (void *)&i2c_data;

    i2c_msgs[1].addr = SENSOR_ADDRESS;
    i2c_msgs[1].flags = 0;
    i2c_msgs[1].len = 1;
    i2c_msgs[1].buf = &gpio_value;

    // Set up SIGINT handler
    signal(SIGINT, sig_handler);

    // Start reading sensor data
    while (1) {
        ret = pigpio_i2c_transfer(i2c_fd, i2c_msgs, 2, NULL);
        if (ret < 0) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(ret));
            return 1;
        }

        // Check for NACK on initial write
        if (gpio_value.value == 0) {
            gpio_value.value = 1;
            if (pigpio_set_gpio_value(gpio_fd, gpio_value) < 0) {
                fprintf(stderr, "Error setting NACK on initial write\n");
                return 1;
            }
        }

        // Check for bus errors
        if (ret == 0) {
            bus_error_count = 0;
        } else {
            bus_error_count++;
        }

        // Check for SIGINT
        if (sig_caught) {
            break;
        }

        // Wait for 500 ms
        sleep(0.5);
    }

    // Clean up
    pigpio_close(sensor_fd);
    pigpio_release_gpio_file(gpio_fd);
    pigpio_close(i2c_fd);

    // Clean up SIGINT handler
    signal(SIGINT, SIG_DFL);

    return 0;
}

// SIGINT handler
void sig_handler(int sig) {
    sig_caught = 1;
}

