#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <stdint.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE 0x1A

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_rdwr_ioctl_data_setup setup;
    int ret;

    // Initialize I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE) < 0) {
        perror("Error setting I2C slave");
        exit(EXIT_FAILURE);
    }

    // Check if Melexis MLX75030 is present
    if (ioctl(i2c_fd, I2C_RDWR, 0) < 0) {
        if (errno == ENODEV) {
            fprintf(stderr, "Error: Melexis MLX75030 not found on I2C bus\n");
            exit(EXIT_FAILURE);
        } else {
            perror("Error reading from I2C device");
            exit(EXIT_FAILURE);
        }
    }

    // Start reading the sensor
    while (1) {
        memset(&data, 0, sizeof(data));
        data.flags = 0;
        data.timeout = 500000;
        data.rdwr_data = (void *)&distance;
        data.rdwr_ndata = sizeof(distance);

        ret = ioctl(i2c_fd, I2C_RDWR, &data);
        if (ret < 0) {
            if (errno == EAGAIN) {
                continue;
            } else {
                perror("Error reading from I2C device");
                exit(EXIT_FAILURE);
            }
        }

        printf("Distance: %d mm\n", distance);
    }

    // Cleanly close the I2C file descriptor
    close(i2c_fd);

    return 0;
}

