#include <fcntl.h>
#include <errno.h>

#define I2C_BUS_NUM 1
#define I2C_SLAVE_ADDR 0x1A
#define GPIO_PIN 17

int main() {
    int i2c_fd, file_fd, log_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    uint8_t sensor_data[2];
    char log_file_path[128] = "distance_log.txt";
    char timestamp[64] = {0};
    char alert_message[128] = "Sensor Alert: Distance below 10.0 cm";

    // Initialize GPIO pin 17
    gpio_set_direction(GPIO_PIN, GPIO_OUTPUT);

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((file_fd = open(log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        perror("Error setting I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C messages
    i2c_msgs[0].addr = I2C_SLAVE_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[1].addr = I2C_SLAVE_ADDR;
    i2c_msgs[1].flags = 0;

    // Read sensor data
    if (ioctl(i2c_fd, I2C_RDWR, I2C_RD_MESSAGE) < 0) {
        perror("Error reading sensor data");
        exit(EXIT_FAILURE);
    }

    // Wait for 100 ms
    sleep(100);

    // Read sensor data again
    if (ioctl(i2c_fd, I2C_RDWR, I2C_RD_MESSAGE) < 0) {
        perror("Error reading sensor data");
        exit(EXIT_FAILURE);
    }

    // Log the distance and timestamp
    snprintf(timestamp, sizeof(timestamp), "%s", asctime(localtime(&(struct timeval){.tv_sec = time(NULL)})));
    snprintf(log_file_path, sizeof(log_file_path), "distance_log.txt");
    if ((log_fd = open(log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    if (write(log_fd, timestamp, strlen(timestamp)) < 0) {
        perror("Error writing timestamp to log file");
        exit(EXIT_FAILURE);
    }

    // Check if distance is below 10.0 cm
    if (sensor_data[0] < 10.0) {
        gpio_set_value(GPIO_PIN, 1);
    } else {
        gpio_set_value(GPIO_PIN, 0);
    }

    // Release resources
    close(file_fd);
    close(log_fd);
    close(i2c_fd);

    return 0;
}

