#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define LED_GPIO_NUM 18
#define LED_GPIO_NAME "GPIO-002"

int main() {
    int i;
    int retries = 3;
    int delay_ms = 10;
    int i2c_fd;
    int gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_request gpio_request;
    struct gpio_config gpio_config;
    struct gpio_status gpio_status;

    gpio_fd = pigpio_open(0);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = i2c_open(I2C_BUS_NUM);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        pigpio_close(gpio_fd);
        return 1;
    }

    gpio_config.gpio_dir = GPIO_OUTPUT;
    gpio_config.gpio_value = 0;
    if (pigpio_set_mode(gpio_fd, gpio_config) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        pigpio_close(gpio_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    gpio_request.gpio_num = LED_GPIO_NUM;
    gpio_request.gpio_mode = GPIO_OUTPUT;
    gpio_request.gpio_value = 0;
    if (pigpio_request_gpio(gpio_fd, &gpio_request) < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        pigpio_close(gpio_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    gpio_status.gpio_status = GPIO_NOT_INITIALIZED;
    if (pigpio_get_gpio_status(gpio_fd, &gpio_status) < 0) {
        fprintf(stderr, "Failed to get GPIO status: %s\n", strerror(errno));
        pigpio_close(gpio_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    if (gpio_status.gpio_status != GPIO_INITIALIZED) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        pigpio_close(gpio_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    pigpio_set_mode(gpio_fd, GPIO_OUTPUT);
    pigpio_set_level(gpio_fd, 0);

    while (1) {
        for (i = 0; i < 100; i++) {
            gpio_request.gpio_num = LED_GPIO_NUM;
            gpio_request.gpio_mode = GPIO_OUTPUT;
            gpio_request.gpio_value = i % 2;
            if (pigpio_request_gpio(gpio_fd, &gpio_request) < 0) {
                fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
                break;
            }

            gpio_data.gpio_status = GPIO_NOT_INITIALIZED;
            if (pigpio_get_gpio_status(gpio_fd, &gpio_data) < 0) {
                fprintf(stderr, "Failed to get GPIO status: %s\n", strerror(errno));
                break;
            }

            if (gpio_data.gpio_status != GPIO_INITIALIZED) {
                fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
                break;
            }

            if (gpio_data.gpio_value == 0) {
                pigpio_set_level(gpio_fd, 1);
            } else {
                pigpio_set_level(gpio_fd, 0);
            }

            usleep(delay_ms * 1000);
        }

        pigpio_set_mode(gpio_fd, GPIO_INPUT);
        pigpio_set_level(gpio_fd, 0);

        retries--;
        if (retries == 0) {
            fprintf(stderr, "Failed to read sensor data after 3 retries\n");
            break;
        }

        if (pigpio_request_gpio(gpio_fd, &gpio_request) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
            break;
        }

        gpio_data.gpio_status = GPIO_NOT_INITIALIZED;
        if (pigpio_get_gpio_status(gpio_fd, &gpio_data) < 0) {
            fprintf(stderr, "Failed to get GPIO status: %s\n", strerror(errno));
            break;
        }

        if (gpio_data.gpio_status != GPIO_INITIALIZED) {
            fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
            break;
        }

        if (gpio_data.gpio_value == 0) {
            pigpio_set_level(gpio_fd, 1);
        } else {
            pigpio_set_level(gpio_fd, 0);
        }

        usleep(delay_ms * 1000);
    }

    pigpio_close(gpio_fd);
    i2c_close(i2c_fd);

    return 0;
}

