#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>

#include <gpiod.h>
#include <pigpio.h>

#define SENSOR_1_GPIO_PIN 17
#define SENSOR_2_GPIO_PIN 13

int main() {
    int fd, ret;
    struct gpiod_event_data event_data;
    struct gpiod_event_data *event_data_ptr;
    struct timespec start_time, end_time;
    char filename[32];
    char log_file_content[256];
    char timestamp[32];
    int sensor_id;
    char event_type;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioSetupPWM(17) < 0 || gpioSetupPWM(27) < 0) {
        fprintf(stderr, "Failed to set up PWM\n");
        return 1;
    }

    // Set up debouncing
    gpioSetMode(SENSOR_1_GPIO_PIN, PI_OUTPUT);
    gpioSetMode(SENSOR_2_GPIO_PIN, PI_OUTPUT);
    gpioSetPwmFrequency(SENSOR_1_GPIO_PIN, 50);
    gpioSetPwmFrequency(SENSOR_2_GPIO_PIN, 50);

    // Log initial state
    snprintf(timestamp, sizeof(timestamp), "%s", gmtime(&start_time.tv_sec));
    snprintf(filename, sizeof(filename), "proximity_log_%s.txt", timestamp);
    FILE *log_file = fopen(filename, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Poll sensors
    sensor_id = 1;
    event_type = 'DETECTED';
    while (1) {
        ret = gpiod_event_wait(fd, &event_data_ptr, &event_data, GPIOD_EVENT_ANY);
        if (ret < 0) {
            fprintf(stderr, "Failed to poll sensors: %s\n", strerror(errno));
            return 1;
        }

        if (event_data_ptr->event_type == GPIOD_EVENT_HIGH_TO_LOW) {
            sensor_id = 1;
            event_type = 'DETECTED';
        } else if (event_data_ptr->event_type == GPIOD_EVENT_LOW_TO_HIGH) {
            sensor_id = 1;
            event_type = 'CLEARED';
        } else {
            fprintf(stderr, "Unexpected event type: %d\n", event_data_ptr->event_type);
            return 1;
        }

        // Log state transition
        snprintf(timestamp, sizeof(timestamp), "%s", gmtime(&end_time.tv_sec));
        snprintf(filename, sizeof(filename), "proximity_log_%s.txt", timestamp);
        fprintf(log_file, "sensor_id=%d, event_type='%c', sensor_state='%s'\n", sensor_id, event_type, gpiod_event_get_state(event_data_ptr));
        fclose(log_file);

        // Release GPIO resources
        gpioReleasePwm(SENSOR_1_GPIO_PIN);
        gpioReleasePwm(SENSOR_2_GPIO_PIN);
        gpioRelease(fd);
        gpiod_exit();
    }

    // Cleanup
    fclose(log_file);
    gpioReleasePwm(SENSOR_1_GPIO_PIN);
    gpioReleasePwm(SENSOR_2_GPIO_PIN);
    gpioRelease(fd);
    gpiod_exit();

    return 0;
}

