#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1A // TDK CH-101 Time-of-Flight sensor address

void log_to_csv(const char* filename, const char* timestamp, double distance_mm) {
    FILE* file = fopen(filename, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", filename);
        return;
    }

    char timestamp_str[50];
    struct tm tm = {0};
    time_t now = time(NULL);
    localtime_r(&now, &tm);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(file, "%s,%s,%f\n", timestamp_str, distance_mm, distance_mm);
    fclose(file);
}

int main() {
    int i2c_fd;
    struct gpiod_i2c_config config = {
        .addr = I2C_ADDR,
        .speed = GPIDO_SPEED_100KHZ,
    };

    if ((i2c_fd = gpiod_i2c_open(I2C_BUS, &config)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", I2C_BUS);
        return 1;
    }

    if ((ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) || (ioctl(i2c_fd, I2C_RDWR, 0) < 0)) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        gpiod_i2c_close(i2c_fd);
        return 1;
    }

    if ((gpiod_get_line_state(i2c_fd, GPIDO_LINE_MEAS_STATUS) & GPIDO_LINE_STATE_HIGH) == 0) {
        struct gpiod_i2c_reg_write_data data = {
            .addr = I2C_ADDR,
            .reg = 0x00,
            .data = 0x00,
        };

        if (ioctl(i2c_fd, GPIDO_I2C_WRITE, &data) < 0) {
            fprintf(stderr, "Error writing to MEAS_STATUS register: %s\n", strerror(errno));
            gpiod_i2c_close(i2c_fd);
            return 1;
        }

        struct gpiod_i2c_reg_read_data read_data = {
            .addr = I2C_ADDR,
            .reg = 0x00,
        };

        if (ioctl(i2c_fd, GPIDO_I2C_READ, &read_data) < 0) {
            fprintf(stderr, "Error reading MEAS_STATUS register: %s\n", strerror(errno));
            gpiod_i2c_close(i2c_fd);
            return 1;
        }

        uint16_t meas_status = read_data.data;
        while ((meas_status & GPIDO_LINE_STATE_HIGH) == 0) {
            struct gpiod_i2c_reg_read_data read_data = {
                .addr = I2C_ADDR,
                .reg = 0x00,
            };

            if (ioctl(i2c_fd, GPIDO_I2C_READ, &read_data) < 0) {
                fprintf(stderr, "Error reading MEAS_STATUS register: %s\n", strerror(errno));
                gpiod_i2c_close(i2c_fd);
                return 1;
            }

            meas_status = read_data.data;
        }

        struct gpiod_i2c_reg_write_data stop_data = {
            .addr = I2C_ADDR,
            .reg = 0x01,
            .data = 0x00,
        };

        if (ioctl(i2c_fd, GPIDO_I2C_WRITE, &stop_data) < 0) {
            fprintf(stderr, "Error writing to MEAS_STATUS register: %s\n", strerror(errno));
            gpiod_i2c_close(i2c_fd);
            return 1;
        }

        struct gpiod_i2c_reg_read_data read_data = {
            .addr = I2C_ADDR,
            .reg = 0x00,
        };

        if (ioctl(i2c_fd, GPIDO_I2C_READ, &read_data) < 0) {
            fprintf(stderr, "Error reading MEAS_STATUS register: %s\n", strerror(errno));
            gpiod_i2c_close(i2c_fd);
            return 1;
        }

        uint16_t meas_status_read = read_data.data;
        while ((meas_status_read & GPIDO_LINE_STATE_HIGH) == 0) {
            struct gpiod_i2c_reg_read_data read_data = {
                .addr = I2C_ADDR,
                .reg = 0x00,
            };

            if (ioctl(i2c_fd, GPIDO_I2C_READ, &read_data) < 0) {
                fprintf(stderr, "Error reading MEAS_STATUS register: %s\n", strerror(errno));
                gpiod_i2c_close(i2c_fd);
                return 1;
            }

            meas_status_read = read_data.data;
        }

        uint16_t distance_mm = (meas_status_read & GPIDO_LINE_STATE_HIGH) ?
                              read_data.data : 0;
        log_to_csv("distance_log.csv", "timestamp", distance_mm);

        gpiod_i2c_close(i2c_fd);
    }

    gpiod_i2c_close(i2c_fd);
    return 0;
}

