#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <linux/i2c.h>
#include <linux/delay.h>
#include <linux/time.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x29
#define BUZZER_GPIO_NUM 22

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct i2c_client *client;
    int buzzer_gpio_direction;
    int buzzer_gpio_value;
    int distance_mm;
    int previous_distance_mm;
    int i;

    // Initialize GPIO and I2C
    gpio_init();
    i2c_init();

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS_NUM);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set I2C device address
    client = i2c_get_client_by_addr(i2c_fd, I2C_DEVICE_ADDR);
    if (client == NULL) {
        fprintf(stderr, "Failed to get I2C client\n");
        return 1;
    }

    // Set GPIO direction and value
    buzzer_gpio_direction = GPIO_OUTPUT;
    buzzer_gpio_value = 1; // Set buzzer to active state
    gpio_set_direction(BUZZER_GPIO_NUM, buzzer_gpio_direction);
    gpio_set_value(BUZZER_GPIO_NUM, buzzer_gpio_value);

    // Configure sensor for continuous ranging mode
    i2c_msgs[0].addr = I2C_DEVICE_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 2;
    i2c_msgs[0].buf = &i2c_data;
    i2c_msgs[0].buf[0] = 0x00;
    i2c_msgs[0].buf[1] = 0x01;
    i2c_msgs[1].addr = I2C_DEVICE_ADDR;
    i2c_msgs[1].flags = 0;
    i2c_msgs[1].len = 2;
    i2c_msgs[1].buf = &i2c_data;
    i2c_msgs[1].buf[0] = 0x00;
    i2c_msgs[1].buf[1] = 0x02;

    while (1) {
        // Wait for sensor to finish a measurement
        i2c_data.flags = 0;
        i2c_data.timeout = 100;
        i2c_data.buf = NULL;
        i2c_data.len = 0;
        i2c_data.retries = 0;
        i2c_data.mode = I2C_RDWR;
        i2c_data.flags |= I2C_POLL_WRITE;
        i2c_data.flags |= I2C_POLL_READ;
        i2c_data.timeout = 0;

        if (i2c_transfer(i2c_fd, &i2c_data, 2, NULL) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        distance_mm = i2c_data.buf[0] << 8 | i2c_data.buf[1];

        // Check if distance falls below 100 mm
        if (distance_mm < 100) {
            // Activate buzzer
            gpio_set_value(BUZZER_GPIO_NUM, 0);
        } else {
            // Deactivate buzzer
            gpio_set_value(BUZZER_GPIO_NUM, 1);
        }

        // Log error and skip iteration
        if (i2c_transfer(i2c_fd, &i2c_data, 2, NULL) < 0) {
            fprintf(stderr, "Failed to read sensor data: %s\n", i2c_strerror(errno));
            continue;
        }

        // Release resources
        i2c_close(i2c_fd);
        gpio_cleanup();

        // Handle SIGINT for graceful shutdown
        signal(SIGINT, graceful_shutdown);
    }

    return 0;
}

// Graceful shutdown function
void graceful_shutdown(int sig) {
    printf("Graceful shutdown detected. Releasing resources...\n");
    i2c_cleanup();
    gpio_cleanup();
    exit(0);
}

