#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpio/service.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x1A

#define SERVO_PIN 17
#define ECHO_PIN 24
#define TRIGGER_PIN 23

int main() {
    int i;
    int ret;
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    uint8_t buf[2];
    uint16_t timeout_ms = 50;
    int16_t distance;
    int angle;
    char log_file[128] = "sensor_data.log";

    // Initialize the driver library
    if ((ret = gpiod_init()) != 0) {
        fprintf(stderr, "Error initializing gpiod library: %s\n", gpiod_strerror(ret));
        return 1;
    }

    // Open the I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpiod_exit();
        return 1;
    }

    // Set up the I2C device
    if ((ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR)) != 0) {
        fprintf(stderr, "Error setting I2C device address: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_exit();
        return 1;
    }

    // Open the GPIO pins
    if ((ret = gpio_request_line(SERVO_PIN, GPIO_OUTPUT)) != 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_exit();
        return 1;
    }
    if ((ret = gpio_request_line(ECHO_PIN, GPIO_INPUT)) != 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpio_release_line(SERVO_PIN);
        gpiod_exit();
        return 1;
    }

    // Set up the trigger, echo, and servo control lines
    if ((ret = gpio_direction_output(SERVO_PIN, 1)) != 0) {
        fprintf(stderr, "Error setting up servo control line: %s\n", strerror(errno));
        gpio_release_line(SERVO_PIN);
        gpio_release_line(ECHO_PIN);
        gpiod_exit();
        return 1;
    }

    // Set up the trigger, echo, and servo control lines
    if ((ret = gpio_direction_output(ECHO_PIN, 1)) != 0) {
        fprintf(stderr, "Error setting up echo line: %s\n", strerror(errno));
        gpio_release_line(SERVO_PIN);
        gpio_release_line(ECHO_PIN);
        gpiod_exit();
        return 1;
    }

    // Set up the servo control line
    if ((ret = gpio_direction_output(SERVO_PIN, 0)) != 0) {
        fprintf(stderr, "Error setting up servo control line: %s\n", strerror(errno));
        gpio_release_line(SERVO_PIN);
        gpio_release_line(ECHO_PIN);
        gpiod_exit();
        return 1;
    }

    // Set up the timeout
    timeout_ms = 50;

    // Loop to read and log distances
    while (1) {
        // Trigger the sensor
        if (ioctl(i2c_fd, I2C_RDWR, i2c_msgs) == -1) {
            fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
            close(i2c_fd);
            gpiod_exit();
            return 1;
        }

        // Wait for the echo
        if (ioctl(i2c_fd, I2C_RDWR, i2c_msgs) == -1) {
            fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
            close(i2c_fd);
            gpiod_exit();
            return 1;
        }

        // Check if the echo is still low or high
        if (ioctl(i2c_fd, I2C_RDWR, i2c_msgs) == -1) {
            fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
            close(i2c_fd);
            gpiod_exit();
            return 1;
        }

        // Map the valid distances to the servo angle range
        distance = (int16_t)((buf[0] << 8) | buf[1]);
        angle = (int)((distance - 2) * (400 - 2) / 2 + 2);

        // Log the distance and timestamp
        if (angle >= -90 && angle <= 90) {
            if (write(1, &angle, sizeof(int16_t)) != sizeof(int16_t)) {
                fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
                close(i2c_fd);
                gpiod_exit();
                return 1;
            }
            if (write(log_file, &angle, sizeof(int16_t)) != sizeof(int16_t)) {
                fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
                close(i2c_fd);
                gpiod_exit();
                return 1;
            }
        }

        // Sleep for 200 ms
        sleep(200);
    }

    // Release the GPIO lines and close the I2C bus
    gpio_release_line(SERVO_PIN);
    gpio_release_line(ECHO_PIN);
    gpio_release_line(SERVO_PIN);
    gpio_release_line(ECHO_PIN);
    close(i2c_fd);
    gpiod_exit();

    return 0;
}

