#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x29

int main() {
    int i2c_fd;
    int gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_desc gpio_desc;
    struct gpio_value gpio_value;
    struct timespec start_time, end_time;
    char log_file_name[] = "gate_events.log";
    char *log_file_path = NULL;
    int log_file_fd;
    int error;

    // Initialize I2C and GPIO
    gpio_fd = pigpio_open(0);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO\n");
        return 1;
    }

    i2c_fd = i2c_open_device_nonblock(I2C_BUS_NUM, I2C_DEVICE_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C device\n");
        pigpio_close(gpio_fd);
        return 1;
    }

    // Initialize GPIO pin 18 as an output
    if (!pigpio_set_mode(gpio_fd, GPIO_OUTPUT)) {
        fprintf(stderr, "Error: Failed to set GPIO 18 as output\n");
        pigpio_close(gpio_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    // Set GPIO 18 HIGH
    if (!pigpio_set_level(gpio_fd, GPIO_HIGH)) {
        fprintf(stderr, "Error: Failed to set GPIO 18 HIGH\n");
        pigpio_close(gpio_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    // Set GPIO 19 as an input
    if (!pigpio_set_mode(gpio_fd, GPIO_INPUT)) {
        fprintf(stderr, "Error: Failed to set GPIO 19 as input\n");
        pigpio_close(gpio_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    // Initialize the VL53L1X sensor
    if (!pigpio_set_mode(gpio_fd, GPIO_OUTPUT)) {
        fprintf(stderr, "Error: Failed to set GPIO 18 as output\n");
        pigpio_close(gpio_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    if (!pigpio_set_level(gpio_fd, GPIO_LOW)) {
        fprintf(stderr, "Error: Failed to set GPIO 18 LOW\n");
        pigpio_close(gpio_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    // Configure the sensor's timing budget
    if (!pigpio_set_timing_budget(gpio_fd, 100)) {
        fprintf(stderr, "Error: Failed to set timing budget\n");
        pigpio_close(gpio_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    // Start the sensor's ranging
    if (!pigpio_start_range(gpio_fd)) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        pigpio_close(gpio_fd);
        i2c_close(i2c_fd);
        return 1;
    }

    // Wait for the sensor to finish ranging
    while (1) {
        // Wait for the next I2C transfer
        if (i2c_transfer(i2c_fd, 0, NULL, 0) < 0) {
            fprintf(stderr, "Error: Failed to read I2C transfer\n");
            pigpio_close(gpio_fd);
            i2c_close(i2c_fd);
            return 1;
        }

        // Read the 16-bit register value
        if (i2c_read_reg16(i2c_fd, I2C_REG_VL53L1X_RANGING_STATUS, &gpio_value) < 0) {
            fprintf(stderr, "Error: Failed to read ranging status\n");
            pigpio_close(gpio_fd);
            i2c_close(i2c_fd);
            return 1;
        }

        // Check if the sensor is absent or the I2C transfer failed
        if (gpio_value.value == 0) {
            fprintf(stderr, "Sensor absent or I2C transfer failed\n");
            pigpio_close(gpio_fd);
            i2c_close(i2c_fd);
            return 1;
        }

        // Check if an object is detected within 20 cm
        if (gpio_value.value == 1) {
            // Log the open event
            if (open_log_file(log_file_path) < 0) {
                fprintf(stderr, "Error: Failed to open log file\n");
                pigpio_close(gpio_fd);
                i2c_close(i2c_fd);
                return 1;
            }

            fprintf(log_file_path, "Object detected at %s\n",
                    ctime(&start_time.tv_sec));
            log_file_fd = open(log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
            if (log_file_fd < 0) {
                fprintf(stderr, "Error: Failed to open log file\n");
                pigpio_close(gpio_fd);
                i2c_close(i2c_fd);
                close(log_file_fd);
                return 1;
            }

            // Log the close event
            if (close_log_file(log_file_fd) < 0) {
                fprintf(stderr, "Error: Failed to close log file\n");
                pigpio_close(gpio_fd);
                i2c_close(i2c_fd);
                close(log_file_fd);
                return 1;
            }

            pigpio_set_level(gpio_fd, GPIO_HIGH);
            pigpio_set_mode(gpio_fd, GPIO_INPUT);
            pigpio_close(gpio_fd);
            i2c_close(i2c_fd);
            close(log_file_fd);
            return 0;
        }

        // Check if an object is not detected within 20 cm
        if (gpio_value.value == 0) {
            // Log the close event
            if (close_log_file(log_file_fd) < 0) {
                fprintf(stderr, "Error: Failed to close log file\n");
                pigpio_close(gpio_fd);
                i2c_close(i2c_fd);
                return 1;
            }

            pigpio_set_level(gpio_fd, GPIO_LOW);
            pigpio_set_mode(gpio_fd, GPIO_OUTPUT);
            pigpio_close(gpio_fd);
            i2c_close(i2c_fd);
            return 1;
        }
    }
}

// Function to open the log file
int open_log_file(char *file_path) {
    FILE *log_file;
    if ((log_file = fopen(file_path, "a")) == NULL) {
        perror("Error: Failed to open log file");
        return -1;
    }
