#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <errno.h>

#include <gpiod.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void handle_sigint(int sig) {
    stop = 1;
}

int main() {
    int fd;
    struct gpiod_event event;
    struct gpiod_event_attr attr;
    struct timespec timeout;
    struct timespec now;
    struct timespec start;
    struct timespec end;
    struct timespec elapsed;
    struct sigaction sa;
    char filename[32];
    char *log_file = "distance_log.txt";

    // Initialize GPIO and PWM
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioPwmInit() < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        return 1;
    }

    // Set up the GPIO pin for the trigger
    if (gpioSetMode(17, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin as output\n");
        return 1;
    }

    // Set up the GPIO pin for the echo
    if (gpioSetMode(18, GPIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin as input\n");
        return 1;
    }

    // Set up the timeout for the echo pulse
    timeout.tv_sec = 0;
    timeout.tv_nsec = 5 * 1000000;

    // Set up the PWM for the trigger
    if (gpioPwmSetRange(17, 0, 255) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return 1;
    }

    if (gpioPwmSetPeriod(17, 10) < 0) {
        fprintf(stderr, "Failed to set PWM period\n");
        return 1;
    }

    // Set up the GPIO event for the trigger pulse
    if (gpioCreateEventAttr(NULL, &attr) < 0) {
        fprintf(stderr, "Failed to create event attribute\n");
        return 1;
    }

    if (gpioCreateEvent(NULL, &event, &attr) < 0) {
        fprintf(stderr, "Failed to create event\n");
        return 1;
    }

    // Set up the GPIO event for the echo pulse
    if (gpioCreateEventAttr(NULL, &attr) < 0) {
        fprintf(stderr, "Failed to create event attribute\n");
        return 1;
    }

    if (gpioCreateEvent(NULL, &event_echo, &attr) < 0) {
        fprintf(stderr, "Failed to create event\n");
        return 1;
    }

    // Set up the signal handler for SIGINT
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_SIGINFO;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        return 1;
    }

    // Main loop
    while (!stop) {
        // Wait for the trigger pulse
        if (gpioWaitEvent(event, &attr, &timeout) < 0) {
            fprintf(stderr, "Failed to wait for trigger pulse\n");
            return 1;
        }

        // Check if the echo pulse has been received
        if (!gpioCheckEvent(event_echo, &attr) || !gpioWaitEvent(event, &attr, &timeout)) {
            fprintf(stderr, "Failed to wait for echo pulse\n");
            return 1;
        }

        // Check if the echo pulse has been received
        if (gpioCheckEvent(event_echo, &attr) < 0) {
            fprintf(stderr, "Failed to check for echo pulse\n");
            return 1;
        }

        // Measure the pulse width
        if (gpioReadEvent(event, &attr) < 0) {
            fprintf(stderr, "Failed to read pulse width\n");
            return 1;
        }

        // Check if the pulse width is within the valid range
        if (attr.value < 2 || attr.value > 400) {
            fprintf(stderr, "Invalid pulse width: %d\n", attr.value);
            continue;
        }

        // Compute the distance
        int distance = (attr.value / 2) * 343;

        // Log the distance
        if (snprintf(filename, sizeof(filename), "distance_log.txt") < 0) {
            fprintf(stderr, "Failed to create log file\n");
            return 1;
        }

        FILE *log_file = fopen(filename, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return 1;
        }

        if (fprintf(log_file, "%s,%.2f\n", get_iso8601_timestamp(), distance) < 0) {
            fprintf(stderr, "Failed to log distance\n");
            return 1;
        }

        fclose(log_file);
    }

    // Release the GPIO resources
    gpioReleaseEvent(event);
    gpioReleaseEvent(event_echo);
    gpioReleasePwm(17);
    gpioReleasePwm(18);
    gpioRelease(fd);

    return 0;
}

