#define TRIG_GPIO 17
#define ECHO_GPIO 18
#define TRIG_PIN GPIO_UNUSED
#define ECHO_PIN GPIO_UNUSED
#define VOLTAGE_DIVIDER 1000
#define TRIG_PERIOD 10 // 10 µs
#define ECHO_PERIOD 1000000 // 1 ms
#define ECHO_THRESHOLD 58 // 58 µs to 25 ms (1 cm to 4 m)
#define MAX_DISTANCE 4.0 // Maximum distance in meters

int main() {
    int fd;
    int gpioHandle;
    struct i2c_rdwr_ioctl_data i2cData;
    struct gpio_desc gpioDesc;
    struct timeval startTime, endTime;
    struct i2c_msg i2cMsg[2];
    int i;

