    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Initialize GPIO pins
    gpioHandle = gpioSetup(TRIG_GPIO, GPIO_OUTPUT);
    gpioSetMode(gpioHandle, GPIO_PUD_UP);
    gpioSetValue(gpioHandle, GPIO_LOW);

    gpioHandle = gpioSetup(ECHO_GPIO, GPIO_INPUT);
    gpioSetMode(gpioHandle, GPIO_PUD_UP);

    // Open log file
    fd = open("distance_log.txt", O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return 1;
    }

    // Install SIGINT/SIGTERM handler
    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    // Initialize HC-SR04 sensor
    gpioSetValue(TRIG_GPIO, GPIO_HIGH);
    gpioDelay(TRIG_PERIOD / 2);
    gpioSetValue(TRIG_GPIO, GPIO_LOW);

    // Wait for the trigger pulse to be detected
    gpioWaitFor(TRIG_GPIO, GPIO_HIGH);

    // Measure echo pulse width
    gpioSetValue(ECHO_GPIO, GPIO_HIGH);
    gpioDelay(TRIG_PERIOD / 2);
    gpioSetValue(ECHO_GPIO, GPIO_LOW);

    gpioWaitFor(ECHO_GPIO, GPIO_INPUT);

    gpioWaitFor(ECHO_GPIO, GPIO_HIGH);

    // Calculate time difference
    gettimeofday(&startTime, NULL);

    // Capture pulse width
    gpioWaitFor(ECHO_GPIO, GPIO_INPUT);
    gpioWaitFor(ECHO_GPIO, GPIO_HIGH);

    gpioWaitFor(ECHO_GPIO, GPIO_INPUT);

    gettimeofday(&endTime, NULL);

    // Calculate pulse width duration
    long duration = (endTime.tv_sec - startTime.tv_sec) * 1000000 + (endTime.tv_usec - startTime.tv_usec);

    // Convert pulse width to distance
    float pulseWidth = duration / (TRIG_PERIOD / 2);
    float distance = pulseWidth * VOLTAGE_DIVIDER / 2.54;

    // Validate distance
    if (distance < 0 || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Invalid distance reading\n");
        return 1;
