    i2cMsg[1].buf = (char*)&startTime;
    i2cMsg[1].len = sizeof(startTime);

    i2cMsg[2].buf = (char*)&endTime;
    i2cMsg[2].len = sizeof(endTime);

    gpioWrite(fd, 2, i2cMsg, 3);

    // Clean up GPIO pins
