#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x29
#define LED_GPIO_NUM 17

static gpio_t gpio;
static pigpio_error_t error;

void initGPIO() {
    gpio = pigpio_initialize();
    if (gpio == NULL) {
        printf("Failed to initialize GPIO.\n");
        return;
    }
    pigpio_set_mode(gpio, PI_OUTPUT);
    pigpio_set_pin_level(gpio, LED_GPIO_NUM, 1);
}

void cleanupGPIO() {
    pigpio_release(gpio);
}

void initI2C() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int ret;

    fd = i2c_open_device_nonblock(I2C_BUS_NUM, I2C_DEVICE_ADDR);
    if (fd < 0) {
        printf("Failed to open I2C device.\n");
        return;
    }

    data.msgs = msg;
    data.nmsgs = 2;
    data.function = I2C_RDWR;
    data.timeout_ms = 50;

    ret = ioctl(fd, I2C_RDWR, &data);
    if (ret < 0) {
        printf("Failed to set I2C device to non-blocking mode.\n");
        return;
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_DEVICE_ADDR);
    if (ret < 0) {
        printf("Failed to set I2C device address.\n");
        return;
    }

    ret = ioctl(fd, I2C_RDWR, &data);
    if (ret < 0) {
        printf("Failed to read I2C device configuration.\n");
        return;
    }

    pigpio_set_mode(gpio, PI_OUTPUT);
    pigpio_set_pin_level(gpio, LED_GPIO_NUM, 1);
}

void cleanupI2C() {
    int fd;
    struct i2c_rdwr_ioctl_data data;

    fd = i2c_open_device_nonblock(I2C_BUS_NUM, I2C_DEVICE_ADDR);
    if (fd < 0) {
        printf("Failed to open I2C device.\n");
        return;
    }

    data.msgs = NULL;
    data.nmsgs = 0;
    data.function = I2C_RDWR;
    data.timeout_ms = 50;

    ret = ioctl(fd, I2C_RDWR, &data);
    if (ret < 0) {
        printf("Failed to set I2C device to non-blocking mode.\n");
        return;
    }

    ret = ioctl(fd, I2C_SLAVE, I2C_DEVICE_ADDR);
    if (ret < 0) {
        printf("Failed to set I2C device address.\n");
        return;
    }

    pigpio_release(gpio);
}

void readDistance(void) {
    int ret;
    uint16_t distance;

    ret = pigpio_start_range(gpio, I2C_DEVICE_ADDR, I2C_RANGE_MODE_NORMAL);
    if (ret < 0) {
        printf("Failed to start range measurement.\n");
        return;
    }

    ret = pigpio_get_range(gpio, &distance);
    if (ret < 0) {
        printf("Failed to read distance measurement.\n");
        return;
    }

    printf("Distance: %.2f mm\n", distance);
}

void setLED(bool on) {
    if (on) {
        gpio_set_level(LED_GPIO_NUM, 1);
    } else {
        gpio_set_level(LED_GPIO_NUM, 0);
    }
}

