    struct timespec timeout;
    int pulse_duration;
    int distance;
    char distance_str[20];
    char close_msg[50];

    // Initialize the gpio driver
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize gpio driver\n");
        return 1;
    }

    // Configure trigger and echo pins
    if (gpiod_direction(TRIG_PIN, GPIDO_OUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin as output\n");
        gpiod_exit();
        return 1;
    }

    if (gpiod_direction(ECHO_PIN, GPIDO_IN) < 0) {
        fprintf(stderr, "Failed to set echo pin as input\n");
        gpiod_exit();
        return 1;
    }

    // Check if the driver library initialization succeeds
    if (gpiod_event_request(TRIG_PIN, GPIDO_PULSE, 1, &event, 1) < 0) {
        fprintf(stderr, "Failed to request trigger event\n");
        gpiod_exit();
        return 1;
    }

    // Wait for the trigger event to occur
    timeout.tv_sec = 0;
    timeout.tv_nsec = 10 * 1000000;
    if (gpiod_event_wait(event, &timeout) < 0) {
        fprintf(stderr, "Failed to wait for trigger event\n");
        gpiod_exit();
        return 1;
    }

    // Read the echo pulse duration
    if (gpiod_event_get_data(event, &pulse_duration) < 0) {
        fprintf(stderr, "Failed to read echo pulse duration\n");
        gpiod_exit();
        return 1;
    }

    // Convert the pulse duration to distance in centimeters
    distance = pulse_duration / 58;

    // Check if the distance is valid
    if (distance < 2 || distance > 400) {
        sprintf(close_msg, "Invalid reading: Distance: %.2f cm", distance);
    } else {
        sprintf(close_msg, "Distance: %.2f cm", distance);
    }

    // Print the distance or close message
    printf("%s\n", close_msg);

    // Check if the distance is below 10 cm
    if (distance < 10) {
        sprintf(close_msg, "Too close!");
    }

    // Print the "Too close!" message
    printf("%s\n", close_msg);

    // Release the resources
    gpiod_event_release(event);
    gpiod_exit();

    return 0;
}
