#include <time.h>
#include <sys/ioctl.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x1A // Silicon Labs Si1120 sensor I2C address
#define I2C_TIMEOUT_MS 1000 // Timeout for I2C operations in milliseconds

// Function prototypes
void init_i2c();
void cleanup_i2c();
void init_gpio();
void cleanup_gpio();
void read_sensor();
void write_sensor(uint8_t data);
void read_proximity_data();
void read_ambient_light_data();
void write_part_id_to_register();
void verify_part_id();
void combine_data();
void append_timestamp_to_file();

int main() {
    int i;
    int retry_count = 3;
    int delay_ms = 10;
    int log_file_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_value gpio_value;
    struct gpio_value gpio_value_prev;
    char log_file_path[128] = "si1120_log.txt";

    init_i2c();
    init_gpio();

    while (1) {
        // Read ambient light and proximity data
        read_ambient_light_data();
        read_proximity_data();

        // Combine and append data to log file
        combine_data();
        append_timestamp_to_file();

        // Wait for a SIGINT signal to exit
        signal(SIGINT, cleanup_i2c);
        while (1) {
            usleep(delay_ms * 1000);
        }
    }

    cleanup_gpio();
    cleanup_i2c();
    return 0;
}

void init_i2c() {
    int ret;
    struct i2c_rdwr_ioctl_data i2c_data;

    // Initialize I2C bus
    ret = pigpio_init();
    if (ret != 0) {
        fprintf(stderr, "Error initializing I2C bus: %s\n", pigpio_error_str(ret));
        exit(1);
    }

    // Set I2C address
    ret = pigpio_set_non_blocking(1, 1);
    if (ret != 0) {
        fprintf(stderr, "Error setting I2C non-blocking mode: %s\n", pigpio_error_str(ret));
        exit(1);
    }

    // Open I2C file descriptor
    log_file_fd = open(log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_file_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(1);
    }

    // Initialize I2C handle
    ret = pigpio_i2c_init(1, I2C_ADDRESS, I2C_TIMEOUT_MS);
    if (ret != 0) {
        fprintf(stderr, "Error initializing I2C bus: %s\n", pigpio_error_str(ret));
        exit(1);
    }

    // Set I2C transfer parameters
    i2c_data.sda_gpio = GPIO_NUM_1;
    i2c_data.scl_gpio = GPIO_NUM_2;
    i2c_data.timeout_ms = I2C_TIMEOUT_MS;

    // Set I2C transfer parameters
    ret = pigpio_i2c_start(1, &i2c_data);
    if (ret != 0) {
        fprintf(stderr, "Error initializing I2C bus: %s\n", pigpio_error_str(ret));
        exit(1);
