#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x1A
#define I2C_TIMEOUT_MS 1000

int i2c_fd;
int gpio_num;

void error_handler(int signum) {
    printf("Error occurred at %s\n", strerror(signum));
    exit(EXIT_FAILURE);
}

void cleanup_and_exit(int exit_code) {
    gpio_close(gpio_num);
    i2c_close(i2c_fd);
    exit(exit_code);
}

int main() {
    int retries = 3;
    int retry_count = 0;

    gpio_num = gpio_request_from_sysfs();
    if (gpio_num < 0) {
        error_handler(errno);
    }

    i2c_fd = i2c_open_sysfs("/dev/i2c-1", I2C_TIMEOUT_MS);
    if (i2c_fd < 0) {
        error_handler(errno);
    }

    gpio_set_mode(gpio_num, GPIO_OUTPUT);
    gpio_set_dir(gpio_num, 1);

    while (1) {
        int ps1_data0 = 0;
        int ps1_data1 = 0;

        retries = 3;
        retry_count = 0;

        while (retry_count < retries) {
            if (ret == 0) {
                break;
            }

            if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
                error_handler(errno);
            }

            if (ioctl(i2c_fd, I2C_RDWR, 0) < 0) {
                error_handler(errno);
            }

            if (ioctl(i2c_fd, I2C_RDWR, 1) < 0) {
                error_handler(errno);
            }

            ps1_data0 = gpio_get_value(gpio_num);
            ps1_data1 = i2c_read_word_data(i2c_fd, 0x00);

            if (ps1_data0 == 0 && ps1_data1 == 0) {
                break;
            }

            retry_count++;
        }

        if (ret == 0) {
            uint16_t proximity_value = (ps1_data0 << 8) | ps1_data1;
            char timestamp[32];
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);

            char log_filename[32];
            snprintf(log_filename, sizeof(log_filename), "proximity_log_%s.txt", timestamp);

            FILE *log_file = fopen(log_filename, "a");
            if (log_file == NULL) {
                error_handler(errno);
            }

            fprintf(log_file, "Proximity value: %u\n", proximity_value);
            fclose(log_file);
        }

        gpio_set_value(gpio_num, 0);
        gpio_close(gpio_num);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

