#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>

#include <gpiod.h>
#include <pigpio.h>

#define SERVO_PULSE_WIDTH_MIN 500
#define SERVO_PULSE_WIDTH_MAX 2500
#define SERVO_ANGLE_MIN 0
#define SERVO_ANGLE_MAX 180
#define SERVO_ANGLE_INTERP_FACTOR 0.01

int main() {
    int gpio_fd;
    struct gpiod_event_attr attr;
    struct gpiod_event event;
    int distance, angle;
    int timeout;
    int servo_angle;
    int servo_direction;
    int servo_pwm_duty;
    int servo_pwm_freq;
    int servo_pwm_timeout;

    // Initialize GPIO and PWM
    gpio_fd = gpiod_get_fd(23);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO23\n");
        return 1;
    }

    gpio_fd = gpiod_get_fd(24);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO24\n");
        return 1;
    }

    // Initialize PWM
    gpio_fd = gpiod_get_fd(18);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO18\n");
        return 1;
    }

    gpio_pwm_freq(gpio_fd, 100);
    gpio_pwm_duty(gpio_fd, 0);

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Initialize pigpio
    if (gpio_set_mode(gpio_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as output\n");
        return 1;
    }

    // Initialize pigpio for PWM
    if (gpio_set_mode(gpio_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as output\n");
        return 1;
    }

    if (gpio_set_dir(gpio_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 as output\n");
        return 1;
    }

    // Set PWM duty
    if (gpio_pwm_duty(gpio_fd, 0) < 0) {
        fprintf(stderr, "Failed to set PWM duty on GPIO18\n");
        return 1;
    }

    // Set PWM frequency
    if (gpio_pwm_freq(gpio_fd, 100) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO18\n");
        return 1;
    }

    // Set servo angle
    servo_angle = 0;
    servo_direction = 1;

    // Main loop
    while (1) {
        // Get distance and angle from sensor
        distance = -1;
        timeout = 0;

        // Trigger the sensor
        gpio_set_value(gpio_fd, 1);
        gpio_delay_us(10);
        gpio_set_value(gpio_fd, 0);
        gpio_delay_us(10);

        // Wait for rising and falling edges
        while (gpio_get_value(gpio_fd) == 0) {
            gpio_delay_us(10);
        }

        while (gpio_get_value(gpio_fd) == 1) {
            gpio_delay_us(10);
        }

        timeout = (distance / 2) * 50;

        // Check if timeout occurred
        if (timeout > 50) {
            distance = -1.0;
        }

        // Map distance to servo angle
        if (distance < 20) {
            servo_angle = 0;
        } else if (distance > 200) {
            servo_angle = 180;
        } else {
            servo_angle = (distance - 20) * SERVO_ANGLE_INTERP_FACTOR;
        }

        // Set servo angle
        if (gpio_pwm_duty(gpio_fd, servo_direction) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
            return 1;
        }

        if (gpio_pwm_duty(gpio_fd, servo_angle) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
            return 1;
        }

        // Sleep for 100 ms
        sleep(100);

        // Check for SIGINT
        if (signal(SIGINT, sig_handler) == SIG_ERR) {
            fprintf(stderr, "Failed to set SIGINT handler\n");
            return 1;
        }

        // Set servo angle to 0 degrees
        if (gpio_pwm_duty(gpio_fd, 0) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
            return 1;
        }

        if (gpio_pwm_duty(gpio_fd, 0) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
            return 1;
        }

        // Release resources
        gpio_close(gpio_fd);
        gpiod_exit();
    }

    return 0;
}

