#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS_NUM 1
#define SENSOR_ADDRESS 0x40

int main() {
    int i2c_fd, gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct i2c_rdwr_ioctl_data i2c_msgs_gpio[2];
    struct i2c_msg i2c_msg;
    int ret;

    // Initialize GPIO and I2C
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_fd, GPIO_I2C_SLAVE, I2C_BUS_NUM) < 0) {
        perror("Failed to set I2C bus number");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c-1");
        exit(EXIT_FAILURE);
    }

    // Initialize the Si7005 sensor
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    // Perform sensor initialization
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    // Open the I2C handle for reading and writing
    if (ioctl(i2c_fd, I2C_RDWR, 1) < 0) {
        perror("Failed to set I2C mode");
        exit(EXIT_FAILURE);
    }

    // Perform I2C read and write operations
    for (;;) {
        // Write the CONFIG register
        i2c_msgs[0].addr = SENSOR_ADDRESS;
        i2c_msgs[0].flags = 0;
        i2c_msgs[0].len = 1;
        i2c_msgs[0].buf = &i2c_msgs_gpio[0].buf[0];
        i2c_msgs[0].buf_len = 1;
        i2c_msgs[0].timeout = 10;
        ret = ioctl(i2c_fd, I2C_RDWR, I2C_RDWR);
        if (ret < 0) {
            perror("Failed to write CONFIG register");
            exit(EXIT_FAILURE);
        }

        // Wait 10 ms
        usleep(10000);

        // Write the register address to be read
        i2c_msgs[1].addr = SENSOR_ADDRESS;
        i2c_msgs[1].flags = 0;
        i2c_msgs[1].len = 1;
        i2c_msgs[1].buf = &i2c_msgs_gpio[1].buf[0];
        i2c_msgs[1].buf_len = 1;
        i2c_msgs[1].timeout = 10;
        ret = ioctl(i2c_fd, I2C_RDWR, I2C_RDWR);
        if (ret < 0) {
            perror("Failed to write register address");
            exit(EXIT_FAILURE);
        }

        // Wait for conversion
        usleep(10000);

        // Perform I2C read
        i2c_msgs[2].addr = SENSOR_ADDRESS;
        i2c_msgs[2].flags = 0;
        i2c_msgs[2].len = 1;
        i2c_msgs[2].buf = &i2c_msgs_gpio[2].buf[0];
        i2c_msgs[2].buf_len = 1;
        i2c_msgs[2].timeout = 10;
        ret = ioctl(i2c_fd, I2C_RDWR, I2C_RDWR);
        if (ret < 0) {
            perror("Failed to perform I2C read");
            exit(EXIT_FAILURE);
        }

        // Print the sensor data to the console
        printf("Humidity: %d%%\n", i2c_msgs_gpio[2].buf[0]);
        printf("Temperature: %d°C\n", i2c_msgs_gpio[2].buf[1]);

        // Wait 2 seconds
        usleep(200000);
    }

    // Close the I2C handle and the GPIO handle
    close(i2c_fd);
    close(gpio_fd);

    return 0;
}

