#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS_NUM 1
#define I2C_SCL_GPIO_NUM 3
#define I2C_SDA_GPIO_NUM 2

int main() {
    int rc;
    int i;
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    uint16_t i2c_buf[4];
    int16_t accelerometer_data[3];
    int16_t gyroscope_data[3];
    int16_t temperature;

    // Initialize GPIOs
    if (gpio_request_from_mem(I2C_SDA_GPIO_NUM, I2C_SDA_GPIO_NUM, 1, "i2c-gpio")) {
        fprintf(stderr, "Failed to request GPIOs\n");
        return 1;
    }
    if (gpio_request_from_mem(I2C_SCL_GPIO_NUM, I2C_SCL_GPIO_NUM, 1, "i2c-gpio")) {
        fprintf(stderr, "Failed to request GPIOs\n");
        return 1;
    }

    // Initialize I2C bus
    if ((rc = gpio_request_mem_region(I2C_SDA_GPIO_NUM, 1, "i2c-sda")) < 0) {
        fprintf(stderr, "Failed to request I2C SDA GPIO\n");
        return 1;
    }
    if ((rc = gpio_request_mem_region(I2C_SCL_GPIO_NUM, 1, "i2c-scl")) < 0) {
        fprintf(stderr, "Failed to request I2C SCL GPIO\n");
        return 1;
    }

    // Open I2C bus
    if ((rc = i2c_open(I2C_BUS_NUM, I2C_SDA_GPIO_NUM, I2C_SCL_GPIO_NUM)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Check if MPU-6050 sensor is present
    if (i2c_ioctl(i2c_fd, I2C_RDWR, 0x1B) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return 1;
    }

    // Start reading data
    while (1) {
        // Read data from MPU-6050
        if (i2c_ioctl(i2c_fd, I2C_RDWR, 0x32) < 0) {
            fprintf(stderr, "Failed to read data from MPU-6050\n");
            return 1;
        }

        // Read accelerometer data
        if (i2c_ioctl(i2c_fd, I2C_RDWR, 0x3B) < 0) {
            fprintf(stderr, "Failed to read data from MPU-6050\n");
            return 1;
        }

        // Read gyroscope data
        if (i2c_ioctl(i2c_fd, I2C_RDWR, 0x39) < 0) {
            fprintf(stderr, "Failed to read data from MPU-6050\n");
            return 1;
        }

        // Read temperature
        if (i2c_ioctl(i2c_fd, I2C_RDWR, 0x1A) < 0) {
            fprintf(stderr, "Failed to read data from MPU-6050\n");
            return 1;
        }

        // Print data to console
        printf("Accelerometer X: %d\n", accelerometer_data[0]);
        printf("Accelerometer Y: %d\n", accelerometer_data[1]);
        printf("Accelerometer Z: %d\n", accelerometer_data[2]);
        printf("Temperature: %d\n", temperature);

        // Wait for 100 ms
        sleep(100);
    }

    // Cleanup I2C bus
    i2c_close(i2c_fd);
    gpio_release_mem_region(I2C_SDA_GPIO_NUM, 1);
    gpio_release_mem_region(I2C_SCL_GPIO_NUM, 1);

    return 0;
}

