#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x5A

int i2c_fd;
int gpio_num;

void i2c_init() {
    gpio_num = gpio_request_from_sysfs(I2C_BUS_NUM);
    if (gpio_num < 0) {
        perror("Failed to request GPIO number");
        exit(EXIT_FAILURE);
    }

    if (gpio_setup(gpio_num, GPIO_OUTPUT) < 0) {
        perror("Failed to set up GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpio_direction_output(gpio_num, 0) < 0) {
        perror("Failed to set up I2C direction");
        exit(EXIT_FAILURE);
    }

    gpio_set_level(gpio_num, 1);
    gpio_set_mode(gpio_num, GPIO_I2C);

    i2c_fd = i2c_open(I2C_BUS_NUM);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void i2c_close() {
    if (i2c_fd >= 0) {
        i2c_close(i2c_fd);
        i2c_fd = -1;
    }
}

void i2c_write(uint8_t *data, int len) {
    if (i2c_write(i2c_fd, data, len) < 0) {
        perror("Failed to write to I2C bus");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(uint8_t *data, int len) {
    if (i2c_read(i2c_fd, data, len) < 0) {
        perror("Failed to read from I2C bus");
        exit(EXIT_FAILURE);
    }
}

void i2c_wait_for_response(uint8_t *data, int len) {
    while (len > 0) {
        int bytes_read = i2c_read(i2c_fd, data, len);
        if (bytes_read < 0) {
            perror("Failed to read from I2C bus");
            exit(EXIT_FAILURE);
        }

        if (bytes_read == 0) {
            break;
        }

        len -= bytes_read;
    }
}

void i2c_validate_crc8(uint8_t crc8_expected, uint8_t crc8_received) {
    uint8_t crc8_calculated = crc8_calculate(crc8_expected, 0, 0);
    if (crc8_received == crc8_calculated) {
        printf("CRC8 checksum for temperature and humidity measurements is valid.\n");
    } else {
        printf("CRC8 checksum for temperature and humidity measurements is invalid.\n");
    }
}

void i2c_measure_temperature_humidity() {
    uint8_t temp_data[2];
    uint8_t humidity_data[2];
    uint8_t crc8_expected, crc8_received;

    i2c_write(temp_data, sizeof(temp_data));
    i2c_write(humidity_data, sizeof(humidity_data));

    i2c_wait_for_response(temp_data, sizeof(temp_data));
    i2c_wait_for_response(humidity_data, sizeof(humidity_data));

    i2c_read(temp_data, sizeof(temp_data));
    i2c_read(humidity_data, sizeof(humidity_data));

    crc8_expected = 0x01;
    crc8_received = 0x00;

    i2c_validate_crc8(crc8_expected, crc8_received);

    printf("Temperature: %d\n", temp_data[0]);
    printf("Humidity: %d\n", humidity_data[0]);
}

void i2c_error_handler(int error) {
    perror("I2C error occurred");
    exit(EXIT_FAILURE);
}

int main() {
    i2c_init();

    while (1) {
        i2c_measure_temperature_humidity();
        sleep(5);
    }

    i2c_close();
    return 0;
}

