#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1A // Default address of the MLX90614ESF-BAA sensor

int main() {
    int i2c_fd, log_fd, sensor_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_rdwr_ioctl_data sensor_data;
    struct i2c_rdwr_ioctl_data log_data;
    struct timespec start_time, end_time;
    struct sigaction sa;
    char log_file_name[] = "temperature_log.csv";
    char *log_file_path = NULL;
    char *log_file_path_tmp = NULL;
    char *timestamp = NULL;
    char *sensor_id = NULL;
    char *sensor_data_str = NULL;
    char *log_data_str = NULL;
    int log_data_len = 0;
    int i, j, k;
    int error;

    // Initialize I2C file descriptor
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) == -1) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((log_fd = open(log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644)) == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for SIGINT
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_SIGINFO;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    if (ioctl(sensor_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Error initializing sensor");
        exit(EXIT_FAILURE);
    }

    // Perform sensor read
    if (ioctl(sensor_fd, I2C_RDWR, I2C_RD) == -1) {
        perror("Error reading sensor data");
        exit(EXIT_FAILURE);
    }

    // Get sensor ID
    if (ioctl(sensor_fd, I2C_RDWR, I2C_ID) == -1) {
        perror("Error reading sensor ID");
        exit(EXIT_FAILURE);
    }

    // Get sensor data
    if (ioctl(sensor_fd, I2C_RDWR, I2C_RD) == -1) {
        perror("Error reading sensor data");
        exit(EXIT_FAILURE);
    }

    // Get timestamp
    if (gettimeofday(&start_time, NULL) == -1) {
        perror("Error getting timestamp");
        exit(EXIT_FAILURE);
    }

    // Perform read loop
    while (1) {
        // Get current time
        if (gettimeofday(&end_time, NULL) == -1) {
            perror("Error getting current time");
            exit(EXIT_FAILURE);
        }

        // Calculate time difference
        if (end_time.tv_sec - start_time.tv_sec > 5) {
            // Perform read every 5 seconds
            if (ioctl(sensor_fd, I2C_RDWR, I2C_RD) == -1) {
                perror("Error reading sensor data");
                exit(EXIT_FAILURE);
            }

            // Get sensor data
            if (ioctl(sensor_fd, I2C_RDWR, I2C_RD) == -1) {
                perror("Error reading sensor data");
                exit(EXIT_FAILURE);
            }

            // Get timestamp
            if (gettimeofday(&end_time, NULL) == -1) {
                perror("Error getting current time");
                exit(EXIT_FAILURE);
            }

            // Calculate time difference
            if (end_time.tv_sec - start_time.tv_sec > 5) {
                // Append data to log file
                if ((log_data_len = strlen(log_data)) == -1) {
                    perror("Error getting log data length");
                    exit(EXIT_FAILURE);
                }

                // Append timestamp to log file
                if (strftime(log_data_str, sizeof(log_data_str), "%Y-%m-%d %H:%M:%S", &end_time) == -1) {
                    perror("Error formatting timestamp");
                    exit(EXIT_FAILURE);
                }

                // Append sensor data to log file
                if (strftime(log_data_str + log_data_len, sizeof(log_data_str) - log_data_len, "%Y-%m-%d %H:%M:%S,%3N", &end_time) == -1) {
                    perror("Error formatting timestamp");
                    exit(EXIT_FAILURE);
                }

                // Append comma and newline to log file
                if (fputs(log_data_str, log_file) == EOF) {
                    perror("Error writing to log file");
                    exit(EXIT_FAILURE);
                }

                // Clear log data
                free(log_data_str);
                log_data_str = NULL;
                log_data_len = 0;
            }

            // Release I2C file descriptor
            close(sensor_fd);
            sensor_fd = -1;
        }

        // Release I2C file descriptor
        close(i2c_fd);
        i2c_fd = -1;
    }

    // Clean up
    if (log_file != NULL) {
        if (close(log_fd) == -1) {
            perror("Error closing log file");
            exit(EXIT_FAILURE);
        }
    }

    if (log_file_path != NULL) {
        free(log_file_path);
    }

    if (log_file_path_tmp != NULL) {
        free(log_file_path_tmp);
    }

    if (sensor_id != NULL) {
        free(sensor_id);
    }

    if (sensor_data_str != NULL) {
        free(sensor_data_str);
    }

    if (log_data_str != NULL) {
        free(log_data_str);
    }

    return 0;
}

