    // Initialize sensor
    if (ioctl(sensor_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Error initializing sensor");
        exit(EXIT_FAILURE);
    }

    // Perform sensor read
    if (ioctl(sensor_fd, I2C_RDWR, I2C_RD) == -1) {
        perror("Error reading sensor data");
        exit(EXIT_FAILURE);
    }

    // Get sensor ID
    if (ioctl(sensor_fd, I2C_RDWR, I2C_ID) == -1) {
        perror("Error reading sensor ID");
        exit(EXIT_FAILURE);
    }

    // Get sensor data
    if (ioctl(sensor_fd, I2C_RDWR, I2C_RD) == -1) {
        perror("Error reading sensor data");
        exit(EXIT_FAILURE);
    }

    // Get timestamp
    if (gettimeofday(&start_time, NULL) == -1) {
        perror("Error getting timestamp");
        exit(EXIT_FAILURE);
    }

    // Perform read loop
    while (1) {
        // Get current time
        if (gettimeofday(&end_time, NULL) == -1) {
            perror("Error getting current time");
            exit(EXIT_FAILURE);
        }

        // Calculate time difference
        if (end_time.tv_sec - start_time.tv_sec > 5) {
            // Perform read every 5 seconds
            if (ioctl(sensor_fd, I2C_RDWR, I2C_RD) == -1) {
                perror("Error reading sensor data");
                exit(EXIT_FAILURE);
            }

            // Get sensor data
            if (ioctl(sensor_fd, I2C_RDWR, I2C_RD) == -1) {
                perror("Error reading sensor data");
                exit(EXIT_FAILURE);
            }

            // Get timestamp
            if (gettimeofday(&end_time, NULL) == -1) {
                perror("Error getting current time");
                exit(EXIT_FAILURE);
            }

            // Calculate time difference
            if (end_time.tv_sec - start_time.tv_sec > 5) {
                // Append data to log file
                if ((log_data_len = strlen(log_data)) == -1) {
                    perror("Error getting log data length");
                    exit(EXIT_FAILURE);
                }

                // Append timestamp to log file
                if (strftime(log_data_str, sizeof(log_data_str), "%Y-%m-%d %H:%M:%S", &end_time) == -1) {
                    perror("Error formatting timestamp");
                    exit(EXIT_FAILURE);
                }

                // Append sensor data to log file
                if (strftime(log_data_str + log_data_len, sizeof(log_data_str) - log_data_len, "%Y-%m-%d %H:%M:%S,%3N", &end_time) == -1) {
                    perror("Error formatting timestamp");
                    exit(EXIT_FAILURE);
                }

                // Append comma and newline to log file
                if (fputs(log_data_str, log_file) == EOF) {
                    perror("Error writing to log file");
                    exit(EXIT_FAILURE);
                }

                // Clear log data
                free(log_data_str);
                log_data_str = NULL;
                log_data_len = 0;
            }

            // Release I2C file descriptor
            close(sensor_fd);
            sensor_fd = -1;
        }

        // Release I2C file descriptor
        close(i2c_fd);
        i2c_fd = -1;
    }

    // Clean up
    if (log_file != NULL) {
        if (close(log_fd) == -1) {
            perror("Error closing log file");
            exit(EXIT_FAILURE);
        }
    }

