#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x5A

#define I2C_SCL_GPIO_PIN 3
#define I2C_SDA_GPIO_PIN 2

#define I2C_FILE_DESC "/dev/i2c-1"
#define I2C_LOG_FILE_NAME "sht40_log.txt"

#define I2C_TIMEOUT_MS 1000

#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0x00

#define SENSIRION_HIGH_REPEATABILITY_COMMAND 0x55

void i2c_write(int file_desc, uint8_t address, const uint8_t* data, int num_bytes) {
    if (ioctl(file_desc, I2C_SLAVE, address) < 0) {
        perror("Error while writing to I2C device");
        exit(EXIT_FAILURE);
    }

    if (write(file_desc, data, num_bytes) != num_bytes) {
        perror("Error while writing to I2C device");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(int file_desc, uint8_t address, uint8_t* data, int num_bytes) {
    if (ioctl(file_desc, I2C_SLAVE, address) < 0) {
        perror("Error while reading from I2C device");
        exit(EXIT_FAILURE);
    }

    if (read(file_desc, data, num_bytes) != num_bytes) {
        perror("Error while reading from I2C device");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int file_desc;
    int i;
    int retries = 0;
    int log_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    uint8_t i2c_buf[2];
    uint8_t crc_buf[2];
    uint8_t high_repeatability_cmd = SENSIRION_HIGH_REPEATABILITY_COMMAND;
    uint8_t high_repeatability_data[2];
    uint8_t crc_calculated;
    uint8_t crc_expected;
    uint8_t log_data[6];
    struct timespec start_time, end_time;
    int log_interval = 5;

    if ((file_desc = open(I2C_FILE_DESC, O_RDWR | O_NONBLOCK)) < 0) {
        perror("Error while opening I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(file_desc, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Error while setting I2C device address");
        exit(EXIT_FAILURE);
    }

    if ((log_fd = open(I2C_LOG_FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Error while opening log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (retries > 10) {
            perror("Error while reading from I2C device");
            exit(EXIT_FAILURE);
        }

        if (ioctl(file_desc, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("Error while setting I2C device address");
            exit(EXIT_FAILURE);
        }

        i2c_write(file_desc, I2C_ADDR, &high_repeatability_cmd, 1);
        i2c_write(file_desc, I2C_ADDR, &high_repeatability_data, 1);

        if (ioctl(file_desc, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("Error while setting I2C device address");
            exit(EXIT_FAILURE);
        }

        i2c_read(file_desc, I2C_ADDR, i2c_buf, 2);

        if (i2c_buf[0] != high_repeatability_data[0] || i2c_buf[1] != high_repeatability_data[1]) {
            perror("Error while reading from I2C device");
            exit(EXIT_FAILURE);
        }

        i2c_read(file_desc, I2C_ADDR, i2c_buf, 2);

        crc_calculated = (i2c_buf[0] << 8) | i2c_buf[1];
        crc_expected = CRC_INITIAL_VALUE;

        for (i = 0; i < 2; i++) {
            crc_buf[i] = crc_calculated >> 8;
            crc_calculated <<= 8;
        }

        for (i = 0; i < 2; i++) {
            crc_buf[i] = crc_calculated & 0xFF;
            crc_calculated >>= 8;
        }

        if (crc_calculated != 0) {
            crc_expected ^= 0xFF;
        }

        if (crc_calculated == crc_expected) {
            printf("Temperature: %d.%02d\n", (int)((high_repeatability_data[0] & 0xF0) >> 4) * 100, (int)(high_repeatability_data[0] & 0x0F));
            printf("Humidity: %d.%02d\n", (int)((high_repeatability_data[1] & 0xF0) >> 4) * 100, (int)(high_repeatability_data[1] & 0x0F));
            printf("Timestamp: %lld\n", (long long)gettimeofday(&start_time, NULL));

            nanosleep(&start_time, NULL);

            i2c_read(file_desc, I2C_ADDR, i2c_buf, 2);

            for (i = 0; i < 2; i++) {
                log_data[i] = i2c_buf[i];
            }

            if (write(log_fd, log_data, 6) < 0) {
                perror("Error while writing to log file");
                exit(EXIT_FAILURE);
            }

            nanosleep(&end_time, NULL);

            retries++;
        }

        if (retries > 10) {
            perror("Error while reading from I2C device");
            exit(EXIT_FAILURE);
        }

        if (ioctl(file_desc, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("Error while setting I2C device address");
            exit(EXIT_FAILURE);
        }
    }

    close(file_desc);
    close(log_fd);

    return 0;
}

