#include <linux/i2c-dev.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDRESS 0x5A

volatile sig_atomic_t stop = 0;

void i2c_write(int file, const uint8_t* data, int len) {
    int ret;
    struct i2c_msg msg[1];
    msg->addr = I2C_ADDRESS;
    msg->flags = 0;
    msg->len = len;
    msg->buf = data;

    do {
        ret = ioctl(file, I2C_SLAVE, I2C_ADDRESS);
        if (ret < 0) {
            perror("Failed to set I2C address");
            exit(EXIT_FAILURE);
        }

        ret = i2c_transfer(file, msg, 2);
        if (ret < 0) {
            perror("Failed to write to I2C device");
            exit(EXIT_FAILURE);
        }
    } while (ret == -EINTR);
}

void i2c_read(int file, uint8_t* data, int len) {
    int ret;
    struct i2c_msg msg[2];
    msg->addr = I2C_ADDRESS;
