#define SDP800_CMD_CONT_MEASURE_RESPONSE 0x0E
#define SDP800_CMD_READ_DATA_RESPONSE 0x0F
#define SDP800_CMD_READ_DATA_RESPONSE_CRC 8
#define SDP800_CMD_READ_DATA_RESPONSE_CRC8 9

#define SDP800_DATA_LEN 6
#define SDP800_DATA_CRC_LEN 1

#define I2C_TIMEOUT_MS 1000

#define BUF_SIZE 1024

