    int i2c_fd, gpio_fd, log_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_mem *gpio_mem;
    struct gpio_mem_range gpio_range;
    struct gpio_mem_range *gpio_range_ptr;
    struct i2c_msg i2c_msgs[2];
    struct i2c_rdwr_ioctl_data i2c_msgs_data;
    uint8_t i2c_buf[BUF_SIZE];
    uint8_t gpio_buf[BUF_SIZE];
    uint8_t crc_buf[BUF_SIZE];
    uint8_t crc_calc[SDP800_DATA_CRC_LEN];
    uint16_t pressure_msb, pressure_lsb, temperature_msb, temperature_lsb;
    uint16_t pressure_raw, temperature_raw;
    uint8_t crc_calculated;
    char timestamp[80];
    char log_file_name[] = "airflow_data.txt";
    FILE *log_file;

    // Initialize I2C and GPIO
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    gpio_range_ptr = mmap(NULL, sizeof(struct gpio_mem_range),
                         PROT_READ | PROT_WRITE, MAP_SHARED, gpio_fd, 0);
    if (gpio_range_ptr == MAP_FAILED) {
        perror("Failed to map GPIO memory");
        exit(EXIT_FAILURE);
    }

    gpio_mem = (struct gpio_mem *)gpio_range_ptr;
    gpio_mem->base = (uint32_t)gpio_range_ptr;
    gpio_mem->length = sizeof(struct gpio_mem);

    // Open log file
    log_file = fopen(log_file_name, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C communication
    if (ioctl(i2c_fd, I2C_RDWR, I2C_ADDR) < 0) {
