        goto end;
    }

    ret = read(fd, data, 10);
    if (ret < 0) {
        perror("Failed to read temperature data");
        goto end;
    }

    if (data[0] < 0 || data[1] < 0) {
        ret = -1;
        goto end;
    }

    if (data[0] > 0 && data[1] > 0) {
        float temperature = (float)(data[0] + data[1]) / 2;
