        if (celsius < -40 || celsius > 150) {
            ret = -1;
            goto end;
        }

        printf("Temperature: %.2f °C\n", celsius);
        printf("ISO-8601 timestamp: %s\n", ctime(&ts.tv_sec));
    }

end:
    gpio_close(fd);
    gpio_init();

    return ret;
}

