#include <gpiod.h>
#include <pigpio.h>

#define SENSOR_ADDRESS 0x44 // Sensirion SHT35-DIS-B sensor I2C address
#define I2C_BUS_NUM 1 // I2C bus number (1 for Raspberry Pi Zero W)

// Function prototypes
void init_gpio(int *gpio_num);
void init_i2c(int *i2c_num);
void cleanup_gpio();
void cleanup_i2c();
void read_sensor_data();
void write_to_csv(const char *filename, uint16_t timestamp, float temperature, float humidity);

int main() {
    int i2c_num;
    int gpio_num;
    int fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_desc *gpio_desc;
    struct gpio_value gpio_value;
    uint8_t i2c_buf[2];
    uint8_t crc_buf[2];
    uint8_t crc_result;
