    struct timespec ts;
    struct timespec start_time;
    struct timespec end_time;
    float temperature, humidity;

    // Initialize GPIO and I2C
    init_gpio(&gpio_num);
    init_i2c(&i2c_num);

    // Open I2C file descriptor
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        cleanup_gpio();
        cleanup_i2c();
        return 1;
    }

