#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_1 1
#define I2C_ADDRESS 0x5A

int main() {
    int i2c_fd;
    struct gpiod_i2c_config i2c_config = {
        .speed = GPIDO_SPEED_100KHZ,
        .address = I2C_ADDRESS,
    };

    gpio_init();
    gpio_set_mode(GPIO_SDP810_POWER, GPIO_MODE_OUTPUT);
    gpio_set_dir(GPIO_SDP810_POWER, GPIO_OUTPUT);

    i2c_fd = gpiod_i2c_open(I2C_BUS_1, &i2c_config);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initiate continuous measurement
    if (gpio_set_level(GPIO_SDP810_POWER, 1) < 0) {
        fprintf(stderr, "Failed to turn on power: %s\n", strerror(errno));
        gpiod_i2c_close(i2c_fd);
        return 1;
    }

    // Wait for the required conversion time
    gpio_set_level(GPIO_SDP810_POWER, 0);
    sleep(1);
    gpio_set_level(GPIO_SDP810_POWER, 1);

    // Read 9-byte response
    uint8_t response[9];
    if (gpio_i2c_read(i2c_fd, I2C_SDP810_RESPONSE, response, 9) < 0) {
        fprintf(stderr, "Failed to read response: %s\n", strerror(errno));
        gpiod_i2c_close(i2c_fd);
        gpio_cleanup();
        return 1;
    }

    // Validate CRC-8 for both pressure and temperature raw values
    uint8_t pressure_crc = 0;
    uint8_t temperature_crc = 0;
    for (int i = 0; i < 9; i++) {
        pressure_crc += response[i];
        temperature_crc += response[i + 1];
    }
    if (crc8(pressure_crc, 8) != response[7] || crc8(temperature_crc, 8) != response[8]) {
        fprintf(stderr, "CRC-8 validation failed for pressure and temperature values\n");
        gpiod_i2c_close(i2c_fd);
        gpio_cleanup();
        return 1;
    }

    // Convert raw data to floating-point pressure (Pa) and temperature (°C)
    float pressure = (float)response[1] / 65536.0 * (float)response[0] / 65536.0;
    float temperature = (float)response[3] / 65536.0 * (float)response[2] / 65536.0;

    // Log each sample once per second
    FILE *log_file = fopen("airflow.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_i2c_close(i2c_fd);
        gpio_cleanup();
        return 1;
    }

    char log_line[32];
    sprintf(log_line, "%.6f %.6f\n", pressure, temperature);
    fputs(log_line, log_file);
    fclose(log_file);

    // Close I2C handle, driver, and file
    gpiod_i2c_close(i2c_fd);
    gpio_cleanup();
    return 0;
}

