#include <unistd.h>
#include <sys/time.h>

#include <gpiod.h>

volatile sig_atomic_t stop_flag;

int main() {
    int i2c_fd;
    struct gpiod_i2c_platform_data *pdata;
    struct gpiod_i2c_channel *channel;
    struct gpiod_i2c_channel_config channel_config;
    struct gpiod_i2c_channel_data channel_data;
    struct gpiod_i2c_channel_info channel_info;
    struct timespec start_time, end_time;
    char log_file_name[] = "environmental_data.txt";
    char error_message[256];

    // Initialize I2C bus
    if ((i2c_fd = gpiod_i2c_open("/dev/i2c-1")) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C channel
    pdata = gpiod_i2c_get_platform_data(i2c_fd);
    if (!pdata) {
        perror("Failed to get platform data");
        exit(EXIT_FAILURE);
    }
    channel = gpiod_i2c_get_channel(i2c_fd, pdata->channel);
    if (!channel) {
        perror("Failed to get channel");
        exit(EXIT_FAILURE);
    }

    // Configure channel
    channel_config.direction = GPIGPIO_OUTPUT;
    channel_config.pull_up_en = GPIGPIO_PULLUP_DISABLE;
    channel_config.pull_down_en = GPIGPIO_PULLDOWN_DISABLE;
    channel_config.intr_type = GPIGPIO_INTR_FALLING;
    channel_config.intr_polarity = GPIGPIO_INTR_ACTIVE_LOW;
    channel_config.intr_debounce = GPIGPIO_INTR_DEBOUNCE_50NS;
    channel_config.intr_edge = GPIGPIO_INTR_FALLING;
    channel_config.intr_type_mask = GPIGPIO_INTR_ALL;
    channel_config.intr_debounce_mask = GPIGPIO_INTR_ALL;
    channel_config.intr_edge_mask = GPIGPIO_INTR_ALL;

    if (gpiod_i2c_channel_config(channel, &channel_config) < 0) {
        perror("Failed to configure channel");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C channel data
    channel_data.data_out_msb = 0;
    channel_data.data_out_lsb = 0;
    channel_data.data_out_flags = GPIGPIO_DATA_OUT_MSB_FIRST;
    channel_data.data_out_width = GPIGPIO_DATA_OUT_8_BIT;
    channel_data.data_in_msb = 0;
    channel_data.data_in_lsb = 0;
    channel_data.data_in_flags = GPIGPIO_DATA_IN_MSB_FIRST;
    channel_data.data_in_width = GPIGPIO_DATA_IN_8_BIT;

    // Initialize time-related variables
    struct timespec start_time, end_time;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    start_time.tv_sec = tv.tv_sec;
    start_time.tv_nsec = tv.tv_nsec;

    // Main loop
    while (1) {
        // Read pressure and temperature data
        if (gpiod_i2c_channel_data(channel, &channel_data) < 0) {
            perror("Failed to read channel data");
            exit(EXIT_FAILURE);
        }

        // Get current time
        gettimeofday(&tv, NULL);
        end_time.tv_sec = tv.tv_sec;
        end_time.tv_nsec = tv.tv_nsec;
        tv.tv_sec = end_time.tv_sec - start_time.tv_sec;
        tv.tv_nsec = end_time.tv_nsec - start_time.tv_nsec;
        tv.tv_usec = end_time.tv_usec - start_time.tv_usec;

        // Convert time to local time
        struct timespec local_start_time, local_end_time;
        gettimeofday(&local_start_time, NULL);
        local_start_time.tv_sec = local_start_time.tv_sec - start_time.tv_sec;
        local_start_time.tv_nsec = local_start_time.tv_nsec - start_time.tv_nsec;
        tv.tv_sec = local_start_time.tv_sec;
        tv.tv_nsec = local_start_time.tv_nsec;
        tv.tv_usec = local_start_time.tv_usec - start_time.tv_usec;

        // Log data
        if (snprintf(error_message, sizeof(error_message),
                     "%s, Pressure: %.2f hPa, Temperature: %.2f °C",
                     localtime_r(&tv.tv_sec), channel_data.data_out_msb,
                     channel_data.data_out_lsb) >= sizeof(error_message)) {
            if (write(1, error_message, sizeof(error_message)) < 0) {
                perror("Failed to write error message to log file");
                exit(EXIT_FAILURE);
            }
        }

        // Flush log file
        if (fdatasync(1) < 0) {
            perror("Failed to sync log file");
            exit(EXIT_FAILURE);
        }

        // Check for errors
        if (gpiod_i2c_channel_data(channel, &channel_data) < 0) {
            perror("Failed to read channel data");
            exit(EXIT_FAILURE);
        }

        // Check if stop flag is set
        if (stop_flag) {
            break;
        }
    }

    // Clean up I2C channel
    if (gpiod_i2c_channel_data(channel, &channel_data) < 0) {
        perror("Failed to clean up I2C channel");
        exit(EXIT_FAILURE);
    }

    // Clean up I2C bus
    if (gpiod_i2c_close(i2c_fd) < 0) {
        perror("Failed to close I2C bus");
        exit(EXIT_FAILURE);
    }

    return 0;
}

