#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>
#include <pigpio.h>

#define LED_GPIO 17

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_rdwr_ioctl_data *i2c_data_ptr;
    int i2c_ret;
    int i2c_addr;
    int i;
    int running_avg;
    int last_reading;
    int running_sum = 0;
    int threshold = 28;

    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        printf("Error: Failed to initialize GPIO.\n");
        return 1;
    }

    if (i2cInit() < 0) {
        printf("Error: Failed to initialize I2C.\n");
        return 1;
    }

    // Open I2C bus
    i2c_addr = 0x48; // STLM75 sensor address
    i2c_fd = i2cOpen(i2c_addr);
    if (i2c_fd < 0) {
        printf("Error: Failed to open I2C bus.\n");
        return 1;
    }

    // Initialize circular buffer
    int buffer_size = 10;
    int buffer[buffer_size];
    int buffer_index = 0;
    int buffer_length = 0;

    // Initialize running average
    running_avg = 0;

    // Main loop
    while (true) {
        // Read temperature from the sensor
        i2c_ret = i2c_read(i2c_fd, &i2c_data, sizeof(i2c_data), &i2c_data_ptr);
        if (i2c_ret < 0) {
            printf("Error: Failed to read temperature from the sensor.\n");
            continue;
        }

        // Check if the read was successful
        if (i2c_data_ptr->wr_len != sizeof(i2c_data)) {
            printf("Error: Failed to read temperature from the sensor.\n");
            continue;
        }

        // Compute running average
        running_sum += i2c_data_ptr->buf[0];
        running_avg = running_sum / buffer_length;

        // Check if the average temperature exceeds the threshold
        if (running_avg > threshold) {
            gpioSetValue(LED_GPIO, 1); // Turn LED on
        } else {
            gpioSetValue(LED_GPIO, 0); // Turn LED off
        }

        // Store the reading in the circular buffer
        buffer[buffer_index++] = i2c_data_ptr->buf[0];
        if (buffer_index >= buffer_size) {
            buffer_index = 0;
        }

        // Check if the buffer is full
        if (buffer_length == buffer_size) {
            // Clear the buffer
            for (i = 0; i < buffer_size; i++) {
                buffer[i] = 0;
            }
            buffer_length = 0;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    gpioTerminate();
    i2cClose(i2c_fd);

    return 0;
}

