    rc = pigpio_set_nonblock(I2C_ADDRESS);
    if (rc < 0) {
        printf("Error setting I2C address: %d\n", rc);
        pigpio_exit();
        return;
    }

    // Enable I2C bus
    rc = pigpio_set_speed(I2C_BUS_NUM, 100000);
    if (rc < 0) {
        printf("Error setting I2C speed: %d\n", rc);
        pigpio_exit();
        return;
    }
}

void i2c_cleanup(void) {
    int rc;

    // Disable I2C bus
    rc = pigpio_set_speed(I2C_BUS_NUM, 0);
    if (rc < 0) {
        printf("Error disabling I2C bus: %d\n", rc);
        return;
    }

    // Release I2C pins
    rc = pigpio_release(I2C_SDA_GPIO_NUM);
    if (rc < 0) {
        printf("Error releasing I2C SDA GPIO: %d\n", rc);
        return;
    }

    rc = pigpio_release(I2C_SCL_GPIO_NUM);
    if (rc < 0) {
        printf("Error releasing I2C SCL GPIO: %d\n", rc);
        return;
    }

    // Release I2C bus
    rc = pigpio_exit();
    if (rc < 0) {
        printf("Error exiting pigpio: %d\n", rc);
        return;
    }
}

void read_sensor(void) {
    int rc;
    uint8_t data[4];
    uint8_t crc;
    uint8_t i;

    // Wait for the sensor to be ready
    while (!pigpio_is_connected()) {
        usleep(500000);
    }

    // Perform 9-byte read
    rc = pigpio_i2c_write(I2C_ADDRESS, I2C_SDA_GPIO_NUM, I2C_SCL_GPIO_NUM, I2C_READ_TIMEOUT, data, 4);
