#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_SLAVE_ADDRESS 0x48 // Si7051 I2C address

int main() {
    int fd;
    int gpio_num = 2; // GPIO2 (BCM) for SDA
    int i2c_gpio_num = 3; // GPIO3 (BCM) for SCL
    int i2c_gpio_dir_mask = 1 << i2c_gpio_num;

    gpio_init(gpio_num);
    gpio_set_direction(gpio_num, i2c_gpio_dir_mask);

    gpio_set_mode(gpio_num, GPIO_OUTPUT);
    gpio_set_level(gpio_num, 0);

    gpio_set_mode(i2c_gpio_num, GPIO_OUTPUT);
    gpio_set_level(i2c_gpio_num, 0);

    gpio_set_mode(gpio_num, GPIO_IN);
    gpio_set_level(gpio_num, 1);

    gpio_set_mode(i2c_gpio_num, GPIO_IN);
    gpio_set_level(i2c_gpio_num, 0);

    gpio_set_interrupt_type(gpio_num, GPIO_INT_EDGE_FALLING);
    gpio_set_interrupt_type(i2c_gpio_num, GPIO_INT_EDGE_FALLING);

    gpio_set_interrupt_mode(gpio_num, GPIO_INT_TYPE_EDGE_FALLING);
    gpio_set_interrupt_mode(i2c_gpio_num, GPIO_INT_TYPE_EDGE_FALLING);

    gpio_set_interrupt_handler(gpio_num, GPIO_INT_EDGE_FALLING, GPIO_INT_EDGE_FALLING,
                               gpio_interrupt_handler);
    gpio_set_interrupt_handler(i2c_gpio_num, GPIO_INT_EDGE_FALLING, GPIO_INT_EDGE_FALLING,
                               gpio_interrupt_handler);

    gpio_set_interrupt_trigger(gpio_num, GPIO_INT_FALLING);
    gpio_set_interrupt_trigger(i2c_gpio_num, GPIO_INT_FALLING);

    gpio_set_interrupt_edge(gpio_num, GPIO_INT_FALLING);
    gpio_set_interrupt_edge(i2c_gpio_num, GPIO_INT_FALLING);

    gpio_set_interrupt_debounce(gpio_num, GPIO_DEBOUNCE_50);
    gpio_set_interrupt_debounce(i2c_gpio_num, GPIO_DEBOUNCE_50);

    fd = gpio_open(I2C_SLAVE_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_i2c_config config = {
        .address = I2C_SLAVE_ADDRESS,
        .gpio_num = I2C_SLAVE_ADDRESS,
        .gpio_dir_mask = i2c_gpio_dir_mask,
    };

    if (gpio_i2c_config(fd, &config) < 0) {
        fprintf(stderr, "Failed to configure I2C device: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_i2c_data data = {
        .timeout_ms = 100,
        .timeout_usec = 100,
    };

    if (gpio_i2c_read(fd, &data) < 0) {
        fprintf(stderr, "Failed to read data from I2C device: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_i2c_data temp_data = {
        .timeout_ms = 100,
        .timeout_usec = 100,
    };

    if (gpio_i2c_read(fd, &temp_data) < 0) {
        fprintf(stderr, "Failed to read temperature data from I2C device: %s\n", strerror(errno));
        return 1;
    }

    int temperature_celsius = (int)((temp_data.data >> 4) * 100);

    printf("Temperature: %.2f Celsius\n", temperature_celsius);

    gpio_close(fd);

    return 0;
}

