#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x76

int i2c_fd;
int gpio_fd;

void i2c_init() {
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        exit(1);
    }

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        exit(1);
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address.\n");
        exit(1);
    }
}

void i2c_cleanup() {
    close(i2c_fd);
    gpio_exit();
}

void read_sensor() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_value value;

    chip = gpiod_chip_open(I2C_BUS);
    if (!chip) {
        fprintf(stderr, "Failed to open I2C chip.\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, "i2c-gpio");
    if (!line) {
        fprintf(stderr, "Failed to get I2C line.\n");
        exit(1);
    }

    if (gpiod_line_read(line, &value) < 0) {
        fprintf(stderr, "Failed to read sensor value.\n");
        exit(1);
    }

    if (value.value == -1) {
        fprintf(stderr, "Sensor absent condition detected.\n");
        exit(1);
    }

    // Assuming the sensor returns pressure in Pa and temperature in °C
    float pressure = value.value;
    float temperature = (value.value - 32768) / 65536 * 175 - 25;

    printf("2024-01-15T14:30:00 - Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
}

int main() {
    i2c_init();

    while (1) {
        read_sensor();
        sleep(7);
    }

    i2c_cleanup();
    return 0;
}

