This program initializes the I2C bus and GPIO, reads the sensor data, and prints the results to stdout. It also handles sensor absence and I2C driver errors. The program installs a SIGINT handler to close the I2C handle and invoke the cleanup function on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x5A // Melexis MLX90819 sensor I2C address

int main() {
    int i2c_fd;
    int gpio_fd;
    int sensor_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_mem_config gpio_config;
    struct gpio_mem_data gpio_data;
    char buffer[32];
    char *sensor_name = "Melexis MLX90819";
    int sensor_present = 0;
    int error = 0;
    int sigint_handler(int signum) {
        fprintf(stderr, "Received SIGINT\n");
        gpio_close(sensor_fd);
        gpio_close(gpio_fd);
        gpio_unexport(sensor_fd);
        gpio_unexport(gpio_fd);
        gpio_release(gpio_fd);
        gpio_release(sensor_fd);
        exit(0);
    }

    gpio_init();
    gpio_set_mode(sensor_fd, GPIO_OUTPUT);
    gpio_set_dir(sensor_fd, GPIO_OUTPUT);

    gpio_mem_config_t gpio_config_data;
    gpio_mem_config_init(&gpio_config_data);
    gpio_config_data.gpio_base = sensor_fd;
    gpio_config_data.gpio_speed = GPIO_SPEED_FREQ_HIGH;
    gpio_config_data.gpio_io_type = GPIO_IO_TYPE_DIGITAL;
    gpio_config_data.gpio_io_standard = GPIO_IO_STANDARD_I2C;
    gpio_config_data.gpio_sda_io_num = 10;
    gpio_config_data.gpio_scl_io_num = 9;
    gpio_config_data.gpio_pull_up_en = GPIO_PULLUP_ENABLE;
    gpio_config_data.gpio_pull_down_en = GPIO_PULLDOWN_DISABLE;
    gpio_config_data.gpio_intr_type = GPIO_INTR_TYPE_EDGE;
    gpio_config_data.gpio_intr_edge = GPIO_INTR_EDGE_FALLING;
    gpio_mem_config(&gpio_config_data);

    gpio_mem_data_t gpio_data_data;
    gpio_mem_data_init(&gpio_data_data);
    gpio_data_data.gpio_base = sensor_fd;
    gpio_data_data.gpio_io_num = sensor_fd;
    gpio_data_data.gpio_intr_type = GPIO_INTR_TYPE_EDGE;
    gpio_data_data.gpio_intr_edge = GPIO_INTR_EDGE_FALLING;
    gpio_mem_data(&gpio_data_data);

    while (1) {
        // Open I2C file descriptor
        if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
            fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
            error++;
            continue;
        }

        // Check if the sensor is present
