        // Check if the sensor is present
        if (ioctl(i2c_fd, I2C_RDWR, I2C_ADDR) < 0) {
            fprintf(stderr, "Failed to read sensor address: %s\n", strerror(errno));
            error++;
            continue;
        }

        // Check if the sensor is present
        if (ioctl(i2c_fd, I2C_RDWR, I2C_ADDR) < 0) {
            fprintf(stderr, "Failed to read sensor address: %s\n", strerror(errno));
            error++;
            continue;
        }

        // Read sensor data
        if (ioctl(i2c_fd, I2C_RDWR, &sensor_data) < 0) {
            fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
            error++;
            continue;
        }

