        snprintf(buffer, sizeof(buffer), "%s%d\n", sensor_data_str, sensor_data);
        printf("%s\n", buffer);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    gpio_unexport(sensor_fd);
    gpio_unexport(gpio_fd);
    gpio_release(gpio_fd);
    gpio_release(sensor_fd);

