#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x28
#define HIH6130_ADDRESS 0x48
#define HIH6130_REG_STATUS 0x00
#define HIH6130_REG_DATA_LOW 0x01
#define HIH6130_REG_DATA_HIGH 0x02
#define HIH6130_REG_THRESHOLD_HIGH 0x03
#define HIH6130_REG_THRESHOLD_LOW 0x04

int i2c_fd;
struct i2c_rdwr_ioctl_data i2c_data;

void i2c_init() {
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HIH6130_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_RDWR, I2C_RDWR) < 0) {
        perror("Failed to set I2C mode");
        exit(1);
    }
}

void i2c_release() {
    close(i2c_fd);
}

int i2c_read_data(uint8_t* data, uint8_t num_bytes) {
    if (ioctl(i2c_fd, I2C_RDWR, I2C_RD) < 0) {
        perror("Failed to read data");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_RDWR, I2C_WR, num_bytes) < 0) {
        perror("Failed to write data");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_RDWR, I2C_RD) < 0) {
        perror("Failed to read data");
        exit(1);
    }

    return 0;
}

int main() {
    i2c_init();

    while (1) {
        uint8_t data[2];
        int bytes_read = i2c_read_data(data, 2);
        if (bytes_read < 0) {
            perror("Failed to read data");
            exit(1);
        }

        uint16_t status = data[0];
        uint16_t data_low = data[1];
        uint16_t data_high = (data_low << 8) | data_high;

        if (status & HIH6130_STATUS_SENSOR_ABSENT) {
            printf("Sensor is absent\n");
            continue;
        }

        if (status & HIH6130_STATUS_DATA_READY) {
            if (data_high & HIH6130_REG_DATA_HIGH) {
                uint16_t data_high_val = data_high & HIH6130_REG_DATA_HIGH;
                uint16_t data_low_val = data_low & HIH6130_REG_DATA_LOW;

                // Perform temperature and humidity calculations here
                // ...

                // Write data to log file
                FILE *log_file = fopen("environmental_data.log", "a");
                if (log_file == NULL) {
                    perror("Failed to open log file");
                    exit(1);
                }

                char timestamp[26];
                time_t now = time(NULL);
                struct tm *ltm = localtime(&now);
                strftime(timestamp, 26, "%Y-%m-%dT%H:%M:%S", ltm);

                fprintf(log_file, "%.6f,%.2f,%.2f\n", temperature, humidity, timestamp);
                fclose(log_file);
            }
        }

        usleep(40000); // Wait for 40 milliseconds
    }

    i2c_release();
    return 0;
}

