#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x48

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    uint8_t i2c_buf[4];
    int ret;

    // Initialize I2C handle
    if ((i2c_fd = i2c_open_board_file("/dev/i2c-1", I2C_CLIENT_ENDPOINT)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Verify sensor device ID
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) < 0) {
        fprintf(stderr, "Failed to verify sensor device ID: %s\n", strerror(errno));
        i2c_close(i2c_fd);
        return 1;
    }

    // Set up I2C communication
    i2c_msgs[0].addr = I2C_DEVICE_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 4;
    i2c_msgs[0].buf = i2c_buf;

    i2c_msgs[1].addr = I2C_DEVICE_ADDR;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 4;
    i2c_msgs[1].buf = i2c_buf;

    // Start I2C communication
    if (i2c_transfer(i2c_fd, i2c_msgs, 2) < 2) {
        fprintf(stderr, "Failed to communicate with the sensor: %s\n", strerror(errno));
        i2c_close(i2c_fd);
        return 1;
    }

    // Log sensor temperature every 60 seconds
    while (1) {
        // Wait for 60 seconds
        sleep(60);

        // Read temperature from the sensor
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_msgs[0]);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature from the sensor: %s\n", strerror(errno));
            continue;
        }

        // Convert temperature to little-endian format
        *(float*)i2c_buf = *(float*)i2c_buf;

        // Log temperature to file
        FILE *file = fopen("greenhouse_temps.dat", "w");
        if (file == NULL) {
            fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
            continue;
        }

        fprintf(file, "%f\n", *(float*)i2c_buf);

        fclose(file);
    }

    // Clean up I2C communication
    i2c_close(i2c_fd);

    return 0;
}

