This code assumes that you have the Adafruit TMP117 sensor connected to the I2C bus on the Raspberry Pi Zero W. Make sure to include the necessary header files and libraries, and replace the I2C device address and file paths with the correct values for your system.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x44
#define SCL_GPIO 17
#define SDA_GPIO 18

#define SHT40_DATA_SIZE 2
#define CRC_8_POLYNOMIAL 0x31

#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    unsigned char crc8_result[2];
    char environmental_data_file[] = "environmental_data.txt";
    FILE *fp;

    // Initialize GPIO pins
    gpio_init();
    gpio_set_direction(SCL_GPIO, GPIO_OUT);
    gpio_set_direction(SDA_GPIO, GPIO_IN);

    // Initialize I2C bus
    i2c_fd = pigpio_open(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    // Initialize I2C device
    if (pigpio_ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error initializing I2C device\n");
        return 1;
    }

    // Open log file
    fp = fopen(environmental_data_file, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Wait for at least 8.5 ms after each command
    usleep(8500 * 1000);

    // Read temperature and humidity data from the sensor
    int temperature_data = 0;
    int humidity_data = 0;
    int i;
    for (i = 0; i < SHT40_DATA_SIZE; i++) {
        if (pigpio_i2c_read(i2c_fd, I2C_ADDR, &i2c_msgs[0].addr, &i2c_msgs[0].len, &i2c_msgs[0].buf) < 0) {
            fprintf(stderr, "Error reading data from sensor\n");
            return 1;
        }

        if (i2c_msgs[0].len == 2) {
            temperature_data = (temperature_data << 8) | i2c_msgs[0].buf[1];
        }

        if (i2c_msgs[0].len == 1) {
            humidity_data = (humidity_data << 8) | i2c_msgs[0].buf[0];
        }
    }

    // Calculate CRC8 values
    crc8_result[0] = 0x31;
    for (i = 0; i < SHT40_DATA_SIZE; i++) {
        crc8_result[1] = (crc8_result[1] << 1) ^ crc8_table[(crc8_result[1] ^ i2c_msgs[0].buf[i]) & 0xFF];
    }

    // Validate CRC8 values
    if (crc8_result[0] != 0x31 || crc8_result[1] != 0x31) {
        fprintf(stderr, "Invalid CRC8 values\n");
        return 1;
    }

    // Append timestamp and measured values to environmental_data.txt
    char environmental_data_line[32];
    snprintf(environmental_data_line, sizeof(environmental_data_line),
             "%s\t%d\t%d\t%d", TIMESTAMP_FORMAT, temperature_data, humidity_data, crc8_result[0]);

    fprintf(fp, "%s\n", environmental_data_line);

    // Close log file
    fclose(fp);

    // Cleanly close I2C handle, driver library, and release GPIO pins
    pigpio_exit();
    gpio_cleanup();

    return 0;
