#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x44
#define SENSOR_ADDRESS_HI 0x48

int i2c_fd;
int gpio_fd;

void init_i2c() {
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    gpio_fd = gpio_open(1);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO file");
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    gpio_close(gpio_fd);
}

void init_sensor() {
    if (gpio_set_mode(gpio_fd, GPIO_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        exit(EXIT_FAILURE);
    }
}

void cleanup_sensor() {
    gpio_set_mode(gpio_fd, GPIO_INPUT);
}

void read_temperature_humidity() {
    uint8_t temp_data[2];
    uint8_t hum_data[2];

    if (gpio_write(gpio_fd, GPIO_PIN_3, 0) < 0) {
        perror("Failed to set SDA to low");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_4, 0) < 0) {
        perror("Failed to set SCL to low");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_1, 1) < 0) {
        perror("Failed to set VDD to high");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_2, 0) < 0) {
        perror("Failed to set VSS to low");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_3, 1) < 0) {
        perror("Failed to set SDA to high");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_4, 1) < 0) {
        perror("Failed to set SCL to high");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_1, 0) < 0) {
        perror("Failed to set VDD to low");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_2, 0) < 0) {
        perror("Failed to set VSS to low");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_3, 0) < 0) {
        perror("Failed to set SDA to low");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_4, 0) < 0) {
        perror("Failed to set SCL to low");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_1, 1) < 0) {
        perror("Failed to set VDD to high");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_2, 1) < 0) {
        perror("Failed to set VSS to high");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_3, 0) < 0) {
        perror("Failed to set SDA to low");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_4, 0) < 0) {
        perror("Failed to set SCL to low");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_1, 0) < 0) {
        perror("Failed to set VDD to low");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_2, 0) < 0) {
        perror("Failed to set VSS to low");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_3, 1) < 0) {
        perror("Failed to set SDA to high");
        exit(EXIT_FAILURE);
    }

    if (gpio_write(gpio_fd, GPIO_PIN_4, 1) < 0) {
        perror("Failed to set SCL to high");
        exit(EXIT_FAILURE);
    }

    if (gpio_read(gpio_fd, GPIO_PIN_3, &temp_data[0], 1) < 0) {
        perror("Failed to read temperature data");
        exit(EXIT_FAILURE);
    }

    if (gpio_read(gpio_fd, GPIO_PIN_4, &hum_data[0], 1) < 0) {
        perror("Failed to read humidity data");
        exit(EXIT_FAILURE);
    }

    uint8_t crc_polynomial = 0x31;
    uint8_t crc_result = 0;

    for (int i = 0; i < 2; i++) {
        crc_result = crc8_update(crc_polynomial, temp_data[i]);
        if (crc_result != temp_data[i]) {
            printf("CRC8 polynomial error\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 2; i++) {
        crc_result = crc8_update(crc_polynomial, hum_data[i]);
        if (crc_result != hum_data[i]) {
            printf("CRC8 polynomial error\n");
            exit(EXIT_FAILURE);
        }
    }

    uint16_t crc = crc8_final(crc_polynomial, (uint8_t*)temp_data, 2);
    if (crc != 0x31) {
        printf("CRC8 error\n");
        exit(EXIT_FAILURE);
    }

    uint16_t temp_c = (temp_data[0] << 8) | temp_data[1];
    uint16_t temp_f = (temp_c - 0.5) * 100;

    uint16_t hum_c = (hum_data[0] << 8) | hum_data[1];
    uint16_t hum_p = (hum_c - 50) * 0.4;

    printf("Temperature: %.2f C\n", temp_f);
    printf("Humidity: %.2f %%\n", hum_p);

    gpio_close(gpio_fd);
}

int main() {
    init_i2c();
    init_gpio();

    while (1) {
        read_temperature_humidity();
    }

    cleanup_gpio();
    cleanup_i2c();

    return 0;
}

