#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <unistd.h>
#include <signal.h>

#define I2C_BUS_NUM 3
#define I2C_DEVICE_ADDR 0x48

int i2c_init(int bus_num, int device_addr) {
    int rc;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int num_msgs = 1;

    if (bus_num < 0 || device_addr < 0) {
        fprintf(stderr, "Invalid I2C bus number or device address.\n");
        return -1;
    }

    memset(&data, 0, sizeof(data));
    data.msgs = &msg[0];
    data.nmsgs = num_msgs;
    data.function = I2C_RDWR;
    data.timeout_ns = 1000000000;

    rc = ioctl(device_addr, I2C_SLAVE, bus_num);
    if (rc < 0) {
        fprintf(stderr, "Failed to set I2C bus number: %d\n", rc);
        return -1;
    }

    msg[0].addr = device_addr;
    msg[0].flags = 0;
    msg[0].len = 2;
    msg[0].buf = &data;
    msg[1].addr = device_addr;
    msg[1].flags = 0;
    msg[1].len = 1;
    msg[1].buf = &num_msgs;

    if (ioctl(device_addr, I2C_MESSAGE_WR, &msg[0]) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", rc);
        return -1;
    }

    return 0;
}

void i2c_cleanup(int bus_num) {
    int rc;
    struct i2c_rdwr_ioctl_data data;

    memset(&data, 0, sizeof(data));
    data.msgs = &msg[0];
    data.nmsgs = 1;
    data.function = I2C_RDWR;
    data.timeout_ns = 1000000000;

    rc = ioctl(device_addr, I2C_SLAVE, bus_num);
    if (rc < 0) {
        fprintf(stderr, "Failed to set I2C bus number: %d\n", rc);
        return;
    }

    msg[0].addr = device_addr;
    msg[0].flags = 0;
    msg[0].len = 2;
    msg[0].buf = &data;

    if (ioctl(device_addr, I2C_MESSAGE_RD, &msg[0]) < 0) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", rc);
        return;
    }

    if (msg[0].buf[0] != 0) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", rc);
        return;
    }

    if (ioctl(device_addr, I2C_SLAVE, bus_num) < 0) {
        fprintf(stderr, "Failed to set I2C bus number: %d\n", rc);
        return;
    }
}

int main() {
    int bus_num = I2C_BUS_NUM;
    int device_addr = I2C_DEVICE_ADDR;
    int i;
    int rc;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int num_msgs = 1;

    if (bus_num < 0 || device_addr < 0) {
        fprintf(stderr, "Invalid I2C bus number or device address.\n");
        return -1;
    }

    memset(&data, 0, sizeof(data));
    data.msgs = &msg[0];
    data.nmsgs = num_msgs;
    data.function = I2C_RDWR;
    data.timeout_ns = 1000000000;

    rc = i2c_init(bus_num, device_addr);
    if (rc < 0) {
        fprintf(stderr, "Failed to initialize I2C bus: %d\n", rc);
        return -1;
    }

    for (i = 0; i < 3; i++) {
        if (i == 0) {
            if (ioctl(device_addr, I2C_SLAVE, bus_num) < 0) {
                fprintf(stderr, "Failed to set I2C bus number: %d\n", rc);
                return -1;
            }
        }

        msg[0].addr = device_addr;
        msg[0].flags = 0;
        msg[0].len = 2;
        msg[0].buf = &data;
        msg[1].addr = device_addr;
        msg[1].flags = 0;
        msg[1].len = 1;
        msg[1].buf = &i;

        if (ioctl(device_addr, I2C_MESSAGE_WR, &msg[0]) < 0) {
            fprintf(stderr, "Failed to write to I2C device: %d\n", rc);
            return -1;
        }

        if (ioctl(device_addr, I2C_MESSAGE_RD, &msg[0]) < 0) {
            fprintf(stderr, "Failed to read from I2C device: %d\n", rc);
            return -1;
        }

        if (msg[0].buf[0] != i) {
            fprintf(stderr, "Failed to read from I2C device: %d\n", rc);
            return -1;
        }

        if (ioctl(device_addr, I2C_SLAVE, bus_num) < 0) {
            fprintf(stderr, "Failed to set I2C bus number: %d\n", rc);
            return -1;
        }
    }

    i2c_cleanup(bus_num);

    return 0;
}

