#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x18

int main() {
    int i2c_fd;
    struct gpiod_i2c_config config = GPIOD_I2C_DEFAULT_CONFIG;
    struct gpiod_i2c_data data;
    struct gpiod_i2c_data *data_ptr;
    struct gpiod_i2c_info info;
    struct timespec start_time, end_time;
    char timestamp[80];
    char log_file_name[] = "pressure_log.txt";
    FILE *log_file;

    // Initialize I2C bus
    if (gpiod_i2c_init(&config) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Open I2C handle
    if ((i2c_fd = gpiod_i2c_open(I2C_BUS, I2C_ADDR, &config)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_i2c_cleanup(&config);
        return 1;
    }

    // Open log file
    if ((log_file = fopen(log_file_name, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_i2c_close(i2c_fd);
        gpiod_i2c_cleanup(&config);
        return 1;
    }

    // Initialize sensor
    if (gpiod_i2c_request_from_device(i2c_fd, I2C_ADDR, &data, 1) < 0) {
        fprintf(stderr, "Failed to request sensor data\n");
        fclose(log_file);
        gpiod_i2c_close(i2c_fd);
        gpiod_i2c_cleanup(&config);
        return 1;
    }

    // Read sensor data
    if (gpiod_i2c_read_data(i2c_fd, &data) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        fclose(log_file);
        gpiod_i2c_close(i2c_fd);
        gpiod_i2c_cleanup(&config);
        return 1;
    }

    // Append timestamp and sensor data to log file
    gettimeofday(&start_time, NULL);
    timestamp[0] = '\0';
    snprintf(timestamp, sizeof(timestamp), "%s", gmtime(&start_time));
    timestamp[sizeof(timestamp) - 1] = '\n';

    if (gpiod_i2c_write_data(i2c_fd, &data, 1) < 0) {
        fprintf(stderr, "Failed to write sensor data\n");
        fclose(log_file);
        gpiod_i2c_close(i2c_fd);
        gpiod_i2c_cleanup(&config);
        return 1;
    }

    // Append timestamp and sensor data to log file
    gettimeofday(&end_time, NULL);
    timestamp[0] = '\0';
    snprintf(timestamp, sizeof(timestamp), "%s", gmtime(&end_time));
    timestamp[sizeof(timestamp) - 1] = '\n';

    if (gpiod_i2c_write_data(i2c_fd, &data, 1) < 0) {
        fprintf(stderr, "Failed to write sensor data\n");
        fclose(log_file);
        gpiod_i2c_close(i2c_fd);
        gpiod_i2c_cleanup(&config);
        return 1;
    }

    // Clean up
    gpiod_i2c_release_from_device(i2c_fd, &data);
    gpiod_i2c_close(i2c_fd);
    gpiod_i2c_cleanup(&config);

    // Append timestamp and log file close to log file
    gettimeofday(&start_time, NULL);
    timestamp[0] = '\0';
    snprintf(timestamp, sizeof(timestamp), "%s", gmtime(&start_time));
    timestamp[sizeof(timestamp) - 1] = '\n';

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Failed to write timestamp to log file\n");
        return 1;
    }

    // Close log file
    fclose(log_file);

    return 0;
}

