#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x48
#define GPIO_FILE "/sys/class/gpio/gpio18"

#define BUFFER_SIZE 60
#define THRESHOLD 28.0
#define MIN_THRESHOLD 26.0

int fan_gpio;
int i2c_fd;
struct i2c_rdwr_ioctl_data i2c_data;

void i2c_init() {
    int ret;

    ret = ioctl(i2c_fd, I2C_RDWR, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(ret));
        exit(1);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(ret));
        exit(1);
    }
}

void i2c_read_byte(int i2c_fd, uint8_t reg_addr) {
    i2c_data.reg_addr = reg_addr;
    i2c_data.flags = 0;
    i2c_data.buf = (uint8_t*)malloc(1);
    if (!i2c_data.buf) {
        fprintf(stderr, "Failed to allocate memory for I2C read\n");
        exit(1);
    }

    ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(ret));
        exit(1);
    }

    free(i2c_data.buf);
}

void i2c_write_byte(int i2c_fd, uint8_t reg_addr, uint8_t data) {
    i2c_data.reg_addr = reg_addr;
    i2c_data.buf[0] = data;
    i2c_data.flags = 0;

    ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(ret));
        exit(1);
    }
}

void i2c_read_buffer(int i2c_fd, uint8_t* buffer, int buffer_size) {
    for (int i = 0; i < buffer_size; i++) {
        buffer[i] = 0;
    }

    for (int i = 0; i < buffer_size; i++) {
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(ret));
            exit(1);
        }

        buffer[i] = i2c_data.buf[0];
    }
}

void i2c_write_buffer(int i2c_fd, uint8_t* buffer, int buffer_size) {
    for (int i = 0; i < buffer_size; i++) {
        i2c_data.buf[0] = buffer[i];
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(ret));
            exit(1);
        }
    }
}

void compute_running_average(int* buffer, int buffer_size, float* average) {
    int sum = 0;
    int count = 0;

    for (int i = 0; i < buffer_size; i++) {
        sum += buffer[i];
        count++;
    }

    *average = sum / count;
}

void set_fan_state(float average) {
    if (average > THRESHOLD) {
        i2c_write_byte(fan_gpio, GPIO_FILE "/active", 1);
    } else if (average < MIN_THRESHOLD) {
        i2c_write_byte(fan_gpio, GPIO_FILE "/inactive", 1);
    } else {
        i2c_write_byte(fan_gpio, GPIO_FILE "/unknown", 1);
    }
}

int main() {
    i2c_init();

    int buffer[BUFFER_SIZE];
    float average[BUFFER_SIZE];

    while (1) {
        i2c_read_buffer(i2c_fd, buffer, BUFFER_SIZE);
        compute_running_average(buffer, BUFFER_SIZE, average);

        set_fan_state(average);

        printf("Current temperature: %0.1f\n", buffer[0]);
        printf("Average temperature: %0.1f\n", average[0]);

        sleep(1);
    }

    return 0;
}

