#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/stat.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x48

int i2c_fd;
int gpio_fd;

void i2c_init() {
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        exit(1);
    }

    if (i2c_init() < 0) {
        perror("Failed to initialize I2C");
        exit(1);
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    gpio_set_mode(GPIO_SDA, GPIO_OUTPUT);
    gpio_set_mode(GPIO_SCL, GPIO_OUTPUT);

    gpio_output(GPIO_SDA, 1);
    gpio_output(GPIO_SCL, 1);
}

void i2c_cleanup() {
    gpio_close(gpio_fd);
    gpio_unexport(GPIO_SDA);
    gpio_unexport(GPIO_SCL);
    gpio_exit();
}

int i2c_read_register(int i2c_fd, int reg, int *value) {
    struct i2c_msg msg[2];
    msg[0].addr = i2c_fd;
    msg[0].flags = 0;
    msg[0].len = 2;
    msg[0].buf = (void *)&reg;
    msg[1].addr = i2c_fd;
    msg[1].flags = I2C_M_RD;
    msg[1].len = 1;
    msg[1].buf = (void *)&value;

    int ret = ioctl(i2c_fd, I2C_RDWR, msg);
    if (ret < 0) {
        perror("Failed to read from I2C device");
        exit(1);
    }

    return 0;
}

int i2c_write_register(int i2c_fd, int reg, int value) {
    struct i2c_msg msg[2];
    msg[0].addr = i2c_fd;
    msg[0].flags = 0;
    msg[0].len = 2;
    msg[0].buf = (void *)&reg;
    msg[1].addr = i2c_fd;
    msg[1].flags = I2C_M_WR;
    msg[1].len = 1;
    msg[1].buf = (void *)&value;

    int ret = ioctl(i2c_fd, I2C_RDWR, msg);
    if (ret < 0) {
        perror("Failed to write to I2C device");
        exit(1);
    }

    return 0;
}

void log_entry(const char *timestamp, int temperature, int humidity) {
    char log_entry[30];
    snprintf(log_entry, sizeof(log_entry), "%s,%.1f,%.1f\n", timestamp, temperature, humidity);
    FILE *log_file = fopen("enviro_log.txt", "a");
    if (log_file) {
        fputs(log_entry, log_file);
        fclose(log_file);
    }
}

int main() {
    i2c_init();

    while (1) {
        int temperature, humidity;
        int ret = i2c_read_register(i2c_fd, I2C_ADDR + 0x00, &temperature);
        if (ret < 0) {
            perror("Failed to read temperature");
            continue;
        }

        ret = i2c_read_register(i2c_fd, I2C_ADDR + 0x01, &humidity);
        if (ret < 0) {
            perror("Failed to read humidity");
            continue;
        }

        log_entry(get_current_time(), temperature, humidity);
    }

    i2c_cleanup();

    return 0;
}

