#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x5A

int main() {
    int i2c_fd;
    struct gpiod_i2c_config config = GPIOD_I2C_DEFAULT_CONFIG();
    struct gpiod_i2c_data data;
    struct gpiod_i2c_file *file;
    struct gpiod_i2c_file_ops file_ops = {
        .write = gpiod_i2c_file_write,
        .read = gpiod_i2c_file_read,
        .close = gpiod_i2c_file_close,
    };

    // Initialize I2C bus
    if (gpiod_i2c_init(&config) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Initialize Sensirion SDP810 sensor
    if (gpiod_i2c_request_line(&config, SENSOR_ADDRESS, GPID_I2C_LINE_SDP810) < 0) {
        fprintf(stderr, "Failed to request line for Sensirion SDP810 sensor\n");
        gpiod_i2c_release(&config);
        return 1;
    }

    // Open I2C file
    if ((i2c_fd = gpiod_i2c_open(I2C_BUS, GPID_I2C_FILE_I2C)) < 0) {
        fprintf(stderr, "Failed to open I2C file\n");
        gpiod_i2c_release(&config);
        gpiod_i2c_release(&data.i2c);
        return 1;
    }

    // Open file for logging
    if ((file = gpiod_i2c_file_open(i2c_fd, "hvac_pressure_log.txt", GPID_I2C_FILE_WRITE)) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_i2c_close(i2c_fd);
        gpiod_i2c_release(&config);
        gpiod_i2c_release(&data.i2c);
        return 1;
    }

