#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <linux/i2c.h>

#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDRESS 0x48

int i2c_fd;

void i2c_init() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("Error setting I2C device address");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_RDWR, 0) < 0) {
        perror("Error setting I2C device to read/write mode");
        exit(1);
    }
}

void i2c_close() {
    close(i2c_fd);
}

void i2c_write(uint8_t reg, uint8_t data) {
    if (ioctl(i2c_fd, I2C_WRITE_BYTE, reg) < 0) {
        perror("Error writing to I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_WRITE_BYTE, data) < 0) {
        perror("Error writing to I2C device");
        exit(1);
    }
}

void i2c_read(uint8_t reg, uint8_t *data) {
    if (ioctl(i2c_fd, I2C_READ_BYTE, reg) < 0) {
        perror("Error reading from I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_READ_BYTE, data) < 0) {
        perror("Error reading from I2C device");
        exit(1);
    }
}

void i2c_wait_for_completion(uint8_t reg) {
    while (1) {
        uint8_t data[2];
        int bytes_read = i2c_read(reg, data);
        if (bytes_read < 2) {
            perror("Error reading from I2C device");
            exit(1);
        }

        if (memcmp(data, &SDP810_REG_CRC_H, 2) == 0) {
            break;
        }
    }
}

void i2c_read_crc8(uint8_t reg, uint8_t *data, uint8_t crc8_poly, uint8_t crc8_initial) {
    uint8_t crc = crc8_initial;
    for (int i = 0; i < 2; i++) {
        uint8_t byte = data[i];
        crc ^= byte;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ crc8_poly;
            } else {
                crc <<= 1;
            }
        }
        data[i] = crc;
    }
}

void i2c_write_crc8(uint8_t reg, uint8_t *data, uint8_t crc8_poly, uint8_t crc8_initial) {
    uint8_t crc = crc8_initial;
    for (int i = 0; i < 2; i++) {
        data[i] = data[i] ^ 0x80;
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ crc8_poly;
            } else {
                crc <<= 1;
            }
        }
        data[i] = data[i] ^ 0x80;
    }
}

void log_sample(uint8_t reg, uint8_t data[2]) {
    uint8_t crc8_poly = 0x31;
    uint8_t crc8_initial = 0x00;
    i2c_write(SDP810_REG_CRC_H, &crc8_poly);
    i2c_write(SDP810_REG_CRC_L, &crc8_initial);
    i2c_write(reg, data);
    i2c_wait_for_completion(reg);
    i2c_write_crc8(reg, data, crc8_poly, crc8_initial);
}

int main() {
    i2c_init();

    while (1) {
        uint8_t reg = 0x00;
        uint8_t data[2];

        log_sample(reg, data);

        i2c_write(reg, data);
        i2c_wait_for_completion(reg);
    }

    i2c_close();
    return 0;
}

