void i2c_write(uint8_t reg, uint8_t data) {
    if (ioctl(i2c_fd, I2C_WRITE_BYTE, reg) < 0) {
        perror("Error writing to I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_WRITE_BYTE, data) < 0) {
        perror("Error writing to I2C device");
        exit(1);
    }
}

void i2c_read(uint8_t reg, uint8_t *data) {
    if (ioctl(i2c_fd, I2C_READ_BYTE, reg) < 0) {
        perror("Error reading from I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_READ_BYTE, data) < 0) {
        perror("Error reading from I2C device");
        exit(1);
    }
}

void i2c_wait_for_completion(uint8_t reg) {
    while (1) {
        uint8_t data[2];
        int bytes_read = i2c_read(reg, data);
        if (bytes_read < 2) {
            perror("Error reading from I2C device");
            exit(1);
        }

        if (memcmp(data, &SDP810_REG_CRC_H, 2) == 0) {
            break;
        }
    }
}

void i2c_read_crc8(uint8_t reg, uint8_t *data, uint8_t crc8_poly, uint8_t crc8_initial) {
    uint8_t crc = crc8_initial;
    for (int i = 0; i < 2; i++) {
        uint8_t byte = data[i];
        crc ^= byte;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ crc8_poly;
            } else {
                crc <<= 1;
            }
        }
        data[i] = crc;
    }
}

void i2c_write_crc8(uint8_t reg, uint8_t *data, uint8_t crc8_poly, uint8_t crc8_initial) {
    uint8_t crc = crc8_initial;
    for (int i = 0; i < 2; i++) {
        data[i] = data[i] ^ 0x80;
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ crc8_poly;
            } else {
                crc <<= 1;
            }
        }
        data[i] = data[i] ^ 0x80;
    }
}

void log_sample(uint8_t reg, uint8_t data[2]) {
    uint8_t crc8_poly = 0x31;
    uint8_t crc8_initial = 0x00;
    i2c_write(SDP810_REG_CRC_H, &crc8_poly);
    i2c_write(SDP810_REG_CRC_L, &crc8_initial);
    i2c_write(reg, data);
    i2c_wait_for_completion(reg);
    i2c_write_crc8(reg, data, crc8_poly, crc8_initial);
}

int main() {
    i2c_init();

    while (1) {
        uint8_t reg = 0x00;
        uint8_t data[2];

        log_sample(reg, data);

        i2c_write(reg, data);
        i2c_wait_for_completion(reg);
    }

    i2c_close();
    return 0;
}
