    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read temperature sensor data\n");
        return 1;
    }

    // Append the data to the sensor file
    char line[32];
    snprintf(line, sizeof(line), "%.2f,%.2f\n", pdata_temp->pressure, pdata_temp->temperature);
    ret = write(fd, line, strlen(line) + 1);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to write to sensor file\n");
        return 1;
    }

    // Print the data to stdout
    printf("Pressure: %.2f, Temperature: %.2f\n", pdata_temp->pressure, pdata_temp->temperature);

    // Close the sensor file
    close(fd);

    // Release the platform data
    gpiod_release_platform_data(pdata);

    // Clean up
    gpioTerminate();

    return 0;
}

