int i2c_fd;

void i2c_init() {
    struct i2c_rdwr_ioctl_data data;
    int rc;

    data.flags = 0;
    data.timeout_ns = 1000000000;
    data.sda_ioctl_function = I2C_FUNC_I2C;
    data.sda_ioctl_function |= I2C_FUNC_SLAVE;
    data.sda_ioctl_function |= I2C_SLAVE_FORCE_TX_ONLY;

    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, &data);
    if (i2c_fd < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    rc = ioctl(i2c_fd, I2C_RDWR, &data);
    if (rc < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
}

void i2c_release() {
    if (i2c_fd >= 0) {
        ioctl(i2c_fd, I2C_RDWR, 0);
        close(i2c_fd);
        i2c_fd = -1;
    }
}

