#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_SENSOR_ADDR 0x44

int main() {
    int i2c_fd;
    int gpio_fd;
    int ret;
    int i;
    int retry_count = 3;
    char buffer[6];
    char *html_content = "<html><body><h1>Temperature and Humidity</h1><p>Current temperature: %d %%, Humidity: %d %%</p></body></html>";

    // Initialize I2C bus
    if ((i2c_fd = i2c_open(I2C_BUS_NUM)) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    // Initialize GPIO
    if ((gpio_fd = gpio_open(I2C_GPIO_BUS_NUM)) < 0) {
        fprintf(stderr, "Error opening GPIO bus\n");
        return 1;
    }

    // Set GPIO as an output
    if (gpio_set_mode(gpio_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return 1;
    }

    // Set Sensirion SHT40 sensor address
    if (gpio_set_level(gpio_fd, I2C_GPIO_SENSOR_ADDR_GPIO) < 0) {
        fprintf(stderr, "Error setting I2C GPIO address\n");
        return 1;
    }

    // Open I2C device file
    if ((ret = i2c_open_device(I2C_BUS_NUM, I2C_SENSOR_ADDR, &i2c_fd)) < 0) {
        fprintf(stderr, "Error opening I2C device file\n");
        return 1;
    }

    // Set I2C device file to non-blocking mode
    if (ioctl(i2c_fd, I2C_RDWR, 0) < 0) {
        fprintf(stderr, "Error setting I2C device file to non-blocking mode\n");
        return 1;
    }

    // Set GPIO as an output
    if (gpio_set_mode(gpio_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return 1;
    }

    // Set GPIO as an output
    if (gpio_set_level(gpio_fd, GPIO_LOW) < 0) {
        fprintf(stderr, "Error setting GPIO level\n");
        return 1;
    }

    // Set sensor address
    if (gpio_set_level(gpio_fd, I2C_SENSOR_ADDR_GPIO) < 0) {
        fprintf(stderr, "Error setting I2C GPIO address\n");
        return 1;
    }

    // Set sensor data direction
    if (gpio_set_dir(gpio_fd, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO direction\n");
        return 1;
    }

    // Set sensor data length
    if (gpio_set_len(gpio_fd, 1) < 0) {
        fprintf(stderr, "Error setting GPIO data length\n");
        return 1;
    }

    // Set sensor data value
    if (gpio_set_level(gpio_fd, 0) < 0) {
        fprintf(stderr, "Error setting GPIO level\n");
        return 1;
    }

    // Wait for sensor to be ready
    while (gpio_get_level(gpio_fd) == 0) {
        usleep(500000);
    }

    // Read sensor data
    if (gpio_read(gpio_fd, &buffer[0], 1) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return 1;
    }

    // Check if the sensor is absent
    if (buffer[0] == 0) {
        fprintf(stderr, "Sensor is absent\n");
        return 1;
    }

    // Read six bytes from the sensor
    if (gpio_read(gpio_fd, &buffer[0], 1) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return 1;
    }

    // Convert the sensor data to temperature and humidity values
    float temperature = (buffer[0] << 8) | buffer[1];
    float humidity = (buffer[2] << 8) | buffer[3];

    // Check if the sensor data is valid
    if (temperature < 0 || temperature > 65535 || humidity < 0 || humidity > 100) {
        fprintf(stderr, "Invalid sensor data\n");
        return 1;
    }

    // Print temperature and humidity values
    printf("Temperature: %.2f °C\n", temperature);
    printf("Humidity: %.2f %%\n", humidity);

    // Close I2C device file
    if (ioctl(i2c_fd, I2C_RDWR, 0) < 0) {
        fprintf(stderr, "Error closing I2C device file\n");
        return 1;
    }

    // Close GPIO file
    if (gpio_close(gpio_fd) < 0) {
        fprintf(stderr, "Error closing GPIO file\n");
        return 1;
    }

    // Close I2C bus
    if (i2c_close(i2c_fd) < 0) {
        fprintf(stderr, "Error closing I2C bus\n");
        return 1;
    }

    return 0;
