#include <sys/syslog.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x40
#define HTTP_PORT 80

#define BUF_SIZE 1024

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[1];
    struct curl_slist *headers = NULL;
    CURL *curl;
    CURLcode res;
    char json[BUF_SIZE];
    char *humidity_str;
    struct sigaction sa;
    int sigint_received = 0;

    // Initialize syslog
    syslog(LOG_INFO, "syslog initialized");

    // Set up syslog facility
    syslog(LOG_INFO, "syslog facility set to: %s", syslog(LOG_INFO, "syslog"));

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return 1;
    }

    // Set up I2C communication
    memset(&data, 0, sizeof(data));
    data.flags = 0;
    data.timeout = 5000;
    data.msgs = msg;
    data.nmsgs = 1;
    data.buf = (char *)malloc(BUF_SIZE);
    if (!data.buf) {
        syslog(LOG_ERR, "Failed to allocate memory for I2C communication");
        close(fd);
        return 1;
    }

    // Set I2C address and read sensor data
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        free(data.buf);
        close(fd);
        return 1;
    }
    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = (char *)&data;
    msg[0].buf_len = 1;

    if (ioctl(fd, I2C_RDWR, 0) < 0) {
        syslog(LOG_ERR, "Failed to read I2C data: %s", strerror(errno));
        free(data.buf);
        close(fd);
        return 1;
    }

    // Read sensor data
    if (msg[0].buf[0] == 0x34) {
        humidity_str = (char *)&data.buf[1];
        sprintf(json, "{\"humidity\": %s}", humidity_str);
        free(humidity_str);
    } else {
        syslog(LOG_ERR, "HTU21D sensor not found");
        free(data.buf);
        close(fd);
        return 1;
    }

    // Close I2C communication
    close(fd);

    // Create a new HTTP POST request
    curl = curl_easy_init();
    if (curl) {
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_URL, "http://api.example.com/humidity");
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "HTTP POST request failed: %s", curl_easy_strerror(res));
        }
        curl_easy_cleanup(curl);
    }

    // Handle signals
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sigaddset(&sa.sa_mask, SIGINT);
    sigaddset(&sa.sa_mask, SIGTERM);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Wait for user input
    while (!sigint_received) {
        // Poll I2C bus
        if (ioctl(fd, I2C_RDWR, 0) < 0) {
            syslog(LOG_ERR, "Failed to poll I2C bus: %s", strerror(errno));
        }

        // Wait for HTTP POST request to complete
        if (res == CURLE_OK) {
            CURLcode res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                syslog(LOG_ERR, "HTTP POST request failed: %s", curl_easy_strerror(res));
            }
        }

        // Wait for user input
        sleep(1);
    }

    return 0;
}

// Signal handler for graceful shutdown
void sig_handler(int sig) {
    sigint_received = 1;
}

