#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x48 // TMP117 I2C address
#define AHT20_I2C_ADDRESS 0x40 // AHT20 I2C address
#define PIR_SENSOR_GPIO_LINE 17 // PIR sensor GPIO line

int i2c_fd;
int pir_gpio_fd;

void init_i2c() {
    if (gpiochip_open(4) < 0) {
        fprintf(stderr, "Failed to open i2c-4\n");
        return;
    }

    if (pi_open() < 0) {
        fprintf(stderr, "Failed to open pi\n");
        return;
    }

    if (pi_set_mode(4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set output mode\n");
        return;
    }

    if (pi_set_mode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set input mode\n");
        return;
    }

    if (pi_mem_alloc(1024, &i2c_fd) < 0) {
        fprintf(stderr, "Failed to allocate memory for i2c\n");
        return;
    }

    if (pi_mem_map(i2c_fd, 0, 1024, &i2c_mem) < 0) {
        fprintf(stderr, "Failed to map memory for i2c\n");
        return;
    }

    if (pi_mem_unmap(i2c_mem) < 0) {
        fprintf(stderr, "Failed to unmap memory for i2c\n");
        return;
    }
}

void cleanup_i2c() {
    if (pi_close(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close i2c\n");
    }

    if (pi_mem_unmap(i2c_mem) < 0) {
        fprintf(stderr, "Failed to unmap memory for i2c\n");
    }

    if (pi_set_mode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set input mode\n");
    }

    if (pi_set_mode(4, PI_OUTPUT) < 0) {
