#define IN2_GPIO_NUM 24
#define ENA_PIN_NUM 17
#define IN1_PIN_NUM 18
#define IN2_PIN_NUM 19

int main() {
    int fd, gpio_fd;
    struct gpiod_event event;
    struct gpiod_event_attr attr;
    char buffer[32];
    struct timespec ts;
    int rain_detected = 0;
    int motor_started = 0;
    int motor_stopped = 0;
    int error_condition = 0;

    // Initialize GPIO
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    // Open GPIO file descriptor
    if ((fd = gpiod_open(ENA_GPIO_NUM, GPIDIO_MODE_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open GPIO file descriptor.\n");
        gpiod_exit();
        return 1;
    }

    // Open GPIO file descriptor for event monitoring
    if ((gpio_fd = gpiod_event_add(fd)) < 0) {
        fprintf(stderr, "Failed to open GPIO file descriptor for event monitoring.\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Set up GPIO event monitoring
    memset(&event, 0, sizeof(event));
    event.type = GPIDIO_EVENT_GPIO;
    event.gpio_num = ENA_GPIO_NUM;
    event.event_type = GPIDIO_EVENT_GPIO_FALLING;
    event.event_attr = &attr;
    event.event_attr->edge = GPIDIO_EVENT_FALLING_EDGE;

    while (1) {
        // Wait for GPIO event
        if (gpiod_event_wait(gpio_fd, &event, NULL) < 0) {
            fprintf(stderr, "Failed to wait for GPIO event.\n");
            break;
        }

        // Check if rain is detected
        if (event.event_type == GPIDIO_EVENT_GPIO_FALLING_EDGE) {
            if (event.gpio_num == ENA_GPIO_NUM) {
                // Close window
                if (motor_started) {
                    close_window();
                }
                // Log the event
                fprintf(stdout, "Rain detected at %s\n", ctime(&ts.tv_sec));
                rain_detected = 1;
            }
        }

        // Check if motor should be started
        if (motor_started && !rain_detected) {
            // Start motor
            if (start_motor()) {
                motor_started = 0;
            }
        }

        // Check if motor should be stopped
        if (motor_started && rain_detected) {
            // Stop motor
            if (stop_motor()) {
                motor_started = 0;
            }
        }

        // Check for any error conditions
        if (error_condition) {
            fprintf(stderr, "Error condition detected.\n");
            break;
        }
    }

    // Release GPIO file descriptor
    gpiod_event_unregister(gpio_fd);
    gpiod_close(gpio_fd);
    gpiod_exit();

    return 0;
}

// Function to close the window
void close_window() {
    // Code to close the window goes here
    printf("Window closed.\n");
}

