    gpio_request.function = GPIO_FUNCTION_PWM;
    gpio_request.flags = GPIO_OUTPUT_LEVEL_HIGH;
    gpio_request.value = 0;
    gpio_desc.line = RGB_LED_GPIO_PWM_GPIO;
    gpio_desc.flags = GPIO_OUTPUT_LEVEL_HIGH;
    gpio_desc.value = 0;
    gpio_desc.direction = GPIO_OUTPUT;

