#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>
#include <pigpio.h>

#define BMP280_ADDRESS 0x76 // I2C address of the BMP280 sensor
#define I2C_SDA_PIN 3
#define I2C_SCL_PIN 5

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpiod_file *gpio_file;
    int ret;

    // Initialize I2C and GPIO
    gpio_file = gpiod_open(I2C_SDA_PIN, GPIO_OUTPUT_DIGITAL);
    gpio_file->direction = GPIO_OUTPUT;
    gpio_file->value = 0;
    gpio_file = gpiod_open(I2C_SCL_PIN, GPIO_INPUT);
    ret = gpiod_request_from_sysfs(gpio_file);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO: %s\n", strerror(ret));
        return 1;
    }

    // Initialize I2C
    ret = pigpio_init();
    if (ret != 0) {
        fprintf(stderr, "Failed to initialize PIGPIO: %s\n", strerror(ret));
        gpiod_release(gpio_file);
        return 1;
    }

    // Open I2C bus
    ret = pigpio_i2c_newbus();
    if (ret != 0) {
        fprintf(stderr, "Failed to initialize I2C bus: %s\n", strerror(ret));
        pigpio_exit();
        gpiod_release(gpio_file);
        return 1;
    }

    // Open BMP280 sensor
    ret = pigpio_i2c_open_device(BMP280_ADDRESS, &i2c_fd);
    if (ret != 0) {
        fprintf(stderr, "Failed to open BMP280 sensor: %s\n", strerror(ret));
        pigpio_i2c_close(i2c_fd);
        pigpio_i2c_newbus();
        gpiod_release(gpio_file);
        return 1;
    }

    // Wait for sensor to be present
    while (1) {
        ret = pigpio_i2c_read(i2c_fd, BMP280_ADDRESS, &i2c_data, 1, 1000);
        if (ret == 0) {
            break;
        }
        usleep(500000); // Wait for 500ms
    }

    // Read temperature and pressure
    uint16_t temp_raw, press_raw;
    ret = pigpio_i2c_read(i2c_fd, BMP280_ADDRESS, &temp_raw, 1, 1000);
    if (ret == 0) {
        uint16_t temp = temp_raw << 1; // Convert raw data to temperature in °C
        ret = pigpio_i2c_read(i2c_fd, BMP280_ADDRESS, &press_raw, 1, 1000);
        if (ret == 0) {
            uint16_t press = (press_raw << 1) - 406.58; // Convert raw data to pressure in hPa
            break;
        }
    }

    // Format and transmit data as JSON
    char json[256];
    snprintf(json, sizeof(json), "{\"temperature\": %.2f, \"pressure\": %.2f}", temp, press);

    // Send JSON data via UDP
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    server_addr.sin_addr.s_addr = inet_addr("192.168.1.100");

    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        fprintf(stderr, "Failed to create UDP socket: %s\n", strerror(errno));
        pigpio_i2c_close(i2c_fd);
        pigpio_i2c_newbus();
        gpiod_release(gpio_file);
        return 1;
    }

    ret = sendto(sock, json, strlen(json), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (ret < 0) {
        fprintf(stderr, "Failed to send UDP data: %s\n", strerror(errno));
        close(sock);
        pigpio_i2c_close(i2c_fd);
        pigpio_i2c_newbus();
        gpiod_release(gpio_file);
        return 1;
    }

    // Close UDP socket
    close(sock);

    // Release I2C and GPIO resources
    pigpio_i2c_close(i2c_fd);
    gpiod_release(gpio_file);

    // Cleanly exit
    pigpio_exit();

    return 0;
}

