#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#include <gpiod.h>
#include <pigpio.h>

#define BMP180_ADDRESS 0x76
#define ALTITUDE_LOG_FILE "altitude_log.txt"

int main() {
    int i2c_fd;
    int gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct bmp180_calibration calibration;
    char log_file_path[128];
    char log_line[128];
    char timestamp[32];
    float temperature, pressure;
    int ret;

    // Initialize GPIO2 as falling-edge interrupt with internal pull-up enabled
    gpio_fd = pigpio_open(0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO2");
        return 1;
    }
    ret = pigpio_set_mode(gpio_fd, PI_INT_EDGE_FALLING);
    if (ret != 0) {
        perror("Failed to set GPIO2 as falling-edge interrupt");
        pigpio_close(gpio_fd);
        return 1;
    }
    ret = pigpio_set_pull_up_down(gpio_fd, PI_PD_UP);
    if (ret != 0) {
        perror("Failed to enable internal pull-up on GPIO2");
        pigpio_close(gpio_fd);
        return 1;
    }

    // Initialize I2C bus
    i2c_fd = i2c_open(1);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Configure I2C address and OSS
    ret = i2c_set_address(i2c_fd, BMP180_ADDRESS);
    if (ret != 0) {
        perror("Failed to set I2C address");
        i2c_close(i2c_fd);
        return 1;
    }
    ret = i2c_set_oversampling(i2c_fd, 3);
    if (ret != 0) {
        perror("Failed to set OSS to 3");
        i2c_close(i2c_fd);
        return 1;
    }

    // Initialize BMP180 sensor
    ret = bmp180_init(i2c_fd, &calibration);
    if (ret != 0) {
        perror("Failed to initialize BMP180 sensor");
        i2c_close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Poll for I2C read and write operations
        ret = i2c_transfer(i2c_fd, BMP180_ADDRESS, &i2c_data, 1);
        if (ret < 0) {
            perror("Failed to read/write to BMP180 sensor");
            i2c_close(i2c_fd);
            return 1;
        }

        // Check for errors on I2C operations
        if (i2c_data.error) {
            perror("I2C error:");
            i2c_close(i2c_fd);
            return 1;
        }

        // Read sensor data
        ret = bmp180_read_temperature_celsius(&temperature);
        if (ret != 0) {
            perror("Failed to read temperature from BMP180 sensor");
            i2c_close(i2c_fd);
            return 1;
        }

        ret = bmp180_read_pressure_pa(&pressure);
        if (ret != 0) {
            perror("Failed to read pressure from BMP180 sensor");
            i2c_close(i2c_fd);
            return 1;
        }

        // Append timestamp, temperature, and pressure to log file
        snprintf(timestamp, sizeof(timestamp), "%s", ctime(&(retire_time_t)now()));
        snprintf(log_line, sizeof(log_line), "%.2f, %.2f, %.2f", temperature, pressure, pressure);
        snprintf(log_file_path, sizeof(log_file_path), "%s/%s", ALTITUDE_LOG_FILE, timestamp);

        // Write log line to file
        ret = write(log_fd, log_line, strlen(log_line) + 1);
        if (ret < 0) {
            perror("Failed to write to log file");
            i2c_close(i2c_fd);
            return 1;
        }

        // Toggle data logging
        if (ret == 0) {
            ret = bmp180_toggle_logging(&temperature, &pressure);
            if (ret != 0) {
                perror("Failed to toggle data logging");
                i2c_close(i2c_fd);
                return 1;
            }
        }

        // Toggle logging file open/close
        ret = write(log_fd, "Data logging enabled\n", strlen("Data logging enabled") + 1);
        if (ret < 0) {
            perror("Failed to write to log file");
            i2c_close(i2c_fd);
            return 1;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    pigpio_close(gpio_fd);
    i2c_close(i2c_fd);
    return 0;
}

