        snprintf(log_line, sizeof(log_line), "%.2f, %.2f, %.2f", temperature, pressure, pressure);
        snprintf(log_file_path, sizeof(log_file_path), "%s/%s", ALTITUDE_LOG_FILE, timestamp);

        // Write log line to file
        ret = write(log_fd, log_line, strlen(log_line) + 1);
        if (ret < 0) {
            perror("Failed to write to log file");
            i2c_close(i2c_fd);
            return 1;
        }

        // Toggle data logging
