void i2c_init(void) {
    int ret;
    struct i2c_rdwr_ioctl_data i2c_data;

    i2c_data.timeout = I2C_TIMEOUT_MS;
    i2c_data.flags = 0;

    ret = gpiod_i2c_map_io(gpio24_pin, &gpiod_data);
    if (ret < 0) {
        fprintf(stderr, "Failed to map GPIO pin %d to I2C\n", gpio24_pin);
        return;
    }

    ret = gpiod_i2c_open(gpiod_data.i2c_fd, &i2c_data);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_i2c_unmap_io(gpiod_data.i2c_fd);
        return;
    }

    ret = gpiod_i2c_write(gpiod_data.i2c_fd, i2c_address, &bmp180_data, sizeof(bmp180_data));
    if (ret < 0) {
        fprintf(stderr, "Failed to write to BMP180 sensor\n");
        gpiod_i2c_close(i2c_data.i2c_fd);
        gpiod_i2c_unmap_io(gpiod_data.i2c_fd);
        return;
    }

    ret = gpiod_i2c_read(gpiod_data.i2c_fd, i2c_address, &bmp180_data, sizeof(bmp180_data));
    if (ret < 0) {
        fprintf(stderr, "Failed to read from BMP180 sensor\n");
        gpiod_i2c_close(i2c_data.i2c_fd);
        gpiod_i2c_unmap_io(gpiod_data.i2c_fd);
        return;
    }

    ret = gpiod_i2c_close(i2c_data.i2c_fd);
    if (ret < 0) {
        fprintf(stderr, "Failed to close I2C bus\n");
        gpiod_i2c_unmap_io(gpiod_data.i2c_fd);
        return;
    }
}

