#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>
#include <pigpio.h>

#define BMP180_ADDRESS 0x76
#define BMP180_I2C_TIMEOUT 5000

int main() {
    int fd, gpio, i2c;
    struct gpiod_device *device;
    struct gpiod_line *line;
    struct gpiod_event event;
    struct gpiod_event_data *data;
    uint16_t temp, pressure;
    char filename[50];
    FILE *fp;
    int oversample = 0;
    int sampleInterval = 500;
    int exitFlag = 0;

    // Initialize GPIO and I2C
    gpio = pigpio_initialize();
    if (gpio < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        exit(1);
    }

    // Open I2C bus
    fd = pigpio_open_i2c(1, BMP180_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        exit(1);
    }

    // Initialize BMP180 sensor
    pigpio_set_mode(fd, PI_OUTPUT);
    pigpio_set_speed(fd, 1000);
    pigpio_set_pull(fd, PI_UP);
    pigpio_set_reset(fd, PI_UP);
    pigpio_set_mode(fd, PI_INPUT);

    // Get GPIO and I2C device
    device = gpiod_get_device(fd);
    line = gpiod_get_line(device, "BMP180_POWER");
    if (line == NULL) {
        fprintf(stderr, "Error getting line\n");
        exit(1);
    }

    // Set oversample to 0 for ultra low power
    pigpio_set_oversample(fd, 0);

    // Open log file
    fp = fopen("bmp180_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        exit(1);
    }

    // Main loop
    while (!exitFlag) {
        // Wait for I2C communication timeout
        if (pigpio_wait_for_event(fd, BMP180_I2C_TIMEOUT) == -1) {
            fprintf(stderr, "Error waiting for I2C communication timeout\n");
            exit(1);
        }

        // Read temperature and pressure
        pigpio_set_mode(fd, PI_INPUT);
        pigpio_set_pull(fd, PI_UP);
        pigpio_set_reset(fd, PI_UP);
        pigpio_set_mode(fd, PI_OUTPUT);
        pigpio_set_speed(fd, 1000);
        pigpio_set_pull(fd, PI_DOWN);

        // Read temperature and pressure
        temp = pigpio_read_temperature(fd);
        pressure = pigpio_read_pressure(fd);

        // Validate calibration data
        if (temp != 0x7C && pressure != 0x34) {
            fprintf(stderr, "Invalid calibration data\n");
            exit(1);
        }

        // Append data to log file
        sprintf(filename, "bmp180_log_%d.txt", (int)((time(NULL) / sampleInterval) * 1000));
        fprintf(fp, "Temperature: %.2f C\n", temp);
        fprintf(fp, "Pressure: %.2f hPa\n", pressure);
        fprintf(fp, "Oversampling: %d\n", oversample);
        fprintf(fp, "Sample interval: %d ms\n", sampleInterval);
        fprintf(fp, "Sample time: %d ms\n", (int)((time(NULL) / 1000) * 1000));

        // Check for I2C communication errors
        if (pigpio_check_error(fd) != 0) {
            fprintf(stderr, "Error in I2C communication\n");
            exit(1);
        }

        // Check for GPIO errors
        if (gpio_get_state(fd) != 0) {
            fprintf(stderr, "Error in GPIO\n");
            exit(1);
        }

        // Check for timer interrupt errors
        if (gpio_is_interrupt_enabled(fd, GPIO_INT_TIMER) == 0) {
            fprintf(stderr, "Error in timer interrupt\n");
            exit(1);
        }

        // Release resources
        pigpio_release(fd);
        gpio_release(device);
        pigpio_uninitialize();
    }

    // Clean up log file
    fclose(fp);

    exit(0);
}

