#include <gpiod.h>
#include <pigpio.h>

#define PWM_FREQ 25000
#define PWM_PERIOD 100000
#define PWM_MIN_DUTY 40
#define PWM_MAX_DUTY 100

int main() {
    int pwm_fd, fan_fd;
    struct gpiod_event event;
    struct gpiod_event_attr attr;
    int fan_gpio = 18;
    int temperature_gpio = 23;
    char fan_log_filename[] = "fan_log.txt";
    char timestamp[80];
    pid_t pid;
    int exit_code;

    // Initialize GPIO and PWM
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    if (gpioSetMode(fan_gpio, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for fan.\n");
        return 1;
    }

    if (gpioSetMode(temperature_gpio, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for temperature sensor.\n");
        return 1;
    }

    if (gpioOpen(fan_gpio, O_RDWR) < 0) {
        fprintf(stderr, "Failed to open fan GPIO.\n");
        return 1;
    }

    if (gpioOpen(temperature_gpio, O_RDWR) < 0) {
        fprintf(stderr, "Failed to open temperature GPIO.\n");
        return 1;
    }

    // Initialize PWM
    if (gpioPwmInit() < 0) {
        fprintf(stderr, "Failed to initialize PWM.\n");
        return 1;
    }

    // Set PWM duty cycle
    if (gpioPwmSetDuty(pwm_fd, PWM_MIN_DUTY) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to %d.\n", PWM_MIN_DUTY);
        return 1;
    }

    // Set PWM frequency
    if (gpioPwmSetFreq(pwm_fd, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz.\n", PWM_FREQ);
        return 1;
    }

    // Set PWM period
    if (gpioPwmSetPeriod(pwm_fd, PWM_PERIOD) < 0) {
        fprintf(stderr, "Failed to set PWM period to %d.\n", PWM_PERIOD);
        return 1;
    }

    // Set PWM duty cycle to 0%
    if (gpioPwmSetDuty(pwm_fd, PWM_MIN_DUTY) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to %d.\n", PWM_MIN_DUTY);
        return 1;
    }

    // Start PWM
    if (gpioPwmStart(pwm_fd) < 0) {
        fprintf(stderr, "Failed to start PWM.\n");
        return 1;
    }

    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        // Read temperature
        if (read(temperature_gpio, &temperature, sizeof(temperature)) < 0) {
            fprintf(stderr, "Failed to read temperature.\n");
            return 1;
        }

        // Map temperature to PWM duty cycle
        int pwm_duty = (temperature - 40) * (PWM_MAX_DUTY - PWM_MIN_DUTY) / (40 - PWM_MIN_DUTY);
        if (pwm_duty < PWM_MIN_DUTY) {
            pwm_duty = PWM_MIN_DUTY;
        } else if (pwm_duty > PWM_MAX_DUTY) {
            pwm_duty = PWM_MAX_DUTY;
        }

        // Set PWM duty cycle
        if (gpioPwmSetDuty(pwm_fd, pwm_duty) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle to %d.\n", pwm_duty);
            return 1;
        }

        // Log current timestamp, temperature, and duty cycle
        if (snprintf(timestamp, sizeof(timestamp), "%s\n", get_timestamp()) < 0) {
            fprintf(stderr, "Failed to format timestamp.\n");
            return 1;
        }

        if (write(fan_log_fd, timestamp, strlen(timestamp)) < 0) {
            fprintf(stderr, "Failed to write to log file.\n");
            return 1;
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Stop PWM
    gpioPwmStop(pwm_fd);

    // Close PWM and log files
    if (gpioClose(pwm_fd) < 0) {
        fprintf(stderr, "Failed to close PWM file.\n");
        return 1;
    }

    if (gpioClose(fan_log_fd) < 0) {
        fprintf(stderr, "Failed to close log file.\n");
        return 1;
    }

    // Clean up GPIO
    gpioTerminate();

    return 0;
}

// Signal handlers
void sigint_handler(int signum) {
    printf("Received SIGINT signal. Shutting down...\n");
    exit_code = 0;
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM signal. Shutting down...\n");
    exit_code = 0;
}

