#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>

#define I2C_BUS_1 1
#define I2C_ADDRESS 0x48
#define TEMP_SENSOR_ADDRESS 0x48
#define TEMP_SENSOR_REG_THRESHOLD 28.0

static bool gpio18_initialized = false;
static bool i2c_initialized = false;
static bool i2c_bus_error = false;
static bool i2c_sensor_absent = false;
static bool alert_led_on = false;

static void i2c_init()
{
    gpio18_initialized = gpio_is_initialized(18);
    if (!gpio18_initialized) {
        gpio_open(&gpio18_gpio_fd);
        gpio_set_mode(gpio18_gpio_fd, GPIO_OUTPUT);
        gpio_write(gpio18_gpio_fd, 0);
    }

    if (!gpio_is_initialized(18)) {
        gpio_open(&gpio18_gpio_fd);
        gpio_set_mode(gpio18_gpio_fd, GPIO_OUTPUT);
        gpio_write(gpio18_gpio_fd, 0);
        gpio_output(gpio18_gpio_fd, GPIO_LOW);
    }

    gpio_set_mode(18, GPIO_OUTPUT);
    gpio_write(18, 0);
    gpio_set_level(18, 1);

    i2c_initialized = pigpio_is_initialized();
    if (!i2c_initialized) {
        pigpio_init();
    }
}

static void i2c_read_and_store_temperature()
{
    int fd = pigpio_open_i2c(I2C_BUS_1, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Error initializing I2C bus: %s\n", strerror(errno));
        i2c_bus_error = true;
        return;
    }

    int result = pigpio_read_i2c_block_data(fd, TEMP_SENSOR_ADDRESS, &(uint8_t*)&temp_sensor_data, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature sensor: %s\n", strerror(errno));
        pigpio_close(fd);
        i2c_bus_error = true;
        return;
    }

    if (temp_sensor_data[0] > TEMP_SENSOR_REG_THRESHOLD) {
        alert_led_on = true;
    } else {
        alert_led_on = false;
    }

    temp_sensor_data[0] = 0;
    pigpio_write_i2c_block_data(fd, TEMP_SENSOR_ADDRESS, &(uint8_t*)&temp_sensor_data, 1);
    pigpio_close(fd);
}

static void i2c_buffer_overflow()
{
    fprintf(stderr, "I2C buffer overflow detected\n");
    i2c_bus_error = true;
}

static void i2c_sensor_absent()
{
    fprintf(stderr, "I2C sensor absent\n");
    i2c_sensor_absent = true;
}

static void i2c_error()
{
    fprintf(stderr, "I2C error\n");
    i2c_bus_error = true;
}

static void i2c_reinitialize()
{
    if (i2c_bus_error) {
        fprintf(stderr, "I2C bus error, reinitializing...\n");
        pigpio_reset();
        pigpio_init();
    }
}

static void i2c_alert_led_on()
{
    gpio_set_level(18, 1);
}

static void i2c_alert_led_off()
{
    gpio_set_level(18, 0);
}

static void i2c_alert_led_toggle()
{
    if (alert_led_on) {
        i2c_alert_led_off();
    } else {
        i2c_alert_led_on();
    }
}

static void i2c_running_average_update(int temperature)
{
    static int running_average = 0;
    static int previous_temperature = 0;

    if (temperature != previous_temperature) {
        running_average = (running_average * 59 + temperature) / 60;
        previous_temperature = temperature;
    }
}

static void i2c_alert_led_control()
{
    if (alert_led_on) {
        i2c_alert_led_on();
    } else {
        i2c_alert_led_off();
    }
}

static void i2c_alert_led_toggle_control()
{
    i2c_alert_led_toggle();
}

static void i2c_read_temperature_buffer(int buffer_size)
{
    int i;
    for (i = 0; i < buffer_size; i++) {
        int temperature;
        if (i2c_read_and_store_temperature() == false) {
            i2c_reinitialize();
            break;
        }
        i2c_running_average_update(temperature);
        if (temperature > TEMP_SENSOR_REG_THRESHOLD) {
            i2c_alert_led_on();
        } else {
            i2c_alert_led_off();
        }
        i2c_alert_led_toggle_control();
    }
}

int main()
{
    i2c_init();

    int buffer_size = 60;
    int buffer[buffer_size];
    int buffer_index = 0;

    while (true) {
        i2c_read_temperature_buffer(buffer_size);
        for (int i = 0; i < buffer_size; i++) {
            printf("Temperature: %d\n", buffer[i]);
        }
        i2c_running_average_update(buffer[0]);
        i2c_alert_led_control();
        sleep(1);
    }

    i2c_sensor_absent();
    i2c_reinitialize();

    return 0;
}

