#define MAX31865_I2C_ADDR 0x40
#define MAX31865_SPI_CS_PIN 18
#define MAX31865_PWM_GPIO_PIN 18
#define MAX31865_PWM_DRIVER_RANGE 1000
#define MAX31865_DEFAULT_TEMP 25
#define MAX31865_DEFAULT_KP 1.0
#define MAX31865_DEFAULT_KI 0.1
#define MAX31865_DEFAULT_KD 0.01

#define MAX31865_FAULT_TEMP 80
#define MAX31865_SPI_TIMEOUT_MS 100
#define MAX31865_MAX_READ_ATTEMPTS 10

#define MAX31865_SPI_MODE_1_KHZ 500000
#define MAX31865_SPI_MODE_500_KHZ 100000

#define MAX31865_DEFAULT_CONFIG_FILE "max31865.json"

struct max31865_config {
    float temperature;
    float kp;
    float ki;
    float kd;
};

struct max31865_config max31865_default_config = {
    .temperature = MAX31865_DEFAULT_TEMP,
    .kp = MAX31865_DEFAULT_KP,
    .ki = MAX31865_DEFAULT_KI,
    .kd = MAX31865_DEFAULT_KD,
};

int max31865_spi_init(int spi_device) {
    int spi_config = (MAX31865_SPI_MODE_1_KHZ << MAX31865_SPI_MODE_1_KHZ_SHIFT) |
                    (MAX31865_SPI_MODE_1_KHZ << MAX31865_SPI_MODE_500_KHZ_SHIFT);

    int spi_result = ioctl(spi_device, SPI_IOC_WR_MODE, &spi_config);
    if (spi_result < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return -1;
    }

    spi_config = (MAX31865_SPI_MODE_500_KHZ << MAX31865_SPI_MODE_1_KHZ_SHIFT) |
                 (MAX31865_SPI_MODE_500_KHZ << MAX31865_SPI_MODE_500_KHZ_SHIFT);

    spi_result = ioctl(spi_device, SPI_IOC_WR_MODE, &spi_config);
    if (spi_result < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int max31865_i2c_init(int i2c_device) {
    int i2c_config = (MAX31865_I2C_ADDR << MAX31865_I2C_ADDR_SHIFT) |
                     (MAX31865_I2C_ADDR << MAX31865_I2C_ADDR_SHIFT);

    int i2c_result = ioctl(i2c_device, I2C_IOC_RDWR, &i2c_config);
    if (i2c_result < 0) {
        fprintf(stderr, "Failed to set I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int max31865_read_temperature(int i2c_device) {
    int i2c_result = ioctl(i2c_device, I2C_IOC_RD, &max31865_config.temperature);
    if (i2c_result < 0) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int max31865_read_config(int i2c_device) {
    int i2c_result = ioctl(i2c_device, I2C_IOC_RD, &max31865_config);
    if (i2c_result < 0) {
        fprintf(stderr, "Failed to read configuration: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int max31865_write_config(int i2c_device, struct max31865_config *config) {
    int i2c_result = ioctl(i2c_device, I2C_IOC_WR, config);
    if (i2c_result < 0) {
        fprintf(stderr, "Failed to write configuration: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int max31865_set_fault_temp(int i2c_device, float temp) {
    int i2c_result = ioctl(i2c_device, I2C_IOC_RD, &max31865_config.temperature);
    if (i2c_result < 0) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return -1;
    }

    max31865_config.temperature = temp;

    return max31865_write_config(i2c_device, &max31865_config);
}

int max31865_set_fault_temp_and_exit(int i2c_device) {
    int i2c_result = max31865_set_fault_temp(i2c_device, MAX31865_FAULT_TEMP);
