#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_DIR_OUT 0x01
#define GPIO_OUTPUT_LOW 0x00
#define GPIO_OUTPUT_HIGH 0x01

int main() {
    int fd, fan_fd, pwm_fd;
    struct gpiod_event event;
    struct gpiod_event_attr attr;
    char filename[32];
    char *log_file = "cooling_log.csv";
    int temperature_threshold = 40;
    int fan_speed_threshold = 70;
    int temperature_scale_factor = 25000;
    int pwm_frequency = 0;
    int pwm_duty_cycle = 0;
    int exit_code = 0;

    // Initialize GPIO and PWM
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        exit(EXIT_FAILURE);
    }

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize PIGPIO.\n");
        exit(EXIT_FAILURE);
    }

    // Open GPIO and PWM files
    snprintf(filename, sizeof(filename), "/sys/class/gpio/gpio18/value");
    fan_fd = open(filename, O_RDWR);
    if (fan_fd < 0) {
        fprintf(stderr, "Failed to open GPIO file.\n");
        exit(EXIT_FAILURE);
    }

    snprintf(filename, sizeof(filename), "/sys/class/gpio/gpio18/direction");
    fd = open(filename, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO direction file.\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO direction to output
    if (ioctl(fd, GPIO_DIR_OUT, GPIO_OUTPUT_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO direction to output.\n");
        exit(EXIT_FAILURE);
    }

    // Open PWM file
    snprintf(filename, sizeof(filename), "/sys/class/gpio/gpio18/value");
    pwm_fd = open(filename, O_WRONLY);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to open PWM file.\n");
        exit(EXIT_FAILURE);
    }

    // Set PWM frequency and duty cycle
    if (pigpioSetPWMfrequency(pwm_fd, pwm_frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency.\n");
        exit(EXIT_FAILURE);
    }

    if (pigpioSetPWMrange(pwm_fd, 0, 255) < 0) {
        fprintf(stderr, "Failed to set PWM range.\n");
        exit(EXIT_FAILURE);
    }

    if (pigpioSetPWMstate(pwm_fd, GPIO_OUTPUT_LOW) < 0) {
        fprintf(stderr, "Failed to set PWM state to output low.\n");
        exit(EXIT_FAILURE);
    }

    // Set PWM duty cycle
    if (pigpioSetPWM(pwm_fd, pwm_frequency, pwm_duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle.\n");
        exit(EXIT_FAILURE);
    }

    // Start polling CPU temperature
    if (pigpioEventRegister(fan_fd, &event, 1, 0) < 0) {
        fprintf(stderr, "Failed to register event.\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Poll CPU temperature and map it to PWM duty cycle
        if (pigpioEventWait(fan_fd, &event, 1) < 0) {
            fprintf(stderr, "Failed to wait for event.\n");
            exit(EXIT_FAILURE);
        }

        if (event.value == GPIO_OUTPUT_HIGH) {
            pwm_duty_cycle = (event.value - GPIO_OUTPUT_LOW) * temperature_scale_factor / 255;
            if (pigpioSetPWM(pwm_fd, pwm_frequency, pwm_duty_cycle) < 0) {
                fprintf(stderr, "Failed to set PWM duty cycle.\n");
                exit(EXIT_FAILURE);
            }
        }

        // Log temperature and PWM duty cycle
        if (pigpioEventDataRead(fan_fd, &event) < 0) {
            fprintf(stderr, "Failed to read event data.\n");
            exit(EXIT_FAILURE);
        }

        if (event.value == GPIO_OUTPUT_LOW) {
            temperature_scale_factor = 25000;
        }

        if (pigpioEventDataRead(fan_fd, &event) < 0) {
            fprintf(stderr, "Failed to read event data.\n");
            exit(EXIT_FAILURE);
        }

        if (event.value == GPIO_OUTPUT_HIGH) {
            temperature_threshold = 40;
            pwm_frequency = 0;
        }

        if (event.value == GPIO_OUTPUT_LOW) {
            temperature_threshold = 70;
            pwm_frequency = 0;
        }

        if (event.value == GPIO_OUTPUT_HIGH) {
            exit_code = 0;
        }

