#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define SENSOR_ADDRESS 0x1A
#define IR_THRESHOLD 2000

int main() {
    int fd;
    int gpio_num = 17;
    int i;
    struct gpiod_event event;
    struct gpiod_event_attr attr;
    char log_file_path[] = "adpd144ri_log.txt";
    FILE *log_file;

    // Initialize I2C file descriptor
    fd = pigpio_open_i2c(I2C_BUS_NUM, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    // Initialize GPIO
    if (!gpio_init()) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    // Open log file
    log_file = fopen(log_file_path, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Initialize sensor
    if (!gpio_set_mode(gpio_num, GPIO_OUTPUT)) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return 1;
    }

    // Set IR threshold
    attr.event_type = GPIGPIOEVENT_RISING;
    attr.event_flags = GPIGPIOEVENT_LEVEL_HIGH;
    attr.event_data = IR_THRESHOLD;
    if (!gpio_event_attr_set(gpio_num, &attr)) {
        fprintf(stderr, "Error setting IR threshold\n");
        return 1;
    }

    // Start sensor sampling
    gpio_set_mode(gpio_num, GPIO_OUTPUT);
    gpio_write(gpio_num, 0);
    gpio_delay_us(10);
    gpio_set_mode(gpio_num, GPIO_INPUT);

    while (1) {
        // Read sensor data
        if (gpio_read(gpio_num) == 0) {
            // IR reading exceeds threshold, activate LED
            gpio_set_level(gpio_num, 1);
            usleep(100);
            gpio_set_level(gpio_num, 0);
        }

        // Wait for 100 ms
        gpio_delay_us(100);

        // Read sensor data
        if (gpio_read(gpio_num) == 0) {
            // IR reading exceeds threshold, activate LED
            gpio_set_level(gpio_num, 1);
            usleep(100);
            gpio_set_level(gpio_num, 0);
        }

        // Log data
        fprintf(log_file, "timestamp,red,ir\n");
        fclose(log_file);

        // Wait for sensor data
        usleep(100);
    }

    // Release resources
    gpio_release(fd);
    gpio_exit();
    pigpio_close(fd);

    return 0;
}

