        return -1;
    }

    ret = gpiod_set_dir(fd, GPID_INPUT);
    if (ret < 0) {
        perror("Failed to set gpiochip0 direction to INPUT");
        return -1;
    }

    ret = gpiod_set_value(fd, GPIO_PULL_DOWN);
    if (ret < 0) {
        perror("Failed to set gpiochip0 pull-down resistor");
        return -1;
    }

    ret = gpiod_request_line(fd, GPIO18, GPIO_LINE_IN);
    if (ret < 0) {
        perror("Failed to request GPIO18 line as input");
        return -1;
    }

    return fd;
}

void rpm_counter_isr(void *arg) {
    struct gpiod_event_data *data = arg;
    uint32_t pulse_count = 0;

    while (1) {
        if (gpiod_event_wait(data->gpio, &data->event) == -1) {
            perror("Failed to wait for gpio event");
            continue;
        }

        if (data->event.type == GPID_EVENT_RISING_EDGE) {
            pulse_count++;
        }
    }
}

