#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define GAIN_SELECT_PIN 18
#define AUDIO_OUTPUT_PIN 17

int main() {
    int gain_fd, audio_fd, log_fd;
    struct gpiod_event event;
    struct gpiod_event_data data;
    char filename[20];
    int log_interval = 10;
    int log_count = 0;
    int rising_edge_count = 0;
    int log_file_fd;

    // Initialize GPIO and log file
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    gain_fd = gpiod_get_direction(GAIN_SELECT_PIN);
    if (gain_fd < 0) {
        fprintf(stderr, "Failed to get gain direction.\n");
        gpiod_exit();
        return 1;
    }

    audio_fd = gpiod_get_value(GAIN_SELECT_PIN);
    if (audio_fd < 0) {
        fprintf(stderr, "Failed to get audio value.\n");
        gpiod_exit();
        return 1;
    }

    // Open log file
    filename[0] = 'a';
    filename[1] = 'd';
    filename[2] = 'a';
    filename[4] = 'a';
    filename[5] = 'u';
    filename[6] = 'f';
    filename[7] = 'f';
    filename[8] = 'i';
    filename[9] = 'l';
    filename[10] = 'e';
    filename[11] = '.';
    filename[12] = 's';
    filename[13] = 'e';
    filename[14] = 'n';
    filename[15] = '.';
    filename[16] = 'r';
    filename[17] = 'e';
    filename[18] = 'a';
    filename[19] = 'l';
    filename[20] = '\0';

    log_file_fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_file_fd < 0) {
        fprintf(stderr, "Failed to open log file.\n");
        gpiod_exit();
        return 1;
    }

    // Initialize log file
    if (write(log_file_fd, "YYYY-MM-DD HH:MM:SS LEVEL\n", 18) < 0) {
        fprintf(stderr, "Failed to write log entry.\n");
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Read audio data
        if (read(audio_fd, &event, sizeof(event)) != sizeof(event)) {
            fprintf(stderr, "Failed to read audio data.\n");
            gpiod_exit();
            return 1;
        }

        // Check for rising edge
        if (event.type == GPIDEV_EVENT_RISING_EDGE) {
            rising_edge_count++;
            if (rising_edge_count >= log_interval) {
                if (write(log_file_fd, "YYYY-MM-DD HH:MM:SS LEVEL\n", 18) < 0) {
                    fprintf(stderr, "Failed to write log entry.\n");
                    gpiod_exit();
                    return 1;
                }
                log_count++;
                rising_edge_count = 0;
            }
        }

        // Log events
        if (log_count > 0) {
            if (write(log_file_fd, "YYYY-MM-DD HH:MM:SS LEVEL\n", 18) < 0) {
                fprintf(stderr, "Failed to write log entry.\n");
                gpiod_exit();
                return 1;
            }
            log_count = 0;
        }
    }

    // Clean up GPIO and log file
    gpiod_exit();
    close(gain_fd);
    close(audio_fd);
    close(log_file_fd);

    return 0;
}

