    char timestamp[50];
    FILE *log_file;
    bool sensor_absent = false;
    bool bus_error = false;

    // Initialize I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO for I2C bus
    i2c_gpio_fd = open("/dev/i2c-gpio1", O_RDWR);
    if (i2c_gpio_fd < 0) {
        perror("Error opening I2C GPIO");
        exit(EXIT_FAILURE);
    }

    // Set up I2C device
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS);
    if (ret < 0) {
        perror("Error setting I2C device address");
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen("air_quality_log.csv", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Initialize IAQ index
    int iaq_index = 0;

    while (true) {
        // Read sensor data
        ret = ioctl(i2c_fd, I2C_RDWR, i2c_buf);
        if (ret < 0) {
            if (errno == EAGAIN) {
                // Wait for sensor to become available
                sleep(1);
                continue;
            } else {
                perror("Error reading sensor data");
                exit(EXIT_FAILURE);
            }
        }

        // Check if sensor is absent
        if (memcmp(i2c_buf, &i2c_gpio_fd, sizeof(i2c_gpio_fd)) != 0) {
            sensor_absent = true;
        }

        // Read TVOC value
        ret = ioctl(i2c_fd, I2C_RDWR, i2c_buf);
        if (ret < 0) {
            if (errno == EAGAIN) {
                // Wait for sensor to become available
                sleep(1);
                continue;
            } else {
                perror("Error reading TVOC value");
                exit(EXIT_FAILURE);
            }
        }
        tvoc_value = (uint16_t)i2c_buf[0];

        // Read eCO2 value
        ret = ioctl(i2c_fd, I2C_RDWR, i2c_buf);
        if (ret < 0) {
            if (errno == EAGAIN) {
                // Wait for sensor to become available
                sleep(1);
                continue;
            } else {
                perror("Error reading eCO2 value");
                exit(EXIT_FAILURE);
            }
        }
        eco2_value = (uint16_t)i2c_buf[1];

        // Compute IAQ index
        iaq_index = (tvoc_value * 100) + (eCO2_THRESHOLD - eco2_value);

        // Log data
        sprintf(timestamp, "%s", ctime(&(time(NULL))));
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, tvoc_value, eco2_value, iaq_index);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close log file
    fclose(log_file);

    // Close I2C device
    close(i2c_fd);

    // Close GPIO device
    close(i2c_gpio_fd);

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

