#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define TTP223_TAMPER "ttp223_tamper"
#define TOUCH_EVENT_TIMEOUT 5000 // 5 seconds

int main() {
    int chip, file, ret;
    struct gpiod_event event;
    struct gpiod_event_data data;
    struct timespec ts_start, ts_end;
    unsigned long long duration;
    char buffer[32];

    // Initialize the GPIO chip
    chip = gpiod_get_chip_by_name("gpiochip0");
    if (chip == -1) {
        fprintf(stderr, "Failed to get chip: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Open the GPIO line
    file = gpiod_get_line_by_name(chip, "17", "gpio17");
    if (file == -1) {
        fprintf(stderr, "Failed to open GPIO line: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the line as an input
    ret = gpiod_set_property(file, "direction", "input");
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the event detection mode
    ret = gpiod_set_event_detect(file, "rising", "both");
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO event detection: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set the event polling interval
    ret = gpiod_set_event_poll(file, TOUCH_EVENT_TIMEOUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO event polling interval: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize the event data
    memset(&event, 0, sizeof(event));
    event.type = GPIGPIO_EVENT_TYPE_LEVEL;
    event.event_mask = GPIGPIO_EVENT_TYPE_LEVEL;
    event.data = &data;

    // Main loop
    while (1) {
        // Wait for the event
        ret = gpiod_wait_event(file, &event, NULL, 0);
        if (ret == -1) {
            fprintf(stderr, "Failed to wait for event: %s\n", gpiod_strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Check if the event is a touch event
        if (event.type == GPIGPIO_EVENT_TYPE_LEVEL) {
            // Get the current state of the line
            ret = gpiod_get_event_data(file, &event);
            if (ret != 0) {
                fprintf(stderr, "Failed to get event data: %s\n", gpiod_strerror(errno));
                exit(EXIT_FAILURE);
            }

            // Check if the line is HIGH
            if (event.level == 1) {
                // Check if the line has been HIGH for more than 5 seconds
                if (event.time_stamp.tv_sec - ts_start.tv_sec > TOUCH_EVENT_TIMEOUT) {
                    // Print the intrusion alert
                    printf("Touch event detected: HIGH for more than 5 seconds\n");

                    // Reset the timer
                    ts_start = ts_end;
                    duration = 0;
                }
            }
        }

        // Release the GPIO line
        ret = gpiod_release_line(file);
        if (ret != 0) {
            fprintf(stderr, "Failed to release GPIO line: %s\n", gpiod_strerror(errno));
            exit(EXIT_FAILURE);
        }
    }

    return 0;
}

