                    // Reset the timer
                    ts_start = ts_end;
                    duration = 0;
                }
            }
        }

        // Release the GPIO line
        ret = gpiod_release_line(file);
        if (ret != 0) {
            fprintf(stderr, "Failed to release GPIO line: %s\n", gpiod_strerror(errno));
            exit(EXIT_FAILURE);
        }
    }

    return 0;
}
