#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <stdlib.h>
#include <pigpio.h>

#define GPIO_DIR_OUT  (1 << 4)
#define GPIO_PWM_CHANNEL 18

int main() {
    int fd, gpio_fd, pwm_fd;
    struct gpiod_event event;
    struct timespec start_time, end_time;
    struct timespec pwm_start_time, pwm_end_time;
    struct timespec pwm_duration;
    int pwm_duty_cycle, pwm_frequency;
    int sensor_absent_timeout = 5000; // 5 seconds
    char filename[32];
    char log_message[256];

    // Initialize GPIO and PWM
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        return 1;
    }

    // Set GPIO4 as an output
    gpioSetMode(4, GPIO_DIR_OUT);

    // Set GPIO18 as an output
    gpioSetMode(18, GPIO_DIR_OUT);

    // Set PWM frequency and duty cycle
    pwmFrequency = 100;
    pwmDutyCycle = 50;

    // Create log file
    snprintf(filename, sizeof(filename), "flame_log.txt");
    fd = open(filename, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up debounce
    start_time = get_time();
    end_time = start_time;
    pwm_start_time = end_time;
    pwm_end_time = end_time;
    pwm_duration.tv_sec = 0;
    pwm_duration.tv_nsec = 0;

    // Main loop
    while (1) {
        // Read sensor
        if (gpioRead(4) == 0) {
            // Flame detected, start PWM
            gpioSetPWM(18, pwm_frequency, pwm_duty_cycle);
            pwm_start_time = get_time();
            pwm_end_time = pwm_start_time;
            pwm_duration.tv_sec = 0;
            pwm_duration.tv_nsec = 0;
            pwm_duty_cycle = 50;
            pwm_frequency = 100;
            start_time = get_time();
            end_time = start_time;
            pwm_start_time = end_time;
            pwm_end_time = end_time;
            pwm_duration.tv_sec = 0;
            pwm_duration.tv_nsec = 0;
        } else {
            // No flame detected, wait for 50 ms
            usleep(50000);
        }

        // Log event
        get_time(&start_time);
        get_time(&end_time);
        pwm_duration.tv_sec = (end_time.tv_sec - start_time.tv_sec) + 1;
        pwm_duration.tv_nsec = (end_time.tv_nsec - start_time.tv_nsec) + 500000;
        snprintf(log_message, sizeof(log_message), "Flame detected at %s\n",
                 ctime_r(&start_time.tv_sec, &start_time.tv_nsec));
        write(fd, log_message, strlen(log_message) + 1);

        // Wait for debounce
        usleep(50);

        // Check for sensor absent condition
        if (gpioRead(4) == 0) {
            // Sensor absent, wait for timeout
            usleep(sensor_absent_timeout * 1000);
            continue;
        }

        // Check for GPIO read errors
        if (gpioRead(4) < 0) {
            fprintf(stderr, "Failed to read sensor\n");
            return 1;
        }

        // Check for PWM errors
        if (pwmSetPWM(18, pwm_frequency, pwm_duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM\n");
            return 1;
        }

        // Check for PWM errors
        if (pwmGetPWM(18, &pwm_duty_cycle) < 0) {
            fprintf(stderr, "Failed to get PWM\n");
            return 1;
        }

        // Check for GPIO errors
        if (gpioRead(4) == 1) {
            fprintf(stderr, "Failed to read sensor\n");
            return 1;
        }
    }

    // Cleanup
    gpioTerminate();
    pigpioTerminate();

    return 0;
}

