#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_DIR_OUT 0x01
#define GPIO_INPUT  0x00

int main()
{
    int fd, gpioHandle;
    struct gpiod_event event;
    struct timespec startTime, endTime;
    char filename[32];
    char buffer[32];
    int state = 0;
    int logFile = 0;
    int logFileHandle;

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Set GPIO 20 as an output
    gpioSetMode(20, GPIO_DIR_OUT);

    // Open the log file
    snprintf(filename, sizeof(filename), "/home/pi/flame_log.txt");
    logFileHandle = open(filename, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (logFileHandle < 0)
    {
        fprintf(stderr, "Error: Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (1)
    {
        // Check if the GPIO chip is initialized
        if (gpioIsInitialized() < 0)
        {
            fprintf(stderr, "Error: Failed to initialize GPIO\n");
            return 1;
        }

        // Wait for the KY-026 Flame Sensor to transition
        gpioWaitForEvent(20, GPIO_INPUT, &event);

        // Check if the sensor state has changed
        if (event.state == 1)
        {
            // Log the new state
            if (logFileHandle != -1)
            {
                struct timeval now;
                gettimeofday(&now, NULL);
                int64_t timestamp = (int64_t)(now.tv_sec * 1000000 + now.tv_usec / 1000);
                snprintf(buffer, sizeof(buffer), "%ld\t%d\n", timestamp, state);
                write(logFileHandle, buffer, strlen(buffer) + 1);
            }

            // Reset the sensor state
            state = 0;
        }

        // Release the GPIO handle
        gpioRelease(gpioHandle);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Cleanup
    gpioTerminate();

    return 0;
}

