#define I2C_DEVICE_ADDR 0x29

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct i2c_rdwr_ioctl_data i2c_msgs_full[2];
    struct i2c_rdwr_data_ptr i2c_data_ptr;
    struct timeval start_time, end_time;
    uint16_t lux_value;
    char filename[20];
    char *timestamp;
    char *log_file = "light_data.txt";
    int retry_count = 0;
    int exit_gracefully = 0;

    // Initialize I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C bus speed
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) < 0) {
        perror("Error setting I2C bus speed");
        exit(EXIT_FAILURE);
    }

    // Open the sensor file
    if ((filename = (char*)malloc(20 * sizeof(char))) == NULL) {
        perror("Error allocating memory for filename");
        exit(EXIT_FAILURE);
    }
    snprintf(filename, 20, "/dev/i2c-1/%s", filename);

    // Open the file for appending
    if ((fp = fopen(filename, "a")) == NULL) {
        perror("Error opening file for appending");
        exit(EXIT_FAILURE);
    }

    // Set up the sensor for continuous conversion mode
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) < 0) {
        perror("Error setting sensor for continuous conversion mode");
        exit(EXIT_FAILURE);
    }

    // Set the sensor to automatic full-scale range
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) < 0) {
        perror("Error setting sensor to automatic full-scale range");
        exit(EXIT_FAILURE);
    }

    // Set up the I2C message structure
    i2c_msgs[0].addr = I2C_DEVICE_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 2;
    i2c_msgs[0].buf = (void*)&i2c_data;
    i2c_msgs[1].addr = I2C_DEVICE_ADDR;
    i2c_msgs[1].flags = 0;
    i2c_msgs[1].len = 2;
    i2c_msgs[1].buf = (void*)&i2c_data_ptr;

    // Set up the I2C message structure for reading data
    i2c_msgs_full[0].addr = I2C_DEVICE_ADDR;
    i2c_msgs_full[0].flags = 0;
    i2c_msgs_full[0].len = 2;
    i2c_msgs_full[0].buf = (void*)&lux_value;

    // Set up the I2C message structure for reading data
    i2c_msgs_full[1].addr = I2C_DEVICE_ADDR;
    i2c_msgs_full[1].flags = 0;
    i2c_msgs_full[1].len = 2;
    i2c_msgs_full[1].buf = (void*)&timestamp;

    // Set up the I2C message structure for reading data
    i2c_msgs_full[2].addr = I2C_DEVICE_ADDR;
    i2c_msgs_full[2].flags = 0;
    i2c_msgs_full[2].len = 2;
    i2c_msgs_full[2].buf = (void*)&start_time;

    // Set up the I2C message structure for reading data
    i2c_msgs_full[3].addr = I2C_DEVICE_ADDR;
    i2c_msgs_full[3].flags = 0;
    i2c_msgs_full[3].len = 2;
    i2c_msgs_full[3].buf = (void*)&end_time;

    // Start the I2C transaction
    if (i2c_transfer(i2c_fd, i2c_msgs, 4, &retry_count) < 4) {
        perror("Error initiating I2C transaction");
        exit(EXIT_FAILURE);
    }

    // Wait for the sensor to complete the conversion
    while (retry_count < 3) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) < 0) {
            perror("Error waiting for sensor to complete conversion");
            exit(EXIT_FAILURE);
        }
        sleep(1);
        retry_count++;
    }

    // Read lux value approximately every 100 ms
    while (1) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) < 0) {
            perror("Error reading lux value");
            exit(EXIT_FAILURE);
        }

        // Append lux value to the log file
        if (fprintf(fp, "%lu\n", lux_value) < 0) {
            perror("Error writing to log file");
            exit(EXIT_FAILURE);
        }

        // Wait for 100 ms
        sleep(100);
    }

    // Release the I2C bus handle
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) < 0) {
        perror("Error releasing I2C bus handle");
        exit(EXIT_FAILURE);
    }

    // Release the driver resources
    if (i2c_unregister_device(i2c_fd) < 0) {
        perror("Error releasing driver resources");
        exit(EXIT_FAILURE);
    }

    // Close all open file handles
    if (fclose(fp) < 0) {
        perror("Error closing file handle");
        exit(EXIT_FAILURE);
    }

    // Cleanup
    free(filename);
    return 0;
}

