    if (gpiod_chip_by_name(GPIO_FILE, &chip_fd) < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpiod_exit();
        return 1;
    }

    // Get chip info
    if (gpiod_chip_info(chip_fd, &chip_info) < 0) {
        fprintf(stderr, "Failed to get chip info\n");
        gpiod_exit();
        return 1;
    }

    // Get line info
    if (gpiod_chip_get_lines(chip_fd, line_info, GPIO_LINE_COUNT) < 0) {
        fprintf(stderr, "Failed to get line info\n");
        gpiod_exit();
