        for (int i = 0; i < GPIO_LINE_COUNT; i++) {
            if (gpiod_line_get_state(line_info[i].line_number, &line_info[i].state) < 0) {
                fprintf(stderr, "Failed to get line state\n");
                continue;
            }

            // Print binary state
            printf("%d ", line_info[i].state);
        }

        // Print newline
