#include <sys/gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define GPIO_DIR_IN  2
#define GPIO_DIR_OUT 3
#define GPIO_PULL_DOWN 4

int main() {
    int fd, gpioHandle;
    struct gpiod_line_config lineConfig;
    struct gpiod_event_config eventConfig;
    char buffer[32];

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize libgpiod\n");
        return 1;
    }

    // Open GPIO file descriptor
    fd = gpiod_open_by_name("/dev/gpiochip0");
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO file descriptor\n");
        gpiod_exit();
        return 1;
    }

    // Configure GPIO pins as inputs with pull-down resistors
    lineConfig.line_id = gpiod_get_line_id("/dev/gpiochip0", GPIO_DIR_IN);
    lineConfig.direction = GPIO_DIR_IN;
    lineConfig.type = GPIO_PULL_DOWN;
    if (gpiod_set_line_config(fd, &lineConfig) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO line configuration\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Configure OUT1-OUT8 as inputs
    lineConfig.line_id = gpiod_get_line_id("/dev/gpiochip0", GPIO_DIR_OUT | GPIO_DIR_IN);
    lineConfig.direction = GPIO_DIR_OUT;
    lineConfig.type = GPIO_PULL_DOWN;
    if (gpiod_set_line_config(fd, &lineConfig) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO line configuration\n");
        gpiod_close(fd);
        gpiod_exit();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Loop to read sensor data
    while (1) {
        // Read sensor data
        if (gpiod_get_event_data(fd, &eventConfig, buffer, sizeof(buffer)) < 0) {
            fprintf(stderr, "Error: Failed to read sensor data\n");
            break;
        }

        // Print sensor data
        printf("[+%03d ms] CH%d=%d\n", (int)(100 * 1000 / (gettimeofday()->tv_sec - start_time).tv_sec), eventConfig.line_id - GPIO_DIR_OUT, eventConfig.value);

        // Wait for 100 ms
        sleep(100);
    }

    // Cleanup
    gpiod_exit();
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    printf("Shutting down...\n");
    exit(0);
}

