#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_ADDR 0x1A // I2C address of the TMAG5110 sensor

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    int ret;

    // Initialize the GPIO pins
    gpio_set_mode(4, GPIO_OUT);
    gpio_set_mode(5, GPIO_OUT);

    // Initialize the I2C bus
    fd = i2c_open(I2C_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize the driver library
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize the driver library: %s\n", strerror(ret));
        return 1;
    }

    // Set up the I2C communication
    i2c_msgs[0].addr = I2C_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 2;
    i2c_msgs[0].buf = (void *)&i2c_data;
    i2c_msgs[1].addr = I2C_ADDR;
    i2c_msgs[1].flags = 0;
    i2c_msgs[1].len = 2;
    i2c_msgs[1].buf = (void *)&i2c_data;

    // Read sensor data
    ret = gpiod_property_read(4, "direction", &i2c_data.direction);
    if (ret < 0) {
        fprintf(stderr, "Failed to read direction property: %s\n", strerror(ret));
        return 1;
    }

    ret = gpiod_property_read(4, "value", &i2c_data.value);
    if (ret < 0) {
        fprintf(stderr, "Failed to read value property: %s\n", strerror(ret));
        return 1;
    }

    // Check if the sensor outputs are configured as open-drain with external pull-up resistors
    if (i2c_data.direction != 0 && i2c_data.value == 0) {
        printf("Sensor 1 OUT is configured as open-drain with external pull-up resistor.\n");
    } else {
        printf("Sensor 1 OUT is configured as push-pull.\n");
    }

    // Read sensor data every 500 ms
    while (1) {
        ret = gpiod_property_read(4, "value", &i2c_data.value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read value property: %s\n", strerror(ret));
            return 1;
        }

        ret = gpiod_property_read(5, "direction", &i2c_data.direction);
        if (ret < 0) {
            fprintf(stderr, "Failed to read direction property: %s\n", strerror(ret));
            return 1;
        }

        if (i2c_data.value == 0) {
            printf("Sensor 2 OUT is asserted.\n");
        } else {
            printf("Sensor 2 OUT is unasserted.\n");
        }

        // Wait for 500 ms
        sleep(0.5);
    }

    // Clean up
    gpio_set_mode(4, GPIO_IN);
    gpio_set_mode(5, GPIO_IN);
    gpiod_term();

    return 0;
}

