        fprintf(stderr, "Failed to set GPIO mode.\n");
        return 1;
    }

    if (gpioSetPullUpDrain(BCM_GPIO, GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-up/down.\n");
        return 1;
    }

    // Initialize the Omron D7E-1 tilt sensor
    if (gpioSetLine(BCM_GPIO, TILT_PIN) < 0) {
        fprintf(stderr, "Failed to set tilt sensor line.\n");
        return 1;
    }

    // Print the startup banner
    printf("Raspberry Pi Zero W Tilt Sensor Monitor\n");

    // Main loop
    while (1) {
        // Read the tilt sensor state
        ret = gpioGetLine(BCM_GPIO, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read sensor state.\n");
            return 1;
        }

        if (event.value == GPIO_LOW) {
            printf("Tilted\n");
        } else {
            printf("Not Tilted\n");
        }

        // Wait for 100 ms
        sleep(100);
    }

    // Cleanup GPIO and pigpio
    gpioTerminate();

    return 0;
}

