#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/i2c-dev.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x40

// Function prototypes
void i2c_init();
void i2c_cleanup();
void i2c_read_uv_index();
void i2c_read_als_visible();
void write_csv_line(const char* timestamp, int uv_index, int als_visible);

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct timeval tv;
    char csv_line[128];
    char* timestamp = NULL;
    int uv_index = 0, als_visible = 0;

    // Initialize I2C bus
    i2c_init();

    // Open I2C file descriptor
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    // Check if the sensor is present
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) < 0) {
        if (errno == ENODEV) {
            fprintf(stderr, "Sensor is missing\n");
            exit(EXIT_FAILURE);
        } else {
            perror("Error accessing sensor");
            exit(EXIT_FAILURE);
        }
    }

    // Initialize the I2C communication
    if (ioctl(i2c_fd, I2C_RDWR, I2C_DEVICE_ADDR) < 0) {
        perror("Error initializing I2C communication");
        exit(EXIT_FAILURE);
    }

    // Start the I2C communication loop
    while (1) {
        // Get the current timestamp
        gettimeofday(&tv, NULL);

        // Read the UV index
        if (ioctl(i2c_fd, I2C_RD, I2C_DEVICE_ADDR, &i2c_msgs[0].msg) < 0) {
            perror("Error reading UV index");
            exit(EXIT_FAILURE);
        }

        i2c_msgs[1].msg.msg_len = sizeof(int);
        if (ioctl(i2c_fd, I2C_RD, I2C_DEVICE_ADDR, &i2c_msgs[1].msg) < 0) {
            perror("Error reading UV index");
            exit(EXIT_FAILURE);
        }

        uv_index = ntohs(i2c_msgs[1].msg.msg_data);

        // Read the visible ambient light
        if (ioctl(i2c_fd, I2C_RD, I2C_DEVICE_ADDR, &i2c_msgs[0].msg) < 0) {
            perror("Error reading visible ambient light");
            exit(EXIT_FAILURE);
        }

        i2c_msgs[1].msg.msg_len = sizeof(int);
        if (ioctl(i2c_fd, I2C_RD, I2C_DEVICE_ADDR, &i2c_msgs[1].msg) < 0) {
            perror("Error reading visible ambient light");
            exit(EXIT_FAILURE);
        }

        als_visible = ntohs(i2c_msgs[1].msg.msg_data);

        // Write the data to the CSV file
        if (write_csv_line(tv.tv_sec, uv_index, als_visible) < 0) {
            perror("Error writing to CSV file");
            exit(EXIT_FAILURE);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up I2C communication
    if (ioctl(i2c_fd, I2C_RDWR, I2C_DEVICE_ADDR) < 0) {
        perror("Error closing I2C device");
        exit(EXIT_FAILURE);
    }

    // Clean up I2C file descriptor
    close(i2c_fd);

    // Clean up CSV file
    if (unlink("uv_als_log.csv") < 0) {
        perror("Error deleting CSV file");
        exit(EXIT_FAILURE);
    }

    // Clean up I2C communication
    i2c_cleanup();

    return 0;
}

// Function to initialize I2C communication
void i2c_init() {
    struct i2c_rdwr_ioctl_data i2c_data;
    int i;

    // Set up the I2C communication parameters
    i2c_data.mode = I2C_MODE_I2C;
    i2c_data.sda_io_num = 1;
    i2c_data.scl_io_num = 2;
    i2c_data.timeout = 100;

    // Open the I2C file descriptor
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    // Set up the I2C communication parameters
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) < 0) {
        if (errno == ENODEV) {
            fprintf(stderr, "Sensor is missing\n");
            exit(EXIT_FAILURE);
        } else {
            perror("Error accessing sensor");
            exit(EXIT_FAILURE);
        }
    }

    // Set up the I2C communication parameters
    if (ioctl(i2c_fd, I2C_RDWR, I2C_DEVICE_ADDR) < 0) {
        perror("Error initializing I2C communication");
        exit(EXIT_FAILURE);
    }
}

// Function to clean up I2C communication
void i2c_cleanup() {
    if (ioctl(i2c_fd, I2C_RDWR, I2C_DEVICE_ADDR) < 0) {
        perror("Error closing I2C device");
        exit(EXIT_FAILURE);
    }

    if (close(i2c_fd) < 0) {
        perror("Error closing I2C file descriptor");
        exit(EXIT_FAILURE);
    }
}

// Function to read the UV index from the sensor
void i2c_read_uv_index() {
    struct i2c_msg i2c_msgs[2];
    int i;

    // Set up the I2C communication parameters
    i2c_msgs[0].msg.msg_len = 2;
    i2c_msgs[0].msg.msg_buf = (char*)&i2c_msgs[1].msg.msg_buf;
    i2c_msgs[0].msg.msg_buf[0] = 0x00;
    i2c_msgs[0].msg.msg_buf[1] = 0x80;

    i2c_msgs[1].msg.msg_len = 1;
    i2c_msgs[1].msg.msg_buf = (char*)&i2c_msgs[0].msg.msg_buf[2];

    // Read the UV index
    if (ioctl(i2c_fd, I2C_RD, I2C_DEVICE_ADDR, i2c_msgs) < 0) {
        perror("Error reading UV index");
        exit(EXIT_FAILURE);
    }
}

// Function to read the visible ambient light from the sensor
void i2c_read_als_visible() {
    struct i2c_msg i2c_msgs[2];
    int i;

    // Set up the I2C communication parameters
    i2c_msgs[0].msg.msg_len = 2;
    i2c_msgs[0].msg.msg_buf = (char*)&i2c_msgs[1].msg.msg_buf;
    i2c_msgs[0].msg.msg_buf[0] = 0x00;
    i2c_msgs[0].msg.msg_buf[1] = 0x40;

    i2c_msgs[1].msg.msg_len = 1;
    i2c_msgs[1].msg.msg_buf = (char*)&i2c_msgs[0].msg.msg_buf[2];

    // Read the visible ambient light
    if (ioctl(i2c_fd, I2C_RD, I2C_DEVICE_ADDR, i2c_msgs) < 0) {
        perror("Error reading visible ambient light");
        exit(EXIT_FAILURE);
    }
}

// Function to write a line to the CSV file
void write_csv_line(const char* timestamp, int uv_index, int als_visible) {
    char line[128];
    snprintf(line, sizeof(line), "%.4f,%.2d\n", (double)get_current_time() / (double)60.0, uv_index);
    if (write(1, line, strlen(line)) < 0) {
        perror("Error writing to CSV file");
        exit(EXIT_FAILURE);
    }
}

// Function to get the current time in seconds
double get_current_time() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (tv.tv_sec / 60.0);
}

