#include <linux/i2c-dev.h>

#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_SCL_GPIO_NUMBER 2
#define I2C_SDA_GPIO_NUMBER 3

int main() {
    int i2c_fd;
    int csv_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpiod_chip_path gpiod_path;
    struct gpiod_value gpiod_value;
    struct timespec start_time, end_time;
    struct timespec sleep_time;
    char header[80];
    char csv_file_name[128];
    char *sensor_mode = "0x01";
    char *sensor_data_path = "/sys/class/gpio/gpio2/value";
    char *csv_file_path = "/home/pi/fan_health.csv";

    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    if (gpioSetMode(I2C_SDA_GPIO_NUMBER, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C SDA GPIO mode.\n");
        return 1;
    }

    if (gpioSetMode(I2C_SCL_GPIO_NUMBER, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C SCL GPIO mode.\n");
        return 1;
    }

    if (gpioOpen(I2C_SDA_GPIO_NUMBER, &gpio_output) < 0) {
        fprintf(stderr, "Failed to open I2C SDA GPIO.\n");
        return 1;
    }

    if (gpioOpen(I2C_SCL_GPIO_NUMBER, &gpio_output) < 0) {
        fprintf(stderr, "Failed to open I2C SCL GPIO.\n");
        return 1;
    }

    // Set sensor mode
    if (gpioSetValue(sensor_mode, GPIO_LEVEL_HIGH) < 0) {
        fprintf(stderr, "Failed to set sensor mode.\n");
        return 1;
    }

    // Set sensor data path
    if (gpioSetValue(sensor_data_path, GPIO_LEVEL_LOW) < 0) {
        fprintf(stderr, "Failed to set sensor data path.\n");
        return 1;
    }

    // Open CSV file
    if (gpioOpen(csv_file_path, &csv_fd, O_WRONLY | O_CREAT | O_TRUNC, 0644) < 0) {
        fprintf(stderr, "Failed to open CSV file.\n");
        return 1;
    }

    // Wait for sensor to become active
    start_time.tv_sec = 0;
    start_time.tv_nsec = 1000000000;
    while (gpioGetValue(sensor_data_path) == GPIO_LEVEL_LOW) {
        nanosleep(&start_time, &sleep_time);
        if (nanosleep(&end_time, &sleep_time) < 0) {
            fprintf(stderr, "Failed to wait for sensor to become active.\n");
            return 1;
        }
    }

    // Poll acceleration registers
    while (1) {
        struct timespec start_poll, end_poll;
        int i;

        // Wait for sensor to become active
        start_time.tv_sec = 0;
        start_time.tv_nsec = 1000000000;
        while (gpioGetValue(sensor_data_path) == GPIO_LEVEL_LOW) {
            nanosleep(&start_time, &sleep_time);
            if (nanosleep(&end_time, &sleep_time) < 0) {
                fprintf(stderr, "Failed to wait for sensor to become active.\n");
                return 1;
            }
        }

        // Poll acceleration registers
        for (i = 0; i < 3; i++) {
            if (gpioGetValue(sensor_data_path) == GPIO_LEVEL_HIGH) {
                // Read acceleration values
                gpioGetValue(sensor_data_path, &gpiod_value);
                // Append to CSV file
                snprintf(header, sizeof(header), "%.6f,%.6f,%.6f", gpiod_value.value, gpiod_value.value, gpiod_value.value);
                snprintf(csv_file_name, sizeof(csv_file_name), "fan_health.csv");
                if (gpioOpen(csv_file_path, &csv_fd, O_WRONLY | O_CREAT | O_TRUNC, 0644) < 0) {
                    fprintf(stderr, "Failed to open CSV file.\n");
                    return 1;
                }
                if (fwrite(header, strlen(header), 1, csv_fd) < 1) {
                    fprintf(stderr, "Failed to write to CSV file.\n");
                    return 1;
                }
                if (fwrite(csv_file_name, strlen(csv_file_name), 1, csv_fd) < 1) {
                    fprintf(stderr, "Failed to write to CSV file.\n");
                    return 1;
                }
                for (int j = 0; j < 3; j++) {
                    if (fwrite(&gpiod_value.value, sizeof(int), 1, csv_fd) < 1) {
                        fprintf(stderr, "Failed to write to CSV file.\n");
                        return 1;
                    }
                }
                fprintf(stderr, "Sensor data: %.6f,%.6f,%.6f\n", gpiod_value.value, gpiod_value.value, gpiod_value.value);
            }
        }

        // Wait for sensor to become active
        start_time.tv_sec = 0;
        start_time.tv_nsec = 1000000000;
        while (gpioGetValue(sensor_data_path) == GPIO_LEVEL_LOW) {
            nanosleep(&start_time, &sleep_time);
            if (nanosleep(&end_time, &sleep_time) < 0) {
                fprintf(stderr, "Failed to wait for sensor to become active.\n");
                return 1;
            }
        }
    }

    // Clean up
    gpioClose(csv_fd);
    gpioClose(gpio_output);
    gpioClose(sensor_data_path);
    gpioClose(sensor_mode);

    return 0;
