#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define SEN0193_GPIO_PIN 23
#define SEN0193_DRIVER_PATH "/dev/gpiochip0"
#define FLOW_LOG_FILE "flood_log.txt"

int gpio_fd;
int gpio_fd_old;

void handle_interrupt(int signum) {
    gpio_set_mode(SEN0193_GPIO_PIN, PI_INPUT);
    gpio_pull_up_enable(SEN0193_GPIO_PIN);
    gpio_interrupt_configure(SEN0193_GPIO_PIN, PI_INT_EDGE_FALLING, handle_water_detect);
}

void handle_water_detect(int signum) {
    gpio_set_mode(SEN0193_GPIO_PIN, PI_OUTPUT);
    gpio_write(SEN0193_GPIO_PIN, 1);
    printf("Water detected\n");

    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    FILE *flood_log = fopen(FLOW_LOG_FILE, "a");
    if (flood_log) {
        char timestamp[80];
        struct tm tm = {0};
        time_t t = now.tv_sec;
        localtime_r(&t, &tm);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(flood_log, "ALERT: Water detected\n");
        fprintf(flood_log, "%s %s\n", timestamp, "");
        fclose(flood_log);
    } else {
        perror("Error opening flood_log.txt");
    }

    gpio_set_mode(SEN0193_GPIO_PIN, PI_INPUT);
    gpio_pull_up_disable(SEN0193_GPIO_PIN);
    gpio_interrupt_configure(SEN0193_GPIO_PIN, 0, 0);
}

int main(void) {
    gpio_init();
    gpio_set_mode(SEN0193_GPIO_PIN, PI_INPUT);
    gpio_pull_up_enable(SEN0193_GPIO_PIN);
    gpio_interrupt_configure(SEN0193_GPIO_PIN, PI_INT_EDGE_FALLING, handle_interrupt);

    gpio_fd = open(SEN0193_DRIVER_PATH, O_RDWR);
    if (gpio_fd < 0) {
        perror("Error opening gpiochip0");
        exit(EXIT_FAILURE);
    }

    gpio_fd_old = open(SEN0193_DRIVER_PATH, O_RDWR);
    if (gpio_fd_old < 0) {
        perror("Error opening gpiochip0");
        exit(EXIT_FAILURE);
    }

    while (1) {
