#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>

#define BCM_GPIO4    7
#define RPM_LOG_FILE "rpm_log.txt"

int main() {
    int fd, ret;
    struct gpiod_event_attr attr;
    struct gpiod_event_data event_data;
    struct gpiod_event_data *event_data_ptr;
    struct timespec start_time, end_time;
    uint64_t pulse_counter = 0;
    int rpm = 0;
    char line[128];
    FILE *log_file;

    // Initialize GPIO and log file
    if ((fd = gpiod_get_event_file(GPIO_DIR_IN, BCM_GPIO4, &attr)) < 0) {
        fprintf(stderr, "Failed to open GPIO file: %s\n", gpiod_strerror(fd));
        return 1;
    }

    if ((log_file = fopen(RPM_LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", RPM_LOG_FILE);
        return 1;
    }

    // Configure GPIO pin as input with internal pull-up resistor enabled
    if (gpiod_set_event_line(fd, BCM_GPIO4, &attr) < 0) {
        fprintf(stderr, "Failed to set GPIO pin as input: %s\n", gpiod_strerror(fd));
        fclose(log_file);
        return 1;
    }

    if (gpiod_event_request_line(fd, BCM_GPIO4) < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", gpiod_strerror(fd));
        gpiod_set_event_line(fd, BCM_GPIO4, NULL);
        fclose(log_file);
        return 1;
    }

    // Initialize pulse counter
    pulse_counter = 0;

    // Set up GPIO interrupt handler
    if (gpiod_event_request_edge(fd, BCM_GPIO4, GPIO_EDGE_RISING) < 0) {
        fprintf(stderr, "Failed to request GPIO interrupt: %s\n", gpiod_strerror(fd));
        gpiod_set_event_line(fd, BCM_GPIO4, NULL);
        fclose(log_file);
        return 1;
    }

    // Start timer
    if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0) {
        fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
        gpiod_set_event_line(fd, BCM_GPIO4, NULL);
        fclose(log_file);
        return 1;
    }

    while (1) {
        // Wait for rising-edge interrupt
        if (gpiod_event_wait(fd, BCM_GPIO4, &event_data, &event_data_ptr, NULL) < 0) {
            fprintf(stderr, "Failed to wait for rising-edge interrupt: %s\n", gpiod_strerror(fd));
            gpiod_set_event_line(fd, BCM_GPIO4, NULL);
            fclose(log_file);
            return 1;
        }

        // Check if the sensor is present and rotating
        if (event_data_ptr->value == 1) {
            pulse_counter++;
        }

        // Compute RPM
        if (pulse_counter > 0) {
            rpm = (1000 * pulse_counter) / (event_data_ptr->event_time.tv_sec - start_time.tv_sec);
            pulse_counter = 0;
        }

        // Log RPM
        if (fprintf(log_file, "%.6f\n", rpm) == EOF) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            gpiod_set_event_line(fd, BCM_GPIO4, NULL);
            fclose(log_file);
            return 1;
        }

        // Print RPM to stdout
        printf("%.6f\n", rpm);

        // Flush log file
        fflush(log_file);
    }

    // Clean up GPIO and log file
    gpiod_event_cancel(event_data_ptr);
    gpiod_event_release(event_data_ptr);
    gpiod_event_release(event_data);
    gpiod_release(fd);
    fclose(log_file);

    return 0;
}

