    }

    // Request output line for the LED
    ret = pigpio_request_gpio(gpio_fd, 18, GPIO_OUTPUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request output line for the LED: %s", strerror(errno));
        pigpio_close(gpio_fd);
        return 1;
    }

    // Initialize LED
    gpio_fd = pigpio_get_gpio(gpio_fd);
    if (gpio_fd < 0) {
