            // LED is illuminated while the sensor is actively touched
            gpio_output_mode(gpio_fd, LED_GPIO_OUTPUT_PIN, GPIO_OUTPUT_HIGH);
            usleep(50 * 1000); // Wait for 50 ms
            gpio_output_mode(gpio_fd, LED_GPIO_OUTPUT_PIN, GPIO_OUTPUT_LOW);
        }

