int main() {
    int chip_fd, line_fd, event_fd;
    struct gpiochip_event event;
    struct gpiochip_line lines[2];
    int debounce_ms = 50;
    int debounce_count = 0;
    int led_value = 0;

    // Initialize GPIO lines
    if (gpiochip_init(GPIO_FILE, &chip_fd) < 0) {
        fprintf(stderr, "Failed to initialize GPIO chip\n");
        return 1;
    }

    if (gpio_request_line(chip_fd, 17, &line_fd, &lines[0], &lines[1]) < 0) {
        fprintf(stderr, "Failed to request line 17\n");
        return 1;
    }

    // Set LED line as an output and drive it LOW at startup
    if (gpio_direction_output(line_fd, led_value, 1) < 0) {
        fprintf(stderr, "Failed to set LED line as output\n");
        return 1;
    }

    // Wait for chip open event
    if (gpio_wait_event_timeout(chip_fd, lines[0].event_bit,
                                 gpio_is_event_pending, NULL, debounce_ms) < 0) {
        fprintf(stderr, "Failed to wait for chip open event\n");
        return 1;
    }

    // Initialize LED line as an output and drive it HIGH
    if (gpio_direction_output(line_fd, led_value, 1) < 0) {
        fprintf(stderr, "Failed to set LED line as output\n");
        return 1;
    }

    // Wait for chip open event
    if (gpio_wait_event_timeout(chip_fd, lines[0].event_bit,
                                 gpio_is_event_pending, NULL, debounce_ms) < 0) {
        fprintf(stderr, "Failed to wait for chip open event\n");
        return 1;
    }

    // Wait for rising edge on the touch sensor
    if (gpio_wait_event_timeout(line_fd, lines[0].event_bit,
                                 gpio_is_event_pending, NULL, debounce_ms) < 0) {
        fprintf(stderr, "Failed to wait for rising edge\n");
        return 1;
    }

    // Apply debounce
    while (1) {
        if (gpio_get_event_value(line_fd) == 1) {
            debounce_count++;
            if (debounce_count >= debounce_ms) {
                debounce_count = 0;
                led_value = 1 - led_value;
                if (gpio_direction_output(line_fd, led_value, 1) < 0) {
                    fprintf(stderr, "Failed to set LED line as output\n");
                    return 1;
                }
            }
        }
        usleep(500000); // Debounce time in microseconds
    }

    // Release all driver resources
    gpio_release(chip_fd);
    gpio_release(line_fd);

    return 0;
}

