#include <linux/i2c-dev.h>

#include <pigpio.h>
#include <gpiod.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x04

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpiod_i2c_config i2c_config;
    struct gpiod_i2c_state i2c_state;
    char log_file_path[] = "biometric_log.txt";
    char log_file_path_with_time[128];
    char heart_rate_str[20];
    char spo2_str[20];
    char line[128];
    int heart_rate, spo2;
    int exit_gracefully = 0;

    // Initialize I2C driver
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize I2C driver.\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    if ((i2c_fd = gpiod_i2c_open(I2C_BUS_NUM)) < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus.\n");
        exit(EXIT_FAILURE);
    }

    // Configure I2C device
    if (gpiod_i2c_config_get(I2C_BUS_NUM, I2C_DEVICE_ADDR, &i2c_config) < 0) {
        fprintf(stderr, "Error: Failed to get I2C device configuration.\n");
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((fp = fopen(log_file_path, "a")) == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize heart rate and SpO2 variables
    heart_rate = 0;
    spo2 = 0;

    // Loop to continuously read and append data to the log file
    while (1) {
        // Wait for 1 second
        gpio_delay_us(1000);

        // Read heart rate data
        if (gpiod_i2c_read(i2c_fd, I2C_DEVICE_ADDR, &i2c_data, 1, &i2c_data) < 0) {
            fprintf(stderr, "Error: Failed to read heart rate data.\n");
            exit(EXIT_FAILURE);
        }

        heart_rate = i2c_data.data;

        // Read SpO2 data
        if (gpiod_i2c_read(i2c_fd, I2C_DEVICE_ADDR, &i2c_data, 1, &i2c_data) < 0) {
            fprintf(stderr, "Error: Failed to read SpO2 data.\n");
            exit(EXIT_FAILURE);
        }

        spo2 = i2c_data.data;

        // Append data to log file
        snprintf(log_file_path_with_time, sizeof(log_file_path_with_time), "%s, Heart Rate: %d BPM, SpO2: %d%%",
                 asctime(localtime()), heart_rate, spo2);
        fprintf(fp, "%s\n", log_file_path_with_time);

        // Flush log file
        fflush(fp);

        // Check if user wants to exit gracefully
        if (exit_gracefully) {
            break;
        }
    }

    // Close log file
    fclose(fp);

    // Close I2C device
    gpiod_i2c_close(i2c_fd);

    // Close I2C bus
    gpiod_i2c_unregister(I2C_BUS_NUM);

    // Uninitialize I2C driver
    gpiod_exit();

    return 0;
}

