    while (1) {
        // Get the current sensor values
        if (gpioRead(17, &event) < 0) {
            fprintf(stderr, "Error: Failed to read sensor 1.\n");
            return 1;
        }

        if (gpioRead(18, &event) < 0) {
            fprintf(stderr, "Error: Failed to read sensor 2.\n");
            return 1;
        }

        // Check if the sensors have exceeded the threshold
        if (event.event_type == GPIGPIO_EVENT_START) {
            if (event.event_value == 1) {
                if (event.event_value == 1) {
                    // Sensor 1 has read HIGH continuously for more than 2 seconds
                    if (gpioRead(17, &event) < 0) {
                        fprintf(stderr, "Error: Failed to read sensor 1.\n");
                        return 1;
                    }

                    if (event.event_value == 1) {
                        // Sensor 1 has read HIGH continuously for more than 2 seconds
                        if (gpioRead(18, &event) < 0) {
                            fprintf(stderr, "Error: Failed to read sensor 2.\n");
                            return 1;
                        }

                        if (gpioRead(18, &event) < 0) {
                            fprintf(stderr, "Error: Failed to read sensor 2.\n");
                            return 1;
                        }

                        if (gpioRead(17, &event) < 0) {
                            fprintf(stderr, "Error: Failed to read sensor 1.\n");
                            return 1;
                        }

                        if (gpioRead(18, &event) < 0) {
                            fprintf(stderr, "Error: Failed to read sensor 2.\n");
                            return 1;
                        }

                        // Log the event
                        fprintf(log_file, "%s, %s, %s\n",
                                iso8601_date_time(time(NULL)),
                                event.event_type == GPIGPIO_EVENT_START ? "start" : "end",
                                event.event_value == 1 ? "high" : "low");

                        // Reset the alarm
                        gpioWrite(27, 0);
                    }
                }
            }
        }

        // Check if the sensors have returned to LOW
        if (event.event_type == GPIGPIO_EVENT_END) {
            if (event.event_value == 0) {
                if (gpioRead(17, &event) < 0) {
                    fprintf(stderr, "Error: Failed to read sensor 1.\n");
                    return 1;
                }

                if (gpioRead(18, &event) < 0) {
                    fprintf(stderr, "Error: Failed to read sensor 2.\n");
                    return 1;
                }

                // Log the event
                fprintf(log_file, "%s, %s, %s\n",
                        iso8601_date_time(time(NULL)),
                        event.event_type == GPIGPIO_EVENT_START ? "start" : "end",
                        event.event_value == 0 ? "low" : "high");

                // Reset the alarm
                gpioWrite(27, 0);
            }
        }

        // Check for log file errors
        if (ferror(log_file)) {
            fprintf(stderr, "Error: Failed to write to log file.\n");
            return 1;
        }

        // Check for API call errors
        if (gpioRead(17, &event) < 0) {
            fprintf(stderr, "Error: Failed to read sensor 1.\n");
            return 1;
        }

        if (gpioRead(18, &event) < 0) {
            fprintf(stderr, "Error: Failed to read sensor 2.\n");
            return 1;
        }

        // Check if the sensors have returned to LOW
        if (event.event_type == GPIGPIO_EVENT_END) {
            if (event.event_value == 0) {
                if (gpioRead(17, &event) < 0) {
                    fprintf(stderr, "Error: Failed to read sensor 1.\n");
                    return 1;
                }

                if (gpioRead(18, &event) < 0) {
                    fprintf(stderr, "Error: Failed to read sensor 2.\n");
                    return 1;
                }

                // Log the event
                fprintf(log_file, "%s, %s, %s\n",
                        iso8601_date_time(time(NULL)),
                        event.event_type == GPIGPIO_EVENT_START ? "start" : "end",
                        event.event_value == 0 ? "low" : "high");

                // Reset the alarm
                gpioWrite(27, 0);
            }
        }

        // Check for errors in the API calls
        if (gpioRead(17, &event) < 0) {
            fprintf(stderr, "Error: Failed to read sensor 1.\n");
            return 1;
        }

        if (gpioRead(18, &event) < 0) {
            fprintf(stderr, "Error: Failed to read sensor 2.\n");
            return 1;
        }

        // Check if the sensors have returned to LOW
        if (event.event_type == GPIGPIO_EVENT_END) {
            if (event.event_value == 0) {
                if (gpioRead(17, &event) < 0) {
                    fprintf(stderr, "Error: Failed to read sensor 1.\n");
                    return 1;
                }

                if (gpioRead(18, &event) < 0) {
                    fprintf(stderr, "Error: Failed to read sensor 2.\n");
                    return 1;
                }

                // Log the event
                fprintf(log_file, "%s, %s, %s\n",
                        iso8601_date_time(time(NULL)),
                        event.event_type == GPIGPIO_EVENT_START ? "start" : "end",
                        event.event_value == 0 ? "low" : "high");

                // Reset the alarm
                gpioWrite(27, 0);
            }
        }

        // Check for errors in the cleanup
        if (gpioClose(17) < 0) {
            fprintf(stderr, "Error: Failed to close sensor 1.\n");
            return 1;
        }

        if (gpioClose(18) < 0) {
            fprintf(stderr, "Error: Failed to close sensor 2.\n");
            return 1;
        }

        if (gpioClose(27) < 0) {
            fprintf(stderr, "Error: Failed to close buzzer/LED.\n");
            return 1;
        }

        // Clean up
        gpioUninitialize();
    }

    // Clean up log file
    fclose(log_file);

    return 0;
}
