#include <stdio.h>
#include <stdlib.h>
#include <sys/syslog.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_COUNT 5
#define LINE_POINTERS [0...4]

volatile sig_atomic_t sigint_handled = 0;

int main() {
    int chip_fd, line_fd[SENSOR_COUNT];
    struct gpiod_event event;
    struct gpiod_event_data data;
    char filename[32];
    char buffer[32];
    struct sigaction sa;
    int sensor_id;
    int i;

    // Initialize syslog
    syslog(LOG_INFO, "Starting flame_monitor program");

    // Initialize GPIO
    if (gpiod_init() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    // Initialize file for logging
    snprintf(filename, sizeof(filename), "/var/log/flame_events.log");
    FILE *log_file = fopen(filename, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        return 1;
    }

    // Install signal handlers
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_SIGINFO;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize sensor pointers
    for (i = 0; i < SENSOR_COUNT; i++) {
        sensor_id = i + 2;
        line_pointers[i] = -1;
    }

    // Loop to continuously monitor sensors
    while (1) {
        // Wait for events
        if (gpiod_get_event(chip_fd, &event, &data) < 0) {
            syslog(LOG_ERR, "Failed to get event");
            continue;
        }

        // Check if a sensor event occurred
        if (event.type == GPIGPIO_EVENT_RISING) {
            // Debounce re-read
            usleep(50000);
            // Check for flame transition
            if (line_pointers[sensor_id] == -1) {
                // Perform debounce re-read
                usleep(50000);
                // Read line
                if (gpiod_get_line(chip_fd, sensor_id, &line_pointers[sensor_id]) < 0) {
                    syslog(LOG_ERR, "Failed to get line");
                    continue;
                }
                // Log event
                snprintf(buffer, sizeof(buffer), "<ISO %s UTC %d> - Sensor %d (%d) - Flame Detected",
                         get_iso_8601_utc_timestamp(), sensor_id, line_pointers[sensor_id]);
                fprintf(log_file, "%s\n", buffer);
                // Release line
                gpiod_release_line(chip_fd, sensor_id);
            }
        }

        // Release chip
        if (gpiod_release_chip(chip_fd) < 0) {
            syslog(LOG_ERR, "Failed to release chip");
            continue;
        }

        // Close log file
        fclose(log_file);
    }

    // Cleanup
    gpiod_exit();

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void sigint_handler(int sig) {
    sigint_handled = 1;
}

