#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/input.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define GPIO_DIR_IN  (1 << 5)
#define GPIO_DIR_OUT (1 << 6)
#define GPIO_INT_EDGE_FALLING (1 << 13)
#define GPIO_INT_EDGE_RISING (1 << 19)
#define GPIO_INT_EDGE_BOTH (1 << 26)

#define TOUCH_SENSOR_GPIO_BASE 5
#define TOUCH_SENSOR_GPIO_PIN_COUNT 8

int main() {
    int gpio_fd;
    struct gpiod_line *lines[TOUCH_SENSOR_GPIO_PIN_COUNT];
    struct gpiod_line_config line_configs[TOUCH_SENSOR_GPIO_PIN_COUNT];
    struct gpiod_event event;
    struct timespec start_time, end_time;
    int touch_states[TOUCH_SENSOR_GPIO_PIN_COUNT];
    int touch_state_changes = 0;
    int error_code = 0;
    int sensor_index = 0;
    int bcm_pin_number;
    int touch_detected = 0;
    int touch_released = 0;
    char timestamp[64];

    if (gpio_init() < 0) {
        fprintf(stderr, "Error initializing GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    if (line_resolution() < 0) {
        fprintf(stderr, "Error setting line resolution\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < TOUCH_SENSOR_GPIO_PIN_COUNT; i++) {
        if (gpio_setup(TOUCH_SENSOR_GPIO_BASE + i, GPIO_DIR_OUT) < 0) {
            fprintf(stderr, "Error setting GPIO line %d as output\n", i + 1);
            exit(EXIT_FAILURE);
        }

        if (gpio_direction(TOUCH_SENSOR_GPIO_BASE + i, GPIO_DIR_OUT) < 0) {
            fprintf(stderr, "Error setting GPIO line %d direction to output\n", i + 1);
            exit(EXIT_FAILURE);
        }

        if (gpio_set_edge(TOUCH_SENSOR_GPIO_BASE + i, GPIO_INT_EDGE_RISING | GPIO_INT_EDGE_FALLING) < 0) {
            fprintf(stderr, "Error setting GPIO line %d edge detection\n", i + 1);
            exit(EXIT_FAILURE);
        }

        if (gpio_get_value(TOUCH_SENSOR_GPIO_BASE + i) < 0) {
            fprintf(stderr, "Error getting GPIO line %d value\n", i + 1);
            exit(EXIT_FAILURE);
        }

        if (gpio_event_request(TOUCH_SENSOR_GPIO_BASE + i, &event) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d event\n", i + 1);
            exit(EXIT_FAILURE);
        }

        if (event.type != GPIO_EVENT_TYPE_GPIO) {
            fprintf(stderr, "Unexpected event type for GPIO line %d\n", i + 1);
            exit(EXIT_FAILURE);
        }

        if (event.gpio_value == GPIO_INT_EDGE_FALLING) {
            touch_detected = 1;
        } else if (event.gpio_value == GPIO_INT_EDGE_RISING) {
            touch_released = 1;
        }

        if (event.gpio_value == GPIO_INT_EDGE_FALLING && touch_detected == 1) {
            touch_state_changes++;
        }

        if (event.gpio_value == GPIO_INT_EDGE_RISING && touch_released == 1) {
            touch_state_changes++;
        }

        if (event.gpio_value == GPIO_INT_EDGE_FALLING && touch_detected == 1) {
            touch_states[sensor_index] = event.gpio_value;
            sensor_index++;
        }

        if (sensor_index == TOUCH_SENSOR_GPIO_PIN_COUNT) {
            sensor_index = 0;
        }
    }

    if (line_release() < 0) {
        fprintf(stderr, "Error releasing GPIO lines\n");
        exit(EXIT_FAILURE);
    }

    if (touch_state_changes > 0) {
        gettimeofday(&start_time, NULL);

        for (int i = 0; i < touch_state_changes; i++) {
            if (read(lines[i].fd, &touch_states[i], sizeof(int)) < 0) {
                fprintf(stderr, "Error reading touch state for line %d\n", i + 1);
                exit(EXIT_FAILURE);
            }

            if (touch_states[i] == 1) {
                snprintf(timestamp, sizeof(timestamp), "Touch detected on line %d\n", i + 1);
            } else {
                snprintf(timestamp, sizeof(timestamp), "Touch released on line %d\n", i + 1);
            }

            if (write(lines[i].fd, timestamp, strlen(timestamp) + 1) < 0) {
                fprintf(stderr, "Error writing timestamp to line %d\n", i + 1);
                exit(EXIT_FAILURE);
            }
        }

        gettimeofday(&end_time, NULL);
        double elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_usec - start_time.tv_usec) / 1000000.0;

        printf("Touch state changes:\n");
        for (int i = 0; i < touch_state_changes; i++) {
            printf("Line %d: %s\n", i + 1, timestamp);
        }

        printf("Total elapsed time: %.2f seconds\n", elapsed_time);
    }

    for (int i = 0; i < TOUCH_SENSOR_GPIO_PIN_COUNT; i++) {
        if (gpio_release(TOUCH_SENSOR_GPIO_BASE + i) < 0) {
            fprintf(stderr, "Error releasing GPIO line %d\n", i + 1);
            exit(EXIT_FAILURE);
        }
    }

    if (gpio_cleanup() < 0) {
        fprintf(stderr, "Error cleaning up GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    return 0;
}

