            touch_state_changes++;
        }

        if (event.gpio_value == GPIO_INT_EDGE_RISING && touch_released == 1) {
            touch_state_changes++;
        }

        if (event.gpio_value == GPIO_INT_EDGE_FALLING && touch_detected == 1) {
            touch_states[sensor_index] = event.gpio_value;
            sensor_index++;
        }

        if (sensor_index == TOUCH_SENSOR_GPIO_PIN_COUNT) {
            sensor_index = 0;
        }
    }

    if (line_release() < 0) {
        fprintf(stderr, "Error releasing GPIO lines\n");
        exit(EXIT_FAILURE);
    }

    if (touch_state_changes > 0) {
        gettimeofday(&start_time, NULL);

        for (int i = 0; i < touch_state_changes; i++) {
            if (read(lines[i].fd, &touch_states[i], sizeof(int)) < 0) {
                fprintf(stderr, "Error reading touch state for line %d\n", i + 1);
                exit(EXIT_FAILURE);
            }

            if (touch_states[i] == 1) {
                snprintf(timestamp, sizeof(timestamp), "Touch detected on line %d\n", i + 1);
            } else {
                snprintf(timestamp, sizeof(timestamp), "Touch released on line %d\n", i + 1);
            }

            if (write(lines[i].fd, timestamp, strlen(timestamp) + 1) < 0) {
                fprintf(stderr, "Error writing timestamp to line %d\n", i + 1);
                exit(EXIT_FAILURE);
            }
        }

        gettimeofday(&end_time, NULL);
        double elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_usec - start_time.tv_usec) / 1000000.0;

        printf("Touch state changes:\n");
        for (int i = 0; i < touch_state_changes; i++) {
            printf("Line %d: %s\n", i + 1, timestamp);
        }

        printf("Total elapsed time: %.2f seconds\n", elapsed_time);
    }

    for (int i = 0; i < TOUCH_SENSOR_GPIO_PIN_COUNT; i++) {
        if (gpio_release(TOUCH_SENSOR_GPIO_BASE + i) < 0) {
            fprintf(stderr, "Error releasing GPIO line %d\n", i + 1);
            exit(EXIT_FAILURE);
        }
    }

    if (gpio_cleanup() < 0) {
        fprintf(stderr, "Error cleaning up GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    return 0;
}
