#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x40
#define OPT3001_ADDRESS 0x30

int i2c_fd;
int gpio_fd;

void byte_swap_16(uint16_t *data) {
    uint16_t temp = data[0];
    data[0] = data[1];
    data[1] = temp;
}

int main() {
    int ret;
    int i;

    // Initialize I2C and GPIO
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    // Set up I2C device file
    struct i2c_rdwr_ioctl_data data;
    memset(&data, 0, sizeof(data));
    data.flags = 0;
    data.msg.flags = 0;
    data.msg.read = 0;
    data.msg.write = 1;
    data.msg.nbytes = 2;
    data.msg.buf = malloc(2 * sizeof(uint16_t));
    if (!data.msg.buf) {
        perror("Failed to allocate memory for I2C buffer");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO
    struct gpio_mem_region region;
    memset(&region, 0, sizeof(region));
    region.start = 0x20;
    region.len = 0x100;
    ret = ioctl(gpio_fd, GPIO_IOC_MEM_REGION_MEM_MAP, &region);
    if (ret < 0) {
        perror("Failed to map GPIO memory");
        exit(EXIT_FAILURE);
    }

    // Set up I2C device file for read-only access
    data.msg.buf[0] = OPT3001_ADDRESS;
    data.msg.buf[1] = 0x00;
    data.msg.buf[2] = 0x00;
    data.msg.buf[3] = 0x00;
    data.msg.buf[4] = 0x00;
    data.msg.buf[5] = 0x00;
    data.msg.buf[6] = 0x00;
    data.msg.buf[7] = 0x00;
    data.msg.buf[8] = 0x00;
    data.msg.buf[9] = 0x00;
    data.msg.buf[10] = 0x00;
    data.msg.buf[11] = 0x00;
    data.msg.buf[12] = 0x00;
    data.msg.buf[13] = 0x00;
    data.msg.buf[14] = 0x00;
    data.msg.buf[15] = 0x00;
    data.msg.buf[16] = 0x00;
    data.msg.buf[17] = 0x00;
    data.msg.buf[18] = 0x00;
    data.msg.buf[19] = 0x00;
    data.msg.buf[20] = 0x00;
    data.msg.buf[21] = 0x00;
    data.msg.buf[22] = 0x00;
    data.msg.buf[23] = 0x00;
    data.msg.buf[24] = 0x00;
    data.msg.buf[25] = 0x00;
    data.msg.buf[26] = 0x00;
    data.msg.buf[27] = 0x00;
    data.msg.buf[28] = 0x00;
    data.msg.buf[29] = 0x00;
    data.msg.buf[30] = 0x00;
    data.msg.buf[31] = 0x00;

    ret = ioctl(i2c_fd, I2C_RDWR, &data);
    if (ret < 0) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    // Wait for the sensor to settle
    ret = ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    // Wait for 100 ms
    struct timespec ts;
    ts.tv_sec = 100;
    ts.tv_nsec = 0;
    nanosleep(&ts, NULL);

    // Write configuration to sensor
    data.msg.flags = 0;
    data.msg.read = 0;
    data.msg.write = 1;
    data.msg.nbytes = 2;
    data.msg.buf[0] = 0x01;
    data.msg.buf[1] = 0x00;
    ret = ioctl(i2c_fd, I2C_RDWR, &data);
    if (ret < 0) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }

    // Wait for 100 ms
    nanosleep(&ts, NULL);

    // Read data from sensor
    ret = ioctl(i2c_fd, I2C_RDWR, &data);
    if (ret < 0) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    // Convert 16-bit values to big-endian format
    for (i = 0; i < data.msg.nbytes / 2; i++) {
        uint16_t temp = data.msg.buf[i * 2];
        data.msg.buf[i * 2] = data.msg.buf[i * 2 + 1];
        data.msg.buf[i * 2 + 1] = temp;
    }

    // Format measurement
    char measurement[50];
    snprintf(measurement, sizeof(measurement), "%.4f,%.4f", data.msg.buf[0], data.msg.buf[1]);

    // Write measurement to file
    FILE *file = fopen("light_data.txt", "a");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%.4f,%.4f\n", data.msg.buf[0], data.msg.buf[1]);
    fclose(file);

    // Print to stdout
    printf("%.4f,%.4f\n", data.msg.buf[0], data.msg.buf[1]);

    // Close I2C device file
    ret = close(i2c_fd);
    if (ret < 0) {
        perror("Failed to close I2C device");
        exit(EXIT_FAILURE);
    }

    // Close GPIO device file
    ret = close(gpio_fd);
    if (ret < 0) {
        perror("Failed to close GPIO device");
        exit(EXIT_FAILURE);
    }

    // Cleanup I2C and GPIO resources
    ret = ioctl(i2c_fd, I2C_RDWR, NULL);
    if (ret < 0) {
        perror("Failed to release I2C device");
        exit(EXIT_FAILURE);
    }

    ret = close(i2c_fd);
    if (ret < 0) {
        perror("Failed to close I2C device");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(gpio_fd, GPIO_CLOSE);
    if (ret < 0) {
        perror("Failed to close GPIO device");
        exit(EXIT_FAILURE);
    }

    ret = close(gpio_fd);
    if (ret < 0) {
        perror("Failed to close GPIO device");
        exit(EXIT_FAILURE);
    }

    return 0;
}

