#include <pigpio.h>

#define GPIO_DIR_OUT  (1 << 4)
#define GPIO_INPUT    (1 << 5)
#define GPIO_PULL_DOWN (1 << 6)

int main() {
    int file_desc, log_fd, ret;
    struct gpiod_event event;
    char buffer[80];
    char log_file_name[] = "touch_log.txt";

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    file_desc = open(log_file_name, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (file_desc < 0) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    ret = gpiod_event_request(GPIO_4, GPIO_INPUT | GPIO_PULL_DOWN, &event);
    if (ret < 0) {
        fprintf(stderr, "Failed to request event for GPIO4.\n");
        return 1;
    }

    while (1) {
        ret = gpiod_event_poll(GPIO_4, 1, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to poll event for GPIO4.\n");
            return 1;
        }

        if (event.state == 1) {
            sprintf(buffer, "YYYY-%m-%d %H:%M:%S: Touch Detected\n",
                    get_localtime()->tm_year + 1900, get_localtime()->tm_mon + 1, get_localtime()->tm_mday,
                    "Touch Detected");
            if (write(file_desc, buffer, strlen(buffer)) < 0) {
                fprintf(stderr, "Failed to write to log file.\n");
                return 1;
            }
        } else if (event.state == 0) {
            sprintf(buffer, "YYYY-%m-%d %H:%M:%S: Touch Released\n",
                    get_localtime()->tm_year + 1900, get_localtime()->tm_mon + 1, get_localtime()->tm_mday,
                    "Touch Released");
            if (write(file_desc, buffer, strlen(buffer)) < 0) {
                fprintf(stderr, "Failed to write to log file.\n");
                return 1;
            }
        }

        if (gpioUnrequestEvent(GPIO_4) < 0) {
            fprintf(stderr, "Failed to unrequest event for GPIO4.\n");
            return 1;
        }

        if (gpioTerminate() < 0) {
            fprintf(stderr, "Failed to terminate GPIO.\n");
            return 1;
        }

        if (close(file_desc) < 0) {
            fprintf(stderr, "Failed to close log file.\n");
            return 1;
        }

        if (gpioUninitialize() < 0) {
            fprintf(stderr, "Failed to uninitialize GPIO.\n");
            return 1;
        }
    }

    return 0;
}

