#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x18

#define SENSOR_ADDRESS 0x48
#define SENSOR_CMD_READ_DATA 0x00
#define SENSOR_CMD_READ_FLAG 0x01
#define SENSOR_FLAG_READ_FLAG_BIT 0x80

#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0x00

#define MAX_FLOW_RATE 100.0
#define MIN_FLOW_RATE 0.0

int main() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpiod_i2c_config gpiod_config = {
        .i2c_bus_num = I2C_BUS_NUM,
        .i2c_device_addr = I2C_DEVICE_ADDR,
    };

    // Initialize I2C bus
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C bus.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpiod_request_line(I2C_BUS_NUM, I2C_DEVICE_ADDR, GPIO_DIR_IN, &gpio_line) < 0) {
        fprintf(stderr, "Failed to request GPIO line.\n");
        gpiod_release();
        return 1;
    }

    // Open I2C file descriptor
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C file descriptor.\n");
        gpiod_release();
        return 1;
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C device address.\n");
        close(i2c_fd);
        gpiod_release();
        return 1;
    }

    // Set GPIO direction
    if (gpiod_set_line(gpio_line, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO direction.\n");
        close(i2c_fd);
        gpiod_release();
        return 1;
    }

    // Set GPIO as an input
    if (gpiod_set_line(gpio_line, GPIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO as input.\n");
        close(i2c_fd);
        gpiod_release();
        return 1;
    }

    // Initialize I2C handle
    if (gpiod_request_line(I2C_BUS_NUM, I2C_DEVICE_ADDR, GPIO_DIR_IN, &gpio_line) < 0) {
        fprintf(stderr, "Failed to request GPIO line.\n");
        close(i2c_fd);
        gpiod_release();
        return 1;
    }

    // Initialize I2C driver
    if (gpiod_request_i2c(I2C_BUS_NUM, &gpiod_config) < 0) {
        fprintf(stderr, "Failed to request I2C driver.\n");
        close(i2c_fd);
        gpiod_release();
        return 1;
    }

    // Open CSV file for writing
    FILE *csv_file = fopen("cooling_log.csv", "w");
