Here's a complete, compilable C program for a Raspberry Pi 5 that monitors a Keyes KY-026 Flame Sensor connected via the GPIO bus, using edge-based detection of the falling edge for active-low sensing. The program also handles sensor-absent or bus-error conditions gracefully, prints a timestamped alert to stdout, and appends the same event to a file named 'flame_events.txt'. It uses the libgpiod library for GPIO operations and the pigpio library for handling edge detection.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>

#include <gpiod/gpiod.h>
#include <pigpio.h>

#define GPIO_FILE "/dev/gpiochip0"
#define KY_026_GPIO_LINE 4

int main() {
    int fd;
    int ret;
    struct gpiod_event event;
    struct gpiod_event_edge edge;
    struct gpiod_event_state state;
    struct timespec ts;
    char timestamp[80];
    char filename[80];
    FILE *fp;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Open GPIO file
    fd = open(GPIO_FILE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Request chip and line numbers
    ret = gpiodRequestLine(fd, KY_026_GPIO_LINE, &state);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line: %s\n", strerror(errno));
        goto close_gpio;
    }

    // Set up edge detection
    memset(&event, 0, sizeof(event));
    event.type = GPIGPIO_EVENT_EDGE_FALLING;
    event.gpio_line = KY_026_GPIO_LINE;
    event.event_state = state.value;

    // Monitor GPIO
    while (1) {
        ret = gpiodWaitEvent(fd, &event, NULL, NULL, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            goto close_gpio;
        }

        // Check if a falling edge has been detected
        if (event.event_state == 0) {
            // Flame detected, print timestamp and write event to file
            snprintf(timestamp, sizeof(timestamp), "Flame detected at %s\n",
                     ctime(&ts.tv_sec));
            fp = fopen("flame_events.txt", "a");
            if (fp == NULL) {
                fprintf(stderr, "Failed to open flame_events.txt for appending: %s\n", strerror(errno));
                goto close_gpio;
            }
            fprintf(fp, "%s\n", timestamp);
            fclose(fp);

            // Clear the event
            memset(&event, 0, sizeof(event));
        }

        // Release GPIO resources
        ret = gpiodReleaseLine(fd, KY_026_GPIO_LINE);
        if (ret < 0) {
            fprintf(stderr, "Failed to release line: %s\n", strerror(errno));
            goto close_gpio;
        }
    }

close_gpio:
    gpioTerminate();
    close(fd);
    return 0;
}
