        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    if ((fd = gpiod_event_add(BUZZER_GPIO, GPIDO_EVENT_ACTIVE_LOW, 0, 0, &event)) < 0) {
        fprintf(stderr, "Failed to add event for buzzer: %s\n", strerror(errno));
        gpiod_exit();
        return 1;
    }

    if ((fd = open(log_file, O_CREAT | O_WRONLY | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_exit();
        return 1;
    }

    if ((log_fd = open(log_file, O_WRONLY | O_APPEND | O_CREAT, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(fd);
        gpiod_exit();
        return 1;
    }

    // Start system timer
    if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0) {
        fprintf(stderr, "Failed to get system time: %s\n", strerror(errno));
        close(fd);
        gpiod_exit();
        return 1;
    }

    // Main loop
    while (1) {
        // Check for flame sensor event
        if (gpiod_event_check(fd) < 0) {
            fprintf(stderr, "Failed to check for flame sensor event: %s\n", strerror(errno));
            break;
        }

        // Check if flame is detected
        if (event.event_state == GPIDO_EVENT_ACTIVE_LOW) {
            // Log timestamp and "FLAME DETECTED" message
            snprintf(alert_log, sizeof(alert_log), "FLAME DETECTED at %s\n", ctime(&start_time.tv_sec));
            write(log_fd, alert_log, strlen(alert_log) + 1);

            // Turn buzzer on
            if (buzzer_on) {
                gpio_close(BUZZER_GPIO);
                buzzer_on = 0;
            }

            // Set GPIO to HIGH
            if (gpio_set_level(BUZZER_GPIO, 1) < 0) {
                fprintf(stderr, "Failed to set GPIO to HIGH: %s\n", strerror(errno));
                break;
            }

            // Wait for 2 seconds
            if (nanosleep(&end_time, NULL) < 0) {
                fprintf(stderr, "Failed to wait for 2 seconds: %s\n", strerror(errno));
                break;
            }

            // Turn buzzer off
            gpio_close(BUZZER_GPIO);
            buzzer_on = 1;

            // Wait for buzzer off time
            if (nanosleep(&end_time, NULL) < 0) {
                fprintf(stderr, "Failed to wait for buzzer off time: %s\n", strerror(errno));
                break;
            }
        }

        // Wait for 100 ms slices
        sleep(100);
    }

    // Cleanup
    close(fd);
    gpiod_exit();

    return 0;
}

