    if (stat(debounce_file_path, &log_stat) == -1) {
        if (errno == ENOENT) {
            perror("Failed to open debounce file");
            exit(EXIT_FAILURE);
        } else {
            perror("Failed to open debounce file");
            exit(EXIT_FAILURE);
        }
    }

    debounce_file_is_open = open(debounce_file_path, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (debounce_file_is_open < 0) {
        perror("Failed to open debounce file");
        exit(EXIT_FAILURE);
    }

    // Toggle LED on GPIO17
    gpio_set_direction(GPIO_17, GPIO_OUT);
    gpio_set_value(GPIO_17, 0);

    // Toggle touch sensor on GPIO4
    gpio_request_irq(GPIO_4, GPIO_INT_EDGE_FALLING, gpiod_edge_trap_t, gpiod_falling_trap_t, NULL, &event, &data);

    while (1) {
        // Read GPIO4 and debounce
        if (gpio_get_value(GPIO_4) == 0) {
            // Toggle LED
            gpio_set_value(GPIO_17, 1);

            // Read touch sensor
            if (gpiod_get_value(GPIO_4) == 0) {
                // Check for rising edge
                if (debounce_count == 0) {
                    debounce_time.tv_sec = 0;
                    debounce_time.tv_nsec = 200 * 1000 * 1000;

                    // Wait for debounce
                    nanosleep(&debounce_time, NULL);

                    // Check for touch again
                    if (gpiod_get_value(GPIO_4) == 0) {
                        // Log the timestamp
                        struct timespec now;
                        gettimeofday(&now, NULL);
                        struct tm* timeinfo = localtime(&now.tv_sec);
                        char timestamp[80];
                        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                        // Append timestamp to log file
                        if (write(log_file_is_open, timestamp, strlen(timestamp)) < 0) {
                            perror("Failed to write to log file");
                            exit(EXIT_FAILURE);
                        }

                        // Increment debounce count
                        debounce_count++;
                    }
                }
            }
        } else {
            // Toggle LED
            gpio_set_value(GPIO_17, 0);

            // Clear debounce
            debounce_count = 0;
        }

        // Wait for 10 ms
        usleep(10000);
    }

    // Cleanup GPIO and debounce
    gpio_free_irq(GPIO_4, NULL);
    gpio_free_irq(GPIO_17, NULL);
    close(debounce_file_is_open);
    close(log_file_is_open);

    return 0;
}
