#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x1A

int main() {
    int fd;
    int part_id;
    int hw_rev;
    int bpm;
    int ret;
    int i;
    int retry_count = 0;
    int i2c_retry_count = 0;

    // Initialize I2C bus
    if (ioctl(I2C_BUS_NUM, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to initialize I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    if (!gpioInitialise()) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    // Open file for appending
    FILE *fp = fopen("heart_rate.csv", "a");
    if (fp == NULL) {
        perror("Failed to open file for appending");
        exit(EXIT_FAILURE);
    }

    // Initialize the heart rate sensor
    if (gpiod_get_line_state(I2C_BUS_NUM, "si1182-gm") < 0) {
        perror("Failed to get sensor line state");
        exit(EXIT_FAILURE);
    }

    // Read sensor data
    if (gpiod_get_value(I2C_BUS_NUM, "si1182-gm") < 0) {
        perror("Failed to read sensor value");
        exit(EXIT_FAILURE);
    }

    // Apply five-sample moving average filter
    bpm = (part_id << 8) | (hw_rev & 0xFF);
    for (i = 0; i < 5; i++) {
        bpm = (bpm + gpiod_get_value(I2C_BUS_NUM, "si1182-gm")) / 6;
    }

    // Validate BPM
    if (bpm < 30 || bpm > 220) {
        fprintf(fp, "%.4f,%.4f\n", bpm, bpm);
        retry_count = 0;
    }

    // Check if sensor is absent or wrong
    if (part_id != 0xFE || hw_rev != 0x01) {
        perror("Sensor absent or wrong");
        exit(EXIT_FAILURE);
    }

    // Check if configuration write was successful
    if (gpiod_set_value(I2C_BUS_NUM, "si1182-gm", 1) < 0) {
        perror("Failed to write configuration");
        exit(EXIT_FAILURE);
    }

    // Retry I2C read errors
    while (i2c_retry_count < 3) {
        ret = gpiod_i2c_read(I2C_BUS_NUM, "si1182-gm", &part_id, sizeof(part_id), &retry_count);
        if (ret < 0) {
            perror("Failed to read sensor value");
            exit(EXIT_FAILURE);
        }
    }

    // Close I2C handle, driver library, and log file
    gpioTerminate();
    gpiod_close(I2C_BUS_NUM);
    fclose(fp);

    return 0;
}

