#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x44
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define BiasPullUp 1

int main() {
    int chip_fd, sensor_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    struct gpiod_chip *chip;
    int ret;

    // Initialize GPIO and I2C
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        return 1;
    }

    // Open I2C bus
    chip_fd = i2c_open(I2C_BUS, I2C_CLIENT_IOCTL);
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        return 1;
    }

    // Open sensors
    sensor_fd = i2c_open_device(chip_fd, SENSOR_ADDRESS, I2C_CLIENT_IOCTL);
    if (sensor_fd < 0) {
        fprintf(stderr, "Failed to open sensor.\n");
        return 1;
    }

    // Configure sensors as inputs with bias pull-up
    if (ioctl(sensor_fd, I2C_RDWR, I2C_PEC_MESSAGE) < 0) {
        fprintf(stderr, "Failed to configure sensors as inputs with bias pull-up.\n");
        return 1;
    }

    if (ioctl(sensor_fd, I2C_RDWR, I2C_LINE_INPUT) < 0) {
        fprintf(stderr, "Failed to configure sensors as inputs with bias pull-up.\n");
        return 1;
    }

    if (ioctl(sensor_fd, I2C_LINE_PULLUP, BiasPullUp) < 0) {
        fprintf(stderr, "Failed to configure sensors as inputs with bias pull-up.\n");
        return 1;
    }

    // Open log file
    char log_file_path[256];
    snprintf(log_file_path, sizeof(log_file_path), "/var/log/tilt_events.log");
    FILE *log_file = fopen(log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Poll sensors
        i2c_msgs[0].addr = sensor_address;
        i2c_msgs[0].flags = 0;
        i2c_msgs[0].len = 2;
        i2c_msgs[0].buf = (void *)&i2c_data;
        i2c_msgs[1].addr = sensor_address;
        i2c_msgs[1].flags = 0;
        i2c_msgs[1].len = 2;
        i2c_msgs[1].buf = (void *)&i2c_data;

        ret = i2c_transfer(chip_fd, i2c_msgs, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to poll sensors.\n");
            return 1;
        }

        // Check for sensor events
        if (i2c_msgs[0].status == 0 && i2c_msgs[1].status == 0) {
            // Log sensor events
            char sensor_event[32];
            snprintf(sensor_event, sizeof(sensor_event), "Sensor %d tilted\n", sensor_1_GPIO);
            fprintf(log_file, "%s\n", sensor_event);

            // Check for debounce
            if (i2c_msgs[0].buf->flags & I2C_M_RD) {
                // Debounce window expired
                i2c_msgs[0].buf->flags &= ~I2C_M_RD;
                i2c_msgs[1].buf->flags &= ~I2C_M_RD;
            }
        }

        // Check for chip open failure
        if (ret < 0) {
            fprintf(stderr, "Failed to poll sensors.\n");
            return 1;
        }

        // Check for line request failure
        if (ret < 0) {
            fprintf(stderr, "Failed to poll sensors.\n");
            return 1;
        }

        // Check for read errors
        if (ret < 0) {
            fprintf(stderr, "Failed to poll sensors.\n");
            return 1;
        }
    }

    // Clean up
    i2c_close(chip_fd);
    i2c_unregister_device(chip_fd);
    gpio_exit();

    return 0;
}

