#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define LED_PIN 22
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

int main() {
    int gpio_fd;
    int error;

    // Initialize GPIO
    gpio_fd = pigpio_initialize();
    if (gpio_fd < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", pigpio_error_str(gpio_fd));
        return 1;
    }

    // Set GPIO17 and GPIO27 as outputs
    if (pigpio_pin_mode(SENSOR1_PIN, PI_OUTPUT) < 0 || pigpio_pin_mode(SENSOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO17 and GPIO27 as outputs: %s\n", pigpio_strerror(pigpio_getLastError()));
        pigpio_close(gpio_fd);
        return 1;
    }

    // Set GPIO22 as an output
    if (pigpio_pin_mode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO22 as output: %s\n", pigpio_strerror(pigpio_getLastError()));
        pigpio_close(gpio_fd);
        return 1;
    }

    // Open obstacle_log.csv file for appending
    gpio_fd = open("obstacle_log.csv", O_CREAT | O_APPEND | O_WRONLY, 0644);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening obstacle_log.csv file: %s\n", strerror(errno));
        pigpio_close(gpio_fd);
        return 1;
    }

    // Loop to read sensor data and log it
    while (1) {
        // Read sensor data
        int sensor1_state = pigpio_gpio_read(SENSOR1_PIN);
        int sensor2_state = pigpio_gpio_read(SENSOR2_PIN);

        // Log sensor data
        char timestamp[80];
        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
        fprintf(gpio_fd, "%s,%d,%d,%d\n", timestamp, sensor1_state, sensor2_state, sensor1_state);

        // Check if both sensors read 0
        if (sensor1_state == 0 && sensor2_state == 0) {
            // Turn LED on
            pigpio_gpio_set(LED_PIN, PI_HIGH);
            usleep(100000);
        }

        // Flush the log file
        if (pigpio_write(gpio_fd, "obstacle_log.csv", -1) < 0) {
            fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
            pigpio_close(gpio_fd);
            return 1;
        }

        // Wait for 100ms
        usleep(100000);
    }

    // Cleanup
    pigpio_close(gpio_fd);
    return 0;
}

