#include <signal.h>
#include <sys/stat.h>
#include <fcntl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1A // ICS-40180 I2C address

volatile sig_atomic_t stop_sampling = 0;

void signal_handler(int sig) {
