#include <fcntl.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_SLAVE_ADDR 0x2A

int main() {
    int fd, gpio, i2c;
    struct gpiod_i2c_config i2c_config = {
        .i2c_bus_num = I2C_BUS_NUM,
        .i2c_slave_addr = I2C_SLAVE_ADDR,
    };

    gpio = pigpio_init();
    if (gpio < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        pigpio_exit(gpio);
        return 1;
    }

    if (ioctl(fd, PI_I2C_SET_MODE, &i2c_config) < 0) {
        fprintf(stderr, "Error setting I2C mode: %s\n", strerror(errno));
        pigpio_exit(gpio);
        close(fd);
        return 1;
    }

    if (pigpio_start() < 0) {
        fprintf(stderr, "Error starting GPIO: %s\n", strerror(errno));
        pigpio_exit(gpio);
        close(fd);
        return 1;
    }

    struct gpiod_i2c_data i2c_data = {
        .i2c_data = {
            .i2c_addr = I2C_SLAVE_ADDR,
            .flags = GPIGPIO_I2C_READ | GPIGPIO_I2C_WRITE,
        },
    };

    while (1) {
        int raw_value = 0;
        if (pigpio_i2c_read_reg16(&i2c_data, 0x00, &raw_value) < 0) {
            fprintf(stderr, "Error reading raw value from sensor: %s\n", strerror(errno));
            continue;
        }

        printf("Raw sensor value: %04X\n", raw_value);

        // Combine LSB and MSB registers into a single 16-bit raw value
        uint16_t combined_value = (raw_value & 0xFFFF) << 8 | (raw_value >> 16);

        // Log the combined sensor reading
        printf("Logged sensor reading: %04X\n", combined_value);

        // Release resources
        pigpio_i2c_release(&i2c_data);
        pigpio_exit(gpio);
    }

    return 0;
}

