int main() {
    int rc;
    int fd;
    int gpioHandle;
    int pwmHandle;
    int syslogHandle;

    // Initialize syslog
    syslogHandle = openlog("led_fader", LOG_PID | LOG_CONS, LOG_USER);
    if (syslogHandle == -1) {
        perror("Failed to open syslog");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    gpioHandle = pigpio_init();
    if (gpioHandle < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    // Open PWM
    rc = pigpio_set_mode(gpioHandle, LED_PIN, PI_OUTPUT);
    if (rc < 0) {
        perror("Failed to set PWM mode");
        exit(EXIT_FAILURE);
    }

    pwmHandle = pigpio_set_pwm_range(gpioHandle, LED_PWM_FREQ, LED_PWM_RESOLUTION);
    if (pwmHandle < 0) {
        perror("Failed to set PWM range");
        exit(EXIT_FAILURE);
    }

    // Fade the LED
    while (1) {
        int hue = rand() % 360; // Generate a random hue
        int targetHue = hue;
        int step = 50;
        int currentHue = hue;

        // Perform linear interpolation
        while (currentHue < targetHue) {
            int red = (currentHue / 360) * 255;
            int green = (currentHue / 360) * 255;
            int blue = (currentHue / 360) * 255;

            pigpio_set_pwm(gpioHandle, LED_PWM_FREQ, LED_PWM_RESOLUTION, red, green, blue);
            usleep(500000); // Wait for 500ms

            currentHue += step;
            if (currentHue > targetHue) {
                currentHue = targetHue;
            }
        }

        // Fade out the LED
        pigpio_set_pwm(gpioHandle, LED_PWM_FREQ, LED_PWM_RESOLUTION, 0, 0, 0);
        usleep(500000); // Wait for 500ms

        // Release resources
        pigpio_release(gpioHandle);
        pigpio_exit();
    }

    // Close syslog
    closelog();

    return 0;
}

