    // Initialize GPIO and I2C
    gpio_request.line = LED_GPIO;
    gpio_request.direction = GPIO_OUT;
    gpio_request.value = 0;
    gpio_request.flags = GPIO_OUTPUT_LOW;
    gpio_request.config = GPIO_OUTPUT_NO_RESET;
    gpio_request.delay_usecs = 0;

    gpio_fd = gpio_request.fd;
    gpio_request.fd = -1;
    gpio_request.flags = GPIO_OUTPUT_NO_RESET;

    gpio_config.line = LED_GPIO;
    gpio_config.flags = GPIO_OUTPUT_NO_RESET;

    gpio_request.fd = gpio_fd;
    gpio_request.config = gpio_config.config;
    gpio_request.value = gpio_config.value;

    if (gpio_request.fd == -1) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_fd, GPIO_SET_OUTPUT_LINE, LED_GPIO) < 0) {
        perror("Failed to set LED line to output");
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_fd, GPIO_SET_OUTPUT_LOW, 0) < 0) {
        perror("Failed to set LED line to low");
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_fd, GPIO_SET_OUTPUT_HIGH, 1) < 0) {
        perror("Failed to set LED line to high");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C bus speed
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C bus slave address");
        exit(EXIT_FAILURE);
    }

    // Power on TCS34725 sensor
    if (ioctl(i2c_fd, TCS34725_POWER_ON, 0) < 0) {
        perror("Failed to power on TCS34725 sensor");
        exit(EXIT_FAILURE);
    }

    // Enable RGBC (AEN)
    if (ioctl(i2c_fd, TCS34725_RGBC_AEN_ENABLE, 0) < 0) {
        perror("Failed to enable RGBC (AEN)");
        exit(EXIT_FAILURE);
    }

    // Set integration time
    if (ioctl(i2c_fd, TCS34725_SET_INT_TIME, 154) < 0) {
        perror("Failed to set integration time");
        exit(EXIT_FAILURE);
    }

    // Start polling loop
    while (1) {
        // Read sensor values
        if (ioctl(i2c_fd, TCS34725_GET_RAW_DATA, &i2c_data) < 0) {
            perror("Failed to read sensor data");
            exit(EXIT_FAILURE);
        }

        // Check if red value exceeds threshold
        if (i2c_data.red > 200) {
            printf("Red value: %d\n", i2c_data.red);
        }

        // Check if green value exceeds threshold
        if (i2c_data.green > 200) {
            printf("Green value: %d\n", i2c_data.green);
        }

        // Check if blue value exceeds threshold
        if (i2c_data.blue > 200) {
            printf("Blue value: %d\n", i2c_data.blue);
        }

        // Check if clear value exceeds threshold
        if (i2c_data.clear > 200) {
            printf("Clear value: %d\n", i2c_data.clear);
        }

        // Check if LED is on
        if (gpio_request.value == 1) {
            printf("LED is on\n");
        } else {
            printf("LED is off\n");
        }

        // Wait for 200 ms
        sleep(200);
    }

    // Release resources
    close(i2c_fd);
    close(gpio_fd);

    return 0;
}

