#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x29
#define WS2812B_PIN 18

int main() {
    int ret;
    int gpioHandle;
    int i2cHandle;
    int i2cError;
    int luxValue;
    int brightnessLevel;
    unsigned long pwmFrequency;
    unsigned int pwmValue;
    unsigned char i;

    // Initialize GPIO and I2C
    gpioHandle = gpioInit();
    if (gpioHandle < 0) {
        printf("Failed to initialize GPIO.\n");
        return 1;
    }

    ret = pigpioSetup(gpioHandle);
    if (ret < 0) {
        printf("Failed to initialize pigpio.\n");
        return 1;
    }

    // Open I2C bus
    i2cHandle = i2cOpen(I2C_BUS);
    if (i2cHandle < 0) {
        printf("Failed to open I2C bus.\n");
        return 1;
    }

    // Set up I2C communication
    i2cError = i2cSetClock(i2cHandle, 100000);
    if (i2cError < 0) {
        printf("Failed to set I2C clock.\n");
        return 1;
    }

    // Set up sensor address
    ret = i2cWriteReg8(i2cHandle, SENSOR_ADDRESS, 0x00);
    if (ret < 0) {
        printf("Failed to set sensor address.\n");
        return 1;
    }

    // Set up WS2812B data line
    ret = gpioSetMode(WS2812B_PIN, GPIO_OUTPUT);
    if (ret < 0) {
        printf("Failed to set WS2812B data line as output.\n");
        return 1;
    }

    // Set up PWM frequency
    pwmFrequency = 1000000; // 1 MHz
    pwmValue = 0;

    // Main loop
    while (1) {
        // Wait 180 ms after issuing the sensor command
        usleep(180000);

        // Read sensor value
        ret = i2cReadReg16(i2cHandle, SENSOR_ADDRESS, 0x01, &luxValue);
        if (ret < 0) {
            printf("Failed to read sensor value.\n");
            continue;
        }

        // Map lux value to brightness level
        brightnessLevel = (int)(10 * (1.0 + (luxValue / 65535.0)) / 100.0);

        // Set PWM value
        pwmValue = brightnessLevel * pwmFrequency / 1000000;
        ret = gpioSetPWM(WS2812B_PIN, pwmValue);
        if (ret < 0) {
            printf("Failed to set PWM value.\n");
            continue;
        }

        // Generate WS2812B timing
        for (i = 0; i < pwmFrequency / 2; i++) {
            gpioSetPulse(WS2812B_PIN, 1);
            gpioDelay(1);
            gpioClearPulse(WS2812B_PIN);
            gpioDelay(1);
        }

        // Wait for PWM to finish
        gpioDelay(pwmFrequency / 2);

        // Release resources
        gpioRelease(gpioHandle);
        i2cClose(i2cHandle);
        pigpioTeardown(gpioHandle);

        // Wait for SIGINT or SIGTERM
        while (1) {
            if (sigismember(&(sigset_t){SIGINT}, SIGINT)) {
                printf("Received SIGINT or SIGTERM, stopping program.\n");
                break;
            }
            sleep(1);
        }
    }

    return 0;
}

