    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1)
    {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_addr) == -1)
    {
        perror("Error setting I2C slave address");
        exit(EXIT_FAILURE);
    }

    if ((i2c_data = (struct i2c_rdwr_ioctl_data *)malloc(sizeof(struct i2c_rdwr_ioctl_data))) == NULL)
    {
        perror("Error allocating memory for i2c_data");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_RDWR, i2c_data) == -1)
    {
        perror("Error initializing I2C bus");
        exit(EXIT_FAILURE);
    }
}

void init_spi()
{
    int spi_addr = 0; // SPI bus address
    int spi_fd = -1;

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) == -1)
    {
        perror("Error opening SPI bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) == -1)
    {
        perror("Error setting SPI mode");
