    if (ioctl(spi_device->devno, SPI_IOC_WR_MODE, SPI_MODE_0) == -1)
    {
        perror("Error setting SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_device->devno, SPI_IOC_RD_MODE, 0) == -1)
    {
        perror("Error reading SPI mode");
        exit(EXIT_FAILURE);
    }

