            }
            else
            {
                perror("Error reading light level");
                exit(EXIT_FAILURE);
            }
        }
    }

    if (light_level == 0)
    {
        set_apa102_led(0);
    }
    else if (light_level > 0)
    {
        set_apa102_led(light_level);
    }
}

void set_apa102_led(uint8_t brightness)
{
    uint8_t red, green, blue;

    red = (brightness >> 16) & 0xFF;
    green = (brightness >> 8) & 0xFF;
    blue = brightness & 0xFF;

    if (write_i2c_data(i2c_data->i2c_fd, &red, 1) == -1)
