#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <linux/spi/spi.h>

#include <gpiod.h>
#include <pigpio.h>

#define APA102_MOSI_PIN 10
#define APA102_SCLK_PIN 11

#define APA102_ADDRESS 0x76

static gpio_t gpio;
static pigpio_t *pi;

static int i2c_init(void)
{
    int rc;

    if ((rc = pigpio_init()) != 0) {
        printf("Error initializing PIGPIO: %d\n", rc);
        return -1;
    }

    if ((rc = gpiod_request_property(GPIO_DIR_IN, GPIO_OUTPUT, "gpio-led", &gpio)) < 0) {
        printf("Error requesting GPIO property: %d\n", rc);
        return -1;
    }

    if ((rc = gpiod_request_property(GPIO_DIR_IN, GPIO_INPUT, "gpio-button", &gpio)) < 0) {
        printf("Error requesting GPIO property: %d\n", rc);
        return -1;
    }

    if ((rc = gpio_open(&gpio, GPIO_OUTPUT | GPIO_INPUT)) < 0) {
        printf("Error opening GPIO: %d\n", rc);
        return -1;
    }

    if ((rc = gpio_set_mode(&gpio, GPIO_OUTPUT)) < 0) {
        printf("Error setting GPIO mode: %d\n", rc);
        return -1;
    }

    if ((rc = gpio_set_direction(&gpio, GPIO_OUTPUT)) < 0) {
        printf("Error setting GPIO direction: %d\n", rc);
        return -1;
    }

    if ((rc = gpio_set_value(&gpio, 1)) < 0) {
        printf("Error setting GPIO value: %d\n", rc);
        return -1;
    }

    if ((rc = pigpio_start()) < 0) {
        printf("Error starting PIGPIO: %d\n", rc);
        return -1;
    }

    return 0;
}

static int i2c_init(void)
{
    int rc;

    if ((rc = i2c_init_device()) < 0) {
        printf("Error initializing I2C bus: %d\n", rc);
        return -1;
    }

    if ((rc = i2c_set_speed(1)) < 0) {
        printf("Error setting I2C speed: %d\n", rc);
        return -1;
    }

    if ((rc = i2c_open(APA102_ADDRESS)) < 0) {
        printf("Error opening I2C device: %d\n", rc);
        return -1;
    }

    return 0;
}

static void i2c_read_data(int i2c_bus)
{
    uint8_t data[2];
    int rc;

    if ((rc = i2c_read(i2c_bus, 0x00, data, 2)) < 0) {
        printf("Error reading I2C data: %d\n", rc);
        return;
    }

    printf("BH1750 Sensor 1: %d, BH1750 Sensor 2: %d\n", data[0], data[1]);
}

static void i2c_write_data(int i2c_bus, uint8_t data[2])
{
    int rc;

    if ((rc = i2c_write(i2c_bus, 0x00, data, 2)) < 0) {
        printf("Error writing I2C data: %d\n", rc);
        return;
    }
}

static void fade_brightness(int target_brightness)
{
    int current_brightness;
    int fade_duration = 500;
    int fade_steps = fade_duration / 100;

    for (int i = 0; i < fade_steps; i++) {
        current_brightness = min(target_brightness, current_brightness + 1);
        i2c_write_data(0, &current_brightness, sizeof(current_brightness));
        usleep(100 * 1000);
    }

    i2c_write_data(0, &target_brightness, sizeof(target_brightness));
}

int main(void)
{
    int rc;
    int i2c_bus;
    int i;

    if ((rc = i2c_init()) < 0) {
        printf("Error initializing I2C: %d\n", rc);
        return -1;
    }

    if ((rc = i2c_init()) < 0) {
        printf("Error initializing I2C: %d\n", rc);
        return -1;
    }

    if ((rc = i2c_init()) < 0) {
        printf("Error initializing I2C: %d\n", rc);
        return -1;
    }

    i2c_bus = 0;

    for (i = 0; i < 3; i++) {
        if ((rc = i2c_init()) < 0) {
            printf("Error initializing I2C: %d\n", rc);
            return -1;
        }

        if ((rc = i2c_read_data(i2c_bus)) < 0) {
            printf("Error reading I2C data from sensor %d: %d\n", i + 1, rc);
            return -1;
        }

        if ((rc = i2c_write_data(i2c_bus, &APA102_ADDRESS)) < 0) {
            printf("Error writing I2C address to sensor %d: %d\n", i + 1, rc);
            return -1;
        }

        if ((rc = i2c_read_data(i2c_bus)) < 0) {
            printf("Error reading I2C data from sensor %d: %d\n", i + 1, rc);
            return -1;
        }

        i2c_bus++;
    }

    printf("BH1750 Sensor 1 and 2 initialized successfully.\n");

    while (1) {
        fade_brightness(0);
        usleep(100000);

        fade_brightness(1);
        usleep(100000);

        fade_brightness(2);
        usleep(100000);

        fade_brightness(0);
        usleep(100000);

        fade_brightness(1);
        usleep(100000);

        fade_brightness(2);
        usleep(100000);
    }

    return 0;
}

