{
    int rc;
    int i2c_bus;
    int i;

    if ((rc = i2c_init()) < 0) {
        printf("Error initializing I2C: %d\n", rc);
        return -1;
    }

    if ((rc = i2c_init()) < 0) {
        printf("Error initializing I2C: %d\n", rc);
        return -1;
    }

    if ((rc = i2c_init()) < 0) {
        printf("Error initializing I2C: %d\n", rc);
        return -1;
    }

    i2c_bus = 0;

    for (i = 0; i < 3; i++) {
        if ((rc = i2c_init()) < 0) {
            printf("Error initializing I2C: %d\n", rc);
            return -1;
        }

        if ((rc = i2c_read_data(i2c_bus)) < 0) {
            printf("Error reading I2C data from sensor %d: %d\n", i + 1, rc);
            return -1;
        }

        if ((rc = i2c_write_data(i2c_bus, &APA102_ADDRESS)) < 0) {
            printf("Error writing I2C address to sensor %d: %d\n", i + 1, rc);
            return -1;
        }

        if ((rc = i2c_read_data(i2c_bus)) < 0) {
            printf("Error reading I2C data from sensor %d: %d\n", i + 1, rc);
            return -1;
        }

        i2c_bus++;
    }

    printf("BH1750 Sensor 1 and 2 initialized successfully.\n");

    while (1) {
        fade_brightness(0);
        usleep(100000);

        fade_brightness(1);
        usleep(100000);

        fade_brightness(2);
        usleep(100000);

        fade_brightness(0);
        usleep(100000);

        fade_brightness(1);
        usleep(100000);

        fade_brightness(2);
        usleep(100000);
    }

    return 0;
}
