#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_BASE 0x20200000
#define GPIO_DIR_MASK 0x1F
#define GPIO_DATA_MASK 0x3F
#define GPIO_CLK_MASK 0x40
#define GPIO_LATCH_MASK 0x80

int main() {
    int chip_num = 1;
    int data_pin = 17;
    int clock_pin = 18;
    int latch_pin = 27;

    // Initialize GPIO bus
    int fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open /dev/mem");
        exit(EXIT_FAILURE);
    }

    struct gpio_desc *gpio = (struct gpio_desc *)GPIO_BASE;
    if (ioctl(fd, GPIO_IOC_BASE + GPIO_IOC_CMD, chip_num) < 0) {
        perror("Failed to initialize GPIO bus");
        exit(EXIT_FAILURE);
    }

    gpio->dir[data_pin] = GPIO_DIR_MASK | GPIO_DATA_MASK;
    gpio->value[data_pin] = 0;

    gpio->dir[clock_pin] = GPIO_DIR_MASK | GPIO_CLK_MASK;
    gpio->value[clock_pin] = 0;

    gpio->dir[latch_pin] = GPIO_DIR_MASK | GPIO_LATCH_MASK;
    gpio->value[latch_pin] = 0;

    close(fd);

    // Set up the 74HC595 shift register
    struct shift_reg_desc *shift_reg = (struct shift_reg_desc *)GPIO_BASE + (chip_num * 16);
    shift_reg->dir[0] = GPIO_DIR_MASK | GPIO_DATA_MASK;
    shift_reg->value[0] = 0x0000FFFF;

    // Set up the seven-segment display
    struct seven_segment_desc *segments = (struct seven_segment_desc *)GPIO_BASE + (chip_num * 16);
    segments->dir[0] = GPIO_DIR_MASK | GPIO_DATA_MASK;
    segments->value[0] = 0x0000FFFF;

    // Set up the common-cathode seven-segment display
    struct common_cathode_seven_segment_desc *common_cathode_segments = (struct common_cathode_seven_segment_desc *)GPIO_BASE + (chip_num * 16);
    common_cathode_segments->dir[0] = GPIO_DIR_MASK | GPIO_DATA_MASK;
    common_cathode_segments->value[0] = 0x0000FFFF;

    // Set up the shift-out routine
    int shift_out_len = 8;
    int shift_out_data = 0x12345678;

    // Set up the blink pattern
    int blink_period_ms = 500;
    int blink_on_ms = 500;
    int blink_off_ms = 500;

    // Main loop
    while (1) {
        // Shift out the 8-bit pattern
        for (int i = 0; i < shift_out_len; i++) {
            if (i < shift_out_data) {
                shift_reg->value[i] = shift_out_data & 0xFF;
            }
            shift_reg->dir[i] = GPIO_DIR_MASK | GPIO_DATA_MASK;
            shift_reg->value[i] = 0;
            ioctl(fd, GPIO_IOC_BASE + GPIO_IOC_CMD, shift_reg);
            usleep(500);
        }

        // Blink the digit
        for (int i = 0; i < shift_out_len; i++) {
            if (i == 5) {
                common_cathode_segments->value[i] = 0xFFFFFF00;
            } else {
                common_cathode_segments->value[i] = 0x0000FFFF;
            }
            common_cathode_segments->dir[i] = GPIO_DIR_MASK | GPIO_DATA_MASK;
            common_cathode_segments->value[i] = 0;
            ioctl(fd, GPIO_IOC_BASE + GPIO_IOC_CMD, common_cathode_segments);
            usleep(blink_on_ms);
        }

        // Wait for the next blink period
        usleep(blink_off_ms);
    }

    return 0;
}

