#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18

int main() {
    int chip_fd;
    struct gpiod_line *led_line;
    struct gpiod_line *button_line;
    struct gpiod_event_request button_request;
    struct gpiod_event_request led_request;
    int timeout_ms = 1000;
    int exit_gracefully = 0;

    // Initialize GPIO lines
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    // Request LED line as output
    led_line = gpiod_request_line(chip_fd, LED_PIN, GPIDO_OUTPUT);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to request LED line as output.\n");
        gpiod_exit(chip_fd);
        return 1;
    }

    // Request button line as input with pull-up and edge detection
    button_line = gpiod_request_line(chip_fd, BUTTON_PIN, GPIDO_INPUT | GPIDO_PULLUP | GPIDO_FALLING);
    if (button_line == NULL) {
        fprintf(stderr, "Failed to request button line as input with pull-up and edge detection.\n");
        gpiod_release_line(chip_fd, LED_PIN);
        gpiod_exit(chip_fd);
        return 1;
    }

    // Open GPIO chip
    chip_fd = gpiod_open(chip_fd);
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        gpiod_release_line(chip_fd, LED_PIN);
        gpiod_release_line(chip_fd, BUTTON_PIN);
        gpiod_exit(chip_fd);
        return 1;
    }

    // Set LED line as output and turn it off
    if (gpio_set_line(chip_fd, LED_PIN, GPIDO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED line as output.\n");
        gpiod_release_line(chip_fd, LED_PIN);
        gpiod_release_line(chip_fd, BUTTON_PIN);
        gpiod_exit(chip_fd);
        return 1;
    }
    gpio_set_line(chip_fd, LED_PIN, GPIDO_LOW);

    // Wait for falling-edge event from button
    button_request.type = GPIDO_FALLING;
    button_request.line = button_line;
    button_request.event_mask = GPIDO_EVENT_FALLING;
    button_request.edge_detection = GPIDO_EDGE_FALLING;
    button_request.timeout_ms = timeout_ms;

    if (gpiod_event_request(chip_fd, &button_request) < 0) {
        fprintf(stderr, "Failed to request falling-edge event from button.\n");
        gpio_set_line(chip_fd, LED_PIN, GPIDO_LOW);
        gpiod_release_line(chip_fd, LED_PIN);
        gpiod_release_line(chip_fd, BUTTON_PIN);
        gpiod_exit(chip_fd);
        return 1;
    }

    // Wait for falling-edge event from button
    while (1) {
        struct gpiod_event_data *event_data;
        if (gpiod_event_wait(chip_fd, timeout_ms) < 0) {
            fprintf(stderr, "Failed to wait for falling-edge event from button.\n");
            gpio_set_line(chip_fd, LED_PIN, GPIDO_LOW);
            gpiod_release_line(chip_fd, LED_PIN);
            gpiod_release_line(chip_fd, BUTTON_PIN);
            gpiod_exit(chip_fd);
            return 1;
        }

        event_data = gpiod_event_data_get(chip_fd);
        if (event_data == NULL) {
            fprintf(stderr, "Failed to get event data.\n");
            gpio_set_line(chip_fd, LED_PIN, GPIDO_LOW);
            gpiod_release_line(chip_fd, LED_PIN);
            gpiod_release_line(chip_fd, BUTTON_PIN);
            gpiod_exit(chip_fd);
            return 1;
        }

        if (event_data->event_type == GPIDO_FALLING) {
            gpio_set_line(chip_fd, LED_PIN, GPIDO_HIGH);
            break;
        }
    }

    // Stop the blinking and turn off the LED
    gpio_set_line(chip_fd, LED_PIN, GPIDO_LOW);

    // Print button press message
    printf("Button press detected.\n");

    // Release resources
    gpio_release_line(chip_fd, LED_PIN);
    gpio_release_line(chip_fd, BUTTON_PIN);
    gpiod_release(chip_fd);

    return 0;
}

