    if (gpio_init() < 0) {
        fprintf(stderr, "Error initializing pigpio library\n");
        return 1;
    }

    // Open GPIO file descriptor
    fd = open("/dev/gpiomem", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO file descriptor\n");
        return 1;
    }

    // Get GPIO file descriptor
    gpio_fd = open(fd, O_RDWR);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO file descriptor\n");
        return 1;
    }

    // Configure GPIO lines
    gpio_desc = (struct gpio_desc *)gpio_fd;
    gpio_desc->gpio_base_address = GPIO_BASE_ADDRESS;
    gpio_desc->gpio_num_periph_base = GPIO_NUM_PERIPH_BASE;
    gpio_desc->gpio_num_periph_offset = GPIO_NUM_PERIPH_OFFSET;

