    gpio_desc->gpio_int_desc = &gpio_int_desc;

    // Set up GPIO interrupt lines
    gpio_int_line.gpio_int_line = GPIO_NUM_PERIPH_BASE + GPIO_NUM_PERIPH_OFFSET + 0;
    gpio_desc->gpio_int_line = &gpio_int_line;

    gpio_int_line.gpio_int_line = GPIO_NUM_PERIPH_BASE + GPIO_NUM_PERIPH_OFFSET + 0;
    gpio_desc->gpio_int_line = &gpio_int_line;

    // Set up random number seed
    srand(time(NULL));

    // Set up PWM for red channel
    red_channel = GPIO_NUM_PERIPH_BASE + GPIO_NUM_PERIPH_OFFSET + 0;
    gpio_desc->gpio_config_desc->gpio_config_output_level = GPIO_OUTPUT_LEVEL_LOW;
    gpio_desc->gpio_config_desc->gpio_config_output_polarity = GPIO_OUTPUT_POLARITY_LOW;
    gpio_desc->gpio_config_desc->gpio_config_output_edge = GPIO_OUTPUT_EDGE_FALLING;
