#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x1A
#define THRESHOLD 2.0f

int main(int argc, char *argv[]) {
    int i2c_fd, gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_direction_ioctl_data gpio_data;
    struct gpio_line_config gpio_config;
    struct gpio_state gpio_state;
    struct gpio_event gpio_event;
    struct timespec start_time, end_time;
    float total_g_force;
    char log_file[128];

    // Initialize GPIO and I2C
    gpio_init();
    gpio_set_mode(17, GPIO_OUTPUT);
    gpio_set_dir(17, GPIO_OUTPUT);

    // Open I2C bus
    i2c_fd = pigpio_open_i2c(I2C_BUS_NUM);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_error_str(pigpio_last_error()));
        return 1;
    }

    // Open GPIO
    gpio_fd = gpio_open(17);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", pigpio_error_str(pigpio_last_error()));
        return 1;
    }

    // Set GPIO direction and configuration
    gpio_config(gpio_fd, GPIO_OUTPUT);
    gpio_config_as_output(gpio_fd, GPIO_LINE_17);

    // Set GPIO direction for I2C communication
    gpio_config(i2c_fd, GPIO_OUTPUT);
    gpio_config_as_output(i2c_fd, GPIO_LINE_1);

    // Initialize I2C communication
    if (pigpio_i2c_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", pigpio_error_str(pigpio_last_error()));
        return 1;
    }

    // Initialize total G-force magnitude
    total_g_force = 0.0f;

    // Main loop
    while (1) {
        // Read accelerometer data
        if (pigpio_i2c_read_reg(i2c_fd, I2C_ADDR, 0x1A, &i2c_data.data32) < 0) {
            fprintf(stderr, "Failed to read data from accelerometer: %s\n", pigpio_error_str(pigpio_last_error()));
            return 1;
        }

        // Compute total G-force magnitude
        total_g_force = sqrtf(i2c_data.data32[0] * i2c_data.data32[0] + i2c_data.data32[1] * i2c_data.data32[1] + i2c_data.data32[2] * i2c_data.data32[2]);

        // Log the timestamped accelerometer data
        snprintf(log_file, sizeof(log_file), "timestamp_%f.txt", gpio_get_time());
        FILE *log_file_fp = fopen(log_file, "w");
        if (log_file_fp == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", log_file);
            return 1;
        }
        fprintf(log_file_fp, "timestamp,x,y,z\n");
        fprintf(log_file_fp, "%.6f,%.6f,%.6f\n", gpio_get_time(), i2c_data.data32[0], i2c_data.data32[1], i2c_data.data32[2]);
        fclose(log_file_fp);

        // Check if the total G-force magnitude exceeds the threshold
        if (total_g_force > THRESHOLD) {
            // Trigger impact interrupt
            gpio_set_value(gpio_fd, 1);
            gpio_event.gpio_line = 17;
            gpio_event.event_type = GPIO_EVENT_TYPE_LEVEL_HIGH;
            gpio_event.event_code = GPIO_EVENT_CODE_GPIO_HIGH;
            gpio_event.gpio_edge = GPIO_EVENT_EDGE_FALLING;
            gpio_event.gpio_line_config = GPIO_LINE_17;
            gpio_event.gpio_state = GPIO_STATE_SET;
            gpio_event.gpio_state_change_time = gpio_get_time();
            gpio_post(gpio_fd, &gpio_event);

            // Wait for 50 ms
            usleep(50000);

            // Clear impact interrupt
            gpio_set_value(gpio_fd, 0);
            gpio_event.gpio_line = 17;
            gpio_event.event_type = GPIO_EVENT_TYPE_LEVEL_LOW;
            gpio_event.event_code = GPIO_EVENT_CODE_GPIO_LOW;
            gpio_event.gpio_edge = GPIO_EVENT_EDGE_RISING;
            gpio_event.gpio_line_config = GPIO_LINE_17;
            gpio_event.gpio_state = GPIO_STATE_SET;
            gpio_event.gpio_state_change_time = gpio_get_time();
            gpio_post(gpio_fd, &gpio_event);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    gpio_close(gpio_fd);
    pigpio_i2c_exit(i2c_fd);
    gpio_uninit();

    return 0;
}

