#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x1A

#define ANALOG_INPUT_X 0
#define ANALOG_INPUT_Y 1
#define ANALOG_INPUT_Z 2

#define ANALOG_RANGE_2G 0x00
#define ANALOG_RANGE_4G 0x01

#define I2C_DATA_RATE 200

#define THRESHOLD_MAGNITUDE 5.0

int main() {
    int i2c_fd;
    struct gpiod_i2c_config config = GPIDO_I2C_DEFAULT_CONFIG;
    struct gpiod_i2c_data data;
    struct gpiod_i2c_data_read_result result;
    char buffer[32];
    char timestamp[30];
    float magnitude;
    char impact_log_filename[100];
    FILE *impact_log_file;

    // Initialize libgpiod
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = gpiod_i2c_open(I2C_BUS_NUM, I2C_DEVICE_ADDR, &config)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_exit();
        return 1;
    }

    // Open impact log file
    if ((impact_log_file = fopen(impact_log_filename, "a")) == NULL) {
        fprintf(stderr, "Failed to open impact log file\n");
        gpiod_i2c_close(i2c_fd);
        gpiod_exit();
        return 1;
    }

    // Verify WHO_AM_I identifier
    if (gpiod_i2c_read(i2c_fd, ANALOG_INPUT_X, &data, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I identifier\n");
        gpiod_i2c_close(i2c_fd);
        fclose(impact_log_file);
        gpiod_exit();
        return 1;
    }

    if (data.data[0] != 0x7c) {
        fprintf(stderr, "Invalid WHO_AM_I identifier\n");
        gpiod_i2c_close(i2c_fd);
        fclose(impact_log_file);
        gpiod_exit();
        return 1;
    }

    // Place device in standby
    if (gpiod_i2c_write(i2c_fd, ANALOG_INPUT_X, &data, 1) < 0) {
        fprintf(stderr, "Failed to place device in standby\n");
        gpiod_i2c_close(i2c_fd);
        fclose(impact_log_file);
        gpiod_exit();
        return 1;
    }

    // Configure sensor for ±2 g range
    if (gpiod_i2c_write(i2c_fd, ANALOG_INPUT_X, &data, 1) < 0) {
        fprintf(stderr, "Failed to configure sensor for ±2 g range\n");
        gpiod_i2c_close(i2c_fd);
        fclose(impact_log_file);
        gpiod_exit();
        return 1;
    }

    // Activate I2C handle
    if (gpiod_i2c_activate(i2c_fd) < 0) {
        fprintf(stderr, "Failed to activate I2C handle\n");
        gpiod_i2c_close(i2c_fd);
        fclose(impact_log_file);
        gpiod_exit();
        return 1;
    }

    // Loop to read sensor data
    while (1) {
        // Read sensor data
        if (gpiod_i2c_read(i2c_fd, ANALOG_INPUT_X, &data, 1) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            gpiod_i2c_close(i2c_fd);
            fclose(impact_log_file);
            gpiod_exit();
            return 1;
        }

        // Compute acceleration magnitude
        magnitude = sqrt(data.data[0] * data.data[0] + data.data[1] * data.data[1] + data.data[2] * data.data[2]);

        // Append timestamp, raw x, y, z values, and magnitude to impact log file
        snprintf(timestamp, 30, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f",
                 asctime(localtime()), data.data[0], data.data[1], data.data[2], magnitude);

        // Append newline to impact log file
        fprintf(impact_log_file, "%s\n", timestamp);

        // Check if acceleration magnitude exceeds threshold
        if (magnitude > THRESHOLD_MAGNITUDE) {
            // Append current timestamp, raw x, y, z values, and magnitude to impact log file
            snprintf(timestamp, 30, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f",
                     asctime(localtime()), data.data[0], data.data[1], data.data[2], magnitude);

            // Append newline to impact log file
            fprintf(impact_log_file, "%s\n", timestamp);
        }

        // Wait for I2C data rate
        usleep(I2C_DATA_RATE * 1000);
    }

    // Deactivate I2C handle
    if (gpiod_i2c_deactivate(i2c_fd) < 0) {
        fprintf(stderr, "Failed to deactivate I2C handle\n");
        gpiod_i2c_close(i2c_fd);
        fclose(impact_log_file);
        gpiod_exit();
        return 1;
    }

    // Close I2C handle
    if (gpiod_i2c_close(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C handle\n");
        gpiod_exit();
        return 1;
    }

    // Cleanup
    gpiod_exit();
    return 0;
