#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define LED_GPIO_NUM 17

int main() {
    int fd;
    int i;
    int16_t data[3];
    int16_t accel_data[3];
    int16_t threshold = 2.0;
    int16_t absolute_threshold = 4.0;
    int16_t absolute_threshold_g = 8.0;
    int16_t log_file_fd;
    char log_file_path[128] = "accel_log.txt";

    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (piSetup() < 0) {
        fprintf(stderr, "Failed to initialize PIGPIO\n");
        return 1;
    }

    // Open I2C file descriptor
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    // Open log file
    log_file_fd = open(log_file_path, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (log_file_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Configure ADXL345 for full-resolution mode
    if (gpioSetMode(LED_GPIO_NUM, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED mode\n");
        return 1;
    }

    if (gpioSetValue(LED_GPIO_NUM, GPIO_VALUE_HIGH) < 0) {
        fprintf(stderr, "Failed to set LED high\n");
        return 1;
    }

    // Set the device ID register to the documented value
    if (gpioReadReg16(I2C_SLV_NDK_REG, 0) != 0x53) {
        fprintf(stderr, "ADXL345 device ID register does not contain 0x53\n");
        return 1;
    }

    // Start I2C communication loop
    while (1) {
        // Read data from ADXL345
        if (gpioI2CReadReg16(I2C_SLV_NDK_REG, 0x32) < 0) {
            fprintf(stderr, "Failed to read data from ADXL345\n");
            return 1;
        }

        // Read acceleration data from ADXL345
        if (gpioI2CReadReg16(I2C_SLV_NDK_REG, 0x2A) < 0) {
            fprintf(stderr, "Failed to read data from ADXL345\n");
            return 1;
        }

        // Convert data to g units
        for (i = 0; i < 3; i++) {
            data[i] = (int16_t)((gpioI2CReadReg16(I2C_SLV_NDK_REG, 0x32) << 8) + gpioI2CReadReg16(I2C_SLV_NDK_REG, 0x2A) >> 2);
            accel_data[i] = (int16_t)((data[i] * 16) / (2.0 * 8));
        }

        // Log each sample
        for (i = 0; i < 3; i++) {
            sprintf(log_file_path, "%.3f,%.3f,%.3f,", accel_data[i], accel_data[i], accel_data[i]);
            if (write(log_file_fd, log_file_path, strlen(log_file_path)) < 0) {
                fprintf(stderr, "Failed to write log entry\n");
                return 1;
            }
        }

        // Check if acceleration exceeds 2.0 g
        for (i = 0; i < 3; i++) {
            if (abs(accel_data[i]) > threshold) {
                gpioSetValue(LED_GPIO_NUM, GPIO_VALUE_HIGH);
                break;
            }
        }

        // Release resources
        gpioRelease();
        close(log_file_fd);
        gpioRelease();
    }

    return 0;
}

