#include <sys/time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_SLAVE_ADDR 0x1A

int main() {
    int i2c_fd;
    struct gpiod_i2c_config config = GPIOD_I2C_DEFAULT_CONFIG();
    struct gpiod_i2c_state i2c_state;
    struct gpiod_i2c_request request;
