    if ((ret = gpiod_i2c_request_data(i2c_fd, I2C_SLAVE_ADDR, &data)) < 0) {
        perror("Failed to request I2C device");
        gpiod_i2c_close(i2c_fd);
        return 1;
    }

    // Open log file
    if ((fp = fopen("audio_log.dat", "w")) == NULL) {
        perror("Failed to open log file");
        gpiod_i2c_release_data(i2c_fd, &data);
        gpiod_i2c_close(i2c_fd);
        return 1;
    }

    // Initialize GPIO pins
    if ((gpio_init() < 0) || (gpio_set_mode(GPIO_SCL, GPIO_MODE_OUTPUT) < 0) || (gpio_set_mode(GPIO_SDA, GPIO_MODE_INPUT) < 0)) {
        perror("Failed to initialize GPIO pins");
        fclose(fp);
        gpiod_i2c_release_data(i2c_fd, &data);
        gpiod_i2c_close(i2c_fd);
        return 1;
    }

    // Initialize I2C driver
    if ((ret = pigpio_init()) < 0) {
        perror("Failed to initialize I2C driver");
        gpio_cleanup();
        gpiod_i2c_release_data(i2c_fd, &data);
