#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE_FILE "/dev/spidev0.0"
#define SPI_MODE_3 0x03
#define SPI_CS_GPIO_8 8

int main() {
    int fd;
    int spi_fd;
    struct spi_device *spi;
    struct gpiod_chip *chip;
    struct gpiod_direction_output gpiod_cs;
    struct gpiod_direction_output gpiod_data;
    struct gpiod_falling_edge_trigger gpiod_trigger;
    struct gpiod_event gpiod_event;
    unsigned int gyro_scale = 0.02;
    unsigned int accel_scale = 0.00025;

    // Initialize SPI device file and chip
    fd = open(SPI_DEVICE_FILE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device file");
        exit(EXIT_FAILURE);
    }

    spi_fd = open(SPI_DEVICE_FILE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device file");
        exit(EXIT_FAILURE);
    }

    // Initialize chip
    chip = gpiod_chip_new(spi_fd);
    if (chip == NULL) {
        perror("Error initializing chip");
        exit(EXIT_FAILURE);
    }

    // Set GPIO8 as chip select
    gpiod_cs.gpio_num = SPI_CS_GPIO_8;
    gpiod_cs.direction = GPIDO_OUTPUT;
    gpiod_cs.active_low = 0;
    gpiod_cs.edge_triggered = 0;
    gpiod_cs.debounce_time = 0;
    gpiod_cs.active_high = 0;
    gpiod_chip_set_direction(chip, &gpiod_cs);

    // Initialize SPI device
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_3) < 0) {
        perror("Error initializing SPI device");
        exit(EXIT_FAILURE);
    }

    // Set chip select as active
    gpiod_chip_set_active(chip);

    // Initialize gpio event
    gpiod_event.gpio_num = SPI_CS_GPIO_8;
    gpiod_event.event_type = GPIDO_EVENT_FALLING_EDGE;
    gpiod_event.edge_trigger_type = GPIDO_EDGE_TRIGGER_FALLING;
    gpiod_event.debounce_time = 0;
    gpiod_event.edge_active_high = 1;
    gpiod_event.edge_active_low = 0;
    gpiod_event.edge_rising_time = 0;
    gpiod_event.edge_falling_time = 0;
    gpiod_chip_set_event(chip, &gpiod_event);

    // Initialize falling edge trigger
    gpiod_trigger.gpio_num = SPI_CS_GPIO_8;
    gpiod_trigger.event_type = GPIDO_EVENT_FALLING_EDGE;
    gpiod_trigger.edge_trigger_type = GPIDO_EDGE_TRIGGER_FALLING;
    gpiod_trigger.debounce_time = 0;
    gpiod_trigger.edge_active_high = 1;
    gpiod_trigger.edge_active_low = 0;
    gpiod_chip_set_event(chip, &gpiod_trigger);

    // Start SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE, 1) < 0) {
        perror("Error initializing SPI device");
        exit(EXIT_FAILURE);
    }

    // Perform single-register read operations
    while (1) {
        // Wait for falling edge trigger
        gpiod_chip_wait_for_event(chip, &gpiod_event);

        // Read gyroscope and accelerometer registers
        unsigned int gyro_data;
        unsigned int accel_data;

        if (ioctl(spi_fd, SPI_IOC_RD_REG32, &gyro_data) < 0) {
            perror("Error reading gyroscope data");
            exit(EXIT_FAILURE);
        }

        if (ioctl(spi_fd, SPI_IOC_RD_REG32, &accel_data) < 0) {
            perror("Error reading accelerometer data");
            exit(EXIT_FAILURE);
        }

        // Apply gyro scale
        gyro_data *= gyro_scale;

        // Apply accel scale
        accel_data *= accel_scale;

        // Log data to console
        printf("Gyroscope X: %u\n", gyro_data);
        printf("Gyroscope Y: %u\n", gyro_data >> 8);
        printf("Gyroscope Z: %u\n", gyro_data >> 16);

        printf("Accelerometer X: %u\n", accel_data);
        printf("Accelerometer Y: %u\n", accel_data >> 8);
        printf("Accelerometer Z: %u\n", accel_data >> 16);

        // Wait for 100 ms
        sleep(100);
    }

    // Clean up resources
    close(spi_fd);
    gpio_chip_unregister(chip);
    gpiod_chip_free(chip);

    return 0;
}

