        return 1;
    }

    // Set SPI transfer data for offset
    if (spi_transfer(spi_fd, (uint8_t *)&adis16448_config.data_offset, sizeof(adis16448_config.data_offset), NULL, 0) < 0) {
        fprintf(stderr, "Failed to set SPI transfer data for offset.\n");
        return 1;
    }

    // Set SPI transfer data for noise density
    if (spi_transfer(spi_fd, (uint8_t *)&adis16448_config.noise_density, sizeof(adis16448_config.noise_density), NULL, 0) < 0) {
