#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x1A

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int retries = 3;
    int i;

    // Initialize I2C library
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C library\n");
        return 1;
    }

    if (pi_open_i2c_bus() < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    fd = pi_i2c_open(I2C_BUS_NUM, I2C_DEVICE_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    // Set up I2C message structure
    msg[0].addr = I2C_DEVICE_ADDR;
    msg[0].flags = 0;
    msg[0].len = 2;
    msg[0].buf = (void *)&data;
    msg[1].addr = I2C_DEVICE_ADDR;
    msg[1].flags = 0;
    msg[1].len = 2;
    msg[1].buf = (void *)&data;

    // Read raw accelerometer and gyroscope values
    for (i = 0; i < 100; i++) {
        retries--;
        if (retries <= 0) {
            fprintf(stderr, "Failed to read data after 3 retries\n");
            return 1;
        }

        if (pi_i2c_read(fd, &msg[0], 1, &data) < 0) {
            fprintf(stderr, "Failed to read data from I2C device\n");
            return 1;
        }

        if (data.status & I2C_RDWR_ERROR) {
            fprintf(stderr, "Sensor-absent or bus-error condition detected\n");
            return 1;
        }

        // Print raw accelerometer and gyroscope values
        printf("Raw Accelerometer: %d\n", data.raw.x);
        printf("Raw Gyroscope: %d\n", data.raw.y);

        // Wait 50 ms before reading again
        usleep(50000);
    }

    // Clean up I2C resources
    pi_i2c_close(fd);
    pi_close_i2c_bus();
    gpio_exit();

    return 0;
}

