#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x1A

int main() {
    int i2c_fd;
    struct gpiod_i2c_config i2c_config = {
        .speed = GPIDO_I2C_SPEED_100KHZ,
        .sda_gpio = 17,
        .scl_gpio = 27,
    };

    int ret;
    struct gpiod_i2c_data i2c_data;

    // Initialize I2C bus
    if ((ret = gpiod_i2c_init(&i2c_config)) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus: %s\n", gpiod_strerror(ret));
        return 1;
    }

    // Open I2C device
    if ((i2c_fd = gpiod_i2c_open(i2c_config.i2c_bus, I2C_DEVICE_ADDR, &i2c_data)) < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", gpiod_strerror(ret));
        gpiod_i2c_close(i2c_fd);
        gpiod_i2c_uninit(&i2c_config);
        return 1;
    }

    // Perform burst reads
    struct timespec start_time, end_time;
    struct i2c_msg msgs[2];
    msgs[0].addr = I2C_DEVICE_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 2;
    msgs[0].buf = (void*)&i2c_data.i2c_data;
    msgs[0].buf[0] = 0x00;
    msgs[0].buf[1] = 0x3F;
