#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdlib.h>
#include <pigpio.h>

#define I2C_SLAVE_ADDRESS 0x1A // Default sensor address
#define I2C_SAMPLE_INTERVAL 1000 // Sample every 1 second

int main() {
    int i2c_fd;
    int csv_fd;
    struct gpiod_i2c_config i2c_config = {
        .speed = GPIDO_SPEED_100KHZ,
        .address = I2C_SLAVE_ADDRESS,
    };
    struct gpiod_i2c_data i2c_data = {
        .gpio_num = GPIO_NUM_2,
        .function = GPIDO_FUNCTION_I2C,
    };

    // Initialize I2C bus
    if (gpioio_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    if (gpio_set_mode(i2c_config.gpio_num, GPMODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C bus output mode\n");
        return 1;
    }

    if (gpio_set_dir(i2c_config.gpio_num, GPMODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C bus direction\n");
        return 1;
    }

    if (gpio_set_level(i2c_config.gpio_num, 1) < 0) {
        fprintf(stderr, "Failed to set I2C bus output to high\n");
        return 1;
    }

    // Open I2C file descriptor
    if ((i2c_fd = gpio_open_i2c(I2C_SLAVE_ADDRESS, &i2c_config)) < 0) {
        fprintf(stderr, "Failed to open I2C file descriptor\n");
        return 1;
    }

    // Open CSV file
    if ((csv_fd = fopen("magnetic_field_log.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    // Initialize the sensor
    if (tmag5273_init() < 0) {
        fprintf(stderr, "Failed to initialize TMAG5273 sensor\n");
        return 1;
    }

    // Start sampling loop
    while (1) {
        // Read data from the sensor
        if (tmag5273_read_data(&i2c_data) < 0) {
            fprintf(stderr, "Failed to read data from sensor\n");
            return 1;
        }

        // Log the reading
        struct timeval now;
        gettimeofday(&now, NULL);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &now);
        fprintf(csv_fd, "%s,%ld\n", timestamp, (long)i2c_data.value);

        // Wait for a second
        usleep(I2C_SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    gpio_close(i2c_fd);
    fclose(csv_fd);
    gpio_exit();

    return 0;
}

