#define CS_GPIO_NUMBER 8
#define CS_GPIO_NAME "cs8"

#define SPI_MODE_3 (1 << 1)
#define SPI_CPOL_1 (1 << 0)
#define SPI_CS_LOW (1 << 7)

#define ADIS16266_WHO_AM_I_REG 0x1A
#define ADIS16266_GYRO_DATA_REG 0x32
#define ADIS16266_GYRO_CONFIG_REG 0x30

#define ADIS16266_GYRO_SAMPLE_INTERVAL_MS 10
#define ADIS16266_GYRO_SCALE_FACTOR 0.0305

#define MAX_CS_TRIES 5

void init_gpio(void) {
    int fd;
    char *devname = "/dev/spidev0.0";

    if ((fd = open(devname, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", devname);
        exit(1);
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, SPI_MODE_3) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", devname);
        exit(1);
    }

    if (ioctl(fd, SPI_IOC_WR_CS_POLARITY, SPI_CPOL_1) < 0) {
        fprintf(stderr, "Failed to set SPI chip select polarity: %s\n", devname);
        exit(1);
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &spi_flags) < 0) {
        fprintf(stderr, "Failed to get SPI mode: %s\n", devname);
        exit(1);
    }

    if (spi_flags & ~SPI_MODE_3) {
        fprintf(stderr, "Invalid SPI mode: %s\n", devname);
        exit(1);
    }

    if (ioctl(fd, SPI_IOC_RD_CS, &cs_gpio_value) < 0) {
        fprintf(stderr, "Failed to get SPI chip select value: %s\n", devname);
        exit(1);
    }

    if (cs_gpio_value != 1) {
        fprintf(stderr, "Failed to set SPI chip select to low: %s\n", devname);
        exit(1);
    }

    close(fd);
}

void release_gpio(void) {
    if (cs_gpio_value == 1) {
        close(open(CS_GPIO_NAME, O_RDWR));
    }
}

int main(void) {
    int fd;
    struct spi_fns *spi_fns;
    struct spi_ioc_transfer transfer;
    uint8_t data[2];
    uint16_t value;
    int ret;

    init_gpio();

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device: /dev/spidev0.0\n");
        exit(1);
    }

    spi_fns = &spi_fns_rpi3;
    ret = spi_open(fd, spi_fns);
    if (ret < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", "/dev/spidev0.0");
        exit(1);
    }

    memset(&transfer, 0, sizeof(transfer));
    transfer.speed_hz = 1000000;
    transfer.mode = SPI_MODE_3;
    transfer.chip_select = CS_GPIO_NUMBER;
    transfer.len = 2;
    transfer.tx_buf = (void *)data;
    transfer.rx_buf = (void *)data;

    while (true) {
        ret = spi_transfer(spi, &transfer);
        if (ret < 0) {
            fprintf(stderr, "Failed to transfer data: %s\n", spi_strerror(ret));
            exit(1);
        }

        value = ntohs(*(uint16_t *)data);
        if (value == ADIS16266_WHO_AM_I_REG) {
            fprintf(stderr, "ADIS16266 WHO_AM_I register read: 0x%02X\n", value);
        } else if (value == ADIS16266_GYRO_DATA_REG) {
            fprintf(stderr, "ADIS16266 gyro data read: 0x%04X\n", value);
        } else {
            fprintf(stderr, "Unknown register read: 0x%04X\n", value);
        }

        usleep(ADIS16266_GYRO_SAMPLE_INTERVAL_MS * 1000);
    }

    release_gpio();

    return 0;
}

