#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/mman.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1A
#define I2C_TIMEOUT 5

#define GY_45_MMA8452Q_WHO_AM_I_REG 0x1F
#define GY_45_MMA8452Q_CTRL_REG 0x00
#define GY_45_MMA8452Q_DATA_REG_X_MSB_LSB_REG 0x1B
#define GY_45_MMA8452Q_DATA_REG_X_LSB_MSB_REG 0x1C
#define GY_45_MMA8452Q_DATA_REG_Y_MSB_LSB_REG 0x1D
#define GY_45_MMA8452Q_DATA_REG_Y_LSB_MSB_REG 0x1E
#define GY_45_MMA8452Q_DATA_REG_Z_MSB_LSB_REG 0x1F

#define X_SHIFT 4
#define Y_SHIFT 4
#define Z_SHIFT 4

#define TILT_THRESHOLD 45

int main() {
    int i, fd, ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    uint8_t buffer[2];
    uint16_t data_reg_values[6];
    struct sigaction sa;
    FILE *log_file;

    // Open log file in append mode
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Install signal handler for SIGINT and SIGTERM
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C file descriptor
    fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    // Check sensor identity
    ret = ioctl(fd, I2C_RDWR, I2C_ADDR);
    if (ret < 0) {
        perror("Error reading sensor identity");
        exit(EXIT_FAILURE);
    }
    if (ret != GY_45_MMA8452Q_WHO_AM_I_REG) {
        fprintf(stderr, "Sensor identity does not match the documented value\n");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C device
    memset(&i2c_data, 0, sizeof(i2c_data));
    i2c_data.flags = I2C_RDWR;
    i2c_data.timeout = I2C_TIMEOUT;
    ret = ioctl(fd, I2C_RDWR, I2C_ADDR);
    if (ret < 0) {
        perror("Error initializing I2C device");
        exit(EXIT_FAILURE);
    }

    // Place sensor in standby mode
