#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/input.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/gpio.h>

#define GPIO_FILE "/dev/gpiochip4"
#define GPIO_LINE 17

int main() {
    int fd;
    struct gpio_line_config line_config;
    struct gpio_event event;
    struct timespec start_time, end_time;
    char log_message[100];

    // Initialize GPIO chip
    fd = open(GPIO_FILE, O_RDWR);
    if (fd < 0) {
        perror("Error opening GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Configure GPIO line
    memset(&line_config, 0, sizeof(line_config));
    line_config.line = GPIO_LINE;
    line_config.direction = GPIO_INPUT;
    if (ioctl(fd, GPIO_GET_LINE_CONFIG, &line_config) < 0) {
        perror("Error getting GPIO line configuration");
        exit(EXIT_FAILURE);
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Start self-parking sequence
    start_time = get_monotonic_time();
    while (1) {
        // Read sensor value
        if (read(fd, &event, sizeof(event)) != sizeof(event)) {
            perror("Error reading sensor value");
            exit(EXIT_FAILURE);
        }

        // Check if obstacle detected
        if (event.value == 0) {
            // Log self-parking sequence started message
            gettimeofday(&start_time, NULL);
            end_time = get_monotonic_time();
            snprintf(log_message, sizeof(log_message), "Self-parking sequence started at %s",
                     tv_secs_to_string(start_time.tv_sec));
            printf("%s\n", log_message);

            // Simulate routine completion
            sleep(5);

            // Log self-parking sequence completed message
            gettimeofday(&end_time, NULL);
            snprintf(log_message, sizeof(log_message), "Self-parking sequence completed at %s",
                     tv_secs_to_string(end_time.tv_sec));
            printf("%s\n", log_message);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up GPIO chip
    close(fd);
    return 0;
}

// SIGINT handler
void sigint_handler(int signum) {
    printf("Self-parking sequence completed\n");
    exit(EXIT_SUCCESS);
}

