#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <poll.h>

#include <gpiod/gpiod.h>
#include <pigpio.h>

#define KY032_GPIO_BASE 0x20200000
#define KY032_GPIO_PULL_UP_PIN 17
#define KY032_GPIO_PULL_DOWN_PIN 27

int main() {
    int fd;
    struct gpiod_event event;
    struct gpiod_event_attr attr;
    struct pollfd fds[1];
    struct timespec timeout;
    int ret;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetLinePolarity(KY032_GPIO_BASE, KY032_GPIO_PULL_UP_PIN, GPIO_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin for pull-up.\n");
        return 1;
    }

    if (gpioSetLinePolarity(KY032_GPIO_BASE, KY032_GPIO_PULL_DOWN_PIN, GPIO_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin for pull-down.\n");
        return 1;
    }

    // Open the bulk-read file descriptor
    fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/mem.\n");
        return 1;
    }

    // Set up the bulk-read file descriptor
    if (ioctl(fd, FBIOGET_BULK_ORIGIN, &attr) < 0) {
        fprintf(stderr, "Failed to get bulk-read origin.\n");
        return 1;
    }

    attr.size = GPIO_LINE_SIZE;
    if (ioctl(fd, FBIOGET_LINE_STATE, &attr) < 0) {
        fprintf(stderr, "Failed to get GPIO line state.\n");
        return 1;
    }

    // Set up the event structure
    event.type = GPIGPIO_EVENT_LINE;
    event.line = KY032_GPIO_BASE + KY032_GPIO_PULL_DOWN_PIN;
    event.value = GPIO_LINE_PULL_DOWN;
    event.flags = 0;

    // Set up the timeout for the bulk-read operation
    timeout.tv_sec = 0;
    timeout.tv_nsec = 100 * 1000 * 1000;

    // Poll for events
    while (1) {
        ret = poll(fds, 1, timeout.tv_sec * 1000 + timeout.tv_nsec);
        if (ret == -1) {
            fprintf(stderr, "Failed to poll.\n");
            return 1;
        }

        if (fds[0].revents & POLLIN) {
            // Read the data from the file descriptor
            if (read(fd, &event, sizeof(event)) < 0) {
                fprintf(stderr, "Failed to read from /dev/mem.\n");
                return 1;
            }

            // Check the active-low output
            if (event.value == GPIO_LINE_PULL_DOWN) {
                printf("Obstacle detected on line %d\n", KY032_GPIO_BASE + KY032_GPIO_PULL_DOWN_PIN);
            } else {
                printf("Path clear on line %d\n", KY032_GPIO_BASE + KY032_GPIO_PULL_DOWN_PIN);
            }
        }

        // Release the file descriptor
        if (close(fd) < 0) {
            fprintf(stderr, "Failed to close /dev/mem.\n");
            return 1;
        }
    }

    // Clean up GPIO
    gpioTerminate();

    return 0;
}

