#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <linux/i2c.h>

#define I2C_BUS_NUM 1
#define I2C_DEVICE_ADDR 0x6A

void i2c_init(void) {
    int i;
    for (i = 0; i < 10; i++) {
        if (i2c_check_functionality(I2C_BUS_NUM, I2C_DEVICE_ADDR) == -1) {
            fprintf(stderr, "Failed to check functionality: %s\n", i2c_errstr(i2c_check_functionality));
            exit(EXIT_FAILURE);
        }
        if (i2c_init() == -1) {
            fprintf(stderr, "Failed to initialize I2C bus: %s\n", i2c_errstr(i2c_init));
            exit(EXIT_FAILURE);
        }
        if (i2c_set_slave_address(I2C_BUS_NUM, I2C_DEVICE_ADDR) == -1) {
            fprintf(stderr, "Failed to set I2C slave address: %s\n", i2c_errstr(i2c_set_slave_address));
            exit(EXIT_FAILURE);
        }
    }
}

void i2c_cleanup(void) {
    if (i2c_exit() == -1) {
        fprintf(stderr, "Failed to exit I2C bus: %s\n", i2c_errstr(i2c_exit));
        exit(EXIT_FAILURE);
    }
}

int main(void) {
    int rc;
    int i;

    i2c_init();

    while (1) {
        struct i2c_msg msg[2];
        msg[0].addr = I2C_DEVICE_ADDR;
        msg[0].flags = 0;
        msg[1].addr = I2C_DEVICE_ADDR;
        msg[1].flags = 0;
        msg[1].len = 6;
        msg[1].buf = (void *)&i2c_msg_data[0];

        rc = i2c_transfer(I2C_BUS_NUM, 2, msg, 2);
        if (rc == -1) {
            fprintf(stderr, "Failed to transfer data: %s\n", i2c_errstr(rc));
            exit(EXIT_FAILURE);
        }

        for (i = 0; i < rc; i++) {
            printf("(%d, %d, %d, %d, %d, %d)\n",
                   msg[i].addr, msg[i].flags, msg[i].len,
                   msg[i].buf[0], msg[i].buf[1], msg[i].buf[2]);
        }
    }

    i2c_cleanup();

    return 0;
}

