        fprintf(stderr, "Failed to set SCL pin as output: %d\n", rc);
        return 1;
    }
    if ((rc = gpio_set_direction(SDA_PIN_NUM, GPIO_IN)) < 0) {
        fprintf(stderr, "Failed to set SDA pin as input: %d\n", rc);
        return 1;
    }

    // Open I2C bus
    if ((rc = i2c_open(I2C_BUS_NUM, I2C_CLIENT_ENDPOINT)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", rc);
        return 1;
    }

    // Confirm device presence
    if ((rc = i2c_read_byte(I2C_BUS_NUM, 0x1B, &i2c_data[0])) < 0) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", rc);
        return 1;
    }
    if (i2c_data[0] != 0xAA) {
        fprintf(stderr, "Device not found or not responding: expected 0xAA, got 0x%02X\n", i2c_data[0]);
        return 1;
    }

    // Initialize sensor
    if ((rc = i2c_write_byte(I2C_BUS_NUM, 0x32, 0x01)) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", rc);
        return 1;
    }

    // Initialize accelerometer data
    ax = ay = az = 0;

    // Initialize magnetometer data
    mx = my = mz = 0;

    // Loop to read data
    while (1) {
        // Read accelerometer data
        if ((rc = i2c_read_byte(I2C_BUS_NUM, 0x32, &i2c_data[0])) < 0) {
            fprintf(stderr, "Failed to read from I2C device: %d\n", rc);
            return 1;
        }
        ax = (i2c_data[0] << 8) | i2c_data[1];
        ay = (i2c_data[2] << 8) | i2c_data[3];
        az = (i2c_data[4] << 8) | i2c_data[5];

        // Read magnetometer data
        if ((rc = i2c_read_byte(I2C_BUS_NUM, 0x34, &i2c_data[0])) < 0) {
            fprintf(stderr, "Failed to read from I2C device: %d\n", rc);
            return 1;
        }
        mx = (i2c_data[0] << 8) | i2c_data[1];
        my = (i2c_data[2] << 8) | i2c_data[3];
        mz = (i2c_data[4] << 8) | i2c_data[5];

        // Print raw data to console
        printf("Accelerometer X: %d\n", ax);
        printf("Accelerometer Y: %d\n", ay);
        printf("Accelerometer Z: %d\n", az);
        printf("Magnetometer X: %d\n", mx);
        printf("Magnetometer Y: %d\n", my);
        printf("Magnetometer Z: %d\n", mz);

        // Wait for 100ms
        usleep(100000);
    }

    // Clean up resources
    gpio_set_mode(SCL_PIN_NUM, GPIO_OUTPUT);
    gpio_set_direction(SCL_PIN_NUM, GPIO_IN);
    gpio_set_mode(SDA_PIN_NUM, GPIO_INPUT);
    gpio_cleanup();

    return 0;
}
