#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpio/driver.h>

#define GPIO_BASE_ADDRESS 0x20  // Base address of GPIO controller
#define GPIO_NUM_DIGITAL 17       // GPIO17 for Door A
#define GPIO_NUM_DIGITAL 27       // GPIO27 for Door B

volatile sig_atomic_t sigint_handler_set = false;

int main() {
    int fd;
    int gpio_num_a = GPIO_NUM_DIGITAL;
    int gpio_num_b = GPIO_NUM_DIGITAL + 1;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_chip *gpio_chip;
    struct gpio_line *gpio_line_a, *gpio_line_b;
    char input_buffer[10];
    char *code = NULL;
    char access_log_filename[] = "access_log.txt";
    char access_log_content[20];
    char *log_message = NULL;
    int log_message_length = 0;
    int log_file_fd;

    // Initialize GPIO
    gpio_chip = gpio_init();
    if (!gpio_chip) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Open I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpio_exit(gpio_chip);
        return 1;
    }

    // Set up GPIO lines
    gpio_line_a = gpio_get_line(gpio_chip, gpio_num_digital, GPIO_DIR_OUT);
    gpio_line_b = gpio_get_line(gpio_chip, gpio_num_digital + 1, GPIO_DIR_OUT);

    // Generate a random 6-digit security code
    code = malloc(10 * sizeof(char));
    if (!code) {
        fprintf(stderr, "Failed to allocate memory for code\n");
        goto exit;
    }
    sprintf(code, "%06d", rand() % 100000);

    // Print the generated code to stdout
    printf("Generated code: %s\n", code);

    // Read user input
    printf("Enter the security code: ");
    fgets(input_buffer, sizeof(input_buffer), stdin);

    // Validate user input
    input_buffer[strcspn(input_buffer, "\n")][0] = '\0';
    if (sscanf(input_buffer, "%06d", code) != 1) {
        printf("Invalid input\n");
        free(code);
        code = NULL;
        goto exit;
    }

    // Check if the entered code matches the generated one
    if (strcmp(code, *code) != 0) {
        printf("Access denied\n");
        free(code);
        code = NULL;
        goto exit;
    }

    // Log the successful access
    log_message = malloc(20 * sizeof(char));
    if (!log_message) {
        fprintf(stderr, "Failed to allocate memory for log message\n");
        goto exit;
    }
    snprintf(log_message, 20, "Accessed successfully on %s\n", asctime(localtime(time(NULL))));
    log_message_length = strlen(log_message);

    // Open the access log file
    log_file_fd = open(access_log_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_file_fd < 0) {
        fprintf(stderr, "Failed to open access log file\n");
        goto exit;
    }

    // Write log message to the access log file
    if (write(log_file_fd, log_message, log_message_length) != log_message_length) {
        fprintf(stderr, "Failed to write to access log file\n");
        goto exit;
    }

    // Close the access log file
    if (close(log_file_fd) < 0) {
        fprintf(stderr, "Failed to close access log file\n");
        goto exit;
    }

exit:
    // Clean up GPIO lines
    gpio_line_a->gpio_line_value = GPIO_LINE_VALUE_LOW;
    gpio_line_b->gpio_line_value = GPIO_LINE_VALUE_LOW;
    gpio_exit(gpio_chip);
    free(code);
    return 0;
}

