#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x29

int main() {
    int fd;
    int i2c_fd;
    int gpio_fd;
    int ret;
    int i2c_addr = I2C_ADDR;
    char buffer[8];
    char log_file_name[] = "light_log.txt";
    struct timespec start_time, end_time;
    struct timespec start_time_prev, end_time_prev;
    int lux_value;
    char log_message[50];

    // Initialize GPIO, I2C, and pigpio
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (pi_open_sysfs() < 0) {
        fprintf(stderr, "Failed to open sysfs\n");
        return 1;
    }

    if (pi_set_mode(I2C_BUS_NUM, I2C_ADDR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C mode\n");
        return 1;
    }

    if (pi_set_speed(I2C_BUS_NUM, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C speed\n");
        return 1;
    }

    if (pi_open_i2c_device(I2C_BUS_NUM, I2C_ADDR, &i2c_fd) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (pi_set_mode(i2c_fd, PI_I2C) < 0) {
        fprintf(stderr, "Failed to set I2C mode\n");
        return 1;
    }

    if (pi_set_speed(i2c_fd, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C speed\n");
        return 1;
    }

    // Open log file
    if ((fd = open(log_file_name, O_CREAT | O_WRONLY | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Initialize I2C buffer
    if (pi_i2c_write(i2c_fd, &buffer, 1, &ret) < 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return 1;
    }

    // Wait for sensor to be ready
    if (pi_delay_ms(100) < 0) {
        fprintf(stderr, "Failed to wait for sensor to be ready\n");
        return 1;
    }

    // Read illuminance from the sensor
    if (pi_i2c_read(i2c_fd, buffer, 1, &ret) < 0) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return 1;
    }

    lux_value = buffer[0];

    // Log the reading
    sprintf(log_message, "Timestamp: %s, Lux: %d\n",
            ctime(&start_time.tv_sec), lux_value);
    if (write(fd, log_message, strlen(log_message)) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return 1;
    }

    // Calculate and log the difference between the current and previous readings
    if (pi_get_time_ns(&start_time_prev) < 0) {
        fprintf(stderr, "Failed to get start time\n");
        return 1;
    }

    if (pi_get_time_ns(&end_time) < 0) {
        fprintf(stderr, "Failed to get end time\n");
        return 1;
    }

    if (pi_get_time_ns(&start_time) > end_time.tv_nsec + 1000000) {
        fprintf(stderr, "Sensor took too long to read\n");
        return 1;
    }

    if (pi_get_time_ns(&end_time_prev) > start_time.tv_nsec + 1000000) {
        fprintf(stderr, "Sensor took too long to read\n");
        return 1;
    }

    if (pi_diff_time_ns(&start_time, &end_time) > 1000000) {
        fprintf(stderr, "Sensor took too long to read\n");
        return 1;
    }

    // Release resources
    pi_close(i2c_fd);
    pi_close(fd);
    gpio_deinit();
    pigpio_exit();

    return 0;
}

