```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_SCL_PIN 17
#define I2C_SDA_PIN 18

int main() {
    int fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg i2c_msgs[2];
    int ret;

    // Initialize I2C bus
    if (ioctl(I2C_BUS_NUM, I2C_SCL_PIN, I2C_I2C_MODE_SLAVE | I2C_I2C_NO_START_DELAY | I2C_I2C_NO_STOP_DELAY) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Initialize GPIO
    gpio_init();

    // Initialize PWM
    gpio_set_mode(17, GPIO_OUTPUT);

    // Initialize I2C file descriptor
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device file\n");
        return 1;
    }

    // Open I2C device file
    if (ioctl(fd, I2C_SLAVE, I2C_BUS_NUM) < 0) {
        fprintf(stderr, "Failed to set I2C device file as slave\n");
        return 1;
    }

    // Set I2C clock speed
    if (ioctl(fd, I2C_SCL_IOCTL, I2C_FREQ) < 0) {
        fprintf(stderr, "Failed to set I2C clock speed\n");
        return 1;
    }

    // Set I2C device address
    if (ioctl(fd, I2C_SLAVE, I2C_BUS_NUM) < 0) {
        fprintf(stderr, "Failed to set I2C device address\n");
        return 1;
    }

    // Set I2C timeout
    if (ioctl(fd, I2C_SCL_IOCTL, I2C_TIMEOUT) < 0) {
        fprintf(stderr, "Failed to set I2C timeout\n");
        return 1;
    }

    // Set I2C file descriptor to non-blocking mode
    if (fcntl(fd, F_SETFL, O_NONBLOCK) < 0) {
        fprintf(stderr, "Failed to set I2C file descriptor to non-blocking mode\n");
        return 1;
    }

    // Initialize magnetometer
    gpio_set_mode(I2C_SDA_PIN, GPIO_OUTPUT);
    gpio_set_mode(I2C_SCL_PIN, GPIO_OUTPUT);

    // Set I2C SDA and SCL pins
    gpio_output(I2C_SDA_PIN);
    gpio_output(I2C_SCL_PIN);

    // Set I2C speed
    gpio_set_speed(I2C_SDA_PIN, I2C_SPEED_100KHZ);
    gpio_set_speed(I2C_SCL_PIN, I2C_SPEED_100KHZ);

    // Set I2C device address
    if (ioctl(fd, I2C_SLAVE, I2C_BUS_NUM) < 0) {
        fprintf(stderr, "Failed to set I2C device address\n");
        return 1;
    }

    // Set I2C timeout
    if (ioctl(fd, I2C_SCL_IOCTL, I2C_TIMEOUT) < 0) {
        fprintf(stderr, "Failed to set I2C timeout\n");
        return 1;
    }

    // Set I2C file descriptor to non-blocking mode
    if (fcntl(fd, F_SETFL, O_NONBLOCK) < 0) {
        fprintf(stderr, "Failed to set I2C file descriptor to non-blocking mode\n");
        return 1;
    }

    // Initialize magnetometer
    gpio_set_mode(I2C_SDA_PIN, GPIO_OUTPUT);
    gpio_set_mode(I2C_SCL_PIN, GPIO_OUTPUT);

