```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x1E

// Constants
#define HMC5883L_ADDRESS 0x1E
#define HMC5883L_REG_X_MSB 0x1B
#define HMC5883L_REG_Y_MSB 0x1C
#define HMC5883L_REG_Z_MSB 0x1D
#define HMC5883L_REG_X_LSB 0x1A
#define HMC5883L_REG_Y_LSB 0x1B
#define HMC5883L_REG_Z_LSB 0x1C
#define HMC5883L_REG_FIFO_CTRL 0x1E
#define HMC5883L_REG_FIFO_DATA 0x20

// Function prototypes
void i2c_init();
void i2c_write(int fd, const uint8_t* data, int len);
void i2c_read(int fd, uint8_t* data, int len);
void i2c_read_register(int fd, uint8_t reg, uint8_t* data);
void i2c_write_register(int fd, uint8_t reg, uint8_t data);
void compute_hard_iron_offsets(uint8_t* raw_data);
void apply_offsets(uint8_t* raw_data, uint8_t* offset_data);
void print_offsets(uint8_t* offset_data);

int main(int argc, char* argv[]) {
    int i2c_fd;
    uint8_t raw_data[3];
    uint8_t offset_data[3];
    uint8_t reg_data[2];
    uint8_t reg_mask = 0x03;
    int offset_count = 0;
    int i, j;

    // Initialize I2C
    i2c_init();

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        return 1;
    }

    // Initialize magnetometer
    if (i2c_write(i2c_fd, &HMC5883L_ADDRESS, 1) < 0) {
        fprintf(stderr, "Failed to write to HMC5883L: %s\n", strerror(errno));
        return 1;
    }

    // Initialize raw data
    for (i = 0; i < 3; i++) {
        raw_data[i] = 0;
    }

    // Initialize offset data
    for (i = 0; i < 3; i++) {
        offset_data[i] = 0;
    }

    // Initialize offset count
    offset_count = 0;

    // Main loop
    while (true) {
        // Read raw data
        if (i2c_read(i2c_fd, raw_data, 3) < 0) {
            fprintf(stderr, "Failed to read raw data: %s\n", strerror(errno));
            break;
        }

        // Compute hard-iron offsets
        compute_hard_iron_offsets(raw_data);

        // Apply offsets
        apply_offsets(raw_data, offset_data);

        // Print offset-corrected X, Y, and Z components
        printf("Offset-corrected X: %d\n", offset_data[0]);
        printf("Offset-corrected Y: %d\n", offset_data[1]);
        printf("Offset-corrected Z: %d\n", offset_data[2]);

        // Sleep for 500 ms
