#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_BASE 0x20200000
#define GPIO_LEN  0x1000

int main()
{
    int fd, gpio_fd;
    int ret;

    // Initialize GPIO
    if (gpio_init() < 0)
    {
        fprintf(stderr, "Error: Failed to initialize GPIO\n");
        return 1;
    }

    // Open GPIO file descriptor
    fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (fd < 0)
    {
        fprintf(stderr, "Error: Failed to open GPIO file descriptor\n");
        return 1;
    }

    gpio_fd = (int)fd;

    // Set both lines LOW
    gpio_set_level(GPIO_BASE + GPIO_LED1, 0);
    gpio_set_level(GPIO_BASE + GPIO_LED2, 0);

    // Set up SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1)
    {
        // Switch active line with a 500 ms delay
        nanosleep(NULL, NULL, NULL, 500 * 1000);

        // Check for errors in GPIO library calls
        ret = pigpio_check_errors();
        if (ret != 0)
        {
            fprintf(stderr, "Error: pigpio library call failed with error code %d\n", ret);
            return 1;
        }

        // Release both lines
        gpio_set_level(GPIO_BASE + GPIO_LED1, 0);
        gpio_set_level(GPIO_BASE + GPIO_LED2, 0);

        // Free driver library resources
        gpio_exit();
    }

    return 0;
}

// SIGINT/SIGTERM handler
void sigint_handler(int signum)
{
    gpio_set_level(GPIO_BASE + GPIO_LED1, 0);
    gpio_set_level(GPIO_BASE + GPIO_LED2, 0);
    gpio_exit();
}

// SIGTERM handler
void sigterm_handler(int signum)
{
    gpio_set_level(GPIO_BASE + GPIO_LED1, 0);
    gpio_set_level(GPIO_BASE + GPIO_LED2, 0);
    gpio_exit();
}

