        // Check if the PIR signal has been HIGH for more than 10 seconds
        if (relays_on == 1 && (get_time_ms() - end_time.tv_sec) >= 10000) {
            syslog(LOG_WARNING, "PIR signal has been HIGH for more than 10 seconds");
            log_shutdown_count++;
            relays_off = 1;
        }

        // Check if the PIR signal has been HIGH for more than 10 seconds
        if (relays_on == 1 && (get_time_ms() - start_time.tv_sec) >= 20000) {
            syslog(LOG_WARNING, "PIR signal has been HIGH for more than 20 seconds");
            log_warning_count++;
            relays_off = 1;
        }

        // Check if the PIR signal has been HIGH for more than 10 seconds
        if (relays_on == 1 && (get_time_ms() - end_time.tv_sec) >= 30000) {
            syslog(LOG_WARNING, "PIR signal has been HIGH for more than 30 seconds");
            log_shutdown_count++;
            relays_off = 1;
        }

        // Check if the PIR signal has been HIGH for more than 10 seconds
        if (relays_on == 1 && (get_time_ms() - start_time.tv_sec) >= 40000) {
            syslog(LOG_WARNING, "PIR signal has been HIGH for more than 40 seconds");
            log_warning_count++;
            relays_off = 1;
        }

        // Check if the PIR signal has been HIGH for more than 10 seconds
        if (relays_on == 1 && (get_time_ms() - end_time.tv_sec) >= 50000) {
            syslog(LOG_WARNING, "PIR signal has been HIGH for more than 50 seconds");
            log_shutdown_count++;
            relays_off = 1;
        }

        // Release the relay
        gpio_set_level(gpio_fd, 0);
        usleep(1000); // Wait for 1 second
        gpio_set_level(gpio_fd, 1);
        usleep(1000); // Wait for 1 second

        // Log the relay state
        if (relays_on == 1) {
            syslog(LOG_INFO, "Relay is on");
        } else {
            syslog(LOG_INFO, "Relay is off");
        }

        // Release the GPIO lines
        gpio_release(gpio_fd);
        gpio_release(gpio_fd);

        // Release the chip
        gpio_exit();

        // Wait for a short period before polling again
        sleep(1);
    }

    return 0;
}

