#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>

#define RELAY_GPIO_4  4
#define RELAY_GPIO_17 17
#define RELAY_GPIO_27 27
#define RELAY_GPIO_22 22

volatile sig_atomic_t stop = 0;

void irrigate(int relay) {
    gpio_set_level(relay, 1);
    usleep(300000);
    gpio_set_level(relay, 0);
    usleep(600000);
}

void activate_relay(int relay) {
    if (gpio_request_from_sysfs(relay) < 0) {
        perror("Failed to request GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_level(relay, 1) < 0) {
        perror("Failed to set relay to HIGH");
        exit(EXIT_FAILURE);
    }

    usleep(300000);
}

void deactivate_relay(int relay) {
    if (gpio_request_from_sysfs(relay) < 0) {
        perror("Failed to request GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_level(relay, 0) < 0) {
        perror("Failed to set relay to LOW");
        exit(EXIT_FAILURE);
    }

    usleep(300000);
}

int main() {
    int relays[] = {RELAY_GPIO_4, RELAY_GPIO_17, RELAY_GPIO_27, RELAY_GPIO_22};
    int num_relays = sizeof(relays) / sizeof(relays[0]);

    int timer_fd;
    struct itimerspec timer_value;
    struct sigaction sa;

    if ((timer_fd = timer_create(CLOCK_MONOTONIC, 0, &timer_value)) < 0) {
        perror("Failed to create timer");
        exit(EXIT_FAILURE);
    }

    if (timer_settime(timer_fd, 0, &timer_value, NULL) < 0) {
        perror("Failed to set timer");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        exit(EXIT_FAILURE);
    }

    if (syslog(LOG_INFO, "Starting irrigation system...") < 0) {
        perror("Failed to log to syslog");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_relays; i++) {
        activate_relay(relays[i]);
        usleep(1000);
    }

    while (!stop) {
        usleep(1000);
    }

    deactivate_relay(relays[0]);
    deactivate_relay(relays[1]);
    deactivate_relay(relays[2]);
    deactivate_relay(relays[3]);

    if (timer_delete(timer_fd) < 0) {
        perror("Failed to delete timer");
        exit(EXIT_FAILURE);
    }

    syslog(LOG_INFO, "Irrigation system stopped.");

    return 0;
}

