#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68
#define BUFFER_SIZE 1024

static int gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }
    return 0;
}

static int i2c_init() {
    int fd;
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(fd);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        close(fd);
        gpioTerminate();
        return -1;
    }

    if (gpioOpenPin(GPIO_OUTPUT_DIGITAL) < 0) {
        fprintf(stderr, "Failed to open GPIO output\n");
        close(fd);
        gpioTerminate();
        return -1;
    }

    gpioSetPwmFrequency(GPIO_PWM_CHANNEL_0, 100);
    gpioSetPwmRange(GPIO_PWM_CHANNEL_0, 0, 255);
    gpioSetPwmPeriod(GPIO_PWM_CHANNEL_0, BUFFER_SIZE);

    gpioSetPwmDuty(GPIO_PWM_CHANNEL_0, 0);

    gpioClosePin(GPIO_PWM_CHANNEL_0);

    return 0;
}

static void i2c_read_write(int fd, uint8_t* data, int size) {
    if (ioctl(fd, I2C_RDWR, 0) < 0) {
        fprintf(stderr, "Failed to enter I2C mode\n");
        return;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return;
    }

    if (write(fd, data, size) != size) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return;
    }

    if (read(fd, data, size) != size) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return;
    }

    if (ioctl(fd, I2C_RDWR, 0) < 0) {
        fprintf(stderr, "Failed to leave I2C mode\n");
        return;
    }
}

static void i2c_read_write_buffer(int fd, uint8_t* data, int size) {
    while (1) {
        uint8_t buffer[BUFFER_SIZE];
        int bytes_read;

        if (read(fd, buffer, BUFFER_SIZE) != BUFFER_SIZE) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        for (int i = 0; i < BUFFER_SIZE; i++) {
            data[i] = buffer[i];
        }
    }
}

static void cleanup_resources() {
    gpioTerminate();
    close(gpio_fd);
}

static void handle_sigint(int signum) {
    fprintf(stderr, "Received SIGINT\n");
    cleanup_resources();
    exit(0);
}

