    struct i2c_rdwr_ioctl_data_t i2c_data;
    struct timespec start_time, stop_time;
    struct sigaction sa;

    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        gpio_cleanup();
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        i2c_cleanup();
        gpio_cleanup();
        return -1;
    }

    if (gpioSetMode(GPIO_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        i2c_cleanup();
        gpio_cleanup();
        return -1;
    }

    if (gpioOpenPin(GPIO_OUTPUT_DIGITAL) < 0) {
        fprintf(stderr, "Failed to open GPIO output\n");
        i2c_cleanup();
        gpio_cleanup();
        return -1;
    }

    gpioSetPwmFrequency(GPIO_PWM_CHANNEL_0, 100);
    gpioSetPwmRange(GPIO_PWM_CHANNEL_0, 0, 255);
    gpioSetPwmPeriod(GPIO_PWM_CHANNEL_0, BUFFER_SIZE);

    gpioSetPwmDuty(GPIO_PWM_CHANNEL_0, 0);

    gpioClosePin(GPIO_PWM_CHANNEL_0);

