#include <linux/input.h>

#include <gpiod.h>
#include <pigpio.h>

#define RELAY_PIN 27
#define SOUND_SENSOR_PIN 17
#define RELAY_ACTIVE_TIMEOUT 3000 // 3 seconds
#define RELAY_INACTIVE_TIMEOUT 1000 // 1 second

int main() {
    int relay_fd;
    int sound_sensor_fd;
    struct gpiod_event event;
    struct gpiod_event_data data;
    struct timespec start_time, end_time;
    int ret;

    // Initialize GPIOs
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO.\n");
        return 1;
    }

    // Open GPIOs
    relay_fd = gpioOpen(RELAY_PIN);
    if (relay_fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO %d.\n", RELAY_PIN);
        return 1;
    }

    sound_sensor_fd = gpioOpen(SOUND_SENSOR_PIN);
    if (sound_sensor_fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO %d.\n", SOUND_SENSOR_PIN);
        gpioClose(relay_fd);
        return 1;
    }

    // Set up debounce/cooldown mechanism
    gpioSetDirection(sound_sensor_fd, GPIO_IN);
    gpioClear(sound_sensor_fd);
    gpioWaitForEvent(sound_sensor_fd, &event, GPIO_IN_EDGE_FALLING);
    while (event.type == GPIO_EVENT_TYPE_FALLING) {
        gpioClear(sound_sensor_fd);
        gpioWaitForEvent(sound_sensor_fd, &event, GPIO_IN_EDGE_FALLING);
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Main loop
    while (1) {
        // Read the sensor data
        if (gpioRead(sound_sensor_fd) == 0) {
            // No sound detected, do nothing
            usleep(RELAY_INACTIVE_TIMEOUT * 1000);
        } else {
            // Sound detected, activate the relay
            gpioSet(relay_fd, GPIO_OUTPUT_HIGH);
            usleep(RELAY_ACTIVE_TIMEOUT * 1000);
            gpioSet(relay_fd, GPIO_OUTPUT_LOW);

            // Log the activation timestamp
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            FILE *fp = fopen("alarm_log.txt", "a");
            if (fp) {
                fprintf(fp, "%s\n", ctime(&now.tv_sec));
                fclose(fp);
            }

            // Wait for the relay to deactivate
            gpioWaitForEvent(relay_fd, &event, GPIO_IN_EDGE_RISING);
            while (event.type == GPIO_EVENT_TYPE_RISING) {
                usleep(RELAY_INACTIVE_TIMEOUT * 1000);
                gpioWaitForEvent(relay_fd, &event, GPIO_IN_EDGE_RISING);
            }
        }

        // Wait for a short interval before polling again
        usleep(100 * 1000);
    }

    // Clean up GPIOs
    gpioClose(relay_fd);
    gpioClose(sound_sensor_fd);
    gpioUninitialize();

    return 0;
