#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>

#include <pigpio.h>

#define MH_Z19B_COMMAND_LENGTH 9
#define CO2_LOG_FILENAME "co2_log.json"
#define ERROR_LOG_FILENAME "co2_error.log"

int main() {
    int fd;
    int ret;
    int timeout_ms = 100;
    int retry_count = 0;
    int sample_interval_ms = 5000;
    int sample_count = 0;
    int sample_index = 0;
    uint16_t ppm;
    uint8_t error_flag;
    char co2_log_file[128];
    char error_log_file[128];
    char co2_log_data[MH_Z19B_COMMAND_LENGTH + 1];
    char error_log_data[MH_Z19B_COMMAND_LENGTH + 1];
    struct timespec start_time, end_time;
    struct timespec timeout_start, timeout_end;
    struct timespec last_sample_time;
    int exit_code;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library\n");
        return 1;
    }

    // Open UART device
    fd = open("/dev/serial0", O_RDWR | O_NOCTTY);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open UART device\n");
        gpioTerminate();
        return 1;
    }

    // Set UART parameters
    if (ioctl(fd, TIOCMGET, &ret) < 0) {
