#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x29

int main() {
    int relays[3] = {17, 27, 22};
    int relays_state[3] = {0, 0, 0};
    int i;

    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (i2cInit() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    // Open I2C file descriptor
    int i2c_fd = i2cOpen(I2C_BUS_NUM);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C file descriptor\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("lighting_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open logging file\n");
        return 1;
    }

    // Initialize the BH1750 sensor
    if (gpioSetMode(relays[0], GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as output\n");
        return 1;
    }

    if (gpioSetMode(relays[1], GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 27 as output\n");
        return 1;
    }

    if (gpioSetMode(relays[2], GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 22 as output\n");
        return 1;
    }

    if (gpioSetValue(relays[0], 0) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 to low\n");
        return 1;
    }

    if (gpioSetValue(relays[1], 0) < 0) {
        fprintf(stderr, "Failed to set GPIO 27 to low\n");
        return 1;
    }

    if (gpioSetValue(relays[2], 0) < 0) {
        fprintf(stderr, "Failed to set GPIO 22 to low\n");
        return 1;
    }

    // Continuously read and log the ambient light level
    while (1) {
        // Wait at least 120 ms after each conversion
        gpioDelay(120);

        // Read the ambient light level from the sensor
        int lux = gpioGetSensorValue(I2C_ADDR, I2C_ADDR);

        // Check if the sensor is absent
        if (lux == 0) {
            fprintf(stderr, "Sensor is absent\n");
            continue;
        }

        // Check the states of the relays
        for (i = 0; i < 3; i++) {
            if (relays_state[i] == 0 && lux >= 50) {
                gpioSetValue(relays[i], 1);
            } else if (relays_state[i] == 1 && lux >= 50 && lux < 150) {
                gpioSetValue(relays[i], 1);
            } else if (relays_state[i] == 2 && lux >= 150 && lux < 300) {
                gpioSetValue(relays[i], 1);
            } else if (relays_state[i] == 3 && lux >= 300) {
                gpioSetValue(relays[i], 1);
            }
        }

        // Log the current timestamp, lux value, and relay states
        char timestamp[80];
        time_t now = time(NULL);
        struct tm *ltm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", ltm);
        fprintf(log_file, "Timestamp: %s, Lux: %d, Relay States: ", timestamp, lux);
        for (i = 0; i < 3; i++) {
            if (relays_state[i] == 1) {
                fprintf(log_file, "1 ");
            } else if (relays_state[i] == 2) {
                fprintf(log_file, "2 ");
            } else if (relays_state[i] == 3) {
                fprintf(log_file, "3 ");
            }
        }
        fprintf(log_file, "\n");

        // Release resources
        gpioRelease(relays[0]);
        gpioRelease(relays[1]);
        gpioRelease(relays[2]);
        gpioClose(i2c_fd);
        i2cClose();
        gpioFinalise();
    }

    return 0;
}

