#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <pigpio.h>

#define DRIVER_NAME "gpiochip0"
#define GPIO_BASE_ADDRESS 0x20012000

int main(int argc, char *argv[]) {
    int rc;
    int motorA_gpio_pin = 17;
    int motorB_gpio_pin = 22;
    int motorA_pwm_pin = 23;
    int motorB_pwm_pin = 18;
    int ultrasonic_distance_threshold = 50;
    int ultrasonic_distance_range = 10;

    if (argc != 4) {
        printf("Usage: %s <distance_threshold_cm> <distance_range_cm> <ultrasonic_pin>\n", argv[0]);
        return 1;
    }

    if (sscanf(argv[1], "%d", &ultrasonic_distance_threshold) != 1 ||
        sscanf(argv[2], "%d", &ultrasonic_distance_range) != 1 ||
        sscanf(argv[3], "%d", &motorA_pwm_pin) != 1 ||
        sscanf(argv[3], "%d", &motorB_pwm_pin) != 1) {
        printf("Invalid input format. Usage: %s <distance_threshold_cm> <distance_range_cm> <ultrasonic_pin>\n", argv[0]);
        return 1;
    }

    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO.\n");
        return 1;
    }

    gpioSetMode(motorA_pwm_pin, PI_OUTPUT);
    gpioSetMode(motorB_pwm_pin, PI_OUTPUT);

    gpioSetValue(motorA_pwm_pin, 0);
    gpioSetValue(motorB_pwm_pin, 0);

    gpioSetPWMfrequency(motorA_pwm_pin, 100);
    gpioSetPWMrange(motorA_pwm_pin, 256);
    gpioSetPWM(motorA_pwm_pin, 0, 255);

    gpioSetPWMfrequency(motorB_pwm_pin, 100);
    gpioSetPWMrange(motorB_pwm_pin, 256);
    gpioSetPWM(motorB_pwm_pin, 0, 255);

    while (1) {
        int ultrasonic_distance = getUltrasonicDistance();

        if (ultrasonic_distance < ultrasonic_distance_threshold) {
            gpioSetValue(motorA_pwm_pin, 0);
            gpioSetValue(motorB_pwm_pin, 0);
            gpioSetPWM(motorA_pwm_pin, ultrasonic_distance * (255 / (ultrasonic_distance_range - ultrasonic_distance_threshold)), 0);
            gpioSetPWM(motorB_pwm_pin, ultrasonic_distance * (255 / (ultrasonic_distance_range - ultrasonic_distance_threshold)), 0);
        } else {
            gpioSetValue(motorA_pwm_pin, 1);
            gpioSetValue(motorB_pwm_pin, 1);
            gpioSetPWM(motorA_pwm_pin, 0, 0);
            gpioSetPWM(motorB_pwm_pin, 0, 0);
        }

        gpioDelay(100);
    }

    gpioTerminate();
    return 0;
}

