#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/pigpio.h>

#define LED_RED 17
#define LED_GREEN 22
#define LED_BLUE 27

int main() {
    int fd, gpioHandle;
    int proximityValue = 0;
    int pwmFreq = 1000;
    int pwmPeriod = 1;
    int pwmValue = 0;

    // Initialize GPIO and PWM
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioHandle = pigpio_open(0);
    if (gpioHandle < 0) {
        fprintf(stderr, "Failed to open GPIO\n");
        return 1;
    }

    if (gpioSetMode(gpioHandle, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    if (gpioSetBrightness(gpioHandle, 255) < 0) {
        fprintf(stderr, "Failed to set LED brightness\n");
        return 1;
    }

    if (gpioAttach(gpioHandle, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to attach GPIO\n");
        return 1;
    }

    // Set up PWM
    if (gpioSetPWMfrequency(gpioHandle, pwmFreq) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    if (gpioSetPWMperiod(gpioHandle, pwmPeriod) < 0) {
        fprintf(stderr, "Failed to set PWM period\n");
        return 1;
    }

    if (gpioSetPWMvalue(gpioHandle, pwmValue) < 0) {
        fprintf(stderr, "Failed to set PWM value\n");
        return 1;
    }

    // Generate color transition
    while (1) {
        proximityValue = (int)(0.5 + 0.5 * sin(proximityValue * M_PI / 0.5));
        pwmValue = (int)(proximityValue * 255);

        if (gpioSetPWMvalue(gpioHandle, pwmValue) < 0) {
            fprintf(stderr, "Failed to set PWM value\n");
            return 1;
        }

        usleep(pwmPeriod * 1000);
    }

    // Release resources
    gpioDetach(gpioHandle);
    pigpio_close(gpioHandle);

    return 0;
}

