    // Set I2C interrupt mode to I2C_INT_DATA
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_INT_DATA) == -1) {
        perror("Error setting I2C interrupt mode");
        exit(EXIT_FAILURE);
    }

    // Set I2C interrupt handler
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_INT_EDGE_FALLING) == -1) {
        perror("Error setting I2C interrupt handler");
        exit(EXIT_FAILURE);
    }

    // Set I2C interrupt priority to 0
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_PRIO_0) == -1) {
        perror("Error setting I2C interrupt priority");
        exit(EXIT_FAILURE);
    }

    // Set I2C interrupt handler function
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_INT_EDGE_FALLING) == -1) {
        perror("Error setting I2C interrupt handler function");
        exit(EXIT_FAILURE);
    }

    // Set I2C interrupt handler function arguments
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_INT_EDGE_FALLING, (void *)handle_interrupt) == -1) {
        perror("Error setting I2C interrupt handler function arguments");
        exit(EXIT_FAILURE);
    }

    // Start I2C transfer
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_START) == -1) {
        perror("Error starting I2C transfer");
        exit(EXIT_FAILURE);
    }

    // Wait for sensor data
    while (1) {
        // Read sensor data
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_RDWR, &i2c_msgs[0]) == -1) {
            perror("Error reading sensor data");
            exit(EXIT_FAILURE);
        }

        // Check if sensor data is available
        if (i2c_msgs[0].len == 0) {
            continue;
        }

        // Read sensor data
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_RDWR, &i2c_msgs[1]) == -1) {
            perror("Error reading sensor data");
            exit(EXIT_FAILURE);
        }

        // Check if sensor data is available
        if (i2c_msgs[1].len == 0) {
            continue;
        }

        // Convert sensor data to degrees per second
        float x_axis_degrees_per_second = (float)i2c_msgs[1].buf[0] * 180.0 / I2C_RES_FREQ;
        float y_axis_degrees_per_second = (float)i2c_msgs[1].buf[1] * 180.0 / I2C_RES_FREQ;
        float z_axis_degrees_per_second = (float)i2c_msgs[1].buf[2] * 180.0 / I2C_RES_FREQ;

        // Append timestamp and sensor values to file
        if (write(file_fd, "timestamp,x,y,z\n", 13) == -1) {
            perror("Error writing to file");
            exit(EXIT_FAILURE);
        }

        // Append sensor values to file
        if (write(file_fd, &x_axis_degrees_per_second, sizeof(x_axis_degrees_per_second)) == -1) {
            perror("Error writing to file");
            exit(EXIT_FAILURE);
        }

        if (write(file_fd, &y_axis_degrees_per_second, sizeof(y_axis_degrees_per_second)) == -1) {
            perror("Error writing to file");
            exit(EXIT_FAILURE);
        }

        if (write(file_fd, &z_axis_degrees_per_second, sizeof(z_axis_degrees_per_second)) == -1) {
            perror("Error writing to file");
            exit(EXIT_FAILURE);
        }

        // Wait for next sensor data
        usleep(100000);
    }

    // Stop I2C transfer
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_STOP) == -1) {
        perror("Error stopping I2C transfer");
        exit(EXIT_FAILURE);
    }

    // Close file descriptors
    close(file_fd);

    // Cleanly close I2C bus
    if (close(i2c_fd) == -1) {
        perror("Error closing I2C bus");
        exit(EXIT_FAILURE);
    }

    return 0;
}
