#define PI_GPIO_BASE_ADDRESS 0x20013000
#define PI_PWM_BASE_ADDRESS 0x20013100

volatile bool melody_playing = false;
volatile bool melody_paused = false;
volatile bool melody_stopped = false;

void handle_signal(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, stopping the melody...\n");
        melody_stopped = true;
    } else if (signum == SIGTERM) {
        printf("Received SIGTERM, stopping the melody...\n");
        melody_stopped = true;
    }
}

void play_melody(const uint8_t* melody, int melody_length) {
    gpio_set_mode(PI_GPIO_BASE_ADDRESS + 17, GPIO_OUTPUT);
    gpio_set_dir(PI_GPIO_BASE_ADDRESS + 17, GPIO_OUTPUT);

    for (int i = 0; i < melody_length; i++) {
        gpio_set_level(PI_GPIO_BASE_ADDRESS + 17, melody[i] ? 1 : 0);
        gpio_delay_usec(50);
    }

    gpio_set_level(PI_GPIO_BASE_ADDRESS + 17, 0);
}

void stop_melody() {
    melody_paused = true;
    while (!melody_stopped) {
        gpio_delay_usec(50);
    }
}

