    gpio_set_mode(PI_PWM_BASE_ADDRESS + pwm_channel, GPIO_OUTPUT);
    gpio_set_dir(PI_PWM_BASE_ADDRESS + pwm_channel, GPIO_OUTPUT);

    gpio_set_level(PI_PWM_BASE_ADDRESS + pwm_channel, duty_cycle);
}

