    gpio_add_event_detect(PI_GPIO_BASE_ADDRESS + 17, GPIO_ANY_EDGE, GPIO_FALLING, handle_signal);

    gpio_set_mode(PI_PWM_BASE_ADDRESS + pwm_channel, GPIO_OUTPUT);
    gpio_set_dir(PI_PWM_BASE_ADDRESS + pwm_channel, GPIO_OUTPUT);

    gpio_set_level(PI_PWM_BASE_ADDRESS + pwm_channel, 0);

    while (true) {
        if (melody_playing) {
