#include <pigpio.h>

#define I2C_ADDRESS 0x1A
#define I2C_SDA_PIN 3
#define I2C_SCL_PIN 5

int main() {
    int i2c_fd;
    int gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_direction_ioctl_data gpio_data;
    char *log_file = "mag_log.csv";
    char heading_direction[8] = {'N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'};
    char heading_direction_str[9] = {'N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW', ' '};

    // Initialize I2C and GPIO
