        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    // Open I2C file descriptor
    if ((i2c_fd = i2c_open_device("/dev/i2c-1", I2C_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

