    gpio_set_mode(I2C_SDA_PIN, GPIO_OUTPUT);
    gpio_set_mode(I2C_SCL_PIN, GPIO_OUTPUT);

    // Set the I2C device address
    if (ioctl(i2c_fd, I2C_RDWR, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C device address\n");
        return 1;
