#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpio/driver.h>

#define L293D_IN1_PIN    4
#define L293D_IN2_PIN    17
#define L293D_IN3_PIN    27
#define L293D_IN4_PIN    22
#define LOCK_BUTTON_PIN  24
#define UNLOCK_BUTTON_PIN 23
#define INTER_STEP_DELAY  3

int gpio_open(int file_num, int direction);
void gpio_close(int file_num);
int gpio_read(int file_num);
void gpio_write(int file_num, int value);

int main() {
    int file_num;
    int direction;
    int lock_button_pin = LOCK_BUTTON_PIN;
    int unlock_button_pin = UNLOCK_BUTTON_PIN;
    int door_locked = 0;

    file_num = gpio_open(L293D_IN1_PIN, GPIO_OUTPUT);
    if (file_num < 0) {
        fprintf(stderr, "Failed to open GPIO file\n");
        return 1;
    }

    direction = GPIO_OUT;
    gpio_write(file_num, direction);

    file_num = gpio_open(L293D_IN2_PIN, GPIO_OUTPUT);
    if (file_num < 0) {
        fprintf(stderr, "Failed to open GPIO file\n");
        gpio_close(file_num);
        return 1;
    }

    direction = GPIO_OUT;
    gpio_write(file_num, direction);

    file_num = gpio_open(L293D_IN3_PIN, GPIO_OUTPUT);
    if (file_num < 0) {
        fprintf(stderr, "Failed to open GPIO file\n");
        gpio_close(file_num);
        gpio_close(file_num);
        return 1;
    }

    direction = GPIO_OUT;
    gpio_write(file_num, direction);

    file_num = gpio_open(L293D_IN4_PIN, GPIO_OUTPUT);
    if (file_num < 0) {
        fprintf(stderr, "Failed to open GPIO file\n");
        gpio_close(file_num);
        gpio_close(file_num);
        gpio_close(file_num);
        return 1;
    }

    direction = GPIO_OUT;
    gpio_write(file_num, direction);

    gpio_close(file_num);

    while (1) {
        int button_pressed = gpio_read(lock_button_pin);
        if (button_pressed) {
            door_locked = 1;
            gpio_write(file_num, GPIO_HIGH);
            gpio_write(file_num, GPIO_LOW);
            gpio_write(unlock_button_pin, GPIO_HIGH);
            gpio_write(unlock_button_pin, GPIO_LOW);
            printf("Door locked\n");
        } else {
            gpio_write(file_num, GPIO_LOW);
            gpio_write(file_num, GPIO_HIGH);
            gpio_write(unlock_button_pin, GPIO_HIGH);
            gpio_write(unlock_button_pin, GPIO_LOW);
            printf("Door unlocked\n");
        }

        usleep(INTER_STEP_DELAY * 1000);
    }

    gpio_close(file_num);
    return 0;
}

int gpio_open(int file_num, int direction) {
    int fd;
    struct gpio_fops *fops;

    fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO file\n");
        return -1;
    }

    fops = gpiochip_fops_open(fd);
    if (fops == NULL) {
        fprintf(stderr, "Failed to open GPIO file\n");
        return -1;
    }

    if (ioctl(fd, GPIO_GET_LINE, &file_num) < 0) {
        fprintf(stderr, "Failed to get GPIO file number\n");
        return -1;
    }

    if (direction == GPIO_IN) {
        if (ioctl(fd, GPIO_GET_IN, &file_num) < 0) {
            fprintf(stderr, "Failed to get GPIO input\n");
            return -1;
        }
    } else {
        if (ioctl(fd, GPIO_GET_OUT, &file_num) < 0) {
            fprintf(stderr, "Failed to get GPIO output\n");
            return -1;
        }
    }

    fops->open(fops, file_num);

    return file_num;
}

void gpio_close(int file_num) {
    struct gpio_fops *fops;

    fops = gpiochip_fops_open(file_num);
    if (fops == NULL) {
        return;
    }

    fops->close(fops, file_num);
}

int gpio_read(int file_num) {
    int value;

    if (ioctl(file_num, GPIO_GET_LINE, &file_num) < 0) {
        fprintf(stderr, "Failed to get GPIO input\n");
        return -1;
    }

    value = (file_num >> file_num) & 1;

    return value;
}

void gpio_write(int file_num, int value) {
    if (ioctl(file_num, GPIO_SET_LINE, &file_num) < 0) {
        fprintf(stderr, "Failed to set GPIO output\n");
        return;
    }

    if (value) {
        if (ioctl(file_num, GPIO_SET_OUT, &file_num) < 0) {
            fprintf(stderr, "Failed to set GPIO output\n");
            return;
        }
    } else {
        if (ioctl(file_num, GPIO_SET_IN, &file_num) < 0) {
            fprintf(stderr, "Failed to set GPIO input\n");
            return;
        }
    }
}

