#define RELAY_MODULES_NAME "relay17"
#define RELAY_MODULES_PATH RELAY_MODULES_FILE "/"

int main() {
    int chip, relays[4];
    struct gpiod_chip_info chip_info;
    int relays_fd, relays_fd_count;
    struct gpiod_line_info line_info;
    int i, rc;

    // Initialize GPIO and relays
    chip = gpiod_init(GPIO_FILE, &chip_info);
    if (chip < 0) {
        fprintf(stderr, "Failed to initialize GPIO chip: %s\n", gpiod_strerror(chip));
        return 1;
    }

    relays[0] = gpiod_request_line(chip, RELAY_MODULES_PATH " " RELAY_MODULES_NAME " " 17, &line_info);
    relays[1] = gpiod_request_line(chip, RELAY_MODULES_PATH " " RELAY_MODULES_NAME " " 18, &line_info);
    relays[2] = gpiod_request_line(chip, RELAY_MODULES_PATH " " RELAY_MODULES_NAME " " 27, &line_info);
    relays[3] = gpiod_request_line(chip, RELAY_MODULES_PATH " " RELAY_MODULES_NAME " " 22, &line_info);

    if (relays[0] < 0 || relays[1] < 0 || relays[2] < 0 || relays[3] < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", gpiod_strerror(relays[0]));
        gpiod_release_lines(chip, relays, 4);
        return 1;
    }

    // Set all lines HIGH (inactive) at startup
    for (i = 0; i < 4; i++) {
        if (gpiod_set_line_level(chip, relays[i], 1) < 0) {
            fprintf(stderr, "Failed to set GPIO line %d HIGH: %s\n", i + 1, gpiod_strerror(relays[i]));
            gpiod_release_lines(chip, relays, 4);
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Sleep for 60 seconds
        sleep(60);

        // Activate each relay for 5 seconds
        for (i = 0; i < 4; i++) {
            if (gpiod_set_line_level(chip, relays[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO line %d LOW: %s\n", i + 1, gpiod_strerror(relays[i]));
                gpiod_release_lines(chip, relays, 4);
                return 1;
            }
            usleep(5000 * 1000); // 5 seconds
        }

        // Wait for 86,400 seconds (24 hours)
        sleep(86400);
    }

    // Release GPIO lines and close the chip
    gpiod_release_lines(chip, relays, 4);
    gpiod_release(chip);

    return 0;
}

