#define MPU_6050_SPI_MODE_0 0x00
#define MPU_6050_SPI_MODE_1 0x01
#define MPU_6050_SPI_MODE_2 0x02
#define MPU_6050_SPI_MODE_3 0x03

#define MPU_6050_GPIO_ENABLE_PIN 8
#define MPU_6050_GPIO_CS_PIN 11
#define MPU_6050_LED_GPIO_PIN 17

#define MPU_6050_BUFFER_SIZE 64
#define MPU_6050_BUFFER_SHIFT 4

#define MPU_6050_THRESHOLD_X 200
#define MPU_6050_THRESHOLD_Y 200
#define MPU_6050_THRESHOLD_Z 200

#define MPU_6050_LED_ON 500
#define MPU_6050_LED_OFF 1000

int main() {
    int spi_fd;
    struct spi_device *spi;
    struct spi_transfer transfer[1];
    uint8_t buffer[MPU_6050_BUFFER_SIZE];
    uint8_t *buffer_ptr;
    uint16_t data;
    int i, j, count;
    int16_t x, y, z;
    int16_t threshold_x, threshold_y, threshold_z;
    int led_state;

    // Initialize GPIO and SPI
    gpio_init();
    gpio_set_direction(MPU_6050_GPIO_ENABLE_PIN, GPIO_MODE_OUTPUT);
    gpio_set_direction(MPU_6050_GPIO_CS_PIN, GPIO_MODE_OUTPUT);
    gpio_set_direction(MPU_6050_LED_GPIO_PIN, GPIO_MODE_OUTPUT);

    spi_fd = spidev_open(MPU_6050_SPI_DEVICE_PATH, SPI_MODE_MASTER | SPI_MODE_SLAVE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    spi = &spi_devices[spi_fd];
    spi->max_speed_hz = MPU_6050_SPI_MAX_SPEED_HZ;
    spi->mode = MPU_6050_SPI_MODE_0;

    // Initialize the buffer
    buffer_ptr = buffer;
    for (i = 0; i < MPU_6050_BUFFER_SIZE; i++) {
        buffer[i] = 0;
    }

    // Initialize threshold values
    threshold_x = MPU_6050_THRESHOLD_X;
    threshold_y = MPU_6050_THRESHOLD_Y;
    threshold_z = MPU_6050_THRESHOLD_Z;

    // Initialize LED state
    led_state = MPU_6050_LED_OFF;

    // Initialize circular buffer
    for (i = 0; i < MPU_6050_BUFFER_SIZE; i++) {
        buffer[i] = 0;
    }

