    while (1) {
        // Check for SPI initialization failure
        if (spi_transfer(spi, transfer, 1) < 0) {
            fprintf(stderr, "Failed to initialize SPI\n");
            return 1;
        }

        // Read data from MPU-6050
        if (spi_transfer(spi, transfer, 1) < 0) {
            fprintf(stderr, "Failed to read data from MPU-6050\n");
            return 1;
        }

        // Check for sensor read failure
        if (transfer->tx_data[0] == 0) {
            fprintf(stderr, "Failed to read data from MPU-6050\n");
            return 1;
        }

        // Check if axis exceeds threshold
        if (buffer_ptr[0] > threshold_x || buffer_ptr[1] > threshold_y || buffer_ptr[2] > threshold_z) {
            // Blink warning LED
            gpio_set_level(MPU_6050_LED_GPIO_PIN, led_state == MPU_6050_LED_ON ? MPU_6050_LED_OFF : MPU_6050_LED_ON);
            led_state = (led_state == MPU_6050_LED_ON) ? MPU_6050_LED_OFF : MPU_6050_LED_ON;

            // Print buffer as CSV
            printf("Timestamp,X,Y,Z\n");
            for (i = 0; i < MPU_6050_BUFFER_SIZE; i++) {
                data = buffer_ptr[i] >> MPU_6050_BUFFER_SHIFT;
                printf("%lu,%.2f,%.2f,%.2f\n", (unsigned long)i, data, 0, 0);
            }

            // Reset buffer pointer
            buffer_ptr = buffer;
        }

        // Wait for next iteration
        usleep(1000);
    }

    // Release SPI resources
    spi_unregister(spi);
    gpio_cleanup();

    return 0;
}

