    int gpio_pin;
    int error;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_desc gpio_desc;
    struct gpio_value gpio_value;
    char i2c_log_file[128];
    char tilt_log_file[128];
    char log_line[128];
    char timestamp[32];
    char roll_pitch[32];
    int roll, pitch;
    int absolute_roll, absolute_pitch;
    int sigint_received = 0;

    // Initialize I2C bus and GPIO
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        exit(1);
    }

    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Error opening GPIO device");
        exit(1);
    }

    // Initialize GPIO pin 21
    gpio_pin = 21;
    if (gpio_pin >= 0 && gpio_pin < 32) {
        gpio_desc.gpio_num = gpio_pin;
        gpio_desc.gpio_value = 0;
        if (gpio_desc.set_value(&gpio_desc) < 0) {
            perror("Error setting GPIO pin value");
            exit(1);
        }
    }

    // Initialize I2C handle
    if ((i2c_handle = i2c_open_device(i2c_fd, I2C_BUS_NUM, I2C_ADDRESS)) < 0) {
        perror("Error opening I2C device");
        exit(1);
    }

    // Initialize pigpio library
    if (gpio_init() < 0) {
        perror("Error initializing pigpio library");
        exit(1);
    }

    // Initialize I2C driver library
    if (i2c_set_mode(i2c_handle, I2C_MODE_I2C) < 0) {
        perror("Error setting I2C mode");
        exit(1);
    }

    // Initialize GPIO driver library
    if (gpio_set_mode(gpio_pin, GPIO_OUTPUT) < 0) {
        perror("Error setting GPIO mode");
        exit(1);
    }

    // Initialize LED
    gpio_desc.gpio_num = 21;
    gpio_desc.gpio_value = 1;
    if (gpio_desc.set_value(&gpio_desc) < 0) {
        perror("Error setting GPIO pin value");
        exit(1);
    }

    // Initialize log file
    snprintf(i2c_log_file, sizeof(i2c_log_file), "tilt_log.txt");
    snprintf(tilt_log_file, sizeof(tilt_log_file), "tilt_log_%s.txt", timestamp);

    while (1) {
        // Read sensor data
        if (i2c_read_i2c_reg16(i2c_handle, MPU_6050_POWER_MGMT_REG, &i2c_data.reg) < 0) {
            perror("Error reading MPU-6050 power management register");
            continue;
        }

        if (i2c_read_i2c_reg16(i2c_handle, MPU_6050_ACCEL_XOUT_H_REG, &i2c_data.reg) < 0) {
            perror("Error reading MPU-6050 accelerometer X-axis output register");
            continue;
        }

        if (i2c_read_i2c_reg16(i2c_handle, MPU_6050_ACCEL_YOUT_H_REG, &i2c_data.reg) < 0) {
            perror("Error reading MPU-6050 accelerometer Y-axis output register");
            continue;
        }

        if (i2c_read_i2c_reg16(i2c_handle, MPU_6050_ACCEL_ZOUT_H_REG, &i2c_data.reg) < 0) {
            perror("Error reading MPU-6050 accelerometer Z-axis output register");
            continue;
        }

        // Compute roll and pitch
        absolute_roll = ((i2c_data.reg & 0x1F) << 2) + ((i2c_data.reg >> 6) & 0x03);
        absolute_pitch = ((i2c_data.reg >> 2) & 0x03) + ((i2c_data.reg & 0x0F) << 1);

        roll = (int)fabs(absolute_roll);
        pitch = (int)fabs(absolute_pitch);

        // Append roll and pitch to log file
        if (snprintf(tilt_log_file, sizeof(tilt_log_file), "%s/%s_%d_%d.txt", i2c_log_file, timestamp, roll, pitch) >= sizeof(tilt_log_file)) {
            perror("Error writing to log file");
            continue;
        }

        // Print roll and pitch to console
        printf("Roll: %d, Pitch: %d\n", roll, pitch);

        // Append log line to file
        if (snprintf(log_line, sizeof(log_line), "%s,%d,%d\n", tilt_log_file, timestamp, roll, pitch) >= sizeof(log_line)) {
            perror("Error writing to log file");
            continue;
        }

        // Print log line to console
        printf("%s\n", log_line);

        // Wait for 100 ms
        usleep(100000);
    }

    // Clean up
    gpio_desc.gpio_value = 0;
    gpio_desc.set_value(&gpio_desc);
    gpio_close(&gpio_desc);
    gpio_uninit();
    gpio_release(&gpio_desc);
    gpio_close(&gpio_desc);
    i2c_close(i2c_handle);
    i2c_release(i2c_fd);
    pigpio_exit();

    return 0;
}

