#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>

#include <gpiod.h>
#include <pigpio.h>

#define CE_GPIO_NUMBER 8
#define SPI_CHANNEL_NUMBER 0
#define SAMPLE_FREQ 1000000
#define DELAY_TIME_MS 10

int main() {
    int spi_fd, gpio_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *gyro_line;
    struct gpiod_event event;
    struct gpiod_event_data data;
    struct timespec start_time, end_time;
    uint16_t raw_x_rate, raw_y_rate;
    char filename[32];
    FILE *fp;
    int retries = 0;
    int exit_flag = 0;

    // Initialize SPI and GPIO
    gpio_fd = gpio_open(CE_GPIO_NUMBER);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpio_chip_open(gpio_fd);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open chip: %s\n", strerror(errno));
        goto cleanup;
    }

    gyro_line = gpio_line_open(chip, "gyro_line");
    if (gyro_line == NULL) {
        fprintf(stderr, "Failed to open line: %s\n", strerror(errno));
        goto cleanup;
    }

    // Set up SPI configuration
    spi_fd = gpio_spi_open(chip, CE_GPIO_NUMBER);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpio_spi_set_mode(spi_fd, SPI_MODE_0, CE_GPIO_NUMBER, 0) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpio_spi_set_frequency(spi_fd, SPI_CHANNEL_NUMBER, SAMPLE_FREQ) < 0) {
        fprintf(stderr, "Failed to set SPI frequency: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpio_spi_set_polarity(spi_fd, CE_GPIO_NUMBER, 0) < 0) {
        fprintf(stderr, "Failed to set SPI polarity: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpio_spi_set_data_order(spi_fd, CE_GPIO_NUMBER, GPIGPIO_LSB_FIRST) < 0) {
        fprintf(stderr, "Failed to set SPI data order: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpio_spi_set_lsbfirst(spi_fd, CE_GPIO_NUMBER) < 0) {
        fprintf(stderr, "Failed to set SPI LSBFirst: %s\n", strerror(errno));
        goto cleanup;
    }

    // Set up GPIO for CE0
    if (gpio_set_mode(CE_GPIO_NUMBER, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CE0 mode: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpio_set_value(CE_GPIO_NUMBER, 0) < 0) {
        fprintf(stderr, "Failed to set CE0 low: %s\n", strerror(errno));
        goto cleanup;
    }

    // Set up SPI transfer parameters
    if (gpio_spi_set_transfer_data(spi_fd, CE_GPIO_NUMBER, &data, sizeof(data)) < 0) {
        fprintf(stderr, "Failed to set SPI transfer data: %s\n", strerror(errno));
        goto cleanup;
    }

    // Set up SPI transfer parameters for reading registers
    if (gpio_spi_set_transfer_data(spi_fd, CE_GPIO_NUMBER, &event, sizeof(event)) < 0) {
        fprintf(stderr, "Failed to set SPI transfer data: %s\n", strerror(errno));
        goto cleanup;
    }

    event.type = GPIGPIO_EVENT_TYPE_DATA;
    event.data.data32 = 0;
    event.data.data32 |= (1 << 16); // Set the X-axis register address

    // Read the X-axis register
    if (gpio_spi_transfer(spi_fd, CE_GPIO_NUMBER, &event, sizeof(event), NULL, 0) < 0) {
        fprintf(stderr, "Failed to read X-axis register: %s\n", strerror(errno));
        goto cleanup;
    }

    // Read the Y-axis register
    if (gpio_spi_transfer(spi_fd, CE_GPIO_NUMBER, &event, sizeof(event), NULL, 0) < 0) {
        fprintf(stderr, "Failed to read Y-axis register: %s\n", strerror(errno));
        goto cleanup;
    }

    // Read the raw X-axis and Y-axis rates
    raw_x_rate = (uint16_t)event.data.data32;
    raw_y_rate = (uint16_t)event.data.data32;

    // Log the data to a CSV file
    sprintf(filename, "gyro_data.csv");
    fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        goto cleanup;
    }

    fprintf(fp, "timestamp,raw_x_rate,raw_y_rate\n");

    // Log the data to the console
    fprintf(stderr, "timestamp,raw_x_rate,raw_y_rate\n");

    // Wait for the next sample
    while (1) {
        // Wait for the next SPI transfer
        if (gpio_spi_wait_for_transfer(spi_fd, CE_GPIO_NUMBER, &event, sizeof(event)) < 0) {
            fprintf(stderr, "Failed to wait for SPI transfer: %s\n", strerror(errno));
            goto cleanup;
        }

        // Wait for the next sample
        nanosleep(&start_time, NULL);
    }

cleanup:
    gpio_close(spi_fd);
    gpio_close(chip);
    gpio_close(gyro_line);
    gpio_unregister(chip);
    gpio_unregister(gyro_line);
    gpio_unregister(spi_fd);

    return 0;
}

