#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS_NUM 1
#define GPIO_FILE "/dev/gpiomem"
#define RELAY_PIN 17

static int i2c_fd;
static int gpio_fd;
static int log_fd;

void i2c_init(void) {
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg[2];
    int rc;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        exit(EXIT_FAILURE);
    }

    memset(&data, 0, sizeof(data));
    data.bit_time = 100; // I2C bit time in microseconds
    data.timeout_ns = 100000; // I2C timeout in nanoseconds
    data.mode = I2C_MODE_I2C;
    data.sda_ioctl_func = i2c_smbus_ioctl;
    data.sda_ioctl_data = (void *)&data;

    msg[0].addr = 0x1A; // I2C address of MPR121
    msg[0].flags = 0;
    msg[0].len = 2;
    msg[0].buf = (void *)&data;
    msg[1].addr = 0x1A; // I2C address of MPR121
    msg[1].flags = 0;
    msg[1].len = 1;
    msg[1].buf = (void *)&0x00;

    rc = ioctl(i2c_fd, I2C_RDWR, &data);
    if (rc < 0) {
        perror("Error initializing I2C device");
        exit(EXIT_FAILURE);
    }

    rc = ioctl(i2c_fd, I2C_SLAVE, 0x1A);
    if (rc < 0) {
        perror("Error setting I2C slave address");
        exit(EXIT_FAILURE);
    }

    rc = ioctl(i2c_fd, I2C_RDWR, &msg[0]);
    if (rc < 0) {
        perror("Error reading I2C data");
        exit(EXIT_FAILURE);
    }

    rc = ioctl(i2c_fd, I2C_RDWR, &msg[1]);
    if (rc < 0) {
        perror("Error reading I2C data");
        exit(EXIT_FAILURE);
    }

    close(i2c_fd);
}

void gpio_init(void) {
    struct gpio_mem_range *gpio_range;
    int rc;

    gpio_range = (struct gpio_mem_range *)ioctl(GPIO_FILE, GPIOIOC_GET_MEM_RANGE);
    if (gpio_range == NULL) {
        perror("Error getting GPIO memory range");
        exit(EXIT_FAILURE);
    }

    gpio_fd = open(GPIO_FILE, O_RDWR);
    if (gpio_fd < 0) {
        perror("Error opening GPIO file");
        exit(EXIT_FAILURE);
    }

    rc = ioctl(gpio_fd, GPIOIOC_SET_MODE, GPIO_INPUT);
    if (rc < 0) {
        perror("Error setting GPIO mode");
        exit(EXIT_FAILURE);
    }

    rc = ioctl(gpio_fd, GPIOIOC_SET_DIR, GPIO_IN);
    if (rc < 0) {
        perror("Error setting GPIO direction");
        exit(EXIT_FAILURE);
    }

    close(gpio_fd);
}

void debounce_touch(void) {
    struct i2c_msg msg[2];
    int rc;

    while (1) {
        msg[0].addr = 0x1A; // I2C address of MPR121
        msg[0].flags = 0;
        msg[0].len = 2;
        msg[0].buf = (void *)&data;
        msg[1].addr = 0x1A; // I2C address of MPR121
        msg[1].flags = 0;
        msg[1].len = 1;
        msg[1].buf = (void *)&0x00;

        rc = ioctl(i2c_fd, I2C_RDWR, &data);
        if (rc < 0) {
            perror("Error reading I2C data");
            exit(EXIT_FAILURE);
        }

        // Debounce the touch event
        // ...

        msg[1].buf = (void *)&0x01;
        rc = ioctl(i2c_fd, I2C_RDWR, &msg[1]);
        if (rc < 0) {
            perror("Error writing I2C data");
            exit(EXIT_FAILURE);
        }

        usleep(100 * 1000); // Debounce delay in microseconds
    }
}

void toggle_relay(void) {
    struct i2c_msg msg[1];
    int rc;

    msg[0].addr = 0x1A; // I2C address of MPR121
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = (void *)&0x00;

    rc = ioctl(i2c_fd, I2C_RDWR, &data);
    if (rc < 0) {
        perror("Error reading I2C data");
        exit(EXIT_FAILURE);
    }

    rc = ioctl(i2c_fd, I2C_RDWR, &msg[0]);
    if (rc < 0) {
        perror("Error writing I2C data");
        exit(EXIT_FAILURE);
    }

    // Toggle the relay
    // ...
}

int main(void) {
    i2c_init();
    gpio_init();
    debounce_touch();
    toggle_relay();

    return 0;
}

