void debounce_touch(void) {
    struct i2c_msg msg[2];
    int rc;

    while (1) {
        msg[0].addr = 0x1A; // I2C address of MPR121
        msg[0].flags = 0;
        msg[0].len = 2;
        msg[0].buf = (void *)&data;
        msg[1].addr = 0x1A; // I2C address of MPR121
        msg[1].flags = 0;
        msg[1].len = 1;
        msg[1].buf = (void *)&0x00;

        rc = ioctl(i2c_fd, I2C_RDWR, &data);
        if (rc < 0) {
            perror("Error reading I2C data");
            exit(EXIT_FAILURE);
        }

        // Debounce the touch event
        // ...

        msg[1].buf = (void *)&0x01;
        rc = ioctl(i2c_fd, I2C_RDWR, &msg[1]);
