int gpio_open(int gpio_num);
void gpio_close(int gpio_num);
int gpio_read(int gpio_num);
void gpio_write(int gpio_num, int value);

int main() {
    int solenoid1_gpio_num = GPIO_NUM_TO_BASE(17);
    int solenoid2_gpio_num = GPIO_NUM_TO_BASE(27);
    int log_fd;
    struct timeval start_time, end_time;
    char log_file_name[] = "dispense_log.txt";

    if (!gpio_open(solenoid1_gpio_num)) {
        fprintf(stderr, "Failed to open GPIO17 for solenoid1\n");
        return 1;
    }

    if (!gpio_open(solenoid2_gpio_num)) {
        fprintf(stderr, "Failed to open GPIO27 for solenoid2\n");
        return 1;
    }

    if (!gpio_write(solenoid1_gpio_num, 1)) {
        fprintf(stderr, "Failed to activate solenoid1\n");
        return 1;
    }

    if (!gpio_write(solenoid2_gpio_num, 1)) {
        fprintf(stderr, "Failed to activate solenoid2\n");
        return 1;
    }

    log_fd = open(log_file_name, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd == -1) {
        fprintf(stderr, "Failed to open log file: %s\n", log_file_name);
        return 1;
    }

    start_time.tv_sec = 0;
    start_time.tv_usec = 0;

