        if (!gpio_read(solenoid1_gpio_num)) {
            fprintf(stderr, "Solenoid1 activated\n");
        }

        if (!gpio_read(solenoid2_gpio_num)) {
            fprintf(stderr, "Solenoid2 activated\n");
        }

