        end_time.tv_usec = 0;

        if (gettimeofday(&start_time, NULL) < 0) {
            fprintf(stderr, "Failed to get start time\n");
            return 1;
        }

        if (gettimeofday(&end_time, NULL) < 0) {
            fprintf(stderr, "Failed to get end time\n");
            return 1;
        }

        int duration_ms = (end_time.tv_sec - start_time.tv_sec) * 1000 + (end_time.tv_usec - start_time.tv_usec) / 1000;
        if (duration_ms < 500) {
            duration_ms = 1000;
        }

        if (!gpio_write(solenoid1_gpio_num, 1)) {
            fprintf(stderr, "Failed to activate solenoid1\n");
            return 1;
