            return 1;
        }

        sleep(duration_ms / 1000);
    }

    gpio_close(solenoid1_gpio_num);
    gpio_close(solenoid2_gpio_num);
    close(log_fd);

    return 0;
}

int gpio_open(int gpio_num) {
    int fd = open("/dev/gpiomem", O_RDWR);
    if (fd < 0) {
        return -1;
    }

    struct gpio_mem_range *mem_range;
    if (ioctl(fd, GPIO_IOC_MEM_RANGE, &mem_range) < 0) {
        close(fd);
        return -1;
    }

    gpio_num = gpio_num - GPIO_BASE_ADDRESS;
    if (mem_range->base_addr + gpio_num >= mem_range->base_addr + mem_range->size) {
        close(fd);
        return -1;
    }

    gpio_base_addr = mem_range->base_addr + gpio_num;
    gpio_num_to_base = gpio_num - GPIO_BASE_ADDRESS;

    return fd;
}

void gpio_close(int gpio_num) {
    close(gpio_num);
}

int gpio_read(int gpio_num) {
    return read(gpio_num, &gpio_base_addr, sizeof(gpio_base_addr));
}

void gpio_write(int gpio_num, int value) {
    if (value) {
        gpio_base_addr |= 1 << gpio_num;
    } else {
        gpio_base_addr &= ~(1 << gpio_num);
    }

    if (write(gpio_num, &gpio_base_addr, sizeof(gpio_base_addr)) < 0) {
        fprintf(stderr, "Failed to write to GPIO: %d\n", gpio_num);
        exit(1);
    }
}

