#include <errno.h>
#include <linux/input.h>
#include <linux/gpio.h>

#define GPIO_DIR_IN  (1 << 4)
#define GPIO_DIR_OUT (1 << 5)
#define GPIO_INT_EDGE_FALLING (1 << 6)

int gpio_fd;
struct gpio_desc *gpio_desc;

void handle_touch_event(int fd, struct gpio_event *event) {
    if (event->type == GPIO_EVENT_TYPE_EDGE_FALLING) {
        if (event->value == GPIO_HIGH) {
            printf("Touch detected on GPIO %d\n", event->gpio_num);
            // Toggle the 5V relay
            gpio_set_value(17, GPIO_HIGH);
        }
    }
}

int main() {
    int ret;

    // Initialize GPIO
    gpio_fd = gpio_open("/dev/gpiochip0", 0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    gpio_desc = gpio_get_desc(gpio_fd);
    if (!gpio_desc) {
        perror("Failed to get GPIO descriptor");
        exit(EXIT_FAILURE);
    }

    gpio_desc->flags |= GPIO_DIR_IN;
    gpio_desc->flags &= ~GPIO_INT_EDGE_FALLING;

    ret = gpio_request_irq(gpio_fd, GPIO_INPUT_PIN_7, handle_touch_event, NULL);
    if (ret < 0) {
        perror("Failed to request GPIO interrupt");
        exit(EXIT_FAILURE);
    }

    // Wait for touch event
    struct gpio_event event;
    event.gpio_num = 7;
    event.type = GPIO_EVENT_TYPE_EDGE_FALLING;
    event.value = GPIO_HIGH;
    event.gpio_event_flags = GPIO_EVENT_FLAG_NONE;

    while (1) {
        ret = gpio_wait_event(gpio_fd, &event, 100);
        if (ret < 0) {
            perror("Failed to wait for touch event");
            exit(EXIT_FAILURE);
        }

        if (event.type == GPIO_EVENT_TYPE_EDGE_FALLING) {
            printf("Touch detected on GPIO %d\n", event.gpio_num);
            // Toggle the 5V relay
            gpio_set_value(17, GPIO_HIGH);
        }
    }

    // Cleanup
    gpio_release_irq(gpio_fd, GPIO_INPUT_PIN_7, handle_touch_event);
    gpio_close(gpio_fd);

    return 0;
}

