#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <gpiod.h>
#include <pigpio.h>

#define DRIVER_PATH "/dev/gpiod/gpio"
#define STEPPER_MOTOR_PINS "4,17,27,22"
#define STEPPER_MOTOR_PULSES "1000,1000,1000,1000"
#define STEPPER_MOTOR_REV_PER_STEP 2048
#define STEPPER_MOTOR_REV_PER_MM 50

int main() {
    int fd, gpio_fd;
    struct gpiod_device *device;
    struct gpiod_line *line;
    struct gpiod_event event;
    int steps = 0;
    int motor_steps_per_mm = STEPPER_MOTOR_REV_PER_MM / STEPPER_MOTOR_REV_PER_STEP;
    int motor_steps_total = 0;
    int motor_steps_left = 0;
    int motor_direction = 1;

    gpio_fd = pigpio_open(0);
    if (gpio_fd < 0) {
        printf("Error opening GPIO device\n");
        return 1;
    }

    fd = open(DRIVER_PATH, O_RDWR);
    if (fd < 0) {
        printf("Error opening GPIO device\n");
        return 1;
    }

    device = gpiod_open_by_path(fd, DRIVER_PATH);
    if (device == NULL) {
        printf("Error opening GPIO device\n");
        return 1;
    }

    line = gpiod_get_line(device, "IN1");
    if (line == NULL) {
        printf("Error getting line for IN1\n");
        return 1;
    }

    line = gpiod_get_line(device, "IN2");
    if (line == NULL) {
        printf("Error getting line for IN2\n");
        return 1;
    }

    line = gpiod_get_line(device, "IN3");
    if (line == NULL) {
        printf("Error getting line for IN3\n");
        return 1;
    }

    line = gpiod_get_line(device, "IN4");
    if (line == NULL) {
        printf("Error getting line for IN4\n");
        return 1;
    }

    pigpio_set_mode(gpio_fd, PI_OUTPUT);
    pigpio_pin_high(line);
    pigpio_pin_high(device->line[0]);
    pigpio_pin_high(device->line[1]);
    pigpio_pin_high(device->line[2]);
    pigpio_pin_high(device->line[3]);

    while (1) {
        if (steps >= motor_steps_total) {
            break;
        }

        pigpio_set_mode(gpio_fd, PI_OUTPUT);
        pigpio_pin_low(line);
        pigpio_pin_low(device->line[0]);
        pigpio_pin_low(device->line[1]);
        pigpio_pin_low(device->line[2]);
        pigpio_pin_low(device->line[3]);

        pigpio_set_pwm_range(gpio_fd, 0, 255);
        pigpio_set_duty_cycle(gpio_fd, line, (steps * motor_steps_per_mm) / STEPPER_MOTOR_REV_PER_STEP);

        usleep(1000);

        steps++;
        pigpio_delay(100);
    }

    pigpio_set_mode(gpio_fd, PI_INPUT);
    pigpio_pin_low(line);
    pigpio_pin_low(device->line[0]);
    pigpio_pin_low(device->line[1]);
    pigpio_pin_low(device->line[2]);
    pigpio_pin_low(device->line[3]);

    pigpio_release(gpio_fd);

    return 0;
}

