#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>
#include <linux/i2c.h>
#include <linux/delay.h>
#include <linux/time.h>

#define I2C_BUS_NUM 1
#define I2C_ADDR 0x1A // Silicon Labs Si7210 I2C address
#define RELAY_GPIO 17
#define RELAY_ACTIVE_HIGH 1

#define I2C_TIMEOUT 5000 // Timeout in milliseconds for I2C operations
#define RELAY_ACTIVE_LOW 0

#define I2C_READ_BLOCK_SIZE 8

#define I2C_READ_TIMEOUT 100 // Timeout in milliseconds for I2C read operations

#define I2C_POLL_ATTEMPTS 50

#define I2C_TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

#define RELAY_STATE_ACTIVE 0
#define RELAY_STATE_INACTIVE 1

void i2c_init(int bus_num);
void i2c_deinit(int bus_num);
int i2c_read_block(int bus_num, uint8_t reg_addr, uint8_t *reg_data, int block_size);
int i2c_write_block(int bus_num, uint8_t reg_addr, uint8_t *reg_data, int block_size);

int main() {
    int bus_num = I2C_BUS_NUM;
    int i;

    // Initialize I2C bus
    i2c_init(bus_num);

    // Initialize relay
    int relay_pin = RELAY_GPIO;
    int relay_state = RELAY_STATE_INACTIVE;

    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open magnetic_events.txt\n");
        exit(1);
    }

    while (1) {
        // Read magnetic field data
        uint8_t reg_data[I2C_READ_BLOCK_SIZE];
        int bytes_read = i2c_read_block(bus_num, I2C_ADDR, reg_data, I2C_READ_BLOCK_SIZE);
        if (bytes_read != I2C_READ_BLOCK_SIZE) {
            fprintf(stderr, "Failed to read magnetic field data\n");
            exit(1);
        }

        // Check if register value clears after 50 poll attempts
        for (i = 0; i < I2C_POLL_ATTEMPTS; i++) {
            if (reg_data[0] == 0) {
                break;
            }
            usleep(100000);
        }

        if (i == I2C_POLL_ATTEMPTS) {
            fprintf(stderr, "Failed to clear register after 50 poll attempts\n");
            exit(1);
        }

        // Check if register contains threshold value
        int threshold_value = reg_data[0];

        // Check if threshold value is above 5.0 mT
        if (threshold_value > 5.0) {
            // Trigger relay
            gpio_set_level(relay_pin, RELAY_ACTIVE_HIGH);

            // Log timestamped entry
            char timestamp[32];
            time_t t = time(NULL);
            struct tm *lt = localtime(&t);
            strftime(timestamp, sizeof(timestamp), I2C_TIMESTAMP_FORMAT, lt);
            fprintf(fp, "%.0f,%.0f,%.0f\n", t, lt->tm_hour, lt->tm_min);

            // Append entry to magnetic_events.txt
            fprintf(fp, "%s,%s,%s\n", timestamp, "magnetic_event", "1");

            // Relay state change
            gpio_set_level(relay_pin, RELAY_ACTIVE_LOW);
        }

        // Wait for next reading
        usleep(I2C_TIMEOUT);
    }

    // Deinitialize I2C bus
    i2c_deinit(bus_num);

    return 0;
}

void i2c_init(int bus_num) {
    struct i2c_rdwr_ioctl_data_t data;
    data.flags = 0;
    data.timeout = I2C_TIMEOUT;

    if (ioctl(bus_num, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        exit(1);
    }
}

void i2c_deinit(int bus_num) {
    struct i2c_rdwr_ioctl_data_t data;
    data.flags = 0;
    data.timeout = I2C_TIMEOUT;

    if (ioctl(bus_num, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "Failed to deinitialize I2C bus\n");
        exit(1);
    }
}

int i2c_read_block(int bus_num, uint8_t reg_addr, uint8_t *reg_data, int block_size) {
    struct i2c_rdwr_ioctl_data_t data;
    data.flags = 0;
    data.timeout = I2C_TIMEOUT;

    if (ioctl(bus_num, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "Failed to read block from I2C device\n");
        exit(1);
    }

    if (block_size != I2C_READ_BLOCK_SIZE) {
        fprintf(stderr, "Invalid block size\n");
        exit(1);
    }

    if (data.wr_buf_len != block_size) {
        fprintf(stderr, "Invalid write buffer length\n");
        exit(1);
    }

    if (data.wr_buf != NULL) {
        memcpy(reg_data, data.wr_buf, block_size);
    }

    if (data.rd_buf != NULL) {
        memcpy(reg_data, data.rd_buf, block_size);
    }

    return block_size;
}

int i2c_write_block(int bus_num, uint8_t reg_addr, uint8_t *reg_data, int block_size) {
    struct i2c_rdwr_ioctl_data_t data;
    data.flags = 0;
    data.timeout = I2C_TIMEOUT;

    if (ioctl(bus_num, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "Failed to write block to I2C device\n");
        exit(1);
    }

    if (block_size != I2C_READ_BLOCK_SIZE) {
        fprintf(stderr, "Invalid block size\n");
        exit(1);
    }

    if (data.wr_buf_len != block_size) {
        fprintf(stderr, "Invalid write buffer length\n");
        exit(1);
    }

    if (data.wr_buf != NULL) {
        memcpy(reg_data, data.wr_buf, block_size);
    }

    if (data.rd_buf != NULL) {
        memcpy(reg_data, data.rd_buf, block_size);
    }

    return block_size;
}
