#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#include <pigpio.h>

#define RELAY_GPIO 18
#define RELAY_PORT 1
#define RELAY_DEVICE "/dev/gpiomem"
#define RELAY_NAME "KY-019"
#define RELAY_MODEL "KY-019"

#define RELAY_ON_COMMAND "ON"
#define RELAY_OFF_COMMAND "OFF"

#define RELAY_LOG_FILE "relay_log.txt"

int main() {
    int sock;
    struct sockaddr_in addr;
    char buffer[256];
    char *command;
    char *log_message;
    struct timespec ts;
    int ret;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    // Initialize socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Failed to create socket");
        gpioDeinitialise();
        return 1;
    }

    // Set up relay control command
    command = (char*)malloc(strlen(RELAY_ON_COMMAND) + strlen(RELAY_OFF_COMMAND) + 1);
    strcpy(command, RELAY_ON_COMMAND);
    strcat(command, RELAY_OFF_COMMAND);

    // Install signal handlers
    signal(SIGINT, relay_handler);
    signal(SIGTERM, relay_handler);

    // Bind socket to localhost
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_LOOPBACK;
    addr.sin_port = htons(5000);
    if (bind(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("Failed to bind socket");
        goto error_socket;
    }

    // Listen for incoming relay commands
    if (listen(sock, 3) < 0) {
        perror("Failed to listen on socket");
        goto error_socket;
    }

    // Accept incoming relay commands
    if ((ret = accept(sock, NULL, NULL)) < 0) {
        perror("Failed to accept incoming relay command");
        goto error_accept;
    }

    // Read relay commands
    while (1) {
        if (read(sock, buffer, sizeof(buffer)) < 0) {
            perror("Failed to read relay command");
            goto error_read;
        }

        // Log command
        log_message = (char*)malloc(strlen(buffer) + 1);
        strcpy(log_message, "Command: ");
        strcat(log_message, buffer);
        strcat(log_message, "\n");
        if (write(STDERR_FILENO, log_message, strlen(log_message)) < 0) {
            perror("Failed to write log message");
            goto error_log;
        }

        // Check command
        if (strcmp(buffer, RELAY_ON_COMMAND) == 0) {
            // Turn on relay
            if (gpioSetValue(RELAY_GPIO, 1) < 0) {
                perror("Failed to turn on relay");
                goto error_gpio;
            }
            printf("Relay turned on at: %s\n", ctime(&ts.tv_sec));
        } else if (strcmp(buffer, RELAY_OFF_COMMAND) == 0) {
            // Turn off relay
            if (gpioSetValue(RELAY_GPIO, 0) < 0) {
                perror("Failed to turn off relay");
                goto error_gpio;
            }
            printf("Relay turned off at: %s\n", ctime(&ts.tv_sec));
        } else {
            // Invalid command
            printf("Invalid command: %s\n", buffer);
        }

        // Sleep for 1 second
        sleep(1);
    }

error_log:
    free(log_message);
error_read:
    close(sock);
error_accept:
    close(STDERR_FILENO);
error_socket:
    gpioDeinitialise();
    return 1;
}

// Signal handler for SIGINT and SIGTERM
void relay_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    gpioDeinitialise();
    exit(0);
}

