#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/syslog.h>
#include <pigpio.h>

#define GPIO_DIR_IN 17
#define GPIO_DIR_OUT 22
#define GPIO_DIR_PULLUP 23
#define GPIO_DIR_OUT_PULLUP 24

int main() {
    int fd, gpioHandle;
    struct gpiod_event event;
    struct gpiod_event_edge edge;
    struct gpiod_event_state state;
    int motorRunning = 0;
    int sensorDryCount = 0;
    int lastMotorState = 0;
    int lastSensorState = 0;
    int syslogFacility = LOG_USER;
    char syslogIdentifier[] = "rain_window";

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return 1;
    }

    // Open GPIO file descriptor
    fd = open("/dev/gpiob", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO file descriptor");
        return 1;
    }

    // Set GPIO direction to input with pull-up
    if (gpioSetMode(GPIO_DIR_IN, GPIO_DIR_IN) < 0) {
        perror("Failed to set GPIO direction to input with pull-up");
        return 1;
    }

    // Set GPIO 17 (BCM) as ENA output
    gpioHandle = gpioOpen(GPIO_DIR_OUT, GPIO_DIR_OUT_PULLUP);
    if (gpioHandle < 0) {
        perror("Failed to open GPIO 17 (BCM)");
        return 1;
    }
    if (gpioSetMode(gpioHandle, GPIO_DIR_OUT) < 0) {
        perror("Failed to set GPIO 17 (BCM) to output");
        return 1;
    }
    gpioSetValue(gpioHandle, 1);

    // Set GPIO 22 (BCM) as IN1 input
    gpioHandle = gpioOpen(GPIO_DIR_IN, GPIO_DIR_IN);
    if (gpioHandle < 0) {
        perror("Failed to open GPIO 22 (BCM)");
        return 1;
    }
    if (gpioSetMode(gpioHandle, GPIO_DIR_IN) < 0) {
        perror("Failed to set GPIO 22 (BCM) to input");
        return 1;
    }
    gpioSetValue(gpioHandle, 0);

    // Set GPIO 23 (BCM) as IN2 input
    gpioHandle = gpioOpen(GPIO_DIR_IN, GPIO_DIR_IN);
    if (gpioHandle < 0) {
        perror("Failed to open GPIO 23 (BCM)");
        return 1;
    }
    if (gpioSetMode(gpioHandle, GPIO_DIR_IN) < 0) {
        perror("Failed to set GPIO 23 (BCM) to input");
        return 1;
    }
    gpioSetValue(gpioHandle, 0);

    // Set GPIO 24 (BCM) as ENA output
    gpioHandle = gpioOpen(GPIO_DIR_OUT, GPIO_DIR_OUT_PULLUP);
    if (gpioHandle < 0) {
        perror("Failed to open GPIO 24 (BCM)");
        return 1;
    }
    if (gpioSetMode(gpioHandle, GPIO_DIR_OUT) < 0) {
        perror("Failed to set GPIO 24 (BCM) to output");
        return 1;
    }
    gpioSetValue(gpioHandle, 1);

    // Set GPIO 17 (BCM) as an event source
    gpioSetEventSource(gpioHandle, GPIO_EDGE_FALLING);

    // Continuously poll the sensor DO pin
    while (1) {
        // Wait for the next event
        if (gpioWaitEvent(gpioHandle, &event, GPIO_EVENT_EDGE_FALLING) < 0) {
            perror("Failed to wait for the next event");
            return 1;
        }

        // Check if the event is a rising-edge (dry-to-wet transition)
        if (event.type == GPIO_EVENT_TYPE_EDGE) {
            if (event.event.falling.value == 0) {
                // Log the dry-to-wet transition
                syslog(LOG_INFO, "Dry-to-wet transition detected");

                // Reset the dry count
                sensorDryCount = 0;
            } else {
                // Log the dry state
                syslog(LOG_INFO, "Dry state detected");
                sensorDryCount++;

                // Check if the sensor has been dry for at least 3 consecutive polls
                if (sensorDryCount >= 3) {
                    // Wait for the next event
                    if (gpioWaitEvent(gpioHandle, &event, GPIO_EVENT_EDGE_FALLING) < 0) {
                        perror("Failed to wait for the next event");
                        return 1;
                    }

                    // Check if the event is a rising-edge (dry-to-wet transition)
                    if (event.type == GPIO_EVENT_TYPE_EDGE) {
                        if (event.event.rising.value == 1) {
                            // Log the motor start
                            syslog(LOG_INFO, "Motor started");

                            // Set ENA high
                            gpioSetValue(gpioHandle, 1);

                            // Wait for 5 seconds
                            usleep(5 * 1000 * 1000);

                            // Set ENA low
                            gpioSetValue(gpioHandle, 0);

                            // Set IN1 high, IN2 low
                            gpioSetValue(gpioHandle, 1);
                            gpioSetValue(gpioHandle, 0);

                            // Log the motor start
                            syslog(LOG_INFO, "Motor started");
                        }
                    }
                }
            }
        }

        // Check if the motor should be started
        if (motorRunning) {
            // Check if the motor is already running
            if (gpioGetValue(gpioHandle) == 1) {
                // Log the motor start
                syslog(LOG_INFO, "Motor started");

                // Set ENA high
                gpioSetValue(gpioHandle, 1);

                // Wait for 5 seconds
                usleep(5 * 1000 * 1000);

                // Set ENA low
                gpioSetValue(gpioHandle, 0);

                // Set IN1 high, IN2 low
                gpioSetValue(gpioHandle, 1);
                gpioSetValue(gpioHandle, 0);

                // Log the motor start
                syslog(LOG_INFO, "Motor started");
            }
        }

        // Check if the motor should be stopped
        if (!motorRunning) {
            // Check if the motor is already stopped
            if (gpioGetValue(gpioHandle) == 0) {
                // Log the motor stop
                syslog(LOG_INFO, "Motor stopped");

                // Wait for 5 seconds
                usleep(5 * 1000 * 1000);

                // Set IN1 high, IN2 low
                gpioSetValue(gpioHandle, 1);
                gpioSetValue(gpioHandle, 0);

                // Log the motor stop
                syslog(LOG_INFO, "Motor stopped");
            }
        }

        // Check if the motor should be started again
        if (sensorDryCount >= 3) {
            motorRunning = 1;
        } else {
            motorRunning = 0;
        }
    }

    // Clean up
    gpioClose(gpioHandle);
    gpioUnsetEventSource(gpioHandle);
    gpioTerminate();

    return 0;
}

