int main() {
    int gpio;
    int ret;

    // Initialize the GPIO
    gpio = pigpio_initialize();
    if (gpio < 0) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    // Check if the driver library is successfully initialized
    if (pigpio_library_initialized() == 0) {
        fprintf(stderr, "Error: Driver library not initialized\n");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Set up the PIR sensor
    ret = pigpio_set_mode(GPIO_4, PI_MODE_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting PIR sensor mode\n");
        return 1;
    }

    // Set up the relay-controlled LED floodlight
    ret = pigpio_set_mode(RELAY_GPIO, PI_MODE_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting relay GPIO mode\n");
        return 1;
    }

    ret = pigpio_set_level(RELAY_GPIO, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting relay GPIO level\n");
        return 1;
    }

    // Set up the PIR sensor polling interval
    ret = pigpio_set_poll_interval(100);
    if (ret < 0) {
        fprintf(stderr, "Error setting PIR sensor polling interval\n");
        return 1;
    }

    // Set up the PIR sensor event handler
    ret = pigpio_set_event_handler(GPIO_4, pir_event_handler);
    if (ret < 0) {
        fprintf(stderr, "Error setting PIR sensor event handler\n");
        return 1;
    }

    // Set up the PIR sensor threshold
    ret = pigpio_set_threshold(GPIO_4, 100);
    if (ret < 0) {
        fprintf(stderr, "Error setting PIR sensor threshold\n");
        return 1;
    }

    // Set up the PIR sensor debounce time
    ret = pigpio_set_debounce(GPIO_4, 50);
    if (ret < 0) {
        fprintf(stderr, "Error setting PIR sensor debounce time\n");
        return 1;
    }

    // Set up the PIR sensor interrupt handler
    ret = pigpio_set_interrupt_handler(GPIO_4, pir_interrupt_handler);
    if (ret < 0) {
        fprintf(stderr, "Error setting PIR sensor interrupt handler\n");
        return 1;
    }

    // Start the PIR sensor polling loop
    while (1) {
        // Wait for the next rising edge
        ret = pigpio_wait_for_event(GPIO_4, PI_EVENT_GPIO_FALLING);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for PIR sensor event\n");
            break;
        }

        // Activate the floodlight
        ret = pigpio_set_level(RELAY_GPIO, 1);
        if (ret < 0) {
            fprintf(stderr, "Error activating floodlight\n");
            break;
        }

        // Wait for 60 seconds
        sleep(60);

        // Deactivate the floodlight
        ret = pigpio_set_level(RELAY_GPIO, 0);
        if (ret < 0) {
            fprintf(stderr, "Error deactivating floodlight\n");
            break;
        }

        // Write activation event with ISO-8601 timestamp
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        char timestamp[80];
        snprintf(timestamp, sizeof(timestamp), "%.6f", now.tv_sec);
        fprintf(log_file, "Activation event: %s\n", timestamp);

        // Release resources and clean up
        pigpio_release();
    }

    // Clean up
    fclose(log_file);
    pigpio_uninitialize();

    return 0;
}

