#include <arpa/inet.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <pigpio.h>

#define BCM_GPIO17 17
#define BCM_GPIO4  4

int main(int argc, char *argv[]) {
    int sockfd, opt, val;
    struct sockaddr_in serv_addr, cli_addr;
    int addrlen = sizeof(cli_addr);
    char buffer[1024];
    char *command;
    char *log_file = "security.log";
    int log_fd;
    int syslog_fd;
    int ret;

    if (argc < 2) {
        printf("Usage: %s <command>\n", argv[0]);
        return 1;
    }

    command = argv[1];

    if (strcmp(command, "PIR") == 0) {
        if (gpioInitialise() < 0) {
            fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(gpioGetLastError()));
            return 1;
        }

        if (gpioRead(BCM_GPIO4) == 0) {
            fprintf(stderr, "PIR sensor is not triggered\n");
            return 1;
        }

        gpioRelease(BCM_GPIO4);
        gpioClose();

        syslog(LOG_INFO, "PIR sensor triggered");
        return 0;
    }

    if (strcmp(command, "SERVO") == 0) {
        if (gpioInitialise() < 0) {
            fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(gpioGetLastError()));
            return 1;
        }

        if (gpioRead(BCM_GPIO17) == 1) {
            gpioRelease(BCM_GPIO17);
            gpioRelease(BCM_GPIO4);
            gpioClose();

            // Generate software PWM signal
            gpioSetMode(BCM_GPIO17, GPIO_OUTPUT);
            gpioSetPwmFrequency(BCM_GPIO17, 50);
            gpioSetPwmRange(BCM_GPIO17, 0, 100);
            gpioSetPwmValue(BCM_GPIO17, 1);

            // Wait for 1-2 ms
            gpioDelay(2);

            gpioSetPwmValue(BCM_GPIO17, 0);
            gpioRelease(BCM_GPIO17);
            gpioRelease(BCM_GPIO4);
            gpioClose();

            syslog(LOG_INFO, "Software PWM signal generated");
            return 0;
        }
    }

    if (argc < 3) {
        printf("Usage: %s <angle> <command>\n", argv[0]);
        return 1;
    }

    if (strcmp(command, "SET_ANGLE") == 0) {
        int angle = atoi(argv[2]);

        if (angle < 0 || angle > 180) {
            fprintf(stderr, "Invalid angle: %d\n", angle);
            return 1;
        }

        if (gpioInitialise() < 0) {
            fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(gpioGetLastError()));
            return 1;
        }

        if (gpioRead(BCM_GPIO4) == 1) {
            fprintf(stderr, "PIR sensor is not triggered\n");
            return 1;
        }

        gpioRelease(BCM_GPIO4);
        gpioClose();

        syslog(LOG_INFO, "PIR sensor triggered");

        // Set servo motor angle
        gpioSetPwmFrequency(BCM_GPIO17, 50);
        gpioSetPwmRange(BCM_GPIO17, 0, 100);
        gpioSetPwmValue(BCM_GPIO17, angle);

        syslog(LOG_INFO, "Servo motor angle set to %d", angle);
        return 0;
    }

    if (argc < 4) {
        printf("Usage: %s <command> <angle> <port>\n", argv[0]);
        return 1;
    }

    if (strcmp(command, "LISTEN") == 0) {
        if (argc < 4) {
            printf("Usage: %s <command> <angle> <port>\n", argv[0]);
            return 1;
        }

        if (gpioInitialise() < 0) {
            fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(gpioGetLastError()));
            return 1;
        }

        if (gpioRead(BCM_GPIO4) == 1) {
            fprintf(stderr, "PIR sensor is not triggered\n");
            return 1;
        }

        gpioRelease(BCM_GPIO4);
        gpioClose();

        syslog(LOG_INFO, "PIR sensor triggered");

        // Listen for TCP connections on the specified port
        if (bind(atoi(argv[3]), (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
            fprintf(stderr, "Failed to bind socket: %s\n", strerror(errno));
            return 1;
        }

        if (listen(atoi(argv[3]), 3) < 0) {
            fprintf(stderr, "Failed to listen on socket: %s\n", strerror(errno));
            return 1;
        }

        if (accept(atoi(argv[3]), (struct sockaddr *)&cli_addr, &addrlen) < 0) {
            fprintf(stderr, "Failed to accept connection: %s\n", strerror(errno));
            return 1;
        }

        syslog(LOG_INFO, "TCP connection accepted");

        // Accept incoming data and handle commands
        while (1) {
            if ((val = recv(accept_fd, buffer, sizeof(buffer), 0)) > 0) {
                command = (char *)malloc(val + 1);
                if (command == NULL) {
