#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x23
#define GPIO_BASE 0x20200000
#define GPIO_PIN_LED 23
#define RELAY_PIN BCM_GPIO_TO_BCM(GPIO23)

int i2c_init() {
    if (gpio_init() < 0) {
        printf("Error initializing GPIO\n");
        return -1;
    }

    if (pi_open_i2c() < 0) {
        printf("Error opening I2C bus\n");
        return -1;
    }

    if (pi_set_mode(I2C_ADDR, I2C_MODE_I2C) < 0) {
        printf("Error setting I2C mode\n");
        return -1;
    }

    if (pi_set_speed(I2C_ADDR, 100000) < 0) {
        printf("Error setting I2C speed\n");
        return -1;
    }

    return 0;
}

void i2c_cleanup() {
    pi_close_i2c();
    gpio_deinit();
}

int main() {
    int rc;
    int i;
    uint16_t lux_value;
    struct i2c_rdwr_ioctl_data data;
    char filename[32];
    FILE *log_file;

    if (i2c_init() < 0) {
        printf("Error initializing I2C\n");
        return -1;
    }

    sprintf(filename, "/tmp/grow_log.txt");
    log_file = fopen(filename, "a");
    if (!log_file) {
        printf("Error opening log file\n");
        return -1;
    }

    rc = pi_set_mode(I2C_ADDR, I2C_MODE_I2C);
    if (rc < 0) {
        printf("Error setting I2C mode\n");
        return -1;
    }

    rc = pi_set_speed(I2C_ADDR, 100000);
    if (rc < 0) {
        printf("Error setting I2C speed\n");
        return -1;
    }

    rc = pi_open_i2c();
    if (rc < 0) {
        printf("Error opening I2C bus\n");
        return -1;
    }

    rc = pi_read_reg16(I2C_ADDR, I2C_REG_BH1750_GAIN, &lux_value);
    if (rc < 0) {
        printf("Error reading BH1750 gain register\n");
        return -1;
    }

    rc = pi_read_reg16(I2C_ADDR, I2C_REG_BH1750_LUX, &lux_value);
    if (rc < 0) {
        printf("Error reading BH1750 lux register\n");
        return -1;
    }

    rc = pi_close_i2c();
    if (rc < 0) {
        printf("Error closing I2C bus\n");
        return -1;
    }

    while (1) {
        // Wait 120 ms after each trigger
        usleep(120000);

        // Trigger the sensor
        rc = pi_write_reg16(I2C_ADDR, I2C_REG_BH1750_TRIGGER, 0x8000);
        if (rc < 0) {
            printf("Error triggering sensor\n");
            continue;
        }

        // Wait for the sensor to complete the read
        rc = pi_read_reg16(I2C_ADDR, I2C_REG_BH1750_READ_DATA, &lux_value);
        if (rc < 0) {
            printf("Error reading sensor data\n");
            continue;
        }

        // Log the lux value
        fprintf(log_file, "Lux value: %d\n", lux_value);

        // Check if the lux reading is below 150
        if (lux_value < 150) {
            // Deactivate the relay
            gpio_set_level(RELAY_PIN, 0);
        } else {
            // Activate the relay
            gpio_set_level(RELAY_PIN, 1);
        }

        // Wait for 2 seconds
        usleep(2000000);
    }

    fclose(log_file);
    i2c_cleanup();

    return 0;
}

