#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <syslog.h>
#include <pthread.h>
#include <signal.h>
#include <gpiod.h>

#define RELAY_GPIO_NUMBER 17
#define RELAY_GPIO_NAME "relay_gpio"
#define RELAY_GPIO_FILE "/dev/gpio"
#define MQTT_BROKER_HOST "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_KEEP_ALIVE 60

static int relay_gpio_fd;
static gpiod_event_t relay_gpio_event;
static pthread_t mqtt_client_thread;

void mqtt_client_loop(void *arg) {
    while (1) {
        // Handle incoming payloads as NUL-terminated strings
        char *payload = (char *)arg;
        if (payload) {
            if (strcmp(payload, "ON") == 0) {
                gpio_set_level(RELAY_GPIO_NUMBER, 1);
            } else if (strcmp(payload, "OFF") == 0) {
                gpio_set_level(RELAY_GPIO_NUMBER, 0);
            } else {
                syslog(LOG_ERR, "Invalid payload: %s", payload);
            }
        }
        usleep(MQTT_KEEP_ALIVE * 1000);
    }
}

int main(int argc, char *argv[]) {
    int ret;
    int keep_alive_count = 0;
    int keep_alive_interval = MQTT_KEEP_ALIVE;

    // Initialize GPIO driver
    ret = gpiod_init();
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO driver: %s", strerror(ret));
        return 1;
    }

    // Open the GPIO file
    relay_gpio_fd = open(RELAY_GPIO_FILE, O_RDWR);
    if (relay_gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO file: %s", strerror(errno));
        gpiod_cleanup();
        return 1;
    }

    // Configure GPIO17 as an output
    ret = gpiod_direction_output(relay_gpio_fd, RELAY_GPIO_NUMBER, 1);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to configure GPIO17 as an output: %s", strerror(ret));
        close(relay_gpio_fd);
        gpiod_cleanup();
        return 1;
    }

    // Set GPIO17 to LOW at startup
    ret = gpiod_set_value(relay_gpio_fd, RELAY_GPIO_NUMBER, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set GPIO17 to LOW: %s", strerror(ret));
        close(relay_gpio_fd);
        gpiod_cleanup();
        return 1;
    }

    // Subscribe to the MQTT topic
    ret = paho_mqtt_client_init(&mqtt_client, MQTT_BROKER_HOST, MQTT_BROKER_PORT, MQTT_CLIENT_ID, MQTT_KEEP_ALIVE);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to initialize MQTT client: %s", strerror(ret));
        close(relay_gpio_fd);
        gpiod_cleanup();
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Start the MQTT client loop
    pthread_create(&mqtt_client_thread, NULL, mqtt_client_loop, (void *)&mqtt_client);

    // Wait for the MQTT client to connect or fail
    while (keep_alive_count < keep_alive_interval) {
        ret = paho_mqtt_client_wait_for_connect(&mqtt_client);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", strerror(ret));
            close(relay_gpio_fd);
            gpiod_cleanup();
            pthread_join(mqtt_client_thread, NULL);
            return 1;
        }
        if (ret == 0) {
            break;
        }
        usleep(1000);
        keep_alive_count++;
    }

    // Disconnect from the MQTT broker
    ret = paho_mqtt_client_disconnect(&mqtt_client);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to disconnect from MQTT broker: %s", strerror(ret));
        close(relay_gpio_fd);
        gpiod_cleanup();
        pthread_join(mqtt_client_thread, NULL);
        return 1;
    }

    // Clean up the MQTT client
    ret = paho_mqtt_client_destroy(&mqtt_client);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to destroy MQTT client: %s", strerror(ret));
        close(relay_gpio_fd);
        gpiod_cleanup();
        pthread_join(mqtt_client_thread, NULL);
        return 1;
    }

    // Clean up the GPIO driver
    gpiod_cleanup();

    // Exit the program
    return 0;
}

void sigint_handler(int signum) {
    syslog(LOG_INFO, "Received SIGINT or SIGTERM");
    close(relay_gpio_fd);
    gpiod_cleanup();
    pthread_exit(NULL);
}

void sigterm_handler(int signum) {
    syslog(LOG_INFO, "Received SIGTERM");
    close(relay_gpio_fd);
    gpiod_cleanup();
    pthread_exit(NULL);
}

