    struct gpiod_i2c_config i2c_config = {
        .i2c_bus = 1,
        .address = I2C_ADDRESS,
    };
    struct gpiod_gpio_config gpio_config = {
        .gpio_num = LED_STRIP_PIN,
        .direction = GPIO_OUT,
        .value = GPIO_LOW,
    };
    struct pigpio_i2c_config pigpio_config = {
        .i2c_bus = 1,
        .address = I2C_ADDRESS,
    };
    struct pigpio_gpio_config pigpio_config_led = {
        .gpio_num = LED_STRIP_PIN,
        .value = GPIO_LOW,
    };
    struct pigpio_gpio_config pigpio_config_relay = {
        .gpio_num = RELAY_PIN,
        .value = GPIO_HIGH,
    };
