    struct gpiod_event event;
    struct gpiod_event_range range;
    struct gpiod_event_range_data data;
    struct timespec start_time, end_time;
    int ret, state;
    char buffer[32];

    // Initialize GPIO and event file descriptors
    relay_fd = gpio_open("/dev/gpiochip0", GPIO_DIR_OUT);
    gpio_fd = gpio_open("/dev/gpiochip0", GPIO_DIR_IN);

    if (relay_fd < 0 || gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO devices\n");
        return 1;
    }

    // Set up event range for debouncing
    range.start = 0;
    range.end = 0;
    range.step = 1;
    range.count = 1;
    range.event_type = GPIGPIO_EVENT_RANGE_EDGE;
    range.event_flags = GPIGPIO_EVENT_RANGE_FALLING;

    // Initialize event structure
    event.type = GPIGPIO_EVENT_TYPE_RANGE;
    event.range = &range;
    event.flags = GPIGPIO_EVENT_FLAG_NONE;

    // Set up event data structure
    data.event_type = GPIGPIO_EVENT_TYPE_RANGE;
    data.range_data = &range;
    data.flags = GPIGPIO_EVENT_FLAG_NONE;

    // Set up GPIO direction and value
    ret = gpiod_set_value(relay_fd, GPIO_DIR_OUT, GPIO_DIR_OUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO direction\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for event
        ret = gpiod_wait_event(relay_fd, &event, NULL, 0);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for event\n");
            return 1;
        }

        // Check if event is valid
        if (event.type != GPIGPIO_EVENT_TYPE_RANGE) {
            fprintf(stderr, "Invalid event type\n");
            continue;
        }

        // Check if event is a falling edge
        if (event.range_data->event_type != GPIGPIO_EVENT_TYPE_RANGE) {
            fprintf(stderr, "Invalid event type\n");
            continue;
        }

        // Check if the sensor is HIGH
        if (event.range_data->range_data == 1) {
            // Toggle relay state
            state = gpiod_get_value(relay_fd);
            if (state == GPIO_DIR_OUT) {
                ret = gpiod_set_value(relay_fd, GPIO_DIR_OUT, GPIO_DIR_IN);
                if (ret < 0) {
                    fprintf(stderr, "Error toggling relay state\n");
                    return 1;
                }
            } else {
                ret = gpiod_set_value(relay_fd, GPIO_DIR_OUT, GPIO_DIR_OUT);
                if (ret < 0) {
                    fprintf(stderr, "Error toggling relay state\n");
                    return 1;
                }
            }
        }

        // Wait for debounce stabilization
        nanosleep(&start_time, NULL);

        // Check if sensor is HIGH again
        if (event.range_data->range_data == 1) {
            // Toggle relay state
            state = gpiod_get_value(relay_fd);
            if (state == GPIO_DIR_OUT) {
                ret = gpiod_set_value(relay_fd, GPIO_DIR_OUT, GPIO_DIR_IN);
                if (ret < 0) {
                    fprintf(stderr, "Error toggling relay state\n");
                    return 1;
                }
            } else {
                ret = gpiod_set_value(relay_fd, GPIO_DIR_OUT, GPIO_DIR_OUT);
                if (ret < 0) {
                    fprintf(stderr, "Error toggling relay state\n");
                    return 1;
                }
            }
        }

        // Sleep for 10 ms
        nanosleep(&end_time, NULL);
    }

    // Release GPIO resources
    gpiod_release(relay_fd);
    gpiod_release(gpio_fd);

    return 0;
}

