#define GPIO_DIR_IN  (1 << 17)
#define GPIO_DIR_OUT (1 << 4)
#define GPIO_INT_EDGE_FALLING (1 << 18)

#define GPIO_FILE "/dev/gpiochip0"
#define RELAY_FILE "/sys/class/gpio/gpio17/value"

#define DEBOUNCE_TIMEOUT 50

int main(int argc, char *argv[]) {
    int relay_fd, debounce_fd, gpio_fd;
    struct input_dev *input_dev;
    struct gpio_desc *gpio_desc;
    struct gpio_event gpio_event;
    char buffer[80];
    char *debounce_ms = NULL;
    int debounce_ms_val = 0;
    int debounce_interval = DEBOUNCE_TIMEOUT;
    int debounce_prev_time = 0;
    int relay_state = 0;

    if (argc < 2) {
        printf("Usage: %s [-d <milliseconds>] <command>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "-h") == 0) {
        printf("This program monitors a TTP223 capacitive touch sensor on GPIO 4 (BCM) and toggles a 5 V relay on GPIO 17 (BCM) each time a valid rising edge (LOW to HIGH) is detected.\n");
        printf("Options:\n");
        printf("-d <milliseconds>\tOverride the debounce interval (default: %d ms)\n", DEBOUNCE_TIMEOUT);
        return 0;
    }

    if (sscanf(argv[1], "-d", &debounce_ms_val) == 0) {
        debounce_ms_val = DEBOUNCE_TIMEOUT;
    }

    if (sscanf(argv[1], "-d", &debounce_ms) == 1) {
        debounce_ms = argv[1];
    }

    if (debounce_ms_val < DEBOUNCE_TIMEOUT) {
        debounce_ms_val = debounce_ms_val;
    } else {
        printf("Invalid debounce interval. Defaulting to %d ms.\n", DEBOUNCE_TIMEOUT);
    }

    if (argc > 2) {
        if (sscanf(argv[2], "%d", &debounce_interval) == 1) {
            debounce_interval = debounce_interval;
