#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/input.h>
#include <linux/uaccess.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/pigpio.h>

#define GPIO_PWM_PIN 18
#define BCM_GPIO 18

int main() {
    int pwmFile;
    int pwmFreq = 50;
    int pwmResolution = 20;
    int angle = 90;
    int angleIncrement = 10;
    int angleDecrement = -10;
    int lastAngle = 0;
    int pwmValue = 0;
    int clampedAngle = 0;
    int exitFlag = 0;

    // Initialize GPIO and PWM
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PWM_PIN, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM mode\n");
        return 1;
    }

    if (gpioSetPWMfrequency(GPIO_PWM_PIN, pwmFreq) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    if (gpioSetPWMresolution(GPIO_PWM_PIN, pwmResolution) < 0) {
        fprintf(stderr, "Failed to set PWM resolution\n");
        return 1;
    }

    // Open PWM file
    pwmFile = open(GPIO_PWM_PIN, O_RDWR);
    if (pwmFile < 0) {
        fprintf(stderr, "Failed to open PWM file\n");
        return 1;
    }

    // Set PWM value to 1500 µs
    if (ioctl(pwmFile, PI_SET_PWM_VALUE, pwmValue) < 0) {
        fprintf(stderr, "Failed to set PWM value\n");
        return 1;
    }

    // Set initial angle
    if (ioctl(pwmFile, PI_SET_PWM_PULSE_WIDTH, angle) < 0) {
        fprintf(stderr, "Failed to set PWM pulse width\n");
        return 1;
    }

    // Set up terminal input
    if (tcgetattr(STDIN_FILENO, &termios_old) < 0) {
        fprintf(stderr, "Failed to get terminal attributes\n");
        return 1;
    }

    struct termios termios_new;
    if (tcgetattr(STDIN_FILENO, &termios_new) < 0) {
        fprintf(stderr, "Failed to get terminal attributes\n");
        return 1;
    }

    termios_new.c_cflag |= (CLOCAL | CREAD);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &termios_new) < 0) {
        fprintf(stderr, "Failed to set terminal attributes\n");
        return 1;
    }

    // Main loop
    while (!exitFlag) {
        int key;
        char buffer[1];

        // Read key from terminal
        if (read(STDIN_FILENO, buffer, 1) < 0) {
            fprintf(stderr, "Failed to read key\n");
            return 1;
        }

        // Check if key is '+' or '-'
        if (buffer[0] == '+') {
            angle += angleIncrement;
            if (angle > 180) {
                angle = 180;
            }
        } else if (buffer[0] == '-') {
            angle -= angleDecrement;
            if (angle < 0) {
                angle = 0;
            }
        }

        // Check if angle is within valid range
        if (angle < 0) {
            angle = 0;
        } else if (angle > 180) {
            angle = 180;
        }

        // Update PWM value
        if (ioctl(pwmFile, PI_SET_PWM_PULSE_WIDTH, angle) < 0) {
            fprintf(stderr, "Failed to set PWM pulse width\n");
            return 1;
        }

        // Update angle
        if (ioctl(pwmFile, PI_GET_PWM_VALUE, &pwmValue) < 0) {
            fprintf(stderr, "Failed to get PWM value\n");
            return 1;
        }

        // Update clamped angle
        clampedAngle = (int) (pwmValue * pwmResolution / (2 * pwmFreq));

        // Print current angle
        printf("Current angle: %d\n", angle);

        // Print clamped angle
        printf("Clamped angle: %d\n", clampedAngle);

        // Close PWM file
        if (close(pwmFile) < 0) {
            fprintf(stderr, "Failed to close PWM file\n");
            return 1;
        }
    }

    // Stop PWM pulses
    if (ioctl(pwmFile, PI_SET_PWM_PULSE_WIDTH, 0) < 0) {
        fprintf(stderr, "Failed to set PWM pulse width to 0\n");
        return 1;
    }

    // Restore terminal settings
    if (tcsetattr(STDIN_FILENO, TCSANOW, &termios_old) < 0) {
        fprintf(stderr, "Failed to restore terminal attributes\n");
        return 1;
    }

    // Clean up
    gpioTerminate();

    return 0;
}

