#define GPIO_BASE_ADDRESS 0x20200000
#define GPIO_PWM_BASE_ADDRESS GPIO_BASE_ADDRESS + 0x100
#define GPIO_ENABLE_BASE_ADDRESS GPIO_BASE_ADDRESS + 0x20
#define GPIO_DIR_BASE_ADDRESS GPIO_BASE_ADDRESS + 0x24

#define PWM_CHANNEL_0 GPIO_PWM_BASE_ADDRESS + 0x0
#define PWM_CHANNEL_1 GPIO_PWM_BASE_ADDRESS + 0x4
#define PWM_CHANNEL_2 GPIO_PWM_BASE_ADDRESS + 0x8

#define GPIO_ENABLE_PIN 23
#define GPIO_DIR_PIN 18

#define PWM_FREQUENCY 50

#define I2C_BUS_ADDRESS 0x1A
#define I2C_SLAVE_ADDRESS 0x34

#define I2C_BUFFER_SIZE 256

#define FILE_NAME "flow_log.csv"

int main(int argc, char *argv[]) {
    int pipe_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpio_desc *gpio_desc;
    struct pwm_desc *pwm_desc;
    struct interrupt_desc *interrupt_desc;
    struct file *file;
    struct timespec start_time, end_time;
    uint16_t flow_rate;
    int pipe_num;
    char buffer[I2C_BUFFER_SIZE];
    char *kp_str;
    char *target_flow_str;
    char *kp_str_err;
    char *target_flow_err;
    int pipe_num_err;
    int ret_val;

    // Initialize GPIO and PWM
    gpio_desc = gpio_get_desc(GPIO_ENABLE_PIN);
    gpio_desc->dir = GPIO_DIR_IN;
    gpio_desc->value = 0;
    gpio_desc->base = GPIO_BASE_ADDRESS + GPIO_ENABLE_PIN;

    pwm_desc = pwm_get_desc(PWM_CHANNEL_0);
    pwm_desc->freq = PWM_FREQUENCY;
    pwm_desc->dir = PWM_DIR_OUTPUT;
    pwm_desc->base = PWM_CHANNEL_0;

    // Initialize I2C
    ret = i2c_master_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize I2C: %d\n", ret);
        return 1;
    }

    // Open the CSV file
    file = fopen(FILE_NAME, "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", FILE_NAME);
        return 1;
    }

    // Initialize the proportional controller
    kp_str = "1.0";
    kp_str_err = kp_str;
    target_flow_str = "0.0";
    target_flow_err = target_flow_str;

    // Check command-line arguments
    if (argc < 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate> [-t <target_flow_rate>]\n", argv[0]);
        return 1;
    }

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 >= argc) {
                fprintf(stderr, "Error: Missing target flow rate argument\n");
                return 1;
            }
            target_flow_str = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 >= argc) {
                fprintf(stderr, "Error: Missing target flow rate argument\n");
                return 1;
            }
            target_flow_err = argv[i + 1];
            i++;
        }
    }

    // Validate Kp argument
    if (strcmp(kp_str, kp_str_err) != 0) {
        fprintf(stderr, "Error: Invalid Kp argument\n");
        return 1;
    }

    // Validate target flow rate argument
    if (strcmp(target_flow_str, target_flow_err) != 0) {
        fprintf(stderr, "Error: Invalid target flow rate argument\n");
        return 1;
    }

    // Initialize the flow sensor
    ret = i2c_master_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize I2C: %d\n", ret);
        return 1;
    }

    ret = i2c_master_write(I2C_SLAVE_ADDRESS, I2C_BUFFER_SIZE, buffer, &ret_val);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to flow sensor: %d\n", ret);
        return 1;
    }

    // Initialize the PWM
    ret = pwm_set_duty_cycle(PWM_CHANNEL_0, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %d\n", ret);
        return 1;
    }

    // Initialize the GPIO
    ret = gpio_request_line(GPIO_DIR_IN, GPIO_ENABLE_PIN, &pipe_num);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %d\n", ret);
        return 1;
    }

    // Initialize the interrupt handler
    interrupt_desc = interrupt_request_irq(pipe_num, ISR_PROFILING_IRQ, ISR_PROFILING_handler, NULL);
    if (interrupt_desc == NULL) {
        fprintf(stderr, "Failed to request interrupt: %d\n", pipe_num);
        return 1;
    }

    // Start the control loop
    while (1) {
        // Get current time
        ret = get_time_ms(&start_time);
        if (ret < 0) {
            fprintf(stderr, "Failed to get current time: %d\n", ret);
            return 1;
        }

        // Read flow sensor
        ret = i2c_master_read(I2C_SLAVE_ADDRESS, I2C_BUFFER_SIZE, buffer, &ret_val);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from flow sensor: %d\n", ret);
            return 1;
        }

        // Calculate flow rate
        flow_rate = (uint16_t)strtoul(buffer, NULL, 10);

        // Calculate PWM duty cycle
        if (flow_rate > 0) {
            flow_rate = (uint16_t)(flow_rate * kp_str_err / target_flow_str);
            if (flow_rate < 0) {
                flow_rate = 0;
            }
        } else {
            flow_rate = 0;
        }

        // Set PWM duty cycle
        ret = pwm_set_duty_cycle(PWM_CHANNEL_0, flow_rate);
        if (ret < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle: %d\n", ret);
            return 1;
        }

        // Log control iteration
        ret = fprintf(file, "%.2f,%.2f,%.2f\n", start_time.tv_sec, flow_rate, (int)gpio_desc->value);
        if (ret < 0) {
            fprintf(stderr, "Failed to log control iteration: %d\n", ret);
            return 1;
        }

        // Wait for next control iteration
        nanosleep(&start_time, NULL);
    }

    // Clean up
    pwm_set_duty_cycle(PWM_CHANNEL_0, 0);
    gpio_release_line(pipe_num);
    i2c_master_deinit();
    return 0;
}

