    int speed;
};

struct encoder_data {
    int motor_num;
    int direction;
    int count;
};

// Global Variables
struct motor_data motors[2];
struct encoder_data encoders[2];
bool motors_initialized = false;
bool encoders_initialized = false;

// Mutex for encoder_data synchronization
pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void init_gpio(void);
void init_pwm(void);
void stop_motors(void);
void read_encoders(void);
void read_motors(void);
void log_speed(int speed);
void log_pid_components(double p, double i, double d);
void log_pid_output(double output);
void log_error(const char* message);

int main(void) {
    int ret;

    // Initialize GPIO
    init_gpio();

    // Initialize PWM
    init_pwm();

    // Initialize encoders
    init_encoders();

    // Start motor monitoring threads
    pthread_t motor_monitor_tid;
    pthread_create(&motor_monitor_tid, NULL, motor_monitor_thread, NULL);

    // Start PID control thread
    pthread_t pid_control_tid;
    pthread_create(&pid_control_tid, NULL, pid_control_thread, NULL);

    // Infinite loop
    while (true) {
        // Wait for motor control signals
        pthread_mutex_lock(&encoder_mutex);
        read_encoders();
        pthread_mutex_unlock(&encoder_mutex);

        // Read motor speeds
        read_motors();

        // Log motor speeds
        log_speed(motors[0].speed);
        log_speed(motors[1].speed);
        log_pid_components(motors[0].speed, motors[1].speed, 0);

        // Log PID components
        log_pid_components(motors[0].speed, motors[1].speed, 0);

        // Log PID output
        log_pid_output(motors[0].speed * PID_SAMPLE_TIME_MS / 1000);
        log_pid_output(motors[1].speed * PID_SAMPLE_TIME_MS / 1000);

        // Wait for PID control signal
        pthread_mutex_lock(&encoder_mutex);
        pthread_cond_wait(&pid_cond, &encoder_mutex);
        pthread_mutex_unlock(&encoder_mutex);
    }

    // Stop motor monitoring threads
    pthread_join(motor_monitor_tid, NULL);
    pthread_join(pid_control_tid, NULL);

    // Release GPIO lines
    gpio_release(DRIVER_PATH);

    return 0;
}

