#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/ioctl.h>

#include <gpiod.h>
#include <pigpio.h>

#define VALVE_1_GPIO 17
#define VALVE_2_GPIO 18
#define VALVE_1_RELAY 17
#define VALVE_2_RELAY 18

int valve_log_fd;

void handle_sigint(int signum) {
    printf("Received SIGINT, cleaning up GPIO and log file...\n");
    gpio_unexport(VALVE_1_GPIO);
    gpio_unexport(VALVE_2_GPIO);
    gpio_close(GPIO_HANDLE(VALVE_1_GPIO));
    gpio_close(GPIO_HANDLE(VALVE_2_GPIO));
    close(valve_log_fd);
    exit(0);
}

void handle_sigterm(int signum) {
    printf("Received SIGTERM, cleaning up GPIO and log file...\n");
    gpio_unexport(VALVE_1_GPIO);
    gpio_unexport(VALVE_2_GPIO);
    gpio_close(GPIO_HANDLE(VALVE_1_GPIO));
    gpio_close(GPIO_HANDLE(VALVE_2_GPIO));
    close(valve_log_fd);
    exit(0);
}

int main() {
    int ret;
    int valve_1_gpio = VALVE_1_GPIO;
    int valve_2_gpio = VALVE_2_GPIO;
    int valve_1_relay = VALVE_1_RELAY;
    int valve_2_relay = VALVE_2_RELAY;

    gpio_init();
    gpio_set_mode(valve_1_gpio, GPIO_OUTPUT);
    gpio_set_mode(valve_2_gpio, GPIO_OUTPUT);
    gpio_set_direction(valve_1_gpio, GPIO_OUT);
    gpio_set_direction(valve_2_gpio, GPIO_OUT);

    gpio_set_level(valve_1_gpio, GPIO_HIGH);
    gpio_set_level(valve_2_gpio, GPIO_HIGH);

    valve_log_fd = open("valve_log.txt", O_CREAT | O_TRUNC | O_WRONLY, 0644);

    struct gpiod_event event;
    event.type = GPIDO_EVENT_GPIO;
    event.gpio = valve_1_gpio;
    event.event = GPIDO_EVENT_FALLING;

    while (1) {
        ret = gpiod_event_wait(NULL, &event, 1);
        if (ret < 0) {
            perror("gpiod_event_wait");
            exit(1);
        }

        if (event.type == GPIDO_EVENT_GPIO) {
            if (event.gpio == valve_1_gpio) {
                gpio_set_level(VALVE_1_GPIO, GPIO_HIGH);
                gpio_set_level(VALVE_2_GPIO, GPIO_LOW);
                sleep(500);
                gpio_set_level(VALVE_1_GPIO, GPIO_LOW);
                gpio_set_level(VALVE_2_GPIO, GPIO_HIGH);
                sleep(5000);
            } else if (event.gpio == valve_2_gpio) {
                gpio_set_level(VALVE_1_GPIO, GPIO_HIGH);
                gpio_set_level(VALVE_2_GPIO, GPIO_LOW);
                sleep(1000);
                gpio_set_level(VALVE_1_GPIO, GPIO_LOW);
                gpio_set_level(VALVE_2_GPIO, GPIO_HIGH);
                sleep(10000);
            }
        }
    }

    gpio_exit();
    return 0;
}

