            return -1;
        }

        struct i2c_rdwr_ioctl_data i2c_data_release = {
            .msgs = 1,
            .msg = &i2c_data_reg_release,
            .nmsgs = 1,
        };

        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data_release) == -1) {
            perror("Failed to perform I2C read/write");
            return -1;
        }

        usleep(100);
    }

    close_i2c();
    close_gpio();

    return 0;
}
