#define GPIO_BASE_ADDRESS 0x20200000
#define GPIO_NUM_PERIPH_BASE 17

int main() {
    int relay_gpio_num = 18;
    int pir_gpio_num = GPIO_BASE_ADDRESS + GPIO_NUM_PERIPH_BASE + 1;
    int log_file_fd;
    struct input_event event;
    struct timespec start_time, end_time;
    int motion_detected = 0;
    int rate_limit_counter = 0;
    int rate_limit_duration = 2000; // 2 seconds
    char log_file_path[128];

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO.\n");
        return 1;
    }

    // Open log file
    snprintf(log_file_path, sizeof(log_file_path), "/home/pi/door_events.log");
    log_file_fd = open(log_file_path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_file_fd < 0) {
        fprintf(stderr, "Error opening log file.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioSetupGpio(GPIO_BASE_ADDRESS) < 0) {
        fprintf(stderr, "Error initializing pigpio.\n");
        return 1;
    }

    // Set up the PIR sensor
    if (gpioSetPwmFrequency(pir_gpio_num, 100) < 0) {
        fprintf(stderr, "Error setting PWM frequency for PIR sensor.\n");
        return 1;
    }

    // Set up the relay
    if (gpioSetPwmFrequency(relay_gpio_num, 100) < 0) {
        fprintf(stderr, "Error setting PWM frequency for relay.\n");
        return 1;
    }

    // Set up the GPIO polling loop
    while (1) {
        // Wait for motion detection
        if (waitForMotionDetection() < 0) {
            continue;
        }

        // Activate the relay for 500 ms
        gpioWrite(relay_gpio_num, 1);
        sleep(500);
        gpioWrite(relay_gpio_num, 0);

        // Log the motion event
        if (writeMotionEventToLogFile() < 0) {
            fprintf(stderr, "Error writing motion event to log file.\n");
            return 1;
        }

        // Check rate limiting
        if (checkRateLimit() < 0) {
            fprintf(stderr, "Error checking rate limit.\n");
            return 1;
        }

        // Increment motion detected counter
        motion_detected = 1;
    }

    // Clean up
    close(log_file_fd);
    gpioTerminate();

    return 0;
}

int waitForMotionDetection() {
    int ret;
    struct input_event event;

    do {
        ret = pigpio_poll(1, &event, GPIO_BASE_ADDRESS, 500);
    } while (ret == -1 && errno == EINTR);

    if (ret == -1) {
        fprintf(stderr, "Error waiting for motion detection.\n");
        return -1;
    }

    if (event.type == INPUT_EVENT_TYPE_REL) {
        if (event.value == 1) {
            motion_detected = 1;
        }
    }

    return 0;
}

int writeMotionEventToLogFile() {
    int ret;
    struct input_event event;

    do {
        ret = pigpio_poll(1, &event, GPIO_BASE_ADDRESS, 500);
    } while (ret == -1 && errno == EINTR);

    if (ret == -1) {
        fprintf(stderr, "Error writing motion event to log file.\n");
        return -1;
    }

    if (event.type == INPUT_EVENT_TYPE_REL) {
        if (event.value == 1) {
            if (write(log_file_fd, &event, sizeof(struct input_event)) < 0) {
                fprintf(stderr, "Error writing motion event to log file.\n");
                return -1;
            }
        }
    }

    return 0;
}

int checkRateLimit() {
    int ret;
    struct input_event event;

    do {
        ret = pigpio_poll(1, &event, GPIO_BASE_ADDRESS, 500);
    } while (ret == -1 && errno == EINTR);

    if (ret == -1) {
        fprintf(stderr, "Error checking rate limit.\n");
        return -1;
    }

    if (event.type == INPUT_EVENT_TYPE_REL) {
        if (event.value == 1) {
            if (rate_limit_counter < rate_limit_duration / 2) {
                sleep(500);
                rate_limit_counter++;
            } else {
                rate_limit_counter = 0;
            }
        }
    }

    return 0;
}

