#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define MOTOR_1_PIN 17
#define MOTOR_2_PIN 27

volatile sig_atomic_t stop_flag = 0;

void randomize_pattern(int motor_num, int num_steps, int min_duty, int max_duty, int duration_ms) {
    int step_duration_ms = duration_ms / 10;
    int step_duration_us = step_duration_ms * 1000;
    int step_duration_step = (step_duration_us / (1000 * 1000)) / num_steps;
    int step_duration_us_per_step = step_duration_us / num_steps;

    for (int i = 0; i < num_steps; i++) {
        int pwm_duty = rand() % (max_duty - min_duty + 1) + min_duty;
        gpioSetPWM(motor_num, pwm_duty);
        gpioDelay(step_duration_step);
        gpioClearPWM(motor_num);
    }
}

int main() {
    int motor_1_pin = MOTOR_1_PIN;
    int motor_2_pin = MOTOR_2_PIN;
    gpioInit();
    gpioSetMode(motor_1_pin, PI_OUTPUT);
    gpioSetMode(motor_2_pin, PI_OUTPUT);

    // Seed the random number generator with time(NULL)
    srand(time(NULL));

    while (!stop_flag) {
        // Generate a random haptic feedback pattern
        int num_steps = rand() % 11 + 5;
        int min_duty = 0;
        int max_duty = 255;
        int duration_ms = rand() % 101 + 50;

        randomize_pattern(motor_1_pin, num_steps, min_duty, max_duty, duration_ms);
        randomize_pattern(motor_2_pin, num_steps, min_duty, max_duty, duration_ms);

        // Wait for user input to stop the program
        printf("Press Ctrl+C to stop the program.\n");
        getchar();
        stop_flag = 1;
    }

    gpioTerminate();
    return 0;
}

