#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <signal.h>
#include <sys/time.h>

#include <gpiod.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLK_PIN 17
#define HX711_THRESHOLD 5.0
#define HX711_TIMEOUT_MS 100

int main() {
    int solenoid_pin = 27;
    int calibration_factor = 0;
    int threshold_weight = HX711_THRESHOLD;
    char calibration_file[128] = "calibration.txt";
    char security_log_file[128] = "security.log";

    int solenoid_fd;
    int calibration_fd;
    int log_fd;

    int ret;
    int i;
    struct gpiod_event event;
    struct gpiod_event_attr attr;
    struct gpiod_event_attr_data data;
    struct timespec start_time, end_time;
    struct timespec timeout;
    struct sigaction sa;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Initialize HX711
    if (hx711Initialize() < 0) {
        fprintf(stderr, "Failed to initialize HX711\n");
        return 1;
    }

    // Open calibration and security log files
    if ((calibration_fd = open(calibration_file, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Failed to open calibration file\n");
        return 1;
    }

    if ((security_log_file[0] = open(security_log_file, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Failed to open security log file\n");
        return 1;
    }

    // Set up GPIO and HX711 event handling
    if (gpioSetEventDetect(HX711_DATA_PIN, GPIO_FALLING, GPIO_EDGE_FALLING, &event, &attr, &data) < 0) {
        fprintf(stderr, "Failed to set up GPIO event handling\n");
        return 1;
    }

    if (gpioSetEventDetect(HX711_CLK_PIN, GPIO_RISING, GPIO_EDGE_RISING, &event, &attr, &data) < 0) {
        fprintf(stderr, "Failed to set up GPIO event handling\n");
        return 1;
    }

    // Set up timeout for HX711
    timeout.tv_sec = HX711_TIMEOUT_MS / 1000000;
    timeout.tv_nsec = (HX711_TIMEOUT_MS % 1000000) * 1000;

    // Set up SIGINT handler
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_SIGINFO;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up SIGINT handler\n");
        return 1;
    }

    // Initialize solenoid pin
    if (gpioSetValue(solenoid_pin, GPIO_HIGH) < 0) {
        fprintf(stderr, "Failed to set up solenoid pin\n");
        return 1;
    }

    // Initialize calibration factor
    if (hx711Calibrate(HX711_DATA_PIN, HX711_CLK_PIN, &calibration_factor) < 0) {
        fprintf(stderr, "Failed to calibrate HX711\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for HX711 data line to go high
        if (gpioWaitForEdge(HX711_DATA_PIN, GPIO_FALLING) < 0) {
            fprintf(stderr, "Failed to wait for HX711 data line to go high\n");
            return 1;
        }

        // Wait for HX711 clock line to go high
        if (gpioWaitForEdge(HX711_CLK_PIN, GPIO_RISING) < 0) {
            fprintf(stderr, "Failed to wait for HX711 clock line to go high\n");
            return 1;
        }

        // Read data from HX711
        if (hx711ReadData(HX711_DATA_PIN, &data) < 0) {
            fprintf(stderr, "Failed to read data from HX711\n");
            return 1;
        }

        // Check if data line is high for more than 100 ms
        if (data.value == GPIO_HIGH && (time(NULL) - start_time.tv_sec) > HX711_TIMEOUT_MS) {
            // Log timestamp and weight
            if (log_timestamp() < 0) {
                fprintf(stderr, "Failed to log timestamp\n");
                return 1;
            }
            if (log_weight() < 0) {
                fprintf(stderr, "Failed to log weight\n");
                return 1;
            }

            // Check if weight exceeds threshold
            if (data.value > threshold_weight) {
                // Engage solenoid lock
                if (gpioSetValue(solenoid_pin, GPIO_HIGH) < 0) {
                    fprintf(stderr, "Failed to engage solenoid lock\n");
                    return 1;
                }
                if (gpioDelay(1000) < 0) {
                    fprintf(stderr, "Failed to delay for 1 second\n");
                    return 1;
                }
                if (gpioSetValue(solenoid_pin, GPIO_LOW) < 0) {
                    fprintf(stderr, "Failed to disengage solenoid lock\n");
                    return 1;
                }
                if (gpioDelay(1000) < 0) {
                    fprintf(stderr, "Failed to delay for 1 second\n");
                    return 1;
                }
            }
        }

        // Wait for HX711 data line to go low
        if (gpioWaitForEdge(HX711_DATA_PIN, GPIO_FALLING) < 0) {
            fprintf(stderr, "Failed to wait for HX711 data line to go low\n");
            return 1;
        }

        // Check if solenoid lock was engaged
        if (gpioGetValue(solenoid_pin) == GPIO_LOW) {
            // Unlock solenoid lock
            if (gpioSetValue(solenoid_pin, GPIO_HIGH) < 0) {
                fprintf(stderr, "Failed to unlock solenoid lock\n");
                return 1;
            }
            if (gpioDelay(1000) < 0) {
                fprintf(stderr, "Failed to delay for 1 second\n");
                return 1;
            }
            if (gpioSetValue(solenoid_pin, GPIO_LOW) < 0) {
                fprintf(stderr, "Failed to disengage solenoid lock\n");
                return 1;
            }
            if (gpioDelay(1000) < 0) {
                fprintf(stderr, "Failed to delay for 1 second\n");
                return 1;
            }
        }

        // Check if calibration factor has changed
        if (hx711ReadData(HX711_DATA_PIN, &data) < 0) {
            fprintf(stderr, "Failed to read data from HX711\n");
            return 1;
        }
        if (data.value != calibration_factor) {
            // Update calibration factor
            if (hx711WriteData(HX711_DATA_PIN, &calibration_factor, sizeof(calibration_factor)) < 0) {
                fprintf(stderr, "Failed to update calibration factor\n");
                return 1;
            }
            if (hx711ReadData(HX711_DATA_PIN, &calibration_factor) < 0) {
                fprintf(stderr, "Failed to read calibration factor\n");
                return 1;
            }
        }

        // Check if threshold weight has been exceeded
        if (data.value > threshold_weight) {
            // Log timestamp and weight
            if (log_timestamp() < 0) {
                fprintf(stderr, "Failed to log timestamp\n");
                return 1;
            }
            if (log_weight() < 0) {
                fprintf(stderr, "Failed to log weight\n");
                return 1;
            }

            // Check if weight exceeds threshold
            if (data.value > threshold_weight) {
                // Engage solenoid lock
                if (gpioSetValue(solenoid_pin, GPIO_HIGH) < 0) {
                    fprintf(stderr, "Failed to engage solenoid lock\n");
                    return 1;
                }
                if (gpioDelay(1000) < 0) {
                    fprintf(stderr, "Failed to delay for 1 second\n");
                    return 1;
                }
                if (gpioSetValue(solenoid_pin, GPIO_LOW) < 0) {
                    fprintf(stderr, "Failed to disengage solenoid lock\n");
                    return 1;
                }
                if (gpioDelay(1000) < 0) {
                    fprintf(stderr, "Failed to delay for 1 second\n");
                    return 1;
                }
            }
        }

        // Wait for HX711 data line to go high
        if (gpioWaitForEdge(HX711_DATA_PIN, GPIO_FALLING) < 0) {
            fprintf(stderr, "Failed to wait for HX711 data line to go high\n");
            return 1;
        }

        // Wait for HX711 clock line to go high
        if (gpioWaitForEdge(HX711_CLK_PIN, GPIO_RISING) < 0) {
            fprintf(stderr, "Failed to wait for HX711 clock line to go high\n");
            return 1;
        }

        // Wait for HX711 data line to go low
        if (gpioWaitForEdge(HX711_DATA_PIN, GPIO_FALLING) < 0) {
            fprintf(stderr, "Failed to wait for HX711 data line to go low\n");
            return 1;
        }
    }

    // Clean up GPIO
    gpioRelease() < 0) {
        fprintf(stderr, "Failed to release GPIO\n");
        return 1;
    }

    // Clean up HX711
    hx711Release() < 0) {
        fprintf(stderr, "Failed to release HX711\n");
        return 1;
    }

    // Clean up security log file
    if (close(security_log_file) < 0) {
        fprintf(stderr, "Failed to close security log file\n");
        return 1;
    }

    // Clean up calibration file
    if (close(calibration_file) < 0) {
        fprintf(stderr, "Failed to close calibration file\n");
        return 1;
    }

    // Clean up solenoid file
    if (close(solenoid_fd) < 0) {
        fprintf(stderr, "Failed to close solenoid file\n");
        return 1;
    }

    // Clean up log file
    if (close(log_fd) < 0) {
        fprintf(stderr, "Failed to close log file\n");
        return 1;
    }

    // Exit program
    return 0;
}

