#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_FILE "/dev/gpiochip0"
#define VALVE_GPIO 18

volatile sig_atomic_t valve_on = 0;

void handle_signal(int signum) {
    valve_on = 0;
}

int main() {
    int fd;
    int ret;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO.\n");
        return 1;
    }

    // Open GPIO file
    fd = open(GPIO_FILE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO file.\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO line as output with active-low = 0 and default low value
    ret = ioctl(fd, GPIO_SET_DIR, GPIO_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO direction.\n");
        goto error;
    }

    ret = ioctl(fd, GPIO_SET_VALUE, GPIO_LOW);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO value to low.\n");
        goto error;
    }

    // Activate the valve by setting the line high
    ret = ioctl(fd, GPIO_SET_VALUE, GPIO_HIGH);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO value to high.\n");
        goto error;
    }

    // Wait for configured duration using signal-safe interruptible sleep
    gpioWaitSignal(SIGINT, handle_signal);

    // Set the line low
    ret = ioctl(fd, GPIO_SET_VALUE, GPIO_LOW);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO value to low.\n");
        goto error;
    }

    // Print status messages
    printf("Watering duration: %d seconds\n", VALVE_GPIO);
    printf("Valve on/off: %s\n", valve_on ? "on" : "off");

    // Release GPIO resources
    gpioTerminate();

    return 0;

error:
    fprintf(stderr, "Error: Failed to close GPIO file.\n");
    return 1;
}

