#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c-gpio.h>

#define I2C_BUS_NUM 1
#define RELAY_GPIO_PIN 23

// Function prototypes
void i2c_init();
void i2c_cleanup();
void i2c_read_sensor();
void relay_control(int state);

int main() {
    int i2c_fd;
    int relay_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct gpiod_value gpiod_value;
    char grow_log_file[] = "grow_log.txt";

    // Initialize I2C bus
    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Open relay GPIO
    if (gpio_request_from_name("gpiochip0", RELAY_GPIO_PIN, &relay_fd) < 0) {
        fprintf(stderr, "Failed to open GPIO\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(grow_log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_request_from_name("gpiochip0", RELAY_GPIO_PIN, &relay_fd) < 0) {
        fprintf(stderr, "Failed to open GPIO\n");
        return 1;
    }

    // Initialize I2C driver
    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
        if (i2c_read_sensor() < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        // Check if lux reading is below 150
        if (sensor_data.lux < 150) {
            relay_control(1);
        } else {
            relay_control(0);
        }

        // Log lux value and relay state change
        fprintf(log_file, "%.3f,%.2d\n", (float)sensor_data.lux, (int)relay_state);

        // Close log file
        fclose(log_file);
    }

    // Clean up I2C bus
    i2c_cleanup();

    // Close relay GPIO
    gpio_release_from_name(relay_fd);

    return 0;
}

void i2c_init() {
    int i2c_fd;
    struct i2c_rdwr_ioctl_data i2c_data;

    // Check if I2C bus is available
    if (ioctl(I2C_BUS_NUM, I2C_RDWR, &i2c_data) < 0) {
        fprintf(stderr, "Failed to check I2C bus availability\n");
        return -1;
    }

