        if (mqtt_subscribe(mqtt_sock, MQTT_TOPIC, 1, NULL) != 0) {
            perror("Failed to subscribe to topic");
            exit(EXIT_FAILURE);
        }

        // Set MQTT client callback for incoming messages
        if (mqtt_set_client_option(mqtt_sock, MQTT_OPT_ON_CONNECT, 1) != 0) {
            perror("Failed to set MQTT client option");
            exit(EXIT_FAILURE);
        }

        // Set MQTT client callback for incoming messages
        if (mqtt_set_client_option(mqtt_sock, MQTT_OPT_ON_DISCONNECT, 1) != 0) {
            perror("Failed to set MQTT client option");
            exit(EXIT_FAILURE);
        }

        // Set MQTT client callback for incoming messages
        if (mqtt_set_client_option(mqtt_sock, MQTT_OPT_ON_PUBLISH, 1) != 0) {
            perror("Failed to set MQTT client option");
            exit(EXIT_FAILURE);
        }

        ir_mqtt_client_initialized = 1;
    }
