        int num_bits = (pulse_duration - pulse_width) / bit_duration;

        // Calculate the command
        int command = 0;
        for (int i = 0; i < num_bits; i++) {
            if (pulse_width - bit_duration * i <= pulse_duration) {
                command |= (1 << i);
            }
        }

        // Check if the command is inverted
        if (command != 0) {
            command = ~command;
        }

        // Check if the command is extended
        if (num_bits > 32) {
            command |= (command << 16);
        }

        // Check if the command is valid
        if (command == 0) {
            syslog(LOG_ERR, "Invalid command");
            exit(EXIT_FAILURE);
        }

        // Publish the command to MQTT broker
        if (mqtt_publish(ir_mqtt_sock, MQTT_TOPIC, &command, sizeof(command)) != 0) {
            perror("Failed to publish command");
            exit(EXIT_FAILURE);
        }
    }
}

