    char buffer[2];
    char log_file_name[] = "airflow_log.txt";
    struct timespec start_time, end_time;
    pid_t pid;

    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(GPIO_I2C, GPIO_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set I2C mode\n");
        return 1;
    }

    if (gpioSetSpeed(GPIO_I2C, 100) < 0) {
        fprintf(stderr, "Failed to set I2C speed\n");
        return 1;
    }

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Open the sensor
    if ((ret = pigpio_open(&pi, SENSOR_ADDRESS)) != 0) {
        if (ret == -1) {
            fprintf(stderr, "Failed to open sensor: ENXIO\n");
            goto error_i2c_close;
        } else {
            fprintf(stderr, "Failed to open sensor: EIO\n");
            goto error_i2c_close;
        }
    }

    // Set up the write message
    msgs[0].addr = SENSOR_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &buffer[0];
    msgs[0].len = 1;

    // Set up the read message
    msgs[1].addr = SENSOR_ADDRESS;
    msgs[1].flags = 0;
    msgs[1].len = 2;
    msgs[1].buf = &buffer[2];
    msgs[1].len = 2;

    // Perform the write and read operations
    if (pigpio_transfer(pi, msgs, 2, &data, NULL) < 0) {
        fprintf(stderr, "Failed to perform I2C write and read operations\n");
        goto error_i2c_close;
    }

    // Mask the 14-bit flow value from the first two bytes
    buffer[0] &= 0x3FF;
    buffer[1] &= 0x3FF;

    // Convert the masked value to SLPM
    buffer[1] = (buffer[1] >> 4) | (buffer[0] << 4);
    buffer[0] = (buffer[0] >> 4) | ((buffer[1] << 4) & 0xF000);

    // Log the flow-rate entry
    if (write(1, buffer, 2) != 2) {
        fprintf(stderr, "Failed to log flow-rate entry\n");
        goto error_log_file_close;
    }

    // Start the timer
    if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0) {
        fprintf(stderr, "Failed to get current time\n");
        goto error_log_file_close;
    }

    // Perform the read operation
    if (pigpio_transfer(pi, msgs, 2, &data, NULL) < 0) {
        fprintf(stderr, "Failed to perform I2C read operation\n");
        goto error_log_file_close;
    }

    // Get the current time
    if (clock_gettime(CLOCK_MONOTONIC, &end_time) < 0) {
        fprintf(stderr, "Failed to get current time\n");
        goto error_log_file_close;
    }

    // Calculate the elapsed time
    if (end_time.tv_sec - start_time.tv_sec > 0) {
        double elapsed_seconds = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;
        printf("Flow rate: %f SLPM\n", elapsed_seconds);
    }

    // Close the I2C file descriptor
    if (close(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C file descriptor\n");
        goto error_log_file_close;
    }

    // Close the log file
    if (close(1) < 0) {
        fprintf(stderr, "Failed to close log file\n");
        goto error_log_file_close;
    }

    // Cleanly close the I2C file descriptor and log file
    if (pi_exit(pi) < 0) {
        fprintf(stderr, "Failed to cleanly exit\n");
        goto error_log_file_close;
    }

error_log_file_close:
    if (close(1) < 0) {
        fprintf(stderr, "Failed to close log file\n");
    }

error_i2c_close:
    if (gpioSetSpeed(GPIO_I2C, 0) < 0) {
        fprintf(stderr, "Failed to set I2C speed to 0\n");
    }

    if (gpioClose(pi) < 0) {
        fprintf(stderr, "Failed to close GPIO\n");
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to close GPIO\n");
    }

    return 1;
}

