#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/select.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define UART_DEVICE_PATH "/dev/serial0"
#define GPIO_TX_PIN 14
#define GPIO_RX_PIN 15

int main() {
    int uart_fd, uart_baud_rate;
    struct termios tty_options;
    struct sigaction sigint_handler, sigterm_handler;
    struct timespec timeout;
    struct fd_set readfds;
    char line[256];
    char *timestamp, *range;
    int uart_timeout = 0;
    int fd;
    int result;

    // Initialize GPIO pins
    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO pins\n");
        return 1;
    }

    // Open UART device
    if ((uart_fd = open(UART_DEVICE_PATH, O_RDWR | O_NOCTTY | O_NDELAY)) < 0) {
        fprintf(stderr, "Failed to open UART device: %s\n", UART_DEVICE_PATH);
        return 1;
    }

    // Set UART parameters
    if (tcgetattr(uart_fd, &tty_options) < 0) {
        fprintf(stderr, "Failed to get UART parameters: %s\n", UART_DEVICE_PATH);
        return 1;
    }

    tty_options.c_cflag &= ~PARENB;
    tty_options.c_cflag &= ~CSTOPB;
    tty_options.c_cflag &= ~CSIZE;
    tty_options.c_cflag |= CS8;
    tty_options.c_cflag &= ~CRTSCTS;
    tty_options.c_cflag |= CREAD | CLOCAL;
    tty_options.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty_options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty_options.c_oflag &= ~OPOST;
    tty_options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);

    if (tcsetattr(uart_fd, TCSANOW, &tty_options) < 0) {
        fprintf(stderr, "Failed to set UART parameters: %s\n", UART_DEVICE_PATH);
        return 1;
    }

    // Set GPIO pins as output
    if (gpio_direction(GPIO_TX_PIN, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", "GPIO_TX_PIN");
        return 1;
    }

    if (gpio_direction(GPIO_RX_PIN, GPIO_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", "GPIO_RX_PIN");
        return 1;
    }

    // Install signal handlers
    sigint_handler.sa_handler = sigint_handler_handler;
    sigterm_handler.sa_handler = sigterm_handler_handler;
    sigaction(SIGINT, &sigint_handler, NULL);
    sigaction(SIGTERM, &sigterm_handler, NULL);

    // Initialize UART for non-canonical mode
    if (ioctl(uart_fd, TIOCMGET, &tty_options) < 0) {
        fprintf(stderr, "Failed to get UART flags: %s\n", UART_DEVICE_PATH);
        return 1;
    }

    tty_options.c_cflag &= ~CRTSCTS;
    tty_options.c_cflag |= CREAD | CLOCAL;
    tty_options.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty_options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty_options.c_oflag &= ~OPOST;
    tty_options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);

    if (ioctl(uart_fd, TIOCMSET, &tty_options) < 0) {
        fprintf(stderr, "Failed to set UART flags: %s\n", UART_DEVICE_PATH);
        return 1;
    }

    // Open UART for reading
    if ((fd = open(UART_DEVICE_PATH, O_RDONLY | O_NONBLOCK)) < 0) {
        fprintf(stderr, "Failed to open UART device: %s\n", UART_DEVICE_PATH);
        return 1;
    }

    // Set timeout for select()
    timeout.tv_sec = 0;
    timeout.tv_nsec = 1000000;

    // Initialize select()
    if (select(0, NULL, NULL, NULL, &timeout) < 0) {
        fprintf(stderr, "Failed to initialize select(): %s\n", strerror(errno));
        return 1;
    }

    // Wait for sensor data or timeout
    fd_set readfds;
    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    while (1) {
        // Wait for data or timeout
        result = select(fd + 1, &readfds, NULL, NULL, &timeout);
        if (result < 0) {
            fprintf(stderr, "Failed to select(): %s\n", strerror(errno));
            return 1;
        }

        // Check for data
        if (FD_ISSET(fd, &readfds)) {
            // Read data from UART
            if (read(fd, line, sizeof(line)) < 0) {
                fprintf(stderr, "Failed to read UART data: %s\n", strerror(errno));
                return 1;
            }

            // Parse line for newline-terminated lines
            if ((sscanf(line, "<%lf,%lf>\n", &range, &timestamp) == 2) &&
                (strcmp(timestamp, "0") == 0)) {
                // Log detection
                printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);
            }
        }
    }

    // Close UART
    close(fd);

    // Close GPIO pins
    gpio_exit();

    return 0;
}

