#define KY_033_GPIO_DIR_IN  (1 << 7)  // GPIO4
#define KY_033_GPIO_DIR_OUT (1 << 11) // GPIO17
#define KY_033_GPIO_DIR_INP  (1 << 13) // GPIO27

int main() {
    int fd, gpio_fd;
    struct gpiod_event event;
    char buffer[32];
    char *uart_path = "/dev/ttyAMA0";
    char *uart_baudrate = "115200";
    int uart_baudrate_fd;

    // Initialize GPIO and UART
    if (gpio_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO.\n");
        return 1;
    }

    if (gpio_request_dir(KY_033_GPIO_DIR_INP) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO direction for input.\n");
        return 1;
    }

    if (gpio_request_dir(KY_033_GPIO_DIR_OUT) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO direction for output.\n");
        return 1;
    }

    if (gpio_request_dir(KY_033_GPIO_DIR_IN) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO direction for input.\n");
        return 1;
    }

    if (gpio_request_pullup_en(KY_033_GPIO_DIR_INP) < 0) {
        fprintf(stderr, "Error: Failed to enable pull-up resistor for input.\n");
        return 1;
    }

    if (gpio_request_pullup_en(KY_033_GPIO_DIR_OUT) < 0) {
        fprintf(stderr, "Error: Failed to enable pull-up resistor for output.\n");
        return 1;
    }

    if (gpio_request_pullup_en(KY_033_GPIO_DIR_IN) < 0) {
        fprintf(stderr, "Error: Failed to enable pull-up resistor for input.\n");
        return 1;
    }

    // Open UART
    if ((uart_baudrate_fd = open(uart_path, O_RDWR | O_NOCTTY | O_NDELAY)) < 0) {
        fprintf(stderr, "Error: Failed to open UART device.\n");
        return 1;
    }

    if (tcsetattr(uart_baudrate_fd, TCSANOW, &termios_settings) < 0) {
        fprintf(stderr, "Error: Failed to set UART baud rate.\n");
        return 1;
    }

    // Initialize UART
    if (pigpio_initialize() < 0) {
        fprintf(stderr, "Error: Failed to initialize UART.\n");
        return 1;
    }

    // Initialize GPIO event
    if (gpio_event_request(&event, KY_033_GPIO_DIR_INP, 0, 0, 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO event.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor states
        if (gpio_read(KY_033_GPIO_DIR_INP) == 0) {
            event.type = GPIGPIO_EVENT_GPIO;
            event.gpio.value = 0;
            if (gpio_event_send(&event) < 0) {
                fprintf(stderr, "Error: Failed to send GPIO event.\n");
                return 1;
            }
        } else {
            event.type = GPIGPIO_EVENT_GPIO;
            event.gpio.value = 1;
            if (gpio_event_send(&event) < 0) {
                fprintf(stderr, "Error: Failed to send GPIO event.\n");
                return 1;
            }
        }

        // Log sensor states
        printf("[%d] Sensor states: Left - %d, Middle - %d, Right - %d\n",
               time(NULL), event.gpio.value_left, event.gpio.value_middle, event.gpio.value_right);

        // Check for emergency stop
        if (event.gpio.value_left == 0 && event.gpio.value_middle == 0 && event.gpio.value_right == 0) {
            printf("EMERGENCY STOP!\n");
            // Send emergency stop string over UART
            if (write(uart_baudrate_fd, "EMERGENCY STOP!\n", 13) < 0) {
                fprintf(stderr, "Error: Failed to send emergency stop string over UART.\n");
                return 1;
            }
        }

        // Wait for 10 ms
        usleep(10000);
    }

    // Clean up
    gpio_event_free(&event);
    gpio_unrequest_dir(KY_033_GPIO_DIR_INP);
